INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zoonk/zoonk/zoonk-issue-writer', 'community', 'zoonk', 'zoonk', 'zoonk/zoonk', 'zoonk-issue-writer', 99, 7, 67, '2026-02-28T21:44:58Z', '2026-03-06T06:31:55.142Z', 'c8e7cf2804a18ee42048f3b80642c8c03c8bf3ad0761be42e22b28b24ee318ef', '{"id":"zoonk/zoonk/zoonk-issue-writer","name":"zoonk-issue-writer","description":{"en":"The zoonk-issue-writer skill generates well-written user stories from structured issue breakdowns, providing engineers with context for implementation. It acts as a product owner layer, utilizing technologies like Next.js, Postgres, and Prisma.","zh":"zoonk-issue-writer是一个将结构化问题分解转化为详细用户故事的AI工具，支持Next.js、Postgres、Prisma等技术","ja":"zoonk-issue-writerは、Next.js、Postgres、Prismaなどをサポートする、構造化された問題分解を詳細なユーザーストーリーに変換するAIエージェントです","ko":"zoonk-issue-writer는 구조화된 문제 분해를 상세한 사용자 스토리로 변환하는 AI 에이전트로, Next.js, Postgres, Prisma 등을 지원합니다","es":"zoonk-issue-writer es una habilidad que escribe historias de usuario detalladas a partir de planes de implementación y las publica en GitHub utilizando tecnologías como NextJS, Prisma y Tailwind CSS","fr":"zoonk-issue-writer est une compétence qui rédige des histoires utilisateur détaillées à partir de plans de mise en œuvre et les publie sur GitHub en utilisant des technologies comme NextJS, Prisma et Tailwind CSS","de":"zoonk-issue-writer ist eine Fähigkeit, die detaillierte Benutzerstories aus Implementierungsplänen erstellt und auf GitHub mit Technologien wie NextJS, Prisma und Tailwind CSS veröffentlicht","pt":"O zoonk-issue-writer é uma habilidade que cria histórias de usuário detalhadas a partir de planos de implementação. Ele utiliza tecnologias como NextJS, Prisma e TailwindCSS.","ru":"Zoonk-issue-writer - это навык, который создает детальные истории пользователей из планов реализации. Он использует технологии như NextJS, Prisma и TailwindCSS.","ar":"زونك-إيشو-رايتير هو مهارة يقوم بإنشاء قصص مستخدم مفصلة من خطط التنفيذ. إنه يستخدم تكنولوجيا مثل NextJS و Prisma و TailwindCSS"},"seo":{"title":{"en":"zoonk-issue-writer: GitHub Issue Creation for AI Agents |...","zh":"zoonk-issue-writer 技术集成指南","ja":"zoonk-issue-writer AIエージェントのセットアップガイド","ko":"zoonk-issue-writer 개발자 안내서","es":"Guía de Configuración de zoonk-issue-writer para Desarrol...","fr":"Guide d''Installation de zoonk-issue-writer pour les Dével...","de":"Einrichtungsleitfaden für zoonk-issue-writer-Entwickler","pt":"Guia de Configuração do zoonk-issue-writer: Escreva Histó...","ru":"Настройка zoonk-issue-writer: Создание детальных историй ...","ar":"دليل الإعداد لزونك-إيشو-رايتير: كتابة قصص المستخدم مع أدو..."},"description":{"en":"Discover how zoonk-issue-writer transforms implementation plans into detailed user stories on GitHub. Learn how to use this AI agent skill today!","zh":"了解zoonk-issue-writer的技术细节和集成方法，提升开发效率","ja":"zoonk-issue-writer AIエージェントを使用して開発プロセスを自動化する","ko":"zoonk-issue-writer를 사용하여 개발 프로세스를 최적화하고 효율성을 높이세요","es":"Aprende a utilizar zoonk-issue-writer para escribir historias de usuario detalladas y publicarlas en GitHub con tecnologías como NextJS y Prisma","fr":"Découvrez comment utiliser zoonk-issue-writer pour écrire des histoires utilisateur détaillées et les publier sur GitHub avec des technologies comme NextJS e...","de":"Erfahren Sie, wie Sie zoonk-issue-writer verwenden, um detaillierte Benutzerstories zu schreiben und auf GitHub mit Technologien wie NextJS und Prisma zu ver...","pt":"Aprenda a configurar o zoonk-issue-writer para criar histórias de usuário detalhadas com step-by-step activities e tecnologias como NextJS e Prisma","ru":"Узнайте, как настроить zoonk-issue-writer для создания детальных историй пользователей с пошаговыми активностями и технологиями như NextJS и Prisma","ar":"تعلم كيفية إعداد زونك-إيشو-رايتير لإنشاء قصص مستخدم مفصلة مع أنشطة خطوة بخطوة وتكنولوجيا مثل NextJS و Prisma"},"definition":{"en":"zoonk-issue-writer is a skill that takes implementation plans and breaks them down into detailed user stories, posted to GitHub, using technologies like Shadcn UI and Tailwind CSS.","zh":"zoonk-issue-writer是一种AI工具，用于生成详细的用户故事和问题分解","ja":"zoonk-issue-writerは、詳細なユーザーストーリーと問題分解を生成するAIエージェントです","ko":"zoonk-issue-writer는 상세한 사용자 스토리와 문제 분해를 생성하는 AI 에이전트입니다","es":"zoonk-issue-writer es una herramienta de inteligencia artificial que actúa como capa de propietario de producto para transformar planes de implementación en historias de usuario","fr":"zoonk-issue-writer est un outil d''intelligence artificielle qui agit comme une couche de propriétaire de produit pour transformer les plans de mise en œuvre en histoires utilisateur","de":"zoonk-issue-writer ist ein KI-Tool, das als Produktbesitzer-Ebene fungiert, um Implementierungspläne in Benutzerstories umzuwandeln","pt":"O zoonk-issue-writer é uma ferramenta de AI que cria histórias de usuário detalhadas a partir de planos de implementação","ru":"Zoonk-issue-writer - это инструмент ИИ, который создает детальные истории пользователей из планов реализации","ar":"زونك-إيشو-رايتير هو أداة ذكاء اصطناعي لإنشاء قصص مستخدم مفصلة من خطط التنفيذ"},"features":{"en":["Transforms structured issue breakdowns from zoonk-issue-planning into well-written user stories","Utilizes Next.js for building and Vercel for deployment","Leverages Prisma for database interactions and Postgres for data storage","Employs Shadcn UI and Tailwind CSS for user interface styling","Posts detailed user stories to GitHub for engineer context","Acts as a product owner layer, providing implementation context without dictating implementation"],"zh":["支持Next.js和Postgres技术栈","集成Prisma和Shadcn-ui","使用Vercel和Vercel AI SDK进行部署","将结构化问题分解转化为详细用户故事","支持Tailwind CSS样式"],"ja":["Next.jsとPostgresテクノロジースタックをサポート","PrismaとShadcn-uiを統合","VercelとVercel AI SDKを使用してデプロイ","構造化された問題分解を詳細なユーザーストーリーに変換","Tailwind CSSスタイルをサポート"],"ko":["Next.js와 Postgres 기술 스택을 지원","Prisma와 Shadcn-ui를 통합","Vercel과 Vercel AI SDK를 사용하여 배포","구조화된 문제 분해를 상세한 사용자 스토리로 변환","Tailwind CSS 스타일을 지원"],"es":["Escribe historias de usuario detalladas a partir de planes de implementación","Utiliza tecnologías como NextJS, Prisma y Tailwind CSS","Publica historias de usuario en GitHub","Actúa como capa de propietario de producto","Se integra con zoonk-issue-planning para desglosar planes en problemas","Soporta la creación de historias de usuario para dar contexto a los ingenieros sin dictar la implementación"],"fr":["Rédige des histoires utilisateur détaillées à partir de plans de mise en œuvre","Utilise des technologies comme NextJS, Prisma et Tailwind CSS","Publie des histoires utilisateur sur GitHub","Agit comme une couche de propriétaire de produit","S''intègre avec zoonk-issue-planning pour décomposer les plans en problèmes","Prend en charge la création d''histoires utilisateur pour donner du contexte aux ingénieurs sans dicter la mise en œuvre"],"de":["Erstellt detaillierte Benutzerstories aus Implementierungsplänen","Verwendet Technologien wie NextJS, Prisma und Tailwind CSS","Veröffentlicht Benutzerstories auf GitHub","Fungiert als Produktbesitzer-Ebene","Integriert sich mit zoonk-issue-planning, um Pläne in Probleme zu zerlegen","Unterstützt die Erstellung von Benutzerstories, um Kontext für Ingenieure zu geben, ohne die Implementierung zu diktieren"],"pt":["Cria histórias de usuário detalhadas a partir de planos de implementação","Utiliza tecnologias como NextJS e Prisma","Suporta step-by-step activities para aprendizado","Integração com GitHub para postar histórias de usuário","Utiliza TailwindCSS para estilização"],"ru":["Создает детальные истории пользователей из планов реализации","Использует технологии как NextJS и Prisma","Поддерживает шаг-за-шагом активности для обучения","Интегрируется с GitHub для публикации историй пользователей","Использует TailwindCSS для стилизации"],"ar":["ينشئ قصص مستخدم مفصلة من خطط التنفيذ","يستخدم تكنولوجيا مثل NextJS و Prisma","يدعم أنشطة خطوة بخطوة للتعلم","يتكامل مع GitHub لنشر قصص المستخدم","يستخدم TailwindCSS للتنسيق"]},"keywords":{"en":["how to use zoonk-issue-writer","zoonk-issue-writer setup guide","zoonk-issue-writer alternative","zoonk-issue-writer vs Jira","zoonk-issue-writer install","what is zoonk-issue-writer","zoonk-issue-writer GitHub integration","zoonk-issue-writer AI agent skill"],"zh":["zoonk-issue-writer","AI工具","Next.js","Postgres","Prisma","Shadcn-ui","Vercel","Vercel AI SDK","Tailwind CSS","问题分解"],"ja":["zoonk-issue-writer","AIエージェント","Next.js","Postgres","Prisma","Shadcn-ui","Vercel","Vercel AI SDK","Tailwind CSS","問題分解"],"ko":["zoonk-issue-writer","AI 에이전트","Next.js","Postgres","Prisma","Shadcn-ui","Vercel","Vercel AI SDK","Tailwind CSS","문제 분해"],"es":["zoonk-issue-writer","herramientas de inteligencia artificial","desarrollo de software","NextJS","Prisma","Tailwind CSS","GitHub","historias de usuario","planes de implementación","Agente de IA para desarrollo"],"fr":["zoonk-issue-writer","outils d''intelligence artificielle","développement de logiciels","NextJS","Prisma","Tailwind CSS","GitHub","histoires utilisateur","plans de mise en œuvre","Agent IA pour développement"],"de":["zoonk-issue-writer","KI-Tools","Software-Entwicklung","NextJS","Prisma","Tailwind CSS","GitHub","Benutzerstories","Implementierungspläne","KI-Agent für Entwicklung"],"pt":["zoonk-issue-writer","AI para educação","NextJS","Prisma","TailwindCSS","GitHub","histórias de usuário","aprendizado com AI"],"ru":["zoonk-issue-writer","ИИ для образования","NextJS","Prisma","TailwindCSS","GitHub","истории пользователей","обучение с ИИ"],"ar":["زونك-إيشو-رايتير","أدوات الذكاء الاصطناعي للتعليم","NextJS","Prisma","TailwindCSS","GitHub","قصص المستخدم","التعلم مع أدوات الذكاء الاصطناعي"]}},"owner":"zoonk","repo":"zoonk","repoPath":"zoonk/zoonk","stars":99,"forks":7,"updatedAt":"2026-02-28T21:44:58Z","topics":["ai","better-auth","education","learning","nextjs","postgres","prisma","shadcn-ui","tailwindcss","vercel","vercel-ai-sdk"],"category":"community","skillMd":{"name":"zoonk-issue-writer","description":"Write detailed user stories from implementation plans and post to GitHub. Use after planning with zoonk-issue-planning. Acts as a product owner, providing context and acceptance criteria while leaving room for implementation decisions.","version":"1.0.0","bodyPreview":"# Issue Writer Skill\n\nWrite detailed user stories from implementation plans and post them to GitHub.\n\n## Role\n\nThis skill acts as a **product owner layer**. It takes structured issue breakdowns (from `zoonk-issue-planning`) and transforms them into well-written user stories that give engineers the context they need without dictating implementation.\n\n## When to Use\n\n- After exiting plan mode with an approved implementation plan\n- After running `zoonk-issue-planning` to break down a plan into issu","body":"# Issue Writer Skill\n\nWrite detailed user stories from implementation plans and post them to GitHub.\n\n## Role\n\nThis skill acts as a **product owner layer**. It takes structured issue breakdowns (from `zoonk-issue-planning`) and transforms them into well-written user stories that give engineers the context they need without dictating implementation.\n\n## When to Use\n\n- After exiting plan mode with an approved implementation plan\n- After running `zoonk-issue-planning` to break down a plan into issues\n- When the user asks to \"write issues\" or \"create GitHub issues\" from a plan\n\n## Workflow\n\n### Step 1: Review the Plan\n\nRead the implementation plan and issue breakdown. Understand:\n\n- The overall goal and why it matters\n- How issues relate to each other (dependencies, epic structure)\n- Key technical insights from the planning phase\n\n### Step 2: Write User Stories\n\nFor each issue in the breakdown, write a user story using the template below. Focus on:\n\n- **Why** this matters (context)\n- **What** success looks like (acceptance criteria)\n- Leave the **how** to the implementing engineer\n\n### Step 3: Review with User\n\nPresent the written stories for approval before posting. Allow edits.\n\n### Step 4: Post to GitHub\n\nUse `zoonk-github-issues` skill to create the issues with proper types, labels, and dependencies.\n\n## User Story Template\n\nUse this adaptive template. Required sections appear in every issue. Optional sections appear when they add value.\n\n```markdown\n## Context\n\n[1-3 sentences. Why does this matter? What problem or pain point does it solve?]\n\n## Goal\n\n[1-2 sentences. What this issue accomplishes when complete.]\n\n## Scope\n\n**Included:**\n\n- [What''s in scope]\n\n**Not included:**\n\n- [What''s explicitly out of scope - handled elsewhere or deferred]\n\n## Technical Notes\n\n- [Relevant file or component]\n- [Pattern to follow from codebase]\n- [Key insight from planning phase]\n\n## Acceptance Criteria\n\n- [ ] [Testable outcome 1]\n- [ ] [Testable outcome 2]\n- [ ] [Testable outcome 3]\n```\n\n### Section Guidelines\n\n| Section             | When to Include                     | When to Skip           |\n| ------------------- | ----------------------------------- | ---------------------- |\n| Context             | Always                              | Never                  |\n| Goal                | Always                              | Never                  |\n| Scope               | Larger issues, unclear boundaries   | Small, obvious scope   |\n| Technical Notes     | Planning revealed specific insights | Generic implementation |\n| Acceptance Criteria | Always                              | Never                  |\n\n## Issue References in Specs\n\n### During Spec Writing (Before GitHub Issues Exist)\n\nWhen writing specs that will become GitHub issues later:\n\n1. **Never use `#NUMBER` format in specs** - These aren''t GitHub issues yet\n2. **Reference other specs by file name** instead:\n   - BAD: `See issue #18 for details`\n   - GOOD: `See spec 18-get-org-courses.md for details`\n\n3. **Never add relationship metadata** - GitHub handles these:\n   - No \"Blocked by: #X\" lines (use GitHub API)\n   - No \"Parent: #X\" lines (use sub-issue feature)\n   - No sub-issue lists (GitHub shows these automatically)\n   - No summary tables (GitHub UI displays this)\n\n### After GitHub Issues Exist\n\nCross-references to **real GitHub issues** are fine when providing context:\n\n- \"Out of scope, handled by #1234\"\n- \"See #1234 for the course endpoint this depends on\"\n\n**But verify the reference first** - never trust #NUMBER from specs. Check GitHub to confirm the issue exists and is the correct one.\n\n## Writing Guidelines\n\n### 1. Context Over Commands\n\nEngineers need to understand _why_ before _how_. Good context enables better decisions.\n\n```markdown\n// BAD\nAdd a button to the header.\n\n// GOOD\nUsers currently can''t access settings without navigating through three menus.\nAdding a settings shortcut reduces friction for power users.\n```\n\n### 2. Specific But Not Prescriptive\n\nMention files and patterns when they help. Don''t dictate implementation details.\n\n```markdown\n// BAD\nIn `src/components/Header.tsx`, add a `<Button variant=\"ghost\">`\non line 47 after the logo div.\n\n// GOOD\nThe header component (`src/components/Header.tsx`) is the right place.\nFollow the existing icon button pattern used for the notification bell.\n```\n\n### 3. Clear Scope Boundaries\n\nPrevent scope creep by stating what''s out of scope. Reference where it''s handled.\n\n```markdown\n## Scope\n\n**Included:**\n\n- Settings button in header\n- Navigate to existing settings page\n\n**Not included:**\n\n- Redesigning settings page (tracked in #234)\n- Mobile navigation changes (separate issue)\n```\n\n### 4. Testable Acceptance Criteria\n\nEach checkbox should be verifiable. Avoid vague criteria.\n\n```markdown\n// BAD\n\n- [ ] Works correctly\n- [ ] Good UX\n\n// GOOD\n\n- [ ] Settings icon visible in header on desktop viewports\n- [ ] Clicking icon navigates to /settings\n- [ ] Icon has hover state matching other header icons\n```\n\n### 5. Concise Writing\n\nEngineers skim. Use bullets, short sentences, no walls of text.\n\n## Examples\n\n### Good User Story\n\n```markdown\n## Context\n\nCourse creators currently can''t reorder chapters after creation. They must delete\nand recreate chapters in the desired order, losing all lesson content.\n\n## Goal\n\nEnable drag-and-drop reordering of chapters within the course editor.\n\n## Scope\n\n**Included:**\n\n- Drag-and-drop UI for chapter list\n- Persist new order to database\n- Optimistic UI updates\n\n**Not included:**\n\n- Reordering lessons within chapters (separate issue #456)\n- Keyboard-only reordering (accessibility follow-up)\n\n## Technical Notes\n\n- Chapter list is in `apps/editor/src/components/course/ChapterList.tsx`\n- Use `@dnd-kit` (already in dependencies) - see `LessonList` for pattern\n- Order is stored in `chapter.position` field\n\n## Acceptance Criteria\n\n- [ ] Chapters can be reordered via drag-and-drop\n- [ ] New order persists after page refresh\n- [ ] Dragging shows visual feedback (lifted card, drop indicator)\n- [ ] Order updates optimistically (no loading state)\n```\n\n### Bad User Story\n\n```markdown\n## Description\n\nWe need to add drag and drop to chapters. Use dnd-kit. The component is in\nChapterList.tsx. Add a DndContext wrapper, then make each chapter a draggable\nitem with useDraggable hook. On drag end, call the updateChapterOrder mutation.\nMake sure to add a loading spinner while saving. Also we should probably add\nkeyboard support but that can come later. Test it works.\n\n## Tasks\n\n- [ ] Add DndContext\n- [ ] Add useDraggable to chapters\n- [ ] Call mutation on drag end\n- [ ] Add loading state\n```\n\n**Why it''s bad:**\n\n- Dictates implementation (hooks to use, exact code structure)\n- No context on why this matters\n- Vague acceptance criteria (\"test it works\")\n- Mixes scope (mentions keyboard support \"later\")\n- Tasks instead of outcomes\n\n### Epic Example\n\nFor epics, provide higher-level context and link to sub-issues:\n\n```markdown\n## Context\n\nOur current authentication only supports email/password. Users have requested\nsocial login options, and analytics show 40% abandonment at signup. Social auth\nreduces friction and increases conversion.\n\n## Goal\n\nAdd Google and GitHub OAuth as login options alongside existing email/password.\n\n## Sub-Issues\n\n- #101 - Google OAuth integration\n- #102 - GitHub OAuth integration\n- #103 - Account linking (connect social to existing account)\n- #104 - Auth provider UI in login/signup forms\n\n## Acceptance Criteria\n\n- [ ] Users can sign up/login with Google\n- [ ] Users can sign up/login with GitHub\n- [ ] Existing users can link social accounts\n- [ ] Auth flow works on mobile browsers\n```\n\n## Advanced Patterns\n\n### Writing Specs to Files (Pre-Review Workflow)\n\nFor large projects, write specs to files for review before creating GitHub issues:\n\n**Directory structure:**\n\n```\n/tasks/specs/\n├── PATTERNS.md                    # Shared patterns for similar issues\n├── epic-name/\n│   ├── 01-first-issue.md\n│   ├── 02-second-issue.md\n│   └── 03-third-issue.md\n└── another-epic/\n    └── ...\n```\n\n**Benefits:**\n\n- Enables batch review before GitHub creation\n- Allows easy editing via pull request\n- Keeps related issues organized by epic\n\n### Shared Pattern Documents\n\nWhen writing specs for similar issues (e.g., CRUD endpoints, API resources), create a `PATTERNS.md` that defines:\n\n- Common URL structures\n- Standard request/response formats\n- Error handling patterns\n- Permission models\n\nIndividual specs then reference patterns: \"See PATTERNS.md for CRUD pattern.\"\n\n**Example reference in spec:**\n\n```markdown\n## Technical Notes\n\nSee PATTERNS.md for CRUD pattern.\n\n- Requires `create` permission in org\n- Generate slug from title (unique within parent)\n```\n\n### Acceptance Criteria Guidelines\n\n**DO include:**\n\n- [ ] Testable behavioral outcomes\n- [ ] API response formats and status codes\n- [ ] Permission/error handling requirements\n- [ ] OpenAPI schema requirements\n\n**DON''T include:**\n\n- [ ] \"Tests exist\" or \"Integration test written\" (testing is implicit)\n- [ ] Implementation steps disguised as criteria\n- [ ] Vague criteria like \"works correctly\"\n\nTesting is an implicit requirement for all issues. Don''t add acceptance criteria like \"unit tests written\" or \"e2e tests pass\" - that''s assumed.\n\n## References\n\n- **Issue Breakdown**: Use `zoonk-issue-planning` skill first to structure the breakdown\n- **GitHub API**: Use `zoonk-github-issues` skill to post issues with proper types/dependencies\n"},"lastSynced":"2026-03-06T06:31:55.142Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated user story generation from structured issue breakdowns","zh":"非常适合需要从结构化问题分解中自动生成用户故事的开发代理","ja":"構造化された問題の分解からの自動ユーザーストーリー生成を必要とする開発エージェントに最適","ko":"구조화된 문제 분해로부터 자동으로 사용자 스토리를 생성해야 하는 개발 에이전트에게 최적","es":"Perfecto para agentes de desarrollo que necesitan generación automática de historias de usuario a partir de desgloses de problemas estructurados","fr":"Parfait pour les agents de développement qui ont besoin de génération automatisée d''histoires utilisateur à partir de décompositions de problèmes structurées","de":"Perfekt für Entwicklungssagenten, die eine automatisierte Generierung von Benutzerstories aus strukturierten Problemaufschlüsselungen benötigen","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de geração automatizada de histórias de usuário a partir de quebras de problemas estruturadas","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированная генерация пользовательских историй из структурированного разбиения проблем","ar":"مثالي لعميل التطوير الذين يحتاجون إلى إنشاء قصة مستخدم آلي من تحليل المشكلة المنظم"},"recommendation":{"en":"Empowers agents to transform implementation plans into well-written user stories using Next.js, Postgres, and Prisma, providing engineers with context for implementation without dictating implementation details","zh":"使代理能够使用Next.js、Postgres和Prisma将实施计划转换为写得好的用户故事，为工程师提供上下文以进行实施，而不指定实施细节","ja":"エージェントがNext.js、Postgres、Prismaを使用して実装計画をきちんとしたユーザーストーリーに変換できるようにし、実装のコンテキストをエンジニアに提供するが、実装の詳細を指定しない","ko":"에이전트가 Next.js, Postgres 및 Prisma를 사용하여 구현 계획을 잘 작성된 사용자 스토리로 변환할 수 있도록 하여 엔지니어에게 구현에 대한 컨텍스트를 제공하지만 구현 세부 정보를 지정하지 않음","es":"Habilita a los agentes a transformar planes de implementación en historias de usuario bien escritas utilizando Next.js, Postgres y Prisma, proporcionando a los ingenieros un contexto para la implementación sin dictar detalles de implementación","fr":"Permet aux agents de transformer des plans d''implémentation en histoires utilisateur bien écrites en utilisant Next.js, Postgres et Prisma, fournissant aux ingénieurs un contexte pour la mise en œuvre sans dicter les détails de mise en œuvre","de":"Ermächtigt Agenten, Umsetzungspläne in gut geschriebene Benutzerstories mit Next.js, Postgres und Prisma zu verwandeln, und bietet Ingenieuren einen Kontext für die Umsetzung ohne Festlegung von Umsetzungsdetails","pt":"Habilita os agentes a transformar planos de implementação em histórias de usuário bem escritas usando Next.js, Postgres e Prisma, fornecendo aos engenheiros contexto para implementação sem ditar detalhes de implementação","ru":"Позволяет агентам превратить планы реализации в хорошо написанные пользовательские истории с использованием Next.js, Postgres и Prisma, предоставляя инженерам контекст для реализации без диктата деталей реализации","ar":"يسمح للوكلاء بتحويل خطط التنفيذ إلى قصص مستخدم مكتوبة جيدًا باستخدام Next.js و Postgres و Prisma، مما يوفر للمهندسين السياق لتطبيق التنفيذ دون ديكتاتة تفاصيل التنفيذ"},"useCases":{"en":["Automating user story creation from approved implementation plans","Generating detailed user stories for GitHub issues","Streamlining product owner tasks with st