INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vamseeachanta/workspace-hub/notion-api', 'notion-api', 'vamseeachanta', 'workspace-hub', 'community', 'notion-api vamseeachanta workspace-hub community The notion-api skill enables developers to automate Notion workspace tasks, including database entries and page creation, using the official REST API and Python SDK. Notion API 是一个强大的工具，用于自动化工作空间，包括数据库、页面、块等功能 Notion API はワークスペースの自動化を実現する強力なツールで、データベース、ページ、ブロックなどを含む Notion API는 작업공간을 자동화하는 강력한 도구로, 데이터베이스, 페이지, 블록 등을 포함 La API de Notion permite la automatización de espacios de trabajo, incluyendo bases de datos, páginas y bloques. Aprende a utilizarla para crear integraciones poderosas L''API Notion permet l''automatisation des espaces de travail, y compris les bases de données, les pages et les blocs. Apprenez à l''utiliser pour créer des intégrations puissantes Die Notion-API ermöglicht die Automatisierung von Arbeitsbereichen, einschließlich Datenbanken, Seiten und Blöcken. Erfahren Sie, wie Sie sie verwenden, um leistungsstarke Integrationen zu erstellen A Notion API permite a automação de workspace, incluindo bancos de dados, páginas, blocos e sintaxe de consulta/filtro Notion API позволяет автоматизировать рабочее пространство, включая базы данных, страницы, блоки и синтаксис запроса/фильтра تمكن Notion API من تأهيل مساحة العمل، بما في ذلك قواعد البيانات والصفحات والكتل وتركيبات استعلام/مرشح how to use notion-api notion-api setup guide notion-api alternative notion-api vs zapier notion-api install notion-api python sdk notion-api rest api notion-api integration patterns notion-api automation Notion API 工作空间自动化 数据库自动化 Notion 数据库 Python SDK REST API AIエージェント Notion 集成 Automates database entries and updates using the Notion REST API Builds custom dashboards from Notion data using query/filter syntax Syncs data between Notion and external systems using integration patterns Creates pages programmatically from templates using the Python SDK Supports modular organization for multiple GitHub repositories Utilizes the official Notion API for secure and reliable integrations notion-api is a centralized management system for automating Notion workspace tasks, including databases, pages, and blocks, using modular organization');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EtroxTaran/conductor/sync-rules', 'community', 'EtroxTaran', 'conductor', 'EtroxTaran/conductor', 'sync-rules', 0, 0, 67, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:21.753Z', '2ad48435c421c366355b99c3164dbcbaefa0fa8d8f3598d74b6c7a98899a22db', '{"id":"EtroxTaran/conductor/sync-rules","name":"sync-rules","description":{"en":"The sync-rules skill synchronizes shared rules from the central shared-rules/ directory to agent context files, including CLAUDE.md and project-level context files. This benefits AI agent developers by automating rule propagation.","zh":"Sync Rules 技术用于同步共享规则到 AI 工具的上下文文件中，包括 CLAUDE.md 和项目级别的上下文文件","ja":"Sync Rules は、AIエージェントの共有ルールを同期するために使用され、CLAUDE.md やプロジェクトレベルのコンテキストファイルが含まれる","ko":"Sync Rules 기술은 AI 에이전트의 공유 규칙을 동기화하여 CLAUDE.md와 프로젝트 수준의 컨텍스트 파일을 포함","es":"El skill de reglas de sincronización permite la propagación de reglas compartidas a archivos de contexto de agentes. Aprende a configurarlo con Python y CLI","fr":"Le skill de règles de synchronisation permet la propagation de règles partagées à des fichiers de contexte d''agents. Découvrez comment le configurer avec Python et CLI","de":"Das Synchronisationsregeln-Skill ermöglicht die Verbreitung von gemeinsamen Regeln an Kontextdateien von Agents. Erfahren Sie, wie Sie es mit Python und CLI einrichten","pt":"O sync-rules é uma habilidade que sincroniza regras compartilhadas de um diretório central para arquivos de contexto de agentes","ru":"Sync-rules - это навык, который синхронизирует общие правила из центрального каталога в файлы контекста агентов","ar":"Sync-Rules هو مهارة تزامن القواعد المشتركة من دليل مركزي إلى ملفات السياق للوكلاء"},"seo":{"title":{"en":"sync-rules: Automation Setup Guide for AI Agents","zh":"Sync Rules Setup Guide: AI工具同步共享规则","ja":"Sync Rules ベストプラクティス: AIエージェントの共有ルールを同期する","ko":"Sync Rules 구축 가이드: AI 에이전트 공유 규칙 동기화","es":"Configuración de Reglas de Sincronización para Agentes de IA","fr":"Guide d''Installation des Règles de Synchronisation pour O...","de":"Einrichtung von Synchronisationsregeln für KI-Agents","pt":"Guia de Configuração do Sync-Rules para Ferramentas de IA","ru":"Настройка Sync-Rules для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد Sync-Rules لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to synchronize shared rules with sync-rules. Learn how to automate rule propagation and streamline your AI agent workflow. Get started now!","zh":"了解如何使用 Sync Rules 技术将共享规则从 central 目录同步到 AI 工具的上下文文件中","ja":"AIエージェントの共有ルールを同期する方法を学ぶ: Sync Rules の使い方と設定","ko":"AI 에이전트의 공유 규칙을 중앙 디렉토리에서 동기화하는 방법: Sync Rules 사용법","es":"Aprende a configurar reglas de sincronización para agentes de IA con Python y CLI. Mejora la eficiencia de tus proyectos con nuestra guía paso a paso","fr":"Découvrez comment configurer des règles de synchronisation pour les outils d''IA avec Python et CLI. Améliorez l''efficacité de vos projets avec notre guide ét...","de":"Erfahren Sie, wie Sie Synchronisationsregeln für KI-Agents mit Python und CLI einrichten. Verbessern Sie die Effizienz Ihrer Projekte mit unserem Schritt-für...","pt":"Aprenda a configurar o sync-rules para ferramentas de IA e mantenha suas regras compartilhadas sincronizadas com facilidade","ru":"Узнайте, как настроить sync-rules для ИИ Агентов и поддерживать общие правила в синхронизации","ar":"تعرف على كيفية إعداد Sync-Rules لأدوات الذكاء الاصطناعي و الحفاظ على القواعد المشتركة بم 略容易"},"definition":{"en":"sync-rules is a skill that automates the synchronization of shared rules from a central directory to various agent context files, ensuring consistency and efficiency in AI agent development.","zh":"Sync Rules 是一种用于同步 AI 工具共享规则的技术","ja":"Sync Rules は、AIエージェントの共有ルールを同期するための技術である","ko":"Sync Rules 는 AI 에이전트의 공유 규칙을 동기화하기 위한 기술","es":"Reglas de sincronización para agentes de IA: un mecanismo para propagar reglas compartidas a archivos de contexto","fr":"Règles de synchronisation pour outils d''IA: un mécanisme pour propager des règles partagées à des fichiers de contexte","de":"Synchronisationsregeln für KI-Agents: ein Mechanismus zur Verbreitung von gemeinsamen Regeln an Kontextdateien","pt":"O que é sync-rules? É uma habilidade que propaga regras de um diretório central para arquivos de contexto de agentes","ru":"Что такое sync-rules? Это навык, который распространяет общие правила из центрального каталога в файлы контекста агентов","ar":"ما هو Sync-Rules؟ هو مهارة تنتشر القواعد المشتركة من دليل مركزي إلى ملفات السياق للوكلاء"},"features":{"en":["Propagates rules from the central shared-rules/ directory to CLAUDE.md","Supports project-level context files and agent-specific overrides","Utilizes a Python environment to run scripts/sync-rules.py","Reads shared rules from files such as core-rules.md and coding-standards.md","Automates rule synchronization using the /sync-rules command"],"zh":["支持Python环境","可以同步共享规则到CLAUDE.md文件","可以同步共享规则到项目级别的上下文文件","可以使用脚本scripts/sync-rules.py运行","支持多个共享规则文件，如core-rules.md和coding-standards.md"],"ja":["Python環境をサポート","CLAUDE.mdファイルに共有ルールを同期可能","プロジェクトレベルのコンテキストファイルに共有ルールを同期可能","scripts/sync-rules.pyスクリプトを使用して実行可能","複数の共有ルールファイルをサポート（例：core-rules.md、coding-standards.md）"],"ko":["Python 환경 지원","CLAUDE.md 파일에 공유 규칙 동기화","프로젝트 수준의 컨텍스트 파일에 공유 규칙 동기화","scripts/sync-rules.py 스크립트 사용","다중 공유 규칙 파일 지원 (예: core-rules.md, coding-standards.md)"],"es":["Propagación de reglas compartidas a archivos de contexto de agentes","Compatibilidad con Python y CLI","Integración con archivos de contexto de proyecto y sobrescritura de agentes","Lectura de reglas compartidas desde el directorio `shared-rules/`","Ejecución del script `scripts/sync-rules.py` para la sincronización"],"fr":["Propagation de règles partagées à des fichiers de contexte d''agents","Compatibilité avec Python et CLI","Intégration avec des fichiers de contexte de projet et surcharge d''agents","Lecture de règles partagées depuis le répertoire `shared-rules/`","Exécution du script `scripts/sync-rules.py` pour la synchronisation"],"de":["Verbreitung von gemeinsamen Regeln an Kontextdateien von Agents","Kompatibilität mit Python und CLI","Integration mit Kontextdateien von Projekten und Überschreibung von Agents","Lesevorgang von gemeinsamen Regeln aus dem Verzeichnis `shared-rules/`","Ausführung des Skripts `scripts/sync-rules.py` für die Synchronisation"],"pt":["Sincronização de regras compartilhadas com Python","Suporte a arquivos de contexto de agentes","Integração com diretório central de regras","Comando CLI para sincronização de regras","Suporte a regras de codificação e padrões de projeto"],"ru":["Синхронизация общих правил с помощью Python","Поддержка файлов контекста агентов","Интеграция с центральным каталогом правил","Команда CLI для синхронизации правил","Поддержка правил кодирования и стандартов проектирования"],"ar":["تنسيق القواعد المشتركة باستخدام Python","دعم ملفات السياق للوكلاء","التكامل مع الدليل المركزي للقواعد","أمر CLI لتنسيق القواعد","دعم قواعد الترميز و معايير التصميم"]},"keywords":{"en":["how to use sync-rules","sync-rules setup guide","sync-rules alternative","sync-rules vs manual rule propagation","sync-rules install","what is sync-rules","sync-rules automation","sync-rules for AI agents","sync-rules Python script"],"zh":["AI工具同步共享规则","Sync Rules技术","Python环境","CLAUDE.md","项目级别的上下文文件","共享规则同步","AI工具开发","Sync Rules设置"],"ja":["AIエージェントの共有ルールを同期","Sync Rules技術","Python環境","CLAUDE.md","プロジェクトレベルのコンテキストファイル","共有ルールの同期","AIエージェント開発","Sync Rulesの設定"],"ko":["AI 에이전트 공유 규칙 동기화","Sync Rules 기술","Python 환경","CLAUDE.md","프로젝트 수준의 컨텍스트 파일","공유 규칙 동기화","AI 에이전트 개발","Sync Rules 설정"],"es":["reglas de sincronización para agentes de IA","configuración de reglas de sincronización","Python para agentes de IA","CLI para agentes de IA","reglas compartidas para agentes de IA","sincronización de reglas para proyectos de IA"],"fr":["règles de synchronisation pour outils d''IA","configuration de règles de synchronisation","Python pour outils d''IA","CLI pour outils d''IA","règles partagées pour outils d''IA","synchronisation de règles pour projets d''IA"],"de":["Synchronisationsregeln für KI-Agents","Einrichtung von Synchronisationsregeln","Python für KI-Agents","CLI für KI-Agents","gemeinsame Regeln für KI-Agents","Synchronisation von Regeln für KI-Projekte"],"pt":["sync-rules","ferramentas de IA","regras compartilhadas","Python","arquivos de contexto de agentes","diretório central de regras","comando CLI","regras de codificação","padrões de projeto"],"ru":["sync-rules","ИИ Агенты","общие правила","Python","файлы контекста агентов","центральный каталог правил","команда CLI","правила кодирования","стандарты проектирования"],"ar":["Sync-Rules","أدوات الذكاء الاصطناعي","القواعد المشتركة","Python","ملفات السياق للوكلاء","الدليل المركزي للقواعد","أمر CLI","قواعد الترميز","معايير التصميم"]}},"owner":"EtroxTaran","repo":"conductor","repoPath":"EtroxTaran/conductor","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"sync-rules","description":"Synchronize shared rules into agent context files and headers.","version":"1.1.0","tags":["rules","governance","sync"],"bodyPreview":"# Sync Rules Skill\n\nSynchronize shared rules from `shared-rules/` to all agent context files.\n\n## Overview\n\nThis skill propagates rules from the central `shared-rules/` directory to:\n- `CLAUDE.md` (this file)\n- Project-level context files\n- Agent-specific overrides\n\n## Usage\n\n```\n/sync-rules\n```\n\n## Prerequisites\n\n- Python environment available to run `scripts/sync-rules.py`.\n\n## How It Works\n\n1. **Read shared rules**:\n   ```\n   shared-rules/\n   ├── core-rules.md\n   ├── coding-standards.md\n   ├─","body":"# Sync Rules Skill\n\nSynchronize shared rules from `shared-rules/` to all agent context files.\n\n## Overview\n\nThis skill propagates rules from the central `shared-rules/` directory to:\n- `CLAUDE.md` (this file)\n- Project-level context files\n- Agent-specific overrides\n\n## Usage\n\n```\n/sync-rules\n```\n\n## Prerequisites\n\n- Python environment available to run `scripts/sync-rules.py`.\n\n## How It Works\n\n1. **Read shared rules**:\n   ```\n   shared-rules/\n   ├── core-rules.md\n   ├── coding-standards.md\n   ├── guardrails.md\n   ├── cli-reference.md\n   ├── lessons-learned.md\n   └── agent-overrides/\n       └── claude.md\n   ```\n\n2. **Assemble CLAUDE.md**:\n   - Start with claude-specific header\n   - Append shared rules in order\n   - Add lessons learned at end\n\n3. **Update timestamp**:\n   ```markdown\n   <!-- AUTO-GENERATED from shared-rules/ -->\n   <!-- Last synced: 2026-01-22 12:00:00 -->\n   ```\n\n## Execution\n\n```bash\npython scripts/sync-rules.py\n```\n\nOr manually:\n1. Read all files from `shared-rules/`\n2. Concatenate in order\n3. Write to `CLAUDE.md`\n\n## File Order\n\n1. `agent-overrides/claude.md` - Claude-specific rules (header)\n2. `core-rules.md` - Core workflow rules\n3. `coding-standards.md` - Coding guidelines\n4. `guardrails.md` - Safety guardrails\n5. `cli-reference.md` - CLI tool reference\n6. `lessons-learned.md` - Lessons from past issues\n\n## Validation\n\nAfter sync, verify:\n- [ ] CLAUDE.md updated\n- [ ] Timestamp current\n- [ ] No merge conflicts\n- [ ] Rules are complete\n\n## Outputs\n\n- Updated `CLAUDE.md` and any derived context files.\n\n## Error Handling\n\n- If sync fails, stop and fix the script or inputs before continuing.\n- If timestamps are stale, rerun the sync to avoid mismatched rules.\n\n## Examples\n\n```\n/sync-rules\n```\n\n## Related Skills\n\n- `/add-lesson` - Add a lesson before syncing rules\n\n## When to Sync\n\nRun sync after:\n- Adding a new lesson learned\n- Updating shared rules\n- Before starting a new workflow\n- After pulling changes from git\n"},"lastSynced":"2026-03-08T02:01:21.753Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing automated rule propagation and synchronization across project context files.","zh":"非常适合需要自动规则传播和同步项目上下文文件的AI代理开发人员。","ja":"プロジェクトのコンテキストファイル全体で自動ルール伝播と同期が必要なAIエージェント開発者に最適です。","ko":"프로젝트 컨텍스트 파일 전체에서 자동 규칙 전파 및 동기화가 필요한 AI 에이전트 개발자에게 적합합니다.","es":"Perfecto para desarrolladores de agentes de inteligencia artificial que necesitan propagación y sincronización de reglas automatizadas en archivos de contexto de proyecto.","fr":"Parfait pour les développeurs d''agents d''intelligence artificielle ayant besoin d''une propagation et d''une synchronisation de règles automatisées dans les fichiers de contexte de projet.","de":"Perfekt für Entwickler von KI-Agenten, die eine automatisierte Regel-Verbreitung und -Synchronisierung in Projekt-Kontext-Dateien benötigen.","pt":"Perfeito para desenvolvedores de Agentes de IA que precisam de propagação e sincronização automatizadas de regras em arquivos de contexto de projeto.","ru":"Идеально для разработчиков агентов ИИ, которым необходима автоматизированная пропагация и синхронизация правил в файлах контекста проекта.","ar":"مثالي للمطورين وكلاء الذكاء الاصطناعي الذين يحتاجون إلى نشر وتزامن قواعد تلقائي عبر ملفات سياق المشروع."},"recommendation":{"en":"Empowers agents to synchronize shared rules from the central shared-rules/ directory to agent context files, including CLAUDE.md and project-level context files, using Python scripts like sync-rules.py.","zh":"使代理能够使用Python脚本（如sync-rules.py）从central shared-rules/目录同步共享规则到代理上下文文件，包括CLAUDE.md和项目级上下文文件。","ja":"Pythonスクリプト（例：sync-rules.py）を使用して、エージェントが中央のshared-rules/ディレクトリから共有ルールをエージェントのコンテキストファイル（CLAUDE.mdやプロジェクトレベルのコンテキストファイルなど）に同期できるようにします。","ko":"Python 스크립트(예: sync-rules.py)를 사용하여 에이전트가 중앙 shared-rules/ 디렉토리에서 공유 규칙을 에이전트 컨텍스트 파일(CLAUDE.md 및 프로젝트 수준 컨텍스트 파일 포함)로 동기화 할 수 있도록 합니다.","es":"Habilita a los agentes a sincronizar reglas compartidas desde el directorio central shared-rules/ hasta los archivos de contexto de los agentes, incluyendo CLAUDE.md y archivos de contexto a nivel de proyecto, utilizando scripts de Python como sync-rules.py.","fr":"Permet aux agents de synchroniser des règles partagées à partir du répertoire central shared-rules/ jusqu''aux fichiers de contexte des agents, y compris CLAUDE.md et les fichiers de contexte au niveau du projet, en utilisant des scripts Python tels que sync-rules.py.","de":"Ermöglicht es Agenten, gemeinsame Regeln aus dem zentralen Verzeichnis shared-rules/ mit den Kontextdateien der Agenten zu synchronisieren, einschließlich CLAUDE.md und Projektniveau-Kontextdateien, unter Verwendung von Python-Skripten wie sync-rules.py.","pt":"Permite que os agentes sincronizem regras compartilhadas do diretório central compartilhado-regras/ para arquivos de contexto de agente, incluindo CLAUDE.md e arquivos de contexto de nível de projeto, usando scripts Python como sync-rules.py.","ru":"Позволяет агентам синхронизировать общие правила из центрального каталога shared-rules/ в файлы контекста агента, включая CLAUDE.md и файлы контекста уровня проекта, используя скрипты Python, такие как sync-rules.py.","ar":"يمكن للوكلاء من خلاله مزامنة القواعد المشتركة من الدليل المركزي shared-rules/ إلى ملفات سياق الوكيل ، بما في ذلك CLAUDE.md وملفات السياق على مستوى المشروع ، باستخدام سكريبتات Python مثل sync-rules.py."},"useCases":{"en":["Automating rule updates in CLAUDE.md","Synchronizing project-level context files with shared rules","Propagating core rules and coding standards to agent-specific overrides"],"zh":["自动更新CLAUDE.md中的规则","同步项目级上下文文件与共享规则","将核心规则和编码标准传播到代理特定覆盖"],"ja":["CLAUDE.md内のルールの自動更新","プロジェクトレベルのコンテキストファイルと共有ルールの同期","コアルールとコーディング規約をエージェント特有のオーバーライドに伝播"],"ko":["CLAUDE.md의 규칙 자동 업데이트","프로젝트 수준 컨텍스트 파일과 공유 규칙의 동기화","코어 규칙과 코딩 표준을 에이전트 특정 오버라이드에 전파"],"es":["Automatizar actualizaciones de reglas en CLAUDE.md","Sincronizar archivos de contexto a nivel de proyecto con reglas compartidas","Propagar reglas básicas y estándares de codificación a anulaciones específicas de agentes"],"fr":["Automatiser les mises à jour des règles dans CLAUDE.md","Synchroniser les fichiers de contexte au niveau du projet avec les règles partagées","Propager les règles de base et les normes de codage aux annulations spécifiques à l''agent"],"de":["Automatisieren von Regel-Aktualisierungen in CLAUDE.md","Synchronisieren von Projektniveau-Kontextdateien mit gemeinsamen Regeln","Verbreiten von Kernregeln und Codierungsstandards auf Agent-spezifische Überschreibungen"],"pt":["Automatizar atualizações de regras em CLAUDE.md","Sincronizar arquivos de contexto de nível de projeto com regras compartilhadas","Propagar regras centrais e normas de codificação para substituições específicas de agente"],"ru":["Автоматизировать обновления правил в CLAUDE.md","Синхронизировать файлы контекста уровня проекта с общими правилами","Пропагировать основные правила и стандарты кодирования в конкретные переопределения агента"],"ar":["توفير تحديثات قواعد تلقائية في CLAUDE.md","مزامنة ملفات السياق على مستوى المشروع مع القواعد المشتركة","نشر القواعد الأساسية ومعايير البرمجة إلى الإضافات المحددة للوكيل"]},"limitations":{"en":["Requires Python environment to run scripts/sync-rules.py","Limited to synchronizing rules from the shared-rules/ directory"],"zh":["需要Python环境来运行脚本/sync-rules.py","仅限从shared-rules/目录同步规则"],"ja":["スクリプト/sync-rules.pyを実行するためにPython環境が必要","shared-rules/ディレクトリからのルール同期のみ"],"ko":["스크립트/sync-rules.py를 실행하기 위해 Python 환경이 필요","shared-rules/ 디렉토리からの 규칙 동기화만"],"es":["Requiere un entorno de Python para ejecutar scripts/sync-rules.py","Limitado a la sincronización de reglas desde el directorio shared-rules/"],"fr":["Nécessite un environnement Python pour exécuter les scripts/sync-rules.py","Limité à la synchronisation des règles à partir du répertoire shared-rules/"],"de":["Benötigt eine Python-Umgebung, um Skripte/sync-rules.py auszuführen","Begrenzt auf die Synchronisierung von Regeln aus dem Verzeichnis shared-rules/"],"pt":["Exige ambiente Python para executar scripts/sync-rules.py","Limitado à sincronização de regras do diretório shared-rules/"],"ru":["Требует среды Python для запуска скриптов/sync-rules.py","Ограничен синхронизацией правил из каталога shared-rules/"],"ar":["يتطلب بيئة Python لتشغيل سكريبتات/sync-rules.py","محدود بمزامنة القواعد من الدليل shared-rules/"]},"version":4},"contentHash":"2ad48435c421c366355b99c3164dbcbaefa0fa8d8f3598d74b6c7a98899a22db","qualityScore":67}');
