INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EtroxTaran/conductor/sync-rules', 'sync-rules', 'EtroxTaran', 'conductor', 'community', 'sync-rules EtroxTaran conductor community The sync-rules skill synchronizes shared rules from the central shared-rules/ directory to agent context files, including CLAUDE.md and project-level context files. This benefits AI agent developers by automating rule propagation. Sync Rules 技术用于同步共享规则到 AI 工具的上下文文件中，包括 CLAUDE.md 和项目级别的上下文文件 Sync Rules は、AIエージェントの共有ルールを同期するために使用され、CLAUDE.md やプロジェクトレベルのコンテキストファイルが含まれる Sync Rules 기술은 AI 에이전트의 공유 규칙을 동기화하여 CLAUDE.md와 프로젝트 수준의 컨텍스트 파일을 포함 El skill de reglas de sincronización permite la propagación de reglas compartidas a archivos de contexto de agentes. Aprende a configurarlo con Python y CLI Le skill de règles de synchronisation permet la propagation de règles partagées à des fichiers de contexte d''agents. Découvrez comment le configurer avec Python et CLI Das Synchronisationsregeln-Skill ermöglicht die Verbreitung von gemeinsamen Regeln an Kontextdateien von Agents. Erfahren Sie, wie Sie es mit Python und CLI einrichten O sync-rules é uma habilidade que sincroniza regras compartilhadas de um diretório central para arquivos de contexto de agentes Sync-rules - это навык, который синхронизирует общие правила из центрального каталога в файлы контекста агентов Sync-Rules هو مهارة تزامن القواعد المشتركة من دليل مركزي إلى ملفات السياق للوكلاء how to use sync-rules sync-rules setup guide sync-rules alternative sync-rules vs manual rule propagation sync-rules install what is sync-rules sync-rules automation sync-rules for AI agents sync-rules Python script AI工具同步共享规则 Sync Rules技术 Python环境 CLAUDE.md 项目级别的上下文文件 共享规则同步 AI工具开发 Sync Rules设置 Propagates rules from the central shared-rules/ directory to CLAUDE.md Supports project-level context files and agent-specific overrides Utilizes a Python environment to run scripts/sync-rules.py Reads shared rules from files such as core-rules.md and coding-standards.md Automates rule synchronization using the /sync-rules command sync-rules is a skill that automates the synchronization of shared rules from a central directory to various agent context files, ensuring consistency and efficiency in AI agent development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mauricioacp/tanstack-convex-better-auth-template/convex-security-audit', 'community', 'mauricioacp', 'tanstack-convex-better-auth-template', 'mauricioacp/tanstack-convex-better-auth-template', 'convex-security-audit', 0, 0, 67, '2026-03-08T01:57:15.454Z', '2026-03-08T02:09:03.820Z', 'bc61c9c16494052941c671f5605bc5d964d88e219ec096ad7ca0931d5e2f39d2', '{"id":"mauricioacp/tanstack-convex-better-auth-template/convex-security-audit","name":"convex-security-audit","description":{"en":"Convex Security Audit provides a comprehensive security review for Convex applications, benefiting developers by ensuring authorization logic, data access boundaries, and action isolation. This skill enhances Convex application security.","zh":"Convex安全审计技能为开发者提供全面的Convex应用安全审查模式，包括授权逻辑验证、数据访问边界控制和敏感操作保护。基于最新Convex官方文档，确保生产环境安全部署。","ja":"Convexセキュリティ監査AIエージェントは、認証ロジックの検証、データアクセス境界の制御、アクション分離を含むConvexアプリケーションの包括的なセキュリティレビューを提供します。","ko":"Convex 보안 감독 스킬은 권한 부여 논리 검증, 데이터 액세스 경계 제어, 작업 격리를 포함한 Convex 애플리케이션의 포괄적인 보안 검토를 제공합니다.","es":"Este agente de IA proporciona patrones de revisión de seguridad para aplicaciones Convex, incluyendo lógica de autorización, límites de acceso a datos, aislamiento de acciones y protección de operaciones sensibles basado en la documentación oficial.","fr":"Cet outil IA fournit des modèles de revue de sécurité pour applications Convex, incluant la logique d''autorisation, les limites d''accès aux données, l''isolation des actions et la protection des opérations sensibles selon la documentation officielle.","de":"Dieses KI-Tool bietet Sicherheitsüberprüfungsmuster für Convex-Anwendungen, einschließlich Autorisierungslogik, Datenzugriffsgrenzen, Aktionsisolierung und dem Schutz sensibler Operationen basierend auf der offiziellen Dokumentation.","pt":"O Convex Security Audit é uma ferramenta de revisão de segurança abrangente para aplicações Convex, incluindo lógica de autorização e isolamento de ações","ru":"Convex Security Audit - это комплексный инструмент проверки безопасности для приложений Convex, включающий логику авторизации и изоляцию действий","ar":"Convex Security Audit هو أداة مراجعة أمان شاملة للتطبيقات Convex، تشمل منطق التفويض وفصل الإجراءات"},"seo":{"title":{"en":"Convex Security Audit: Comprehensive Setup Guide | AI Age...","zh":"Convex安全审计设置指南：授权逻辑与数据访问边界","ja":"Convexセキュリティ監査のベストプラクティス：認証ロジックとAIエージェント","ko":"Convex 보안 감독 설정 가이드: 권한 로직 및 데이터 액세스 경계","es":"Convex Security Audit: Guía de mejores prácticas para des...","fr":"Convex Security Audit: Guide des meilleures pratiques pou...","de":"Convex Security Audit: Best Practices Leitfaden für Entwi...","pt":"Guia de Configuração do Convex Security Audit para Desenv...","ru":"Настройка ИИ Агента Convex Security Audit: Руководство","ar":"إعداد وتشغيل Convex Security Audit لتحسين الأمان"},"description":{"en":"Boost security for Convex applications with our expert audit guide. Learn how to implement authorization logic, data access boundaries, and more. Get started...","zh":"Convex安全审计技能提供全面的安全审查模式，包括授权逻辑验证、数据访问边界控制、操作隔离和速率限制。专为Convex应用开发者设计，确保生产环境安全。","ja":"Convexセキュリティ監査AIエージェントは、認証ロジック、データアクセス境界、アクション分離、レート制限を含む包括的なセキュリティレビューパターンを提供。","ko":"Convex 보안 감독 스킬은 권한 부여 논리, 데이터 액세스 경계, 작업 격리, 속도 제한을 포함한 포괄적인 보안 검토 패턴을 제공합니다.","es":"Auditoría de seguridad completa para aplicaciones Convex. Implementa autorización, límites de acceso a datos, aislamiento de acciones y rate limiting siguien...","fr":"Audit de sécurité complet pour applications Convex. Implémentez l''autorisation, les limites d''accès aux données, l''isolation des actions et le rate limiting ...","de":"Umfassende Sicherheitsprüfung für Convex-Anwendungen. Implementieren Sie Autorisierung, Datenzugriffsgrenzen, Aktionsisolierung und Ratenbegrenzung gemäß der...","pt":"Aprenda a configurar o Convex Security Audit para proteger suas aplicações com autenticação, autorização e isolamento de ações","ru":"Узнайте, как настроить Convex Security Audit для защиты ваших приложений с помощью аутентификации, авторизации и изоляции действий","ar":"اكتشف كيفية إعداد Convex Security Audit لحماية تطبيقاتك باستخدام التحقق والتفويض وفصل الإجراءات"},"definition":{"en":"Convex-security-audit is a comprehensive security review pattern for Convex applications, covering authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations.","zh":"Convex安全审计是一项专门针对Convex应用程序的安全审查技能，提供授权逻辑验证、数据访问边界控制、操作隔离和速率限制等安全模式，基于Convex官方文档确保应用安全性。","ja":"Convexセキュリティ監査は、Convexアプリケーション向けのセキュリティレビューAIエージェントで、認証ロジック検証、データアクセス境界制御、アクション分離などのセキュリティパターンを提供します。","ko":"Convex 보안 감독은 Convex 애플리케이션을 위한 보안 검토 스킬로, 권한 부여 논리 검증, 데이터 액세스 경계 제어, 작업 격리 등의 보안 패턴을 제공합니다.","es":"Convex Security Audit es un agente de IA que proporciona patrones completos de revisión de seguridad para aplicaciones Convex, incluyendo autorización, límites de acceso a datos, aislamiento de acciones y rate limiting basados en la documentación oficial de Convex.","fr":"Convex Security Audit est un outil IA qui fournit des modèles complets de revue de sécurité pour applications Convex, incluant l''autorisation, les limites d''accès aux données, l''isolation des actions et le rate limiting basés sur la documentation officielle de Convex.","de":"Convex Security Audit ist ein KI-Tool, das umfassende Sicherheitsüberprüfungsmuster für Convex-Anwendungen bereitstellt, einschließlich Autorisierung, Datenzugriffsgrenzen, Aktionsisolierung und Ratenbegrenzung basierend auf der offiziellen Convex-Dokumentation.","pt":"O que é Convex Security Audit? É uma ferramenta de revisão de segurança para aplicações Convex","ru":"Что такое Convex Security Audit? Это инструмент проверки безопасности для приложений Convex","ar":"ما هو Convex Security Audit؟ إنه أداة مراجعة أمان للتطبيقات Convex"},"features":{"en":["Comprehensive security review patterns for Convex applications","Implementation of authorization logic using Convex functions auth","Enforcement of data access boundaries and action isolation","Rate limiting and protection of sensitive operations","Integration with Convex production security guidelines","Reference to official Convex documentation for latest updates"],"zh":["授权逻辑验证基于docs.convex.dev/auth/functions-auth","数据访问边界控制确保数据隔离","操作隔离保护敏感功能","速率限制防止滥用","生产环境安全部署指南","基于最新Convex官方文档实现"],"ja":["docs.convex.dev/auth/functions-authに基づく認証ロジック検証","データアクセス境界制御による分離確保","機密操作保護のためのアクション分離","悪用防止のためのレート制限","本番環境セキュリティガイドライン","最新Convex公式ドキュメント準拠"],"ko":["docs.convex.dev/auth/functions-auth 기반 권한 부여 논리 검증","데이터 액세스 경계 제어를 통한 격리 보장","민감한 작업 보호를 위한 작업 격리","악용 방지를 위한 속도 제한","프로덕션 환경 보안 가이드라인","최신 Convex 공식 문서 준수"],"es":["Revisión de lógica de autorización para funciones Convex","Definición de límites de acceso a datos en aplicaciones","Aislamiento de acciones para prevenir vulnerabilidades","Implementación de rate limiting basado en documentación oficial","Protección de operaciones sensibles en producción","Integración con documentación oficial de Convex (docs.convex.dev)"],"fr":["Revue de logique d''autorisation pour fonctions Convex","Définition de limites d''accès aux données dans les applications","Isolation d''actions pour prévenir les vulnérabilités","Implémentation de rate limiting basé sur la documentation officielle","Protection d''opérations sensibles en production","Intégration avec la documentation officielle de Convex (docs.convex.dev)"],"de":["Überprüfung der Autorisierungslogik für Convex-Funktionen","Definition von Datenzugriffsgrenzen in Anwendungen","Isolierung von Aktionen zur Vermeidung von Sicherheitslücken","Implementierung von Ratenbegrenzung basierend auf offizieller Dokumentation","Schutz sensibler Operationen in der Produktion","Integration mit offizieller Convex-Dokumentation (docs.convex.dev)"],"pt":["Autenticação e autorização de funções","Isolamento de ações e limitação de taxas","Proteção de operações sensíveis","Revisão de segurança abrangente para aplicações Convex","Integração com a documentação oficial do Convex"],"ru":["Аутентификация и авторизация функций","Изоляция действий и ограничение скорости","Защита чувствительных операций","Комплексная проверка безопасности для приложений Convex","Интеграция с официальной документацией Convex"],"ar":["التحقق والتفويض للوظائف","فصل الإجراءات وضبط سرعة التنفيذ","حماية العمليات الحساسة","مراجعة أمان شاملة للتطبيقات Convex","التكامل مع الوثائق الرسمية لبرنامج Convex"]},"keywords":{"en":["convex security audit setup guide","how to use convex security audit","convex security audit vs competitor","what is convex security audit","convex security audit install","convex security audit alternative","convex application security best practices","authorization logic in convex","data access boundaries in convex","convex production security guidelines"],"zh":["Convex安全审计","Convex授权逻辑","数据访问边界","Convex操作隔离","Convex速率限制","Convex生产安全","Convex函数认证","Convex安全最佳实践"],"ja":["Convexセキュリティ監査","Convex認証ロジック","データアクセス境界","Convexアクション分離","Convexレート制限","Convex本番セキュリティ","Convex関数認証","ConvexセキュリティAIエージェント"],"ko":["Convex 보안 감독","Convex 권한 부여 논리","데이터 액세스 경계","Convex 작업 격리","Convex 속도 제한","Convex 프로덕션 보안","Convex 함수 인증","Convex 보안 최적实践"],"es":["convex security audit","autorización convex","límites acceso datos convex","rate limiting convex","auditoría seguridad aplicaciones convex","protección operaciones sensibles convex","convex production security","agente IA desarrollo convex"],"fr":["audit sécurité convex","autorisation convex","limites accès données convex","rate limiting convex","sécurité production convex","protection opérations sensibles convex","outil IA développement convex","audit applications convex"],"de":["convex security audit","convex autorisierung","datenzugriffsgrenzen convex","ratenbegrenzung convex","produktionssicherheit convex","schutz sensibler operationen convex","convex sicherheitsüberprüfung","ki-tool convex entwicklung"],"pt":["Convex Security Audit","segurança de aplicações","autenticação e autorização","isolamento de ações","limitação de taxas","proteção de operações sensíveis","desenvolvimento de aplicações Convex"],"ru":["Convex Security Audit","безопасность приложений","аутентификация и авторизация","изоляция действий","ограничение скорости","защита чувствительных операций","разработка приложений Convex"],"ar":["Convex Security Audit","أمان التطبيقات","التحقق والتفويض","فصل الإجراءات","ضبط سرعة التنفيذ","حماية العمليات الحساسة","تطوير تطبيقات Convex"]}},"owner":"mauricioacp","repo":"tanstack-convex-better-auth-template","repoPath":"mauricioacp/tanstack-convex-better-auth-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.454Z","topics":[],"category":"community","skillMd":{"name":"convex-security-audit","description":"Deep security review patterns for authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations","version":"1.0.0","tags":["convex","security","audit","authorization","rate-limiting","protection"],"bodyPreview":"# Convex Security Audit\n\nComprehensive security review patterns for Convex applications including authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/auth/functions-auth\n- Production Security: https://docs.convex.dev/production\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n###","body":"# Convex Security Audit\n\nComprehensive security review patterns for Convex applications including authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/auth/functions-auth\n- Production Security: https://docs.convex.dev/production\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n### Security Audit Areas\n\n1. **Authorization Logic** - Who can do what\n2. **Data Access Boundaries** - What data users can see\n3. **Action Isolation** - Protecting external API calls\n4. **Rate Limiting** - Preventing abuse\n5. **Sensitive Operations** - Protecting critical functions\n\n### Authorization Logic Audit\n\n#### Role-Based Access Control (RBAC)\n\n```typescript\n// convex/lib/auth.ts\nimport { QueryCtx, MutationCtx } from \"./_generated/server\";\nimport { ConvexError } from \"convex/values\";\nimport { Doc } from \"./_generated/dataModel\";\n\ntype UserRole = \"user\" | \"moderator\" | \"admin\" | \"superadmin\";\n\nconst roleHierarchy: Record<UserRole, number> = {\n  user: 0,\n  moderator: 1,\n  admin: 2,\n  superadmin: 3,\n};\n\nexport async function getUser(ctx: QueryCtx | MutationCtx): Promise<Doc<\"users\"> | null> {\n  const identity = await ctx.auth.getUserIdentity();\n  if (!identity) return null;\n\n  return await ctx.db\n    .query(\"users\")\n    .withIndex(\"by_tokenIdentifier\", (q) => q.eq(\"tokenIdentifier\", identity.tokenIdentifier))\n    .unique();\n}\n\nexport async function requireRole(\n  ctx: QueryCtx | MutationCtx,\n  minRole: UserRole,\n): Promise<Doc<\"users\">> {\n  const user = await getUser(ctx);\n\n  if (!user) {\n    throw new ConvexError({\n      code: \"UNAUTHENTICATED\",\n      message: \"Authentication required\",\n    });\n  }\n\n  const userRoleLevel = roleHierarchy[user.role as UserRole] ?? 0;\n  const requiredLevel = roleHierarchy[minRole];\n\n  if (userRoleLevel < requiredLevel) {\n    throw new ConvexError({\n      code: \"FORBIDDEN\",\n      message: `Role ''${minRole}'' or higher required`,\n    });\n  }\n\n  return user;\n}\n\n// Permission-based check\ntype Permission = \"read:users\" | \"write:users\" | \"delete:users\" | \"admin:system\";\n\nconst rolePermissions: Record<UserRole, Permission[]> = {\n  user: [\"read:users\"],\n  moderator: [\"read:users\", \"write:users\"],\n  admin: [\"read:users\", \"write:users\", \"delete:users\"],\n  superadmin: [\"read:users\", \"write:users\", \"delete:users\", \"admin:system\"],\n};\n\nexport async function requirePermission(\n  ctx: QueryCtx | MutationCtx,\n  permission: Permission,\n): Promise<Doc<\"users\">> {\n  const user = await getUser(ctx);\n\n  if (!user) {\n    throw new ConvexError({ code: \"UNAUTHENTICATED\", message: \"Authentication required\" });\n  }\n\n  const userRole = user.role as UserRole;\n  const permissions = rolePermissions[userRole] ?? [];\n\n  if (!permissions.includes(permission)) {\n    throw new ConvexError({\n      code: \"FORBIDDEN\",\n      message: `Permission ''${permission}'' required`,\n    });\n  }\n\n  return user;\n}\n```\n\n### Data Access Boundaries Audit\n\n```typescript\n// convex/data.ts\nimport { query, mutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { getUser, requireRole } from \"./lib/auth\";\nimport { ConvexError } from \"convex/values\";\n\n// Audit: Users can only see their own data\nexport const getMyData = query({\n  args: {},\n  returns: v.array(\n    v.object({\n      _id: v.id(\"userData\"),\n      content: v.string(),\n    }),\n  ),\n  handler: async (ctx) => {\n    const user = await getUser(ctx);\n    if (!user) return [];\n\n    // SECURITY: Filter by userId\n    return await ctx.db\n      .query(\"userData\")\n      .withIndex(\"by_user\", (q) => q.eq(\"userId\", user._id))\n      .collect();\n  },\n});\n\n// Audit: Verify ownership before returning sensitive data\nexport const getSensitiveItem = query({\n  args: { itemId: v.id(\"sensitiveItems\") },\n  returns: v.union(\n    v.object({\n      _id: v.id(\"sensitiveItems\"),\n      secret: v.string(),\n    }),\n    v.null(),\n  ),\n  handler: async (ctx, args) => {\n    const user = await getUser(ctx);\n    if (!user) return null;\n\n    const item = await ctx.db.get(args.itemId);\n\n    // SECURITY: Verify ownership\n    if (!item || item.ownerId !== user._id) {\n      return null; // Don''t reveal if item exists\n    }\n\n    return item;\n  },\n});\n\n// Audit: Shared resources with access list\nexport const getSharedDocument = query({\n  args: { docId: v.id(\"documents\") },\n  returns: v.union(\n    v.object({\n      _id: v.id(\"documents\"),\n      content: v.string(),\n      accessLevel: v.string(),\n    }),\n    v.null(),\n  ),\n  handler: async (ctx, args) => {\n    const user = await getUser(ctx);\n    const doc = await ctx.db.get(args.docId);\n\n    if (!doc) return null;\n\n    // Public documents\n    if (doc.visibility === \"public\") {\n      return { ...doc, accessLevel: \"public\" };\n    }\n\n    // Must be authenticated for non-public\n    if (!user) return null;\n\n    // Owner has full access\n    if (doc.ownerId === user._id) {\n      return { ...doc, accessLevel: \"owner\" };\n    }\n\n    // Check shared access\n    const access = await ctx.db\n      .query(\"documentAccess\")\n      .withIndex(\"by_doc_and_user\", (q) => q.eq(\"documentId\", args.docId).eq(\"userId\", user._id))\n      .unique();\n\n    if (!access) return null;\n\n    return { ...doc, accessLevel: access.level };\n  },\n});\n```\n\n### Action Isolation Audit\n\n```typescript\n// convex/actions.ts\n\"use node\";\n\nimport { action, internalAction } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { api, internal } from \"./_generated/api\";\nimport { ConvexError } from \"convex/values\";\n\n// SECURITY: Never expose API keys in responses\nexport const callExternalAPI = action({\n  args: { query: v.string() },\n  returns: v.object({ result: v.string() }),\n  handler: async (ctx, args) => {\n    // Verify user is authenticated\n    const identity = await ctx.auth.getUserIdentity();\n    if (!identity) {\n      throw new ConvexError(\"Authentication required\");\n    }\n\n    // Get API key from environment (not hardcoded)\n    const apiKey = process.env.EXTERNAL_API_KEY;\n    if (!apiKey) {\n      throw new Error(\"API key not configured\");\n    }\n\n    // Log usage for audit trail\n    await ctx.runMutation(internal.audit.logAPICall, {\n      userId: identity.tokenIdentifier,\n      endpoint: \"external-api\",\n      timestamp: Date.now(),\n    });\n\n    const response = await fetch(\"https://api.example.com/query\", {\n      method: \"POST\",\n      headers: {\n        Authorization: `Bearer ${apiKey}`,\n        \"Content-Type\": \"application/json\",\n      },\n      body: JSON.stringify({ query: args.query }),\n    });\n\n    if (!response.ok) {\n      // Don''t expose external API error details\n      throw new ConvexError(\"External service unavailable\");\n    }\n\n    const data = await response.json();\n\n    // Sanitize response before returning\n    return { result: sanitizeResponse(data) };\n  },\n});\n\n// Internal action - not exposed to clients\nexport const _processPayment = internalAction({\n  args: {\n    userId: v.id(\"users\"),\n    amount: v.number(),\n    paymentMethodId: v.string(),\n  },\n  returns: v.object({ success: v.boolean(), transactionId: v.optional(v.string()) }),\n  handler: async (ctx, args) => {\n    const stripeKey = process.env.STRIPE_SECRET_KEY;\n\n    // Process payment with Stripe\n    // This should NEVER be exposed as a public action\n\n    return { success: true, transactionId: \"txn_xxx\" };\n  },\n});\n```\n\n### Rate Limiting Audit\n\n```typescript\n// convex/rateLimit.ts\nimport { mutation, query } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { ConvexError } from \"convex/values\";\n\nconst RATE_LIMITS = {\n  message: { requests: 10, windowMs: 60000 }, // 10 per minute\n  upload: { requests: 5, windowMs: 300000 }, // 5 per 5 minutes\n  api: { requests: 100, windowMs: 3600000 }, // 100 per hour\n};\n\nexport const checkRateLimit = mutation({\n  args: {\n    userId: v.string(),\n    action: v.union(v.literal(\"message\"), v.literal(\"upload\"), v.literal(\"api\")),\n  },\n  returns: v.object({ allowed: v.boolean(), retryAfter: v.optional(v.number()) }),\n  handler: async (ctx, args) => {\n    const limit = RATE_LIMITS[args.action];\n    const now = Date.now();\n    const windowStart = now - limit.windowMs;\n\n    // Count requests in window\n    const requests = await ctx.db\n      .query(\"rateLimits\")\n      .withIndex(\"by_user_and_action\", (q) => q.eq(\"userId\", args.userId).eq(\"action\", args.action))\n      .filter((q) => q.gt(q.field(\"timestamp\"), windowStart))\n      .collect();\n\n    if (requests.length >= limit.requests) {\n      const oldestRequest = requests[0];\n      const retryAfter = oldestRequest.timestamp + limit.windowMs - now;\n\n      return { allowed: false, retryAfter };\n    }\n\n    // Record this request\n    await ctx.db.insert(\"rateLimits\", {\n      userId: args.userId,\n      action: args.action,\n      timestamp: now,\n    });\n\n    return { allowed: true };\n  },\n});\n\n// Use in mutations\nexport const sendMessage = mutation({\n  args: { content: v.string() },\n  returns: v.id(\"messages\"),\n  handler: async (ctx, args) => {\n    const identity = await ctx.auth.getUserIdentity();\n    if (!identity) throw new ConvexError(\"Authentication required\");\n\n    // Check rate limit\n    const rateCheck = await checkRateLimit(ctx, {\n      userId: identity.tokenIdentifier,\n      action: \"message\",\n    });\n\n    if (!rateCheck.allowed) {\n      throw new ConvexError({\n        code: \"RATE_LIMITED\",\n        message: `Too many requests. Try again in ${Math.ceil(rateCheck.retryAfter! / 1000)} seconds`,\n      });\n    }\n\n    return await ctx.db.insert(\"messages\", {\n      content: args.content,\n      authorId: identity.tokenIdentifier,\n      createdAt: Date.now(),\n    });\n  },\n});\n```\n\n### Sensitive Operations Protection\n\n```typescript\n// convex/admin.ts\nimport { mutation, internalMutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { requireRole, requirePermission } from \"./lib/auth\";\nimport { internal } from \"./_generated/api\";\n\n// Two-factor confirmation for dangerous operations\nexport const deleteAllUserData = mutation({\n  args: {\n    userId: v.id(\"users\"),\n    confirmationCode: v.string(),\n  },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    // Require superadmin\n    const admin = await requireRole(ctx, \"superadmin\");\n\n    // Verify confirmation code\n    const confirmation = await ctx.db\n      .query(\"confirmations\")\n      .withIndex(\"by_admin_and_code\", (q) =>\n        q.eq(\"adminId\", admin._id).eq(\"code\", args.confirmationCode),\n      )\n      .filter((q) => q.gt(q.field(\"expiresAt\"), Date.now()))\n      .unique();\n\n    if (!confirmation || confirmation.action !== \"delete_user_data\") {\n      throw new ConvexError(\"Invalid or expired confirmation code\");\n    }\n\n    // Delete confirmation to prevent reuse\n    await ctx.db.delete(confirmation._id);\n\n    // Schedule deletion (don''t do it inline)\n    await ctx.scheduler.runAfter(0, internal.admin._performDeletion, {\n      userId: args.userId,\n      requestedBy: admin._id,\n    });\n\n    // Audit log\n    await ctx.db.insert(\"auditLogs\", {\n      action: \"delete_user_data\",\n      targetUserId: args.userId,\n      performedBy: admin._id,\n      timestamp: Date.now(),\n    });\n\n    return null;\n  },\n});\n\n// Generate confirmation code for sensitive action\nexport const requestDeletionConfirmation = mutation({\n  args: { userId: v.id(\"users\") },\n  returns: v.string(),\n  handler: async (ctx, args) => {\n    const admin = await requireRole(ctx, \"superadmin\");\n\n    const code = generateSecureCode();\n\n    await ctx.db.insert(\"confirmations\", {\n      adminId: admin._id,\n      code,\n      action: \"delete_user_data\",\n      targetUserId: args.userId,\n      expiresAt: Date.now() + 5 * 60 * 1000, // 5 minutes\n    });\n\n    // In production, send code via secure channel (email, SMS)\n    return code;\n  },\n});\n```\n\n## Examples\n\n### Complete Audit Trail System\n\n```typescript\n// convex/audit.ts\nimport { mutation, query, internalMutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { getUser, requireRole } from \"./lib/auth\";\n\nconst auditEventValidator = v.object({\n  _id: v.id(\"auditLogs\"),\n  _creationTime: v.number(),\n  action: v.string(),\n  userId: v.optional(v.string()),\n  resourceType: v.string(),\n  resourceId: v.string(),\n  details: v.optional(v.any()),\n  ipAddress: v.optional(v.string()),\n  timestamp: v.number(),\n});\n\n// Internal: Log audit event\nexport const logEvent = internalMutation({\n  args: {\n    action: v.string(),\n    userId: v.optional(v.string()),\n    resourceType: v.string(),\n    resourceId: v.string(),\n    details: v.optional(v.any()),\n  },\n  returns: v.id(\"auditLogs\"),\n  handler: async (ctx, args) => {\n    return await ctx.db.insert(\"auditLogs\", {\n      ...args,\n      timestamp: Date.now(),\n    });\n  },\n});\n\n// Admin: View audit logs\nexport const getAuditLogs = query({\n  args: {\n    resourceType: v.optional(v.string()),\n    userId: v.optional(v.string()),\n    limit: v.optional(v.number()),\n  },\n  returns: v.array(auditEventValidator),\n  handler: async (ctx, args) => {\n    await requireRole(ctx, \"admin\");\n\n    let query = ctx.db.query(\"auditLogs\");\n\n    if (args.resourceType) {\n      query = query.withIndex(\"by_resource_type\", (q) => q.eq(\"resourceType\", args.resourceType));\n    }\n\n    return await query.order(\"desc\").take(args.limit ?? 100);\n  },\n});\n```\n\n## Best Practices\n\n- Never run `npx convex deploy` unless explicitly instructed\n- Never run any git commands unless explicitly instructed\n- Implement defense in depth (multiple security layers)\n- Log all sensitive operations for audit trails\n- Use confirmation codes for destructive actions\n- Rate limit all user-facing endpoints\n- Never expose internal API keys or errors\n- Review access patterns regularly\n\n## Common Pitfalls\n\n1. **Single point of failure** - Implement multiple auth checks\n2. **Missing audit logs** - Log all sensitive operations\n3. **Trusting client data** - Always validate server-side\n4. **Exposing error details** - Sanitize error messages\n5. **No rate limiting** - Always implement rate limits\n\n## References\n\n- Convex Documentation: https://docs.convex.dev/\n- Convex LLMs.txt: https://docs.convex.dev/llms.txt\n- Functions Auth: https://docs.convex.dev/auth/functions-auth\n- Production Security: https://docs.convex.dev/production\n"},"lastSynced":"2026-03-08T02:09:03.820Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Security Agents needing comprehensive Convex application security audits with advanced authorization logic and data access boundary checks.","zh":"非常适合需要对 Convex 应用程序进行全面安全审计的 Cloud Security Agents，包括高级授权逻辑和数据访问边界检查。","ja":"Convex アプリケーションの包括的なセキュリティ監査が必要な Cloud Security Agents に最適です。高度な認可ロジックとデータアクセス境界チェックを実行します。","ko":"Convex 애플리케이션의 포괄적인 보안 감사를 필요로 하는 Cloud Security 에이전트에게 적합합니다. 고급 인증 로직 및 데이터 액세스 경계 검사를 수행합니다.","es":"Perfecto para Agentes de Seguridad en la Nube que necesitan auditorías de seguridad de aplicaciones Convex exhaustivas con lógica de autorización avanzada y comprobaciones de límites de acceso a datos.","fr":"Idéal pour les agents de sécurité cloud ayant besoin d''audits de sécurité d''applications Convex complets avec une logique d''autorisation avancée et des vérifications de limites d''accès aux données.","de":"Perfekt für Cloud-Sicherheitsagenten, die umfassende Sicherheitsaudits von Convex-Anwendungen mit erweiterter Autorisierungslogik und Datenzugriffsgrenzprüfungen benötigen.","pt":"Perfeito para Agentes de Segurança em Nuvem que necessitam de auditorias de segurança de aplicativos Convex abrangentes com lógica de autorização avançada e verificações de limites de acesso a dados.","ru":"Идеально подходит для агентов облачной безопасности, которым необходимы комплексные аудиты безопасности приложений Convex с продвинутой логикой авторизации и проверками границ доступа к данным.","ar":"مثالي للوكلاء أمن السحابة الذين يحتاجون إلى تدقيقات أمن تطبيقات Convex الشاملة مع منطق تفويض متقدم وفحوصات حدود وصول البيانات."},"recommendation":{"en":"Empowers agents to perform thorough security reviews of Convex applications, ensuring robust authorization logic, secure data access boundaries, and effective action isolation, while also implementing rate limiting and protecting sensitive operations using protocols outlined in the Convex documentation.","zh":"赋予代理执行 Convex 应用程序的彻底安全审查的能力，确保强大的授权逻辑、安全的数据访问边界、有效的动作隔离，同时实施速率限制并使用 Convex 文档中概述的协议保护敏感操作。","ja":"エージェントが Convex アプリケーションの徹底的なセキュリティレビューを実行できるようにし、強力な認可ロジック、セキュアなデータアクセス境界、効果的なアクションの分離を確実に実施し、同時にレート制限を実施し、Convex ドキュメントに概説されているプロトコルを使用して機密操作を保護します。","ko":"에이전트가 Convex 애플리케이션의 철저한 보안 검토를 수행할 수 있도록 하며, 강력한 인증 로직, 보안 데이터 액세스 경계, 효과적인 액션 분리를 확실히 구현하며,同時에 속도 제한을 구현하고 Convex 문서에概説된 프로토콜을 사용하여 민감한 작업을 보호합니다.","es":"Habilita a los agentes a realizar exhaustivas revisiones de seguridad de aplicaciones Convex, garantizando una lógica de autorización robusta, límites de acceso a datos seguros, y aislamiento de acciones efectivo, al tiempo que implementa límites de velocidad y protege operaciones sensibles utilizando protocolos descritos en la documentación de Convex.","fr":"Permet aux agents d''effectuer des examens de sécurité approfondis des applications Convex, en garantissant une logique d''autorisation robuste, des limites d''accès aux données sécurisées, et un isolement d''actions efficace, tout en mettant en œuvre une limitation de débit et en protégeant les opérations sensibles en utilisant les protocoles décrits dans la documentation Convex.","de":"Ermächtigt Agenten, umfassende Sicherheitsprüfungen von Convex-Anwendungen durchzuführen, eine robuste Autorisierungslogik, sichere Datenzugriffsgrenzen und wirksames Handlungsisolierung sicherzustellen und gleichzeitig Rate Limiting umzusetzen und sensible Operationen unter Verwendung der in der Convex-Dokumentation beschriebenen Protokolle zu schützen.","pt":"Habilita os agentes a realizar revisões de segurança abrangentes de aplicativos Convex, garantindo lógica de autorização robusta, limites de acesso a dados seguros e isolamento de ação eficaz, além de implementar limitação de taxa e proteger operações sensíveis usando protocolos descritos na documentação do Convex.","ru":"Наделяет агентов возможностью проводить тщательные проверки безопасности приложений Convex, гарантируя прочную логику авторизации, безопасные границы доступа к данным и эффективную изоляцию действий, а также реализацию ограничения скорости и защиту чувствительных операций с использованием протоколов, изложенных в документации Convex.","ar":"يمنح الوكلاء القدرة على إجراء استعراضات أمن شاملة لتطبيقات Convex، مما يضمن منطق تفويض قوي وحدود وصول بيانات آمنة وعزل فعل فعال، بالإضافة إلى تنفيذ حد Rate و حماية العمليات الحساسة باستخدام البروتوكولات الموصى بها في وثائق Convex."},"useCases":{"en":["Auditing Convex application authorization logic for vulnerabilities","Validating data access boundaries to prevent unauthorized access","Implementing rate limiting to protect against denial-of-service attacks"],"zh":["审计 Convex 应用程序授权逻辑以查找漏洞","验证数据访问边界以防止未经授权的访问","实施速率限制以保护免受拒绝服务攻击"],"ja":["Convex アプリケーションの認可ロジックを脆弱性のために監査する","データアクセス境界を検証して未認可のアクセスを防止する","レート制限を実施してサービス拒否攻撃から保護する"],"ko":["Convex 애플리케이션의 인증 로직을 취약점을 위해 감사하는 것","데이터 액세스 경계를 검증하여 무단 액세스를 방지하는 것","속도 제한을 구현하여 서비스 거부 공격으로부터 보호하는 것"],"es":["Auditoría de la lógica de autorización de la aplicación Convex en busca de vulnerabilidades","Validación de los límites de acceso a datos para prevenir el acceso no autorizado","Implementación de límites de velocidad para proteger contra ataques de denegación de servicio"],"fr":["Audit de la logique d''autorisation de l''application Convex pour les vulnérabilités","Validation des limites d''accès aux données pour prévenir l''accès non autorisé","Mise en œuvre de la limitation de débit pour protéger contre les attaques de déni de service"],"de":["Prüfung der Autorisierungslogik der Convex-Anwendung auf Sicherheitslücken","Validierung der Datenzugriffsgrenzen, um unbefugten Zugriff zu verhindern","Umsetzung von Rate Limiting, um Angriffe mit Dienstverweigerung zu schützen"],"pt":["Auditoria da lógica de autorização do aplicativo Convex para vulnerabilidades","Validação de limites de acesso a dados para prevenir acesso não autorizado","Implementação de limitação de taxa para proteger contra ataques de negação de serviço"],"ru":["Аудит логики авторизации приложения Convex на наличие уязвимостей","Проверка границ доступа к данным для предотвращения несанкционированного доступа","Реализация ограничения скорости для защиты от атак типа \"отказ в обслуживании\""],"ar":["تدقيق منطق تفويض تطبيق Convex للضعف","التحقق من حدود وصول البيانات لمنع الوصول غير المصرح به","تنفيذ حد التصفح لحماية ضد هجمات رفض الخدمة"]},"limitations":{"en":["Requires access to Convex application code and documentation","Depends on Convex API and documentation for authentication and authorization protocols"],"zh":["需要访问 Convex 应用程序代码和文档","依赖 Convex API 和文档用于认证和授权协议"],"ja":["Convex アプリケーションのコードとドキュメントへのアクセスが必要","認証および認可プロトコルに Convex API およびドキュメントに依存する"],"ko":["Convex 애플리케이션 코드 및 문서에 액세스해야 함","인증 및 인가 프로토콜에 Convex API 및 문서에 의존"],"es":["Requiere acceso al código y documentación de la aplicación Convex","Depende de la API de Convex y la documentación para los protocolos de autenticación y autorización"],"fr":["Nécessite un accès au code et à la documentation de l''application Convex","Dépend de l''API Convex et de la documentation pour les protocoles d''authentification et d''autorisation"],"de":["Benötigt Zugriff auf den Code und die Dokumentation der Convex-Anwendung","Hängt von der Convex-API und der Dokumentation für Authentifizierungs- und Autorisierungsprotokolle ab"],"pt":["Exige acesso ao código e documentação do aplicativo Convex","Depende da API e documentação do Convex para protocolos de autenticação e autorização"],"ru":["Требует доступа к коду и документации приложения Convex","Зависит от API и документации Convex для протоколов аутентификации и авторизации"],"ar":["يتطلب الوصول إلى код وثائق تطبيق Convex","يعتمد على API ووثائق Convex لبروتوكولات التحقق والتفويض"]},"version":4},"contentHash":"bc61c9c16494052941c671f5605bc5d964d88e219ec096ad7ca0931d5e2f39d2","qualityScore":67}');
