INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mauricioacp/tanstack-convex-better-auth-template/convex-security-audit', 'convex-security-audit', 'mauricioacp', 'tanstack-convex-better-auth-template', 'community', 'convex-security-audit mauricioacp tanstack-convex-better-auth-template community Convex Security Audit provides a comprehensive security review for Convex applications, benefiting developers by ensuring authorization logic, data access boundaries, and action isolation. This skill enhances Convex application security. Convex安全审计技能为开发者提供全面的Convex应用安全审查模式，包括授权逻辑验证、数据访问边界控制和敏感操作保护。基于最新Convex官方文档，确保生产环境安全部署。 Convexセキュリティ監査AIエージェントは、認証ロジックの検証、データアクセス境界の制御、アクション分離を含むConvexアプリケーションの包括的なセキュリティレビューを提供します。 Convex 보안 감독 스킬은 권한 부여 논리 검증, 데이터 액세스 경계 제어, 작업 격리를 포함한 Convex 애플리케이션의 포괄적인 보안 검토를 제공합니다. Este agente de IA proporciona patrones de revisión de seguridad para aplicaciones Convex, incluyendo lógica de autorización, límites de acceso a datos, aislamiento de acciones y protección de operaciones sensibles basado en la documentación oficial. Cet outil IA fournit des modèles de revue de sécurité pour applications Convex, incluant la logique d''autorisation, les limites d''accès aux données, l''isolation des actions et la protection des opérations sensibles selon la documentation officielle. Dieses KI-Tool bietet Sicherheitsüberprüfungsmuster für Convex-Anwendungen, einschließlich Autorisierungslogik, Datenzugriffsgrenzen, Aktionsisolierung und dem Schutz sensibler Operationen basierend auf der offiziellen Dokumentation. O Convex Security Audit é uma ferramenta de revisão de segurança abrangente para aplicações Convex, incluindo lógica de autorização e isolamento de ações Convex Security Audit - это комплексный инструмент проверки безопасности для приложений Convex, включающий логику авторизации и изоляцию действий Convex Security Audit هو أداة مراجعة أمان شاملة للتطبيقات Convex، تشمل منطق التفويض وفصل الإجراءات convex security audit setup guide how to use convex security audit convex security audit vs competitor what is convex security audit convex security audit install convex security audit alternative convex application security best practices authorization logic in convex data access boundaries in convex convex production security guidelines Convex安全审计 Convex授权逻辑 数据访问边界 Convex操作隔离 Convex速率限制 Convex生产安全 Convex函数认证 Convex安全最佳实践 Comprehensive security review patterns for Convex applications Implementation of authorization logic using Convex functions auth Enforcement of data access boundaries and action isolation Rate limiting and protection of sensitive operations Integration with Convex production security guidelines Reference to official Convex documentation for latest updates Convex-security-audit is a comprehensive security review pattern for Convex applications, covering authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('charlietlamb/ferix/Convex Security Audit', 'community', 'charlietlamb', 'ferix', 'charlietlamb/ferix', 'Convex Security Audit', 0, 0, 67, '2026-03-08T01:57:15.521Z', '2026-03-08T02:10:46.592Z', '73c90c2153d3308e020d46674240abb682bba4746179b4942c60cabda7a2e5b3', '{"id":"charlietlamb/ferix/Convex Security Audit","name":"Convex Security Audit","description":{"en":"The Convex Security Audit skill provides a centralized hub for comprehensive security review patterns, benefiting developers of Convex applications. It ensures authorization logic, data access boundaries, and rate limiting are properly implemented.","zh":"Convex 安全审计提供了全面安全审查模式，包括授权逻辑、数据访问边界、操作隔离、速率限制等","ja":"Convex セキュリティ監査は、認証ロジック、データアクセス境界、操作の分離、レート制限など、包括的なセキュリティレビューパターンを提供する","ko":"Convex 보안 감사는 권한 부여 논리, 데이터 액세스 경계, 동작 분리, 레이트 제한 등을 포함하는 종합적인 보안 검토 패턴을 제공한다","es":"Convex Security Audit es una herramienta centralizada para revisar la seguridad de aplicaciones Convex, incluyendo lógica de autorización y límites de velocidad","fr":"Convex Security Audit est un outil centralisé pour examiner la sécurité des applications Convex, y compris la logique d''autorisation et les limites de débit","de":"Convex Security Audit ist ein zentrales Tool zur Überprüfung der Sicherheit von Convex-Anwendungen, einschließlich Autorisierungslogik und Rate Limiting","pt":"O Convex Security Audit é uma ferramenta de revisão de segurança abrangente para aplicações Convex, incluindo lógica de autorização e isolamento de ações","ru":"Convex Security Audit - это комплексный инструмент проверки безопасности для приложений Convex, включая логику авторизации и изоляцию действий","ar":"Convex Security Audit هو أداة مراجعة أمن شاملة للتطبيقات Convex، بما في ذلك منطق التعريف والمعزل الإجرائي"},"seo":{"title":{"en":"Convex Security Audit: Comprehensive Security Review Guid...","zh":"Convex 安全审计设置指南 - 优化 Convex 应用安全","ja":"Convex セキュリティ監査のベストプラクティス - AIエージェントによるセキュリティ強化","ko":"Convex 보안 감사 설정 가이드 - Convex 애플리케이션 보안 최적화","es":"Guía de Configuración de Convex Security Audit para Agent...","fr":"Guide de Configuration de Convex Security Audit pour Outi...","de":"Einrichtungsleitfaden für Convex Security Audit in KI-Age...","pt":"Guia de Configuração do Convex Security Audit","ru":"Руководство по настройке Convex Security Audit для ИИ Аге...","ar":"دليل إعداد Convex Security Audit لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock robust security for your Convex applications with our expert audit guide - learn how to protect sensitive operations and data access boundaries today!","zh":"了解 Convex 安全审计的功能和优点，优化 Convex 应用安全，保护敏感操作","ja":"Convex セキュリティ監査の機能と利点を学び、Convex アプリケーションのセキュリティを強化する","ko":"Convex 보안 감사의 기능과 이점을 알아보고 Convex 애플리케이션 보안을 강화하는 방법","es":"Aprende a configurar Convex Security Audit para proteger tus aplicaciones con patrones de revisión de seguridad, lógica de autorización y límites de velocidad","fr":"Découvrez comment configurer Convex Security Audit pour protéger vos applications avec des modèles d''audit de sécurité, une logique d''autorisation et des lim...","de":"Erfahren Sie, wie Sie Convex Security Audit einrichten, um Ihre Anwendungen mit Sicherheitsprüfmustern, Autorisierungslogik und Rate Limiting zu schützen","pt":"Aprenda a proteger suas aplicações Convex com o Convex Security Audit, incluindo lógica de autorização e isolamento de ações","ru":"Защитите свои приложения Convex с помощью Convex Security Audit, включая логику авторизации и изоляцию действий для ИИ Агентов","ar":"تعلم حماية تطبيقات Convex الخاصة بك باستخدام Convex Security Audit، بما في ذلك منطق التعريف والمعزل الإجرائي لأدوات الذكاء الاصطناعي"},"definition":{"en":"Convex Security Audit is a security review framework for Convex applications, focusing on authorization logic, data access boundaries, action isolation, and rate limiting.","zh":"Convex 安全审计是 Convex 应用程序的安全审查工具，用于保护敏感操作","ja":"Convex セキュリティ監査は、Convex アプリケーションのセキュリティを強化するために使用されるセキュリティレビューツールです","ko":"Convex 보안 감사는 Convex 애플리케이션의 보안을 강화하기 위해 사용되는 보안 검토 도구입니다","es":"Convex Security Audit es un patrón de revisión de seguridad para aplicaciones Convex que verifica la lógica de autorización, los límites de velocidad y la protección de operaciones sensibles","fr":"Convex Security Audit est un modèle d''audit de sécurité pour les applications Convex qui vérifie la logique d''autorisation, les limites de débit et la protection des opérations sensibles","de":"Convex Security Audit ist ein Sicherheitsprüfmuster für Convex-Anwendungen, das die Autorisierungslogik, die Rate Limiting und den Schutz sensibler Operationen überprüft","pt":"O Convex Security Audit é uma ferramenta de segurança que realiza uma revisão abrangente de aplicações Convex","ru":"Convex Security Audit - это инструмент безопасности, который проводит комплексную проверку приложений Convex","ar":"Convex Security Audit هو أداة أمن تقوم بمراجعة شاملة للتطبيقات Convex"},"features":{"en":["Comprehensive security review patterns for Convex applications","Authorization logic implementation using Convex functions auth","Data access boundary protection as per https://docs.convex.dev/production","Action isolation and rate limiting for sensitive operations","Documentation sources from https://docs.convex.dev/auth/functions-auth and https://docs.convex.dev/llms.txt"],"zh":["授权逻辑审查","数据访问边界保护","操作隔离和速率限制","保护敏感操作","Convex 应用程序安全审查模式"],"ja":["認証ロジックのレビュー","データアクセス境界の保護","操作の分離とレート制限","機密操作の保護","Convex アプリケーションのセキュリティレビューパターン"],"ko":["권한 부여 논리 검토","데이터 액세스 경계 보호","동작 분리 및 레이트 제한","민감한 동작 보호","Convex 애플리케이션 보안 검토 패턴"],"es":["Revisión de lógica de autorización","Verificación de límites de velocidad","Protección de operaciones sensibles","Patrones de revisión de seguridad para aplicaciones Convex","Integración con la documentación de Convex","Soporte para funciones de autenticación"],"fr":["Vérification de la logique d''autorisation","Vérification des limites de débit","Protection des opérations sensibles","Modèles d''audit de sécurité pour les applications Convex","Intégration avec la documentation de Convex","Prise en charge des fonctions d''authentification"],"de":["Überprüfung der Autorisierungslogik","Überprüfung der Rate Limiting","Schutz sensibler Operationen","Sicherheitsprüfmuster für Convex-Anwendungen","Integration mit der Convex-Dokumentation","Unterstützung für Authentifizierungsfunktionen"],"pt":["Revisão de lógica de autorização","Isolamento de ações","Controle de acesso a dados","Limitação de taxa","Proteção de operações sensíveis"],"ru":["Проверка логики авторизации","Изоляция действий","Контроль доступа к данным","Ограничение скорости","Защита чувствительных операций"],"ar":["مراجعة منطق التعريف","المعزل الإجرائي","مراقبة الوصول إلى البيانات","تحديد معدل","حماية العمليات الحساسة"]},"keywords":{"en":["Convex Security Audit setup guide","how to use Convex Security Audit","what is Convex Security Audit","Convex Security Audit alternative","Convex Security Audit vs competitor","Convex Security Audit install","Convex application security best practices","authorization logic implementation in Convex"],"zh":["Convex 安全审计","Convex 应用安全","AI工具安全","Convex 安全设置","Convex 应用优化","安全审查模式"],"ja":["Convex セキュリティ監査","Convex アプリケーションセキュリティ","AIエージェントセキュリティ","Convex セキュリティ設定","Convex アプリケーション最適化","セキュリティレビューパターン"],"ko":["Convex 보안 감사","Convex 애플리케이션 보안","AI 도구 보안","Convex 보안 설정","Convex 애플리케이션 최적화","보안 검토 패턴"],"es":["Convex Security Audit","seguridad de aplicaciones","lógica de autorización","límites de velocidad","protección de operaciones sensibles","patrones de revisión de seguridad","documentación de Convex","autenticación","agentes de inteligencia artificial"],"fr":["Convex Security Audit","sécurité des applications","logique d''autorisation","limites de débit","protection des opérations sensibles","modèles d''audit de sécurité","documentation de Convex","authentification","outils d''intelligence artificielle"],"de":["Convex Security Audit","Sicherheit von Anwendungen","Autorisierungslogik","Rate Limiting","Schutz sensibler Operationen","Sicherheitsprüfmuster","Convex-Dokumentation","Authentifizierung","KI-Agenten"],"pt":["Convex Security Audit","segurança de aplicações Convex","lógica de autorização","isolamento de ações","controle de acesso a dados","limitação de taxa","proteção de operações sensíveis"],"ru":["Convex Security Audit","безопасность приложений Convex","логика авторизации","изоляция действий","контроль доступа к данным","ограничение скорости","защита чувствительных операций","ИИ Агенты"],"ar":["Convex Security Audit","أمان التطبيقات Convex","منطق التعريف","المعزل الإجرائي","مراقبة الوصول إلى البيانات","تحديد معدل","حماية العمليات الحساسة","أدوات الذكاء الاصطناعي"]}},"owner":"charlietlamb","repo":"ferix","repoPath":"charlietlamb/ferix","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.521Z","topics":[],"category":"community","skillMd":{"name":"Convex Security Audit","description":"Deep security review patterns for authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations","version":"1.0.0","tags":["convex","security","audit","authorization","rate-limiting","protection"],"bodyPreview":"# Convex Security Audit\n\nComprehensive security review patterns for Convex applications including authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/auth/functions-auth\n- Production Security: https://docs.convex.dev/production\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n###","body":"# Convex Security Audit\n\nComprehensive security review patterns for Convex applications including authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/auth/functions-auth\n- Production Security: https://docs.convex.dev/production\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n### Security Audit Areas\n\n1. **Authorization Logic** - Who can do what\n2. **Data Access Boundaries** - What data users can see\n3. **Action Isolation** - Protecting external API calls\n4. **Rate Limiting** - Preventing abuse\n5. **Sensitive Operations** - Protecting critical functions\n\n### Authorization Logic Audit\n\n#### Role-Based Access Control (RBAC)\n\n```typescript\n// convex/lib/auth.ts\nimport { QueryCtx, MutationCtx } from \"./_generated/server\";\nimport { ConvexError } from \"convex/values\";\nimport { Doc } from \"./_generated/dataModel\";\n\ntype UserRole = \"user\" | \"moderator\" | \"admin\" | \"superadmin\";\n\nconst roleHierarchy: Record<UserRole, number> = {\n  user: 0,\n  moderator: 1,\n  admin: 2,\n  superadmin: 3,\n};\n\nexport async function getUser(ctx: QueryCtx | MutationCtx): Promise<Doc<\"users\"> | null> {\n  const identity = await ctx.auth.getUserIdentity();\n  if (!identity) return null;\n  \n  return await ctx.db\n    .query(\"users\")\n    .withIndex(\"by_tokenIdentifier\", (q) => \n      q.eq(\"tokenIdentifier\", identity.tokenIdentifier)\n    )\n    .unique();\n}\n\nexport async function requireRole(\n  ctx: QueryCtx | MutationCtx, \n  minRole: UserRole\n): Promise<Doc<\"users\">> {\n  const user = await getUser(ctx);\n  \n  if (!user) {\n    throw new ConvexError({\n      code: \"UNAUTHENTICATED\",\n      message: \"Authentication required\",\n    });\n  }\n  \n  const userRoleLevel = roleHierarchy[user.role as UserRole] ?? 0;\n  const requiredLevel = roleHierarchy[minRole];\n  \n  if (userRoleLevel < requiredLevel) {\n    throw new ConvexError({\n      code: \"FORBIDDEN\",\n      message: `Role ''${minRole}'' or higher required`,\n    });\n  }\n  \n  return user;\n}\n\n// Permission-based check\ntype Permission = \"read:users\" | \"write:users\" | \"delete:users\" | \"admin:system\";\n\nconst rolePermissions: Record<UserRole, Permission[]> = {\n  user: [\"read:users\"],\n  moderator: [\"read:users\", \"write:users\"],\n  admin: [\"read:users\", \"write:users\", \"delete:users\"],\n  superadmin: [\"read:users\", \"write:users\", \"delete:users\", \"admin:system\"],\n};\n\nexport async function requirePermission(\n  ctx: QueryCtx | MutationCtx,\n  permission: Permission\n): Promise<Doc<\"users\">> {\n  const user = await getUser(ctx);\n  \n  if (!user) {\n    throw new ConvexError({ code: \"UNAUTHENTICATED\", message: \"Authentication required\" });\n  }\n  \n  const userRole = user.role as UserRole;\n  const permissions = rolePermissions[userRole] ?? [];\n  \n  if (!permissions.includes(permission)) {\n    throw new ConvexError({\n      code: \"FORBIDDEN\",\n      message: `Permission ''${permission}'' required`,\n    });\n  }\n  \n  return user;\n}\n```\n\n### Data Access Boundaries Audit\n\n```typescript\n// convex/data.ts\nimport { query, mutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { getUser, requireRole } from \"./lib/auth\";\nimport { ConvexError } from \"convex/values\";\n\n// Audit: Users can only see their own data\nexport const getMyData = query({\n  args: {},\n  returns: v.array(v.object({\n    _id: v.id(\"userData\"),\n    content: v.string(),\n  })),\n  handler: async (ctx) => {\n    const user = await getUser(ctx);\n    if (!user) return [];\n    \n    // SECURITY: Filter by userId\n    return await ctx.db\n      .query(\"userData\")\n      .withIndex(\"by_user\", (q) => q.eq(\"userId\", user._id))\n      .collect();\n  },\n});\n\n// Audit: Verify ownership before returning sensitive data\nexport const getSensitiveItem = query({\n  args: { itemId: v.id(\"sensitiveItems\") },\n  returns: v.union(v.object({\n    _id: v.id(\"sensitiveItems\"),\n    secret: v.string(),\n  }), v.null()),\n  handler: async (ctx, args) => {\n    const user = await getUser(ctx);\n    if (!user) return null;\n    \n    const item = await ctx.db.get(args.itemId);\n    \n    // SECURITY: Verify ownership\n    if (!item || item.ownerId !== user._id) {\n      return null; // Don''t reveal if item exists\n    }\n    \n    return item;\n  },\n});\n\n// Audit: Shared resources with access list\nexport const getSharedDocument = query({\n  args: { docId: v.id(\"documents\") },\n  returns: v.union(v.object({\n    _id: v.id(\"documents\"),\n    content: v.string(),\n    accessLevel: v.string(),\n  }), v.null()),\n  handler: async (ctx, args) => {\n    const user = await getUser(ctx);\n    const doc = await ctx.db.get(args.docId);\n    \n    if (!doc) return null;\n    \n    // Public documents\n    if (doc.visibility === \"public\") {\n      return { ...doc, accessLevel: \"public\" };\n    }\n    \n    // Must be authenticated for non-public\n    if (!user) return null;\n    \n    // Owner has full access\n    if (doc.ownerId === user._id) {\n      return { ...doc, accessLevel: \"owner\" };\n    }\n    \n    // Check shared access\n    const access = await ctx.db\n      .query(\"documentAccess\")\n      .withIndex(\"by_doc_and_user\", (q) => \n        q.eq(\"documentId\", args.docId).eq(\"userId\", user._id)\n      )\n      .unique();\n    \n    if (!access) return null;\n    \n    return { ...doc, accessLevel: access.level };\n  },\n});\n```\n\n### Action Isolation Audit\n\n```typescript\n// convex/actions.ts\n\"use node\";\n\nimport { action, internalAction } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { api, internal } from \"./_generated/api\";\nimport { ConvexError } from \"convex/values\";\n\n// SECURITY: Never expose API keys in responses\nexport const callExternalAPI = action({\n  args: { query: v.string() },\n  returns: v.object({ result: v.string() }),\n  handler: async (ctx, args) => {\n    // Verify user is authenticated\n    const identity = await ctx.auth.getUserIdentity();\n    if (!identity) {\n      throw new ConvexError(\"Authentication required\");\n    }\n    \n    // Get API key from environment (not hardcoded)\n    const apiKey = process.env.EXTERNAL_API_KEY;\n    if (!apiKey) {\n      throw new Error(\"API key not configured\");\n    }\n    \n    // Log usage for audit trail\n    await ctx.runMutation(internal.audit.logAPICall, {\n      userId: identity.tokenIdentifier,\n      endpoint: \"external-api\",\n      timestamp: Date.now(),\n    });\n    \n    const response = await fetch(\"https://api.example.com/query\", {\n      method: \"POST\",\n      headers: {\n        \"Authorization\": `Bearer ${apiKey}`,\n        \"Content-Type\": \"application/json\",\n      },\n      body: JSON.stringify({ query: args.query }),\n    });\n    \n    if (!response.ok) {\n      // Don''t expose external API error details\n      throw new ConvexError(\"External service unavailable\");\n    }\n    \n    const data = await response.json();\n    \n    // Sanitize response before returning\n    return { result: sanitizeResponse(data) };\n  },\n});\n\n// Internal action - not exposed to clients\nexport const _processPayment = internalAction({\n  args: {\n    userId: v.id(\"users\"),\n    amount: v.number(),\n    paymentMethodId: v.string(),\n  },\n  returns: v.object({ success: v.boolean(), transactionId: v.optional(v.string()) }),\n  handler: async (ctx, args) => {\n    const stripeKey = process.env.STRIPE_SECRET_KEY;\n    \n    // Process payment with Stripe\n    // This should NEVER be exposed as a public action\n    \n    return { success: true, transactionId: \"txn_xxx\" };\n  },\n});\n```\n\n### Rate Limiting Audit\n\n```typescript\n// convex/rateLimit.ts\nimport { mutation, query } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { ConvexError } from \"convex/values\";\n\nconst RATE_LIMITS = {\n  message: { requests: 10, windowMs: 60000 }, // 10 per minute\n  upload: { requests: 5, windowMs: 300000 },  // 5 per 5 minutes\n  api: { requests: 100, windowMs: 3600000 },  // 100 per hour\n};\n\nexport const checkRateLimit = mutation({\n  args: {\n    userId: v.string(),\n    action: v.union(v.literal(\"message\"), v.literal(\"upload\"), v.literal(\"api\")),\n  },\n  returns: v.object({ allowed: v.boolean(), retryAfter: v.optional(v.number()) }),\n  handler: async (ctx, args) => {\n    const limit = RATE_LIMITS[args.action];\n    const now = Date.now();\n    const windowStart = now - limit.windowMs;\n    \n    // Count requests in window\n    const requests = await ctx.db\n      .query(\"rateLimits\")\n      .withIndex(\"by_user_and_action\", (q) => \n        q.eq(\"userId\", args.userId).eq(\"action\", args.action)\n      )\n      .filter((q) => q.gt(q.field(\"timestamp\"), windowStart))\n      .collect();\n    \n    if (requests.length >= limit.requests) {\n      const oldestRequest = requests[0];\n      const retryAfter = oldestRequest.timestamp + limit.windowMs - now;\n      \n      return { allowed: false, retryAfter };\n    }\n    \n    // Record this request\n    await ctx.db.insert(\"rateLimits\", {\n      userId: args.userId,\n      action: args.action,\n      timestamp: now,\n    });\n    \n    return { allowed: true };\n  },\n});\n\n// Use in mutations\nexport const sendMessage = mutation({\n  args: { content: v.string() },\n  returns: v.id(\"messages\"),\n  handler: async (ctx, args) => {\n    const identity = await ctx.auth.getUserIdentity();\n    if (!identity) throw new ConvexError(\"Authentication required\");\n    \n    // Check rate limit\n    const rateCheck = await checkRateLimit(ctx, {\n      userId: identity.tokenIdentifier,\n      action: \"message\",\n    });\n    \n    if (!rateCheck.allowed) {\n      throw new ConvexError({\n        code: \"RATE_LIMITED\",\n        message: `Too many requests. Try again in ${Math.ceil(rateCheck.retryAfter! / 1000)} seconds`,\n      });\n    }\n    \n    return await ctx.db.insert(\"messages\", {\n      content: args.content,\n      authorId: identity.tokenIdentifier,\n      createdAt: Date.now(),\n    });\n  },\n});\n```\n\n### Sensitive Operations Protection\n\n```typescript\n// convex/admin.ts\nimport { mutation, internalMutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { requireRole, requirePermission } from \"./lib/auth\";\nimport { internal } from \"./_generated/api\";\n\n// Two-factor confirmation for dangerous operations\nexport const deleteAllUserData = mutation({\n  args: {\n    userId: v.id(\"users\"),\n    confirmationCode: v.string(),\n  },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    // Require superadmin\n    const admin = await requireRole(ctx, \"superadmin\");\n    \n    // Verify confirmation code\n    const confirmation = await ctx.db\n      .query(\"confirmations\")\n      .withIndex(\"by_admin_and_code\", (q) => \n        q.eq(\"adminId\", admin._id).eq(\"code\", args.confirmationCode)\n      )\n      .filter((q) => q.gt(q.field(\"expiresAt\"), Date.now()))\n      .unique();\n    \n    if (!confirmation || confirmation.action !== \"delete_user_data\") {\n      throw new ConvexError(\"Invalid or expired confirmation code\");\n    }\n    \n    // Delete confirmation to prevent reuse\n    await ctx.db.delete(confirmation._id);\n    \n    // Schedule deletion (don''t do it inline)\n    await ctx.scheduler.runAfter(0, internal.admin._performDeletion, {\n      userId: args.userId,\n      requestedBy: admin._id,\n    });\n    \n    // Audit log\n    await ctx.db.insert(\"auditLogs\", {\n      action: \"delete_user_data\",\n      targetUserId: args.userId,\n      performedBy: admin._id,\n      timestamp: Date.now(),\n    });\n    \n    return null;\n  },\n});\n\n// Generate confirmation code for sensitive action\nexport const requestDeletionConfirmation = mutation({\n  args: { userId: v.id(\"users\") },\n  returns: v.string(),\n  handler: async (ctx, args) => {\n    const admin = await requireRole(ctx, \"superadmin\");\n    \n    const code = generateSecureCode();\n    \n    await ctx.db.insert(\"confirmations\", {\n      adminId: admin._id,\n      code,\n      action: \"delete_user_data\",\n      targetUserId: args.userId,\n      expiresAt: Date.now() + 5 * 60 * 1000, // 5 minutes\n    });\n    \n    // In production, send code via secure channel (email, SMS)\n    return code;\n  },\n});\n```\n\n## Examples\n\n### Complete Audit Trail System\n\n```typescript\n// convex/audit.ts\nimport { mutation, query, internalMutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport { getUser, requireRole } from \"./lib/auth\";\n\nconst auditEventValidator = v.object({\n  _id: v.id(\"auditLogs\"),\n  _creationTime: v.number(),\n  action: v.string(),\n  userId: v.optional(v.string()),\n  resourceType: v.string(),\n  resourceId: v.string(),\n  details: v.optional(v.any()),\n  ipAddress: v.optional(v.string()),\n  timestamp: v.number(),\n});\n\n// Internal: Log audit event\nexport const logEvent = internalMutation({\n  args: {\n    action: v.string(),\n    userId: v.optional(v.string()),\n    resourceType: v.string(),\n    resourceId: v.string(),\n    details: v.optional(v.any()),\n  },\n  returns: v.id(\"auditLogs\"),\n  handler: async (ctx, args) => {\n    return await ctx.db.insert(\"auditLogs\", {\n      ...args,\n      timestamp: Date.now(),\n    });\n  },\n});\n\n// Admin: View audit logs\nexport const getAuditLogs = query({\n  args: {\n    resourceType: v.optional(v.string()),\n    userId: v.optional(v.string()),\n    limit: v.optional(v.number()),\n  },\n  returns: v.array(auditEventValidator),\n  handler: async (ctx, args) => {\n    await requireRole(ctx, \"admin\");\n    \n    let query = ctx.db.query(\"auditLogs\");\n    \n    if (args.resourceType) {\n      query = query.withIndex(\"by_resource_type\", (q) => \n        q.eq(\"resourceType\", args.resourceType)\n      );\n    }\n    \n    return await query\n      .order(\"desc\")\n      .take(args.limit ?? 100);\n  },\n});\n```\n\n## Best Practices\n\n- Never run `npx convex deploy` unless explicitly instructed\n- Never run any git commands unless explicitly instructed\n- Implement defense in depth (multiple security layers)\n- Log all sensitive operations for audit trails\n- Use confirmation codes for destructive actions\n- Rate limit all user-facing endpoints\n- Never expose internal API keys or errors\n- Review access patterns regularly\n\n## Common Pitfalls\n\n1. **Single point of failure** - Implement multiple auth checks\n2. **Missing audit logs** - Log all sensitive operations\n3. **Trusting client data** - Always validate server-side\n4. **Exposing error details** - Sanitize error messages\n5. **No rate limiting** - Always implement rate limits\n\n## References\n\n- Convex Documentation: https://docs.convex.dev/\n- Convex LLMs.txt: https://docs.convex.dev/llms.txt\n- Functions Auth: https://docs.convex.dev/auth/functions-auth\n- Production Security: https://docs.convex.dev/production\n"},"lastSynced":"2026-03-08T02:10:46.592Z","agentAnalysis":{"suitability":{"en":"Perfect for Security Audit Agents needing comprehensive review patterns for Convex applications, including authorization logic and data access boundaries.","zh":"非常适合需要对 Convex 应用程序进行全面审查的安全审计代理，包括授权逻辑和数据访问边界。","ja":"Convex アプリケーションの包括的なレビュー パターンを必要とするセキュリティ監査エージェントに最適です。承認ロジックおよびデータ アクセス境界を含みます。","ko":"Convex 애플리케이션에 대한 포괄적인 리뷰 패턴이 필요한 보안 감사 에이전트에게 적합합니다. 승인 로직 및 데이터 액세스 경계가 포함됩니다.","es":"Perfecto para agentes de auditoría de seguridad que necesitan patrones de revisión comprehensivos para aplicaciones Convex, incluyendo lógica de autorización y límites de acceso a datos.","fr":"Parfait pour les agents d''audit de sécurité nécessitant des modèles d''examen complets pour les applications Convex, y compris la logique d''autorisation et les limites d''accès aux données.","de":"Perfekt für Sicherheitsaudit-Agenten, die umfassende Überprüfungsmuster für Convex-Anwendungen benötigen, einschließlich Autorisierungslogik und Datenzugriffsgrenzen.","pt":"Perfeito para Agentes de Auditoria de Segurança que precisam de padrões de revisão abrangentes para aplicações Convex, incluindo lógica de autorização e limites de acesso a dados.","ru":"Идеально подходит для агентов аудита безопасности, которым требуются комплексные шаблоны проверки для приложений Convex, включая логику авторизации и границы доступа к данным.","ar":"مثالي لعميلوك تدقيق الأمن الذين يحتاجون إلى أنماط مراجعة شاملة لتطبيقات Convex، بما في ذلك منطق التصريح وحدود الوصول إلى البيانات."},"recommendation":{"en":"Empowers agents to ensure secure Convex application development by implementing proper authorization logic, data access boundaries, action isolation, rate limiting, and protecting sensitive operations using Convex functions and production security best practices.","zh":"赋予代理确保 Convex 应用程序的安全开发能力，通过实施适当的授权逻辑、数据访问边界、操作隔离、速率限制，并使用 Convex 函数和生产安全最佳实践来保护敏感操作。","ja":"Convex アプリケーションのセキュアな開発を確実にするエージェントをEmpowerすることで、適切な承認ロジック、データ アクセス境界、操作の分離、レート制限、および Convex 関数とプロダクション セキュリティのベスト プラクティスを使用して、機密操作を保護します。","ko":"Convex 애플리케이션의 보안 개발을 보장하기 위해 에이전트를 강화하여 적절한 승인 로직, 데이터 액세스 경계, 작업 분리, 속도 제한 및 Convex 함수 및 프로덕션 보안 모범 사례를 사용하여 민감한 작업을 보호합니다.","es":"Habilita a los agentes a garantizar el desarrollo seguro de aplicaciones Convex implementando una lógica de autorización adecuada, límites de acceso a datos, aislamiento de acciones, limitación de velocidad y protección de operaciones sensibles utilizando funciones Convex y las mejores prácticas de seguridad de producción.","fr":"Permet aux agents de garantir le développement sécurisé d''applications Convex en mettant en œuvre une logique d''autorisation appropriée, des limites d''accès aux données, une isolation des actions, une limitation de débit et une protection des opérations sensibles en utilisant des fonctions Convex et les meilleures pratiques de sécurité de production.","de":"Ermöglicht es Agenten, die sichere Entwicklung von Convex-Anwendungen sicherzustellen, indem sie eine ordnungsgemäße Autorisierungslogik, Datenzugriffsgrenzen, Aktionstrennung, Rate Limiting und Schutz sensibler Operationen mithilfe von Convex-Funktionen und Produktions-Sicherheitsbest-Practices implementieren.","pt":"Habilita os agentes a garantir o desenvolvimento de aplicações Convex seguras, implementando lógica de autorização adequada, limites de acesso a dados, isolamento de ações, limitação de taxa e proteção de operações sensíveis usando funções Convex e as melhores práticas de segurança de produção.","ru":"Наделяет агентов возможностью обеспечить безопасное развитие приложений Convex, реализуя правильную логику авторизации, границы доступа к данным, изоляцию действий, ограничение скорости и защиту чувствительных операций с помощью функций Convex и лучших практик безопасности производства.","ar":"يمنح الوكلاء القدرة على ضمان تطوير تطبيقات Convex بشكل آمن من خلال تنفيذ منطق التصريح المناسب وحدود الوصول إلى البيانات وعزل الإجراءات وتقييد معدل الحماية وعمليات حماية الحساسة باستخدام دوال Convex وأفضل الممارسات أمن الإنتاج."},"useCases":{"en":["Auditing Convex application authorization logic for security vulnerabilities","Implementing data access boundaries and rate limiting for secure data management","Protecting sensitive operations in Convex applications with secure authentication protocols"],"zh":["审计 Convex 应用程序的授权逻辑以发现安全漏洞","实施数据访问边界和速率限制以实现安全的数据管理","使用安全的身份验证协议保护 Convex 应用程序中的敏感操作"],"ja":["セキュリティの脆弱性を検出するため Convex アプリケーションの承認ロジックを監査する","セキュアなデータ管理のためにデータ アクセス境界とレート制限を実装する","Convex アプリケーション内の機密操作をセキュアな認証プロトコルで保護する"],"ko":["보안 취약성을 발견하기 위해 Convex 애플리케이션의 승인 로직을 감사하는 것","보안 데이터 관리를 위한 데이터 액세스 경계 및 속도 제한을 구현하는 것","Convex 애플리케이션의 민감한 작업을 보안 인증 프로토콜로 보호하는 것"],"es":["Auditoría de la lógica de autorización de aplicaciones Convex para vulnerabilidades de seguridad","Implementación de límites de acceso a datos y limitación de velocidad para una gestión de datos segura","Protección de operaciones sensibles en aplicaciones Convex con protocolos de autenticación seguros"],"fr":["Audit de la logique d''autorisation des applications Convex pour les vulnérabilités de sécurité","Mise en œuvre de limites d''accès aux données et de limitation de débit pour une gestion de données sécurisée","Protection des opérations sensibles dans les applications Convex avec des protocoles d''authentification sécurisés"],"de":["Überprüfung der Autorisierungslogik von Convex-Anwendungen auf Sicherheitsverletzungen","Implementierung von Datenzugriffsgrenzen und Rate Limiting für sichere Datenverwaltung","Schutz sensibler Operationen in Convex-Anwendungen mit sicheren Authentifizierungsprotokollen"],"pt":["Auditoria da lógica de autorização de aplicações Convex para vulnerabilidades de segurança","Implementação de limites de acesso a dados e limitação de taxa para gestão de dados segura","Proteção de operações sensíveis em aplicações Convex com protocolos de autenticação seguros"],"ru":["Аудит логики авторизации приложений Convex на наличие уязвимостей безопасности","Реализация границ доступа к данным и ограничения скорости для безопасного управления данными","Защита чувствительных операций в приложениях Convex с помощью безопасных протоколов аутентификации"],"ar":["تدقيق منطق التصريح لتطبيقات Convex للكشف عن نقاط الضعف الأمنية","تنفيذ حدود الوصول إلى البيانات وتقييد معدل للحصول على إدارة بيانات آمنة","حماية العمليات الحساسة في تطبيقات Convex باستخدام بروتوكولات التحقق الآمن"]},"limitations":{"en":["Requires knowledge of Convex development and security best practices","Limited to Convex applications and platforms","Needs access to Convex documentation and production security guidelines"],"zh":["需要 Convex 开发和安全最佳实践的知识","仅限 Convex 应用程序和平台","需要访问 Convex 文档和生产安全指南"],"ja":["Convex 開発およびセキュリティのベスト プラクティスの知識が必要","Convex アプリケーションおよびプラットフォームのみ","Convex ドキュメントおよびプロダクション セキュリティ ガイドラインへのアクセスが必要"],"ko":["Convex 개발 및 보안 모범 사례에 대한 지식이 필요합니다","Convex 애플리케이션 및 플랫폼으로 제한됩니다","Convex 문서 및 프로덕션 보안 지침에 대한 액세스가 필요합니다"],"es":["Requiere conocimiento del desarrollo Convex y de las mejores prácticas de seguridad","Limitado a aplicaciones y plataformas Convex","Necesita acceso a la documentación Convex y a las directrices de seguridad de producción"],"fr":["Nécessite des connaissances en développement Convex et en meilleures pratiques de sécurité","Limité aux applications et plates-formes Convex","Nécessite un accès à la documentation Convex et aux lignes directrices de sécurité de production"],"de":["Benötigt Kenntnisse in Convex-Entwicklung und Sicherheitsbest-Practices","Begrenzt auf Convex-Anwendungen und -Plattformen","Benötigt Zugriff auf Convex-Dokumentation und Produktions-Sicherheitsrichtlinien"],"pt":["Exige conhecimento do desenvolvimento Convex e das melhores práticas de segurança","Limitado a aplicações e plataformas Convex","Necessita acesso à documentação Convex e às diretrizes de segurança de produção"],"ru":["Требует знания разработки Convex и лучших практик безопасности","Ограничен приложениями и платформами Convex","Требует доступа к документации Convex и руководящим принципам безопасности производства"],"ar":["يتطلب معرفة بتطوير Convex وأفضل الممارسات الأمنية","محدود لتطبيقات و منصات Convex","يحتاج إلى الوصول إلى توثيق Convex و إرشادات أمن الإنتاج"]},"version":4},"contentHash":"73c90c2153d3308e020d46674240abb682bba4746179b4942c60cabda7a2e5b3","qualityScore":67}');
