INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frankxai/arcanea/guardian-evolution-system', 'guardian-evolution-system', 'frankxai', 'arcanea', 'community', 'guardian-evolution-system frankxai arcanea community 守护进化系统是一套开源的AI智能代理解决方案，用于创意工作的增强 ガーディアン進化システムは、創造的仕事の強化のためのオープンソースのAIエージェントソリューションです 가디언 진화 시스템은 창의적인 작업 강화를 위한 오픈소스의 AI 에이전트 솔루션입니다 El sistema de evolución de guardianes es un conjunto de agentes, habilidades y leyendas de código abierto para trabajo creativo con IA Le système d''évolution de gardien est un ensemble d''agents, de compétences et de légendes open source pour le travail créatif avec l''IA Das Guardian-Evolution-System ist eine Sammlung von Open-Source-Agents, Fähigkeiten und Legenden für kreatives Arbeiten mit KI O sistema de evolução de agente é uma plataforma de código aberto para criar trabalhos criativos com IA Система эволюции ИИ агентов - это открытая платформа для создания творческих работ с помощью ИИ نظام تطور الوكيل الذكي هو منصة مفتوحة المصدر لإنشاء أعمال إبداعية مع الذكاء الاصطناعي Open source agents, skills, and lore for AI-powered creative work. Transform your AI assistant into a creative companion. AI智能代理 守护进化系统 创意工作增强 开源AI解决方案 如何使用AI智能代理 AI智能代理安装 AI智能代理设置指南 Open source agents, skills, and lore for AI-powered creative work. Transform your AI assistant into a creative companion.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affaan-m/everything-claude-code/frontend-slides', 'official', 'affaan-m', 'everything-claude-code', 'affaan-m/everything-claude-code', 'frontend-slides', 61988, 7678, 67, '2026-03-06T03:39:20Z', '2026-03-06T04:12:31.960Z', 'bc890c0deeb766e78991d6de150fd981a70b3dac5507a4d20b43c1a210b1819d', '{"id":"affaan-m/everything-claude-code/frontend-slides","name":"frontend-slides","description":{"en":"frontend-slides generates zero-dependency, animation-rich HTML presentations from scratch or by converting PowerPoint files, ideal for non-designers and developers alike.","zh":"Frontend Slides 是一个创建动画丰富的 HTML 演示文稿的工具，支持从零开始创建或从 PowerPoint 文件转换","ja":"Frontend Slides は、アニメーション豊かな HTML プレゼンテーションを作成するためのツールです。ゼロから作成することも、PowerPoint ファイルから変換することもできます","ko":"Frontend Slides는 애니메이션 풍부한 HTML 프레젠테이션을 생성하는 툴로, 초보부터 파워포인트 파일 변환까지 지원합니다","es":"frontend-slides es una herramienta de AI Agent que genera presentaciones HTML ricas en animaciones sin dependencias externas. Permite convertir archivos PowerPoint existentes y crear presentaciones visualmente atractivas directamente en el navegador.","fr":"frontend-slides est un outil d''IA Agent qui génère des présentations HTML riches en animations sans dépendances externes. Permet de convertir des fichiers PowerPoint existants et créer des présentations visuellement attrayantes directement dans le navigateur.","de":"frontend-slides ist ein KI-Tool, das HTML-Präsentationen mit umfangreichen Animationen ohne externe Abhängigkeiten erstellt. Ermöglicht die Konvertierung vorhandener PowerPoint-Dateien und die Erstellung visuell ansprechender Präsentationen direkt im Browser.","pt":"Agente de IA que cria apresentações HTML com animações avançadas diretamente no navegador, sem dependências externas. Converte arquivos PowerPoint (.ppt/.pptx) em código web e ajuda a explorar estilos visuais para palestras ou pitches.","ru":"ИИ агент для создания анимированных HTML-презентаций, работающих полностью в браузере без зависимостей. Конвертирует файлы PowerPoint (.ppt/.pptx) в веб-код и помогает исследовать визуальные стили для выступлений.","ar":"عامل ذكاء اصطناعي لإنشاء عروض HTML تفاعلية غنية بالرسوم المتحركة تعمل بالكامل في المتصفح بدون تبعيات. يحول ملفات PowerPoint (.ppt/.pptx) إلى كود ويب ويساعد في استكشاف الأنماط البصرية للعروض التقديمية."},"owner":"affaan-m","repo":"everything-claude-code","repoPath":"affaan-m/everything-claude-code","stars":61988,"forks":7678,"updatedAt":"2026-03-06T03:39:20Z","topics":["ai-agents","anthropic","claude","claude-code","developer-tools","llm","mcp","productivity"],"skillMd":{"name":"frontend-slides","description":"Create stunning, animation-rich HTML presentations from scratch or by converting PowerPoint files. Use when the user wants to build a presentation, convert a PPT/PPTX to web, or create slides for a talk/pitch. Helps non-designers discover their aesthetic through visual exploration rather than abstract choices.","bodyPreview":"# Frontend Slides\n\nCreate zero-dependency, animation-rich HTML presentations that run entirely in the browser.\n\nInspired by the visual exploration approach showcased in work by zarazhangrui (credit: @zarazhangrui).\n\n## When to Activate\n\n- Creating a talk deck, pitch deck, workshop deck, or internal presentation\n- Converting `.ppt` or `.pptx` slides into an HTML presentation\n- Improving an existing HTML presentation''s layout, motion, or typography\n- Exploring presentation styles with a user who d","body":"# Frontend Slides\n\nCreate zero-dependency, animation-rich HTML presentations that run entirely in the browser.\n\nInspired by the visual exploration approach showcased in work by zarazhangrui (credit: @zarazhangrui).\n\n## When to Activate\n\n- Creating a talk deck, pitch deck, workshop deck, or internal presentation\n- Converting `.ppt` or `.pptx` slides into an HTML presentation\n- Improving an existing HTML presentation''s layout, motion, or typography\n- Exploring presentation styles with a user who does not know their design preference yet\n\n## Non-Negotiables\n\n1. **Zero dependencies**: default to one self-contained HTML file with inline CSS and JS.\n2. **Viewport fit is mandatory**: every slide must fit inside one viewport with no internal scrolling.\n3. **Show, don''t tell**: use visual previews instead of abstract style questionnaires.\n4. **Distinctive design**: avoid generic purple-gradient, Inter-on-white, template-looking decks.\n5. **Production quality**: keep code commented, accessible, responsive, and performant.\n\nBefore generating, read `STYLE_PRESETS.md` for the viewport-safe CSS base, density limits, preset catalog, and CSS gotchas.\n\n## Workflow\n\n### 1. Detect Mode\n\nChoose one path:\n- **New presentation**: user has a topic, notes, or full draft\n- **PPT conversion**: user has `.ppt` or `.pptx`\n- **Enhancement**: user already has HTML slides and wants improvements\n\n### 2. Discover Content\n\nAsk only the minimum needed:\n- purpose: pitch, teaching, conference talk, internal update\n- length: short (5-10), medium (10-20), long (20+)\n- content state: finished copy, rough notes, topic only\n\nIf the user has content, ask them to paste it before styling.\n\n### 3. Discover Style\n\nDefault to visual exploration.\n\nIf the user already knows the desired preset, skip previews and use it directly.\n\nOtherwise:\n1. Ask what feeling the deck should create: impressed, energized, focused, inspired.\n2. Generate **3 single-slide preview files** in `.ecc-design/slide-previews/`.\n3. Each preview must be self-contained, show typography/color/motion clearly, and stay under roughly 100 lines of slide content.\n4. Ask the user which preview to keep or what elements to mix.\n\nUse the preset guide in `STYLE_PRESETS.md` when mapping mood to style.\n\n### 4. Build the Presentation\n\nOutput either:\n- `presentation.html`\n- `[presentation-name].html`\n\nUse an `assets/` folder only when the deck contains extracted or user-supplied images.\n\nRequired structure:\n- semantic slide sections\n- a viewport-safe CSS base from `STYLE_PRESETS.md`\n- CSS custom properties for theme values\n- a presentation controller class for keyboard, wheel, and touch navigation\n- Intersection Observer for reveal animations\n- reduced-motion support\n\n### 5. Enforce Viewport Fit\n\nTreat this as a hard gate.\n\nRules:\n- every `.slide` must use `height: 100vh; height: 100dvh; overflow: hidden;`\n- all type and spacing must scale with `clamp()`\n- when content does not fit, split into multiple slides\n- never solve overflow by shrinking text below readable sizes\n- never allow scrollbars inside a slide\n\nUse the density limits and mandatory CSS block in `STYLE_PRESETS.md`.\n\n### 6. Validate\n\nCheck the finished deck at these sizes:\n- 1920x1080\n- 1280x720\n- 768x1024\n- 375x667\n- 667x375\n\nIf browser automation is available, use it to verify no slide overflows and that keyboard navigation works.\n\n### 7. Deliver\n\nAt handoff:\n- delete temporary preview files unless the user wants to keep them\n- open the deck with the platform-appropriate opener when useful\n- summarize file path, preset used, slide count, and easy theme customization points\n\nUse the correct opener for the current OS:\n- macOS: `open file.html`\n- Linux: `xdg-open file.html`\n- Windows: `start \"\" file.html`\n\n## PPT / PPTX Conversion\n\nFor PowerPoint conversion:\n1. Prefer `python3` with `python-pptx` to extract text, images, and notes.\n2. If `python-pptx` is unavailable, ask whether to install it or fall back to a manual/export-based workflow.\n3. Preserve slide order, speaker notes, and extracted assets.\n4. After extraction, run the same style-selection workflow as a new presentation.\n\nKeep conversion cross-platform. Do not rely on macOS-only tools when Python can do the job.\n\n## Implementation Requirements\n\n### HTML / CSS\n\n- Use inline CSS and JS unless the user explicitly wants a multi-file project.\n- Fonts may come from Google Fonts or Fontshare.\n- Prefer atmospheric backgrounds, strong type hierarchy, and a clear visual direction.\n- Use abstract shapes, gradients, grids, noise, and geometry rather than illustrations.\n\n### JavaScript\n\nInclude:\n- keyboard navigation\n- touch / swipe navigation\n- mouse wheel navigation\n- progress indicator or slide index\n- reveal-on-enter animation triggers\n\n### Accessibility\n\n- use semantic structure (`main`, `section`, `nav`)\n- keep contrast readable\n- support keyboard-only navigation\n- respect `prefers-reduced-motion`\n\n## Content Density Limits\n\nUse these maxima unless the user explicitly asks for denser slides and readability still holds:\n\n| Slide type | Limit |\n|------------|-------|\n| Title | 1 heading + 1 subtitle + optional tagline |\n| Content | 1 heading + 4-6 bullets or 2 short paragraphs |\n| Feature grid | 6 cards max |\n| Code | 8-10 lines max |\n| Quote | 1 quote + attribution |\n| Image | 1 image constrained by viewport |\n\n## Anti-Patterns\n\n- generic startup gradients with no visual identity\n- system-font decks unless intentionally editorial\n- long bullet walls\n- code blocks that need scrolling\n- fixed-height content boxes that break on short screens\n- invalid negated CSS functions like `-clamp(...)`\n\n## Related ECC Skills\n\n- `frontend-patterns` for component and interaction patterns around the deck\n- `liquid-glass-design` when a presentation intentionally borrows Apple glass aesthetics\n- `e2e-testing` if you need automated browser verification for the final deck\n\n## Deliverable Checklist\n\n- presentation runs from a local file in a browser\n- every slide fits the viewport without scrolling\n- style is distinctive and intentional\n- animation is meaningful, not noisy\n- reduced motion is respected\n- file paths and customization points are explained at handoff\n"},"category":"official","lastSynced":"2026-03-06T04:12:31.960Z","seo":{"title":{"en":"frontend-slides: Create Stunning HTML Presentations | AI ...","zh":"Frontend Slides 设计指南 - 创建动画丰富的 HTML 演示文稿","ja":"Frontend Slides セットアップガイド - アニメーション豊かな HTML プレゼンテーションを作成","ko":"Frontend Slides 설정 가이드 - 애니메이션 풍부한 HTML 프레젠테이션 생성","es":"frontend-slides: Guía para crear presentaciones HTML con ...","fr":"frontend-slides: Guide pour créer des présentations HTML ...","de":"frontend-slides: Anleitung für animierte HTML-Präsentationen","pt":"frontend-slides: Guia para Criar Apresentações HTML com A...","ru":"frontend-slides: Руководство по созданию анимированных HT...","ar":"frontend-slides: دليل إنشاء عروض HTML تفاعلية باستخدام أد..."},"description":{"en":"Unlock visually stunning presentations with frontend-slides. Convert PPT/PPTX to HTML, create interactive slides, and discover your aesthetic with ease. Get ...","zh":"使用 Frontend Slides 创建动画丰富的 HTML 演示文稿，从零开始或从 PowerPoint 文件转换。提高您的演示文稿设计水平","ja":"Frontend Slides を使用して、アニメーション豊かな HTML プレゼンテーションを作成します。PowerPoint ファイルから変換することもできます","ko":"Frontend Slides를 사용하여 애니메이션 풍부한 HTML 프레젠테이션을 생성하십시오. 파워포인트 파일에서 변환도 가능합니다","es":"Crea presentaciones HTML con animaciones avanzadas sin dependencias externas. Convierte archivos PPT/PPTX a web y mejora el diseño con AI Agents. Herramienta...","fr":"Créez des présentations HTML avec des animations avancées sans dépendances externes. Convertissez des fichiers PPT/PPTX en web et améliorez le design avec de...","de":"Erstellen Sie HTML-Präsentationen mit erweiterten Animationen ohne externe Abhängigkeiten. Konvertieren Sie PPT/PPTX-Dateien ins Web und verbessern Sie das D...","pt":"Use o agente de IA frontend-slides para converter PPT/PPTX em HTML ou criar apresentações com animações ricas sem dependências. Ideal para pitch decks e pale...","ru":"Используйте ИИ агент frontend-slides для преобразования PPT/PPTX в HTML и создания анимированных презентаций без зависимостей. Идеально для питч-деков и выст...","ar":"استخدم أداة الذكاء الاصطناعي frontend-slides لتحويل ملفات PPT/PPTX إلى HTML وإنشاء عروض تقديمية غنية بالرسوم المتحركة بدون تبعيات. مثالي لعروض البيتش والمحاض..."},"definition":{"en":"frontend-slides is a skill that creates interactive, animation-rich HTML presentations from scratch or by converting PowerPoint files, inspired by visual exploration approaches.","zh":"Frontend Slides 是一个创建动画丰富的 HTML 演示文稿的工具，使用零依赖的 HTML 和 CSS 实现","ja":"Frontend Slides は、アニメーション豊かな HTML プレゼンテーションを作成するためのツールで、ゼロ依存の HTML と CSS を使用します","ko":"Frontend Slides는 애니메이션 풍부한 HTML 프레젠테이션을 생성하는 툴로, 제로 의존성 HTML과 CSS를 사용합니다","es":"frontend-slides es un AI Agent especializado en crear presentaciones HTML con animaciones avanzadas que se ejecutan completamente en el navegador. Convierte archivos PPT/PPTX a formato web y ayuda a explorar estilos visuales mediante un enfoque de exploración visual en lugar de opciones abstractas.","fr":"frontend-slides est un Agent IA spécialisé dans la création de présentations HTML avec des animations avancées fonctionnant entièrement dans le navigateur. Convertit les fichiers PPT/PPTX au format web et aide à explorer les styles visuels via une approche d''exploration visuelle plutôt que des choix abstraits.","de":"frontend-slides ist ein KI-Agent, der spezialisiert ist auf die Erstellung von HTML-Präsentationen mit erweiterten Animationen, die vollständig im Browser laufen. Konvertiert PPT/PPTX-Dateien ins Web-Format und hilft bei der Erkundung visueller Stile durch einen visuellen Explorationsansatz statt abstrakter Wahlmöglichkeiten.","pt":"frontend-slides é um agente de IA especializado em criar apresentações HTML com animações ricas e zero dependências. Converte arquivos PowerPoint em código web e facilita a exploração visual de estilos para desenvolvedores.","ru":"frontend-slides - это ИИ агент для создания анимированных HTML-презентаций без зависимостей. Преобразует файлы PowerPoint в веб-код и помогает визуально исследовать стили для разработчиков.","ar":"frontend-slides هو أداة ذكاء اصطناعي متخصصة في إنشاء عروض HTML تفاعلية غنية بالرسوم المتحركة بدون تبعيات. يحول ملفات PowerPoint إلى كود ويب ويساعد في استكشاف الأنماط البصرية للمطورين."},"features":{"en":["Creates zero-dependency, animation-rich HTML presentations that run entirely in the browser","Converts .ppt or .pptx slides into HTML presentations","Improves existing HTML presentation''s layout, motion, or typography","Supports visual exploration for non-designers to discover their aesthetic","Inspired by the work of zarazhangrui, providing a unique design approach"],"zh":["创建动画丰富的 HTML 演示文稿","支持从 PowerPoint 文件转换","使用零依赖的 HTML 和 CSS","提高演示文稿设计水平","支持多种动画效果"],"ja":["アニメーション豊かな HTML プレゼンテーションを作成","PowerPoint ファイルから変換することができます","ゼロ依存の HTML と CSS を使用","プレゼンテーションデザインのレベルを上げる","複数のアニメーション効果に対応"],"ko":["애니메이션 풍부한 HTML 프레젠테이션 생성","파워포인트 파일에서 변환 가능","제로 의존성 HTML과 CSS 사용","프레젠테이션 디자인 레벨 업","다중 애니메이션 효과 지원"],"es":["Generación de presentaciones HTML sin dependencias externas","Conversión nativa de archivos PPT/PPTX a formato web","Animaciones avanzadas que se ejecutan completamente en el navegador","Exploración visual de estilos para no diseñadores","Mejora de presentaciones HTML existentes en diseño y tipografía","Creación de pitch decks y talk decks con enfoque visual"],"fr":["Génération de présentations HTML sans dépendances externes","Conversion native des fichiers PPT/PPTX au format web","Animations avancées fonctionnant entièrement dans le navigateur","Exploration visuelle des styles pour les non-designers","Amélioration des présentations HTML existantes en design et typographie","Création de pitch decks et talk decks avec approche visuelle"],"de":["Generierung von HTML-Präsentationen ohne externe Abhängigkeiten","Native Konvertierung von PPT/PPTX-Dateien ins Web-Format","Erweiterte Animationen, die vollständig im Browser laufen","Visuelle Stilerkundung für Nicht-Designer","Verbesserung bestehender HTML-Präsentationen in Design und Typografie","Erstellung von Pitch Decks und Talk Decks mit visuellem Ansatz"],"pt":["Conversão de PPT/PPTX para HTML sem dependências externas","Animações ricas executadas diretamente no navegador","Exploração visual de estilos para não-designers","Criação de apresentações para talks, pitches e workshops","Melhoria de layouts, motion e tipografia existentes"],"ru":["Преобразование PPT/PPTX в HTML без внешних зависимостей","Богатая анимация, работающая непосредственно в браузере","Визуальное исследование стилей для нон-дизайнеров","Создание презентаций для выступлений и питчей","Улучшение существующих макетов и типографики"],"ar":["تحويل PPT/PPTX إلى HTML بدون تبعيات خارجية","رسوم متحركة غنية تعمل مباشرة في المتصفح","استكشاف بصري للأنماط لغير المصممين","إنشاء عروض للمحاضرات وعروض البيتش","تحسين التخطيطات والحركة والطباعة الموجودة"]},"keywords":{"en":["how to use frontend-slides","frontend-slides alternative","frontend-slides setup guide","convert PPT to HTML","create interactive slides","frontend-slides vs PowerPoint","visual exploration in presentation design","zero-dependency HTML presentations","animation-rich HTML slides"],"zh":["Frontend Slides","AI エージェント","HTML 演示文稿","PowerPoint 转换","零依赖 HTML","CSS 动画","前端开发工具"],"ja":["Frontend Slides","AI エージェント","HTML プレゼンテーション","PowerPoint 変換","ゼロ依存 HTML","CSS アニメーション","フロントエンド開発ツール"],"ko":["Frontend Slides","AI 에이전트","HTML 프레젠테이션","파워포인트 변환","제로 의존성 HTML","CSS 애니메이션","프론트엔드 개발 툴"],"es":["presentaciones HTML animadas","convertir PPT a HTML","AI Agents para desarrolladores","herramientas de presentación web","animaciones CSS avanzadas","pitch deck HTML","conversor PowerPoint web","presentaciones sin dependencias"],"fr":["présentations HTML animées","convertir PPT en HTML","outils IA pour développeurs","outils de présentation web","animations CSS avancées","pitch deck HTML","convertisseur PowerPoint web","présentations sans dépendances"],"de":["animierte HTML Präsentationen","PPT zu HTML konvertieren","KI-Tools für Entwickler","Web Präsentationstools","erweiterte CSS Animationen","HTML Pitch Deck","PowerPoint Web Konverter","präsentationen ohne abhängigkeiten"],"pt":["agente IA converter PowerPoint HTML","apresentações HTML sem dependências","animations rich browser presentations","converter PPTX para web","ferramenta desenvolvedor apresentações","frontend-slides MCP agent","Claude Code apresentações","criar pitch deck HTML"],"ru":["ИИ агент конвертер PowerPoint HTML","HTML презентации без зависимостей","анимированные браузерные презентации","конвертировать PPTX в веб","инструмент разработчика презентаций","frontend-slides MCP агент","Claude Code презентации","создать питч дек HTML"],"ar":["أداة ذكاء اصطناعي لتحويل PowerPoint إلى HTML","عروض HTML بدون تبعيات","عروض متصفح غنية بالرسوم المتحركة","تحويل PPTX إلى ويب","أداة مطور للعروض التقديمية","frontend-slides أداة MCP","عروض Claude Code","إنشاء عرض بيتش بـ HTML"]}},"agentAnalysis":{"suitability":{"en":"Ideal for Presentation Agent personas needing to generate browser-native, animation-rich HTML slides from scratch or PowerPoint conversions.","zh":"非常适合需要从头开始生成浏览器原生、动画丰富的HTML幻灯片或进行PowerPoint转换的Presentation Agent角色。","ja":"PowerPoint変換やゼロからブラウザネイティブでアニメーション豊富なHTMLスライドを生成する必要があるPresentation Agentペルソナに理想的です。","ko":"PowerPoint 변환이나 처음부터 브라우저 기본, 애니메이션이 풍부한 HTML 슬라이드를 생성해야 하는 Presentation Agent 페르소나에 이상적입니다.","es":"Ideal para agentes de presentación que necesitan generar diapositivas HTML nativas del navegador, ricas en animaciones, desde cero o conversiones de PowerPoint.","fr":"Idéal pour les agents de présentation ayant besoin de générer des diapositives HTML natives au navigateur, riches en animations, à partir de zéro ou de conversions PowerPoint.","de":"Ideal für Präsentations-Agenten, die browser-native, animationsreiche HTML-Folien von Grund auf oder aus PowerPoint-Konvertierungen generieren müssen.","pt":"Ideal para personagens de Agente de Apresentação que precisam gerar slides HTML nativos do navegador, ricos em animação, do zero ou conversões do PowerPoint.","ru":"Идеально подходит для персонажей агента презентации, которым необходимо генерировать родные для браузера HTML-слайды с богатой анимацией с нуля или конвертировать их из PowerPoint.","ar":"مثالي لشخصيات وكيل العرض التي تحتاج إلى توليد شرائح HTML أصلية للمتصفح ، غنية بالرسوم المتحركة من الصفر أو تحويلات PowerPoint."},"recommendation":{"en":"Empowers agents to create zero-dependency HTML presentations with rich animations that run entirely in the browser, bypassing design tools by enabling visual exploration for non-designers.","zh":"使Agent能够创建零依赖、动画丰富的HTML演示文稿，完全在浏览器中运行，通过为非设计人员启用可视化探索来绕过设计工具。","ja":"非デザイナー向けのビジュアル探索を可能にすることでデザインツールをバイパスし、ブラウザ内で完全に動作するゼロ依存のアニメーション豊富なHTMLプレゼンテーションをAgentが作成できるようにします。","ko":"비디자이너를 위한 시각적 탐색을 가능하게 하여 디자인 도구를 우회함으로써, 완전히 브라우저에서 실행되는 제로 의존성의 애니메이션이 풍부한 HTML 프레젠테이션을 Agent가 생성할 수 있도록 합니다.","es":"Permite a los agentes crear presentaciones HTML sin dependencias externas con animaciones ricas que se ejecutan completamente en el navegador, evitando herramientas de diseño al permitir la exploración visual para no diseñadores.","fr":"Permet aux agents de créer des présentations HTML sans dépendances externes avec des animations riches qui s''exécutent entièrement dans le navigateur, contournant les outils de conception en permettant l''exploration visuelle pour les non-concepteurs.","de":"Ermöglicht Agenten die Erstellung von HTML-Präsentationen ohne externe Abhängigkeiten mit reichhaltigen Animationen, die vollständig im Browser laufen, wodurch Design-Tools umgangen werden, indem visuelle Erkundung für Nicht-Designer ermöglicht wird.","pt":"Habilita os agentes a criar apresentações HTML sem dependência, com animações ricas que são executadas entirely no navegador, ignorando as ferramentas de design e permitindo a exploração visual para não-designers.","ru":"Наделяет агентов возможностью создавать презентации HTML без внешних зависимостей, с богатой анимацией, которая работает полностью в браузере, минуя инструменты дизайна и позволяя визуальное исследование для не-дизайнеров.","ar":"تمكين الوكلاء من إنشاء عروض HTML دون اعتمادية ، مع رسوم متحركة غنية التي تعمل بالكامل في المتصفح ، وتجاوز أدوات التصميم وتتمكن من الاستكشاف البصري للغير مصممين."},"useCases":{"en":["Converting .ppt/.pptx files into web-native HTML presentations","Generating animation-rich talk or pitch decks from scratch","Improving existing HTML presentations'' layout, motion, and typography"],"zh":[".ppt/.pptx 파일을 웹 네이티브 HTML 프레젠테이션으로 변환","처음부터 애니메이션이 풍부한 토크 또는 피치 데크 생성","기존 HTML 프레젠테이션의 레이아웃, 모션 및 타이포그래피 개선"],"ja":[".ppt/.pptxファイルをウェブネイティブなHTMLプレゼンテーションに変換","ゼロからアニメーション豊富なトークやピッチデッキを生成","既存のHTMLプレゼンテーションのレイアウト、モーション、タイポグラフィを改善"],"ko":[".ppt/.pptx 파일을 웹 네이티브 HTML 프레젠테이션으로 변환","처음부터 애니메이션이 풍부한 토크 또는 피치 데크 생성","기존 HTML 프레젠테이션의 레이아웃, 모션 및 타이포그래피 개선"],"es":["Convertir archivos .ppt/.pptx en presentaciones HTML nativas de la web","Generar decks de charlas o presentaciones ricos en animaciones desde cero","Mejorar el diseño, el movimiento y la tipografía de presentaciones HTML existentes"],"fr":["Convertir des fichiers .ppt/.ppx en présentations HTML natives du web","Générer des decks de présentation ou de pitch riches en animations à partir de zéro","Améliorer la mise en page, le mouvement et la typographie des présentations HTML existantes"],"de":[".ppt/.ppx-Dateien in web-native HTML-Präsentationen umwandeln","Animationsreiche Vortrags- oder Pitch-Decks von Grund auf generieren","Layout, Bewegung und Typografie bestehender HTML-Präsentationen verbessern"],"pt":["Conversão de arquivos .ppt/.pptx em apresentações HTML nativas da web","Geração de decks de apresentação ou pitch ricos em animação do zero","Melhoria do layout, movimento e tipografia de apresentações HTML existentes"],"ru":["Преобразование файлов .ppt/.pptx в веб-родные презентации HTML","Генерация презентационных или питч-деcks с богатой анимацией с нуля","Улучшение макета, движения и типографики существующих презентаций HTML"],"ar":["تحويل ملفات .ppt/.pptx إلى عروض HTML أصلية على الويب","توليد عروض أو شرائح متحركة غنية من الصفر","تحسين تخطيط وحركة وطباعة عروض HTML الحالية"]},"limitations":{"en":["Handles PowerPoint conversion but focuses primarily on HTML output","Designed for browser execution without external dependencies"],"zh":["PowerPoint 변환을 처리하지만 주로 HTML 출력에 중점을 둠","외부 종속성 없이 브라우저 실행을 위해 설계됨"],"ja":["PowerPoint変換を処理するが、主にHTML出力に重点を置いている","外部依存関係なしのブラウザ実行用に設計されている"],"ko":["PowerPoint 변환을 처리하지만 주로 HTML 출력에 중점을 둠","외부 종속성 없이 브라우저 실행을 위해 설계됨"],"es":["Maneja la conversión de PowerPoint pero se centra principalmente en la salida HTML","Diseñado para su ejecución en el navegador sin dependencias externas"],"fr":["Gère la conversion PowerPoint mais se concentre principalement sur la sortie HTML","Conçu pour une exécution dans le navigateur sans dépendances externes"],"de":["Bewältigt PowerPoint-Konvertierung, konzentriert sich aber primär auf die HTML-Ausgabe","Für die Ausführung im Browser ohne externe Abhängigkeiten konzipiert"],"pt":["Lida com a conversão do PowerPoint, mas se concentra principalmente na saída HTML","Projetado para execução no navegador sem dependências externas"],"ru":["Обрабатывает конверсию PowerPoint, но фокусируется в основном на выходе HTML","Разработан для выполнения в браузере без внешних зависимостей"],"ar":["يتعامل مع تحويل PowerPoint ، ولكن يركز بشكل رئيسي على الإخراج HTML","مصمم لتنفيذ في المتصفح بدون اعتمادية خارجية"]},"version":4},"contentHash":"bc890c0deeb766e78991d6de150fd981a70b3dac5507a4d20b43c1a210b1819d","repoEtag":"W/\"17419377ef7f2503c42e281412122ddeab8c81f4b1318b553fe11e1d0191022f\"","qualityScore":67}');
