INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ArtemYurov/TomoBar/aif-fix', 'aif-fix', 'ArtemYurov', 'TomoBar', 'community', 'aif-fix ArtemYurov TomoBar community macos-app macos-application macos-menubar macos-menubar-application menubar-app menubar-timer pomodoro pomodoro-app pomodoro-clock pomodoro-technique pomodoro-timer productivity timer timer-app timer-application aif-fix is a flexible Pomodoro focus timer for MacOS menu bar that supports immediate fix or plan-first approaches for bug fixing. It benefits developers by streamlining their workflow. aif-fix 是一个 macOS 菜单栏的 Pomodoro 定时器，帮助您提高生产力。它支持即时修复和计划优先的方法 aif-fix は、macOS メニューバー用の Pomodoro タイマーです。生産性を向上させるために即時修復や計画優先の方法をサポートします aif-fix는 macOS 메뉴 바용 Pomodoro 타이머로 생산성을 높여줍니다. 즉시 수정 및 계획 우선 접근 방식을 지원합니다 aif-fix es una herramienta de temporizador Pomodoro flexible para MacOS que te ayuda a mejorar tu productividad. Con su tecnología de temporización avanzada, puedes trabajar de manera más eficiente aif-fix est un outil de temporisation Pomodoro flexible pour MacOS qui vous aide à améliorer votre productivité. Avec sa technologie de temporisation avancée, vous pouvez travailler de manière plus efficace aif-fix ist ein flexibles Pomodoro-Timer-Tool für MacOS, das Ihnen hilft, Ihre Produktivität zu verbessern. Mit seiner fortschrittlichen Zeitmess-Technologie können Sie effizienter arbeiten O aif-fix é uma ferramenta de timer Pomodoro para MacOS que ajuda a melhorar a produtividade. Ele oferece um fluxo de trabalho de correção de bugs com duas modalidades: correção imediata ou abordagem planejada. aif-fix - это инструмент таймера Помодоро для MacOS, который помогает повысить производительность. Он предлагает рабочий процесс исправления ошибок с двумя режимами: немедленное исправление или планируемый подход. aif-fix هو أداة مؤقت بومودورو لماكوس التي تساعد على تحسين الإنتاجية. يقدم سير عمل لتصحيح الأخطاء بطريقتين: تصحيح فوري أو نهج مخطط how to use aif-fix aif-fix alternative aif-fix setup guide what is aif-fix aif-fix vs pomodoro timers install aif-fix on MacOS aif-fix macOS 菜单栏 Pomodoro 定时器 AI 工具 生产力提高 即时修复 计划优先 macOS 应用 Checks for existing fix plans in .ai-factory/FIX_PLAN.md Executes fixes based on predefined plans, skipping unnecessary steps Supports two modes: immediate fix or plan-first approach Investigates the codebase using the plan as a guide Informs the user of existing fix plans and execution progress aif-fix is a MacOS menubar application that implements the Pomodoro technique for focused bug fixing, utilizing a flexible timer and plan-first approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yi-john-huang/sdd-mcp/simple-task', 'community', 'yi-john-huang', 'sdd-mcp', 'yi-john-huang/sdd-mcp', 'simple-task', 35, 3, 65, '2026-02-08T00:07:58Z', '2026-03-06T06:37:28.149Z', '9c99da4c3560fe00cd1e96cf344ebea272f99496e68633e40915ceaae8795358', '{"id":"yi-john-huang/sdd-mcp/simple-task","name":"simple-task","description":{"en":"The simple-task skill implements small features, bug fixes, or quick enhancements while following best practices. It benefits developers working on AI agent projects.","zh":"简单任务是指在项目中实现小功能、修复bug和快速增强的过程，遵循项目的指导文档","ja":"シンプルタスクは、小さな機能の追加、バグの修正、クイックリファクタリングを行うプロセスです","ko":"심플 태스크는 프로젝트의 가이드라인을 따라 작은 기능 추가, 버그 수정, 빠른 리팩토링을 수행하는 프로세스입니다","es":"La implementación de tareas simples es un proceso que sigue las mejores prácticas para agregar funciones, arreglar errores y mejorar el código","fr":"L''implémentation de tâches simples est un processus qui suit les meilleures pratiques pour ajouter des fonctionnalités, corriger des erreurs et améliorer le code","de":"Die Implementierung von einfachen Aufgaben ist ein Prozess, der die besten Praktiken für die Hinzufügung von Funktionen, die Korrektur von Fehlern und die Verbesserung des Codes befolgt","pt":"O Simple Task é uma ferramenta para implementar pequenas funcionalidades, correções de bugs e melhorias rápidas, seguindo as melhores práticas do projeto","ru":"Simple Task - это инструмент для реализации небольших функций, исправления ошибок и быстрого улучшения, следуя лучшим практикам проекта","ar":"أداة المهام البسيطة هي أداة لتنفيذ الميزات الصغيرة وتصحيح الأخطاء والتحسين السريع، متبعًا أفضل الممارسات للمشروع"},"seo":{"title":{"en":"simple-task: Implementation Guide for AI Agents","zh":"简单任务设置指南 - AIエージェント","ja":"シンプルタスクのベストプラクティス - AIエージェント","ko":"심플 태스크 구현 가이드 - AI 에이전트","es":"Guía de Implementación de Tareas Simples con Herramientas...","fr":"Guide d''Implémentation de Tâches Simples avec Outils d''IA","de":"Leitfaden für die Implementierung von Einfachen Aufgaben ...","pt":"Guia de Configuração do Simple Task para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке Simple Task","ar":"دليل إعداد أداة المهام البسيطة للمطورين"},"description":{"en":"Discover how to use simple-task for small feature additions, bug fixes, and minor enhancements. Learn the best practices and workflow for AI agents.","zh":"了解如何使用简单任务实现小功能、修复bug和快速增强，遵循项目的指导文档","ja":"プロジェクトのガイドラインに従って、小さな機能の追加、バグの修正、クイックリファクタリングを行う方法を学びます","ko":"프로젝트의 가이드라인을 따라 작은 기능 추가, 버그 수정, 빠른 리팩토링을 수행하는 방법을 알아보세요","es":"Aprende a implementar tareas simples con herramientas de AI, siguiendo las mejores prácticas para agregar funciones, arreglar errores y mejorar el código","fr":"Découvrez comment implémenter des tâches simples avec des outils d''IA, en suivant les meilleures pratiques pour ajouter des fonctionnalités, corriger des err...","de":"Erfahren Sie, wie Sie einfache Aufgaben mit KI-Tools implementieren, indem Sie die besten Praktiken für die Hinzufügung von Funktionen, die Korrektur von Feh...","pt":"Aprenda a implementar pequenas funcionalidades e correções de bugs com o Simple Task, seguindo as melhores práticas do projeto","ru":"Узнайте, как реализовать небольшие функции и исправить ошибки с помощью Simple Task, следуя лучшим практикам проекта","ar":"تعرف على كيفية تنفيذ الميزات الصغيرة وتصحيح الأخطاء باستخدام أداة المهام البسيطة، متبعًا أفضل الممارسات للمشروع"},"definition":{"en":"simple-task is a skill that enables the implementation of small features, bug fixes, or quick enhancements in AI agent projects","zh":"简单任务是指遵循项目指导文档，实现小功能、修复bug和快速增强的AIエージェント功能","ja":"シンプルタスクは、プロジェクトのガイドラインに従って、小さな機能の追加、バグの修正、クイックリファクタリングを行うAIエージェントの機能です","ko":"심플 태스크는 프로젝트의 가이드라인을 따라 작은 기능 추가, 버그 수정, 빠른 리팩토링을 수행하는 AI 에이전트의 기능입니다","es":"Una tarea simple es una función o característica que se puede implementar siguiendo un conjunto de prácticas y directrices establecidas","fr":"Une tâche simple est une fonctionnalité ou une caractéristique qui peut être implémentée en suivant un ensemble de pratiques et de directives établies","de":"Eine einfache Aufgabe ist eine Funktion oder ein Merkmal, das implementiert werden kann, indem ein Satz von Praktiken und Richtlinien befolgt wird","pt":"O Simple Task é uma técnica de desenvolvimento para implementar pequenas funcionalidades e correções de bugs de forma rápida e eficiente","ru":"Simple Task - это методология разработки для реализации небольших функций и исправления ошибок быстро и эффективно","ar":"أداة المهام البسيطة هي تقنية تطوير لتنفيذ الميزات الصغيرة وتصحيح الأخطاء بسرعة وكفاءة"},"features":{"en":["Implements small feature additions using /simple-task command","Supports bug fixes and minor enhancements","Follows best practices from project''s steering documents","Uses full SDD workflow for complex features","Enables quick refactoring for improved code quality","Facilitates minor enhancements without formal requirements review"],"zh":["小功能添加（例如添加退出按钮）","bug修复","快速增强","遵循项目指导文档","适用于小规模的功能实现","支持快速迭代开发"],"ja":["小さな機能の追加（例：ログアウトボタンの追加）","バグの修正","クイックリファクタリング","プロジェクトのガイドラインに従った開発","小規模な機能実装に適している","クイックイテレーション開発をサポート"],"ko":["작은 기능 추가（예：로그아웃 버튼 추가）","버그 수정","빠른 리팩토링","프로젝트의 가이드라인을 따라 개발","소규모 기능 구현에 적합","빠른 반복 개발을 지원"],"es":["Agregar funciones pequeñas como un botón de cierre de sesión","Arreglar errores y mejorar el código","Realizar refactorizaciones rápidas","Seguir las mejores prácticas de la documentación del proyecto","Utilizar el flujo de trabajo de SDD para tareas complejas"],"fr":["Ajouter des fonctionnalités petites comme un bouton de déconnexion","Corriger des erreurs et améliorer le code","Réalisé des refactorisations rapides","Suivre les meilleures pratiques de la documentation du projet","Utiliser le flux de travail de SDD pour les tâches complexes"],"de":["Hinzufügen von kleinen Funktionen wie einem Abmelden-Button","Korrigieren von Fehlern und Verbesserung des Codes","Durchführen von schnellen Refactorings","Befolgen der besten Praktiken der Projektdokumentation","Verwenden des SDD-Workflows für komplexe Aufgaben"],"pt":["Implementação de pequenas funcionalidades","Correção de bugs","Melhorias rápidas","Refatoração de código","Seguimento das melhores práticas do projeto"],"ru":["Реализация небольших функций","Исправление ошибок","Быстрое улучшение","Рефакторинг кода","Следование лучшим практикам проекта"],"ar":["تنفيذ الميزات الصغيرة","تصحيح الأخطاء","التحسين السريع","إعادة هيكلة الكود","اتباع أفضل الممارسات للمشروع"]},"keywords":{"en":["how to use simple-task","simple-task alternative","simple-task setup guide","what is simple-task","simple-task vs full SDD workflow","simple-task implementation best practices","simple-task install","simple-task for AI agents"],"zh":["AIエージェント","简单任务","小功能添加","bug修复","快速增强","项目指导文档","快速迭代开发","小规模功能实现"],"ja":["AIエージェント","シンプルタスク","小さな機能の追加","バグの修正","クイックリファクタリング","プロジェクトのガイドライン","クイックイテレーション開発","小規模な機能実装"],"ko":["AI 에이전트","심플 태스크","작은 기능 추가","버그 수정","빠른 리팩토링","프로젝트의 가이드라인","빠른 반복 개발","소규모 기능 구현"],"es":["herramientas de AI","implementación de tareas simples","mejores prácticas de código","agregar funciones","arreglar errores","refactorizar código","flujo de trabajo de SDD","desarrollo de software"],"fr":["outils d''IA","implémentation de tâches simples","meilleures pratiques de code","ajouter des fonctionnalités","corriger des erreurs","réfactoriser du code","flux de travail de SDD","développement de logiciels"],"de":["KI-Tools","Implementierung von einfachen Aufgaben","beste Praktiken für Code","Hinzufügen von Funktionen","Korrigieren von Fehlern","Refaktorisieren von Code","SDD-Workflow","Software-Entwicklung"],"pt":["Simple Task","desenvolvimento de software","melhores práticas","implementação de funcionalidades","correção de bugs","refatoração de código","desenvolvedores","ferramentas de desenvolvimento"],"ru":["Simple Task","ИИ Агенты","разработка программного обеспечения","лучшие практики","реализация функций","исправление ошибок","рефакторинг кода","разработчики","инструменты разработки"],"ar":["أداة المهام البسيطة","أدوات الذكاء الاصطناعي","تطوير البرمجيات","أفضل الممارسات","تنفيذ الميزات","تصحيح الأخطاء","إعادة هيكلة الكود","المطورون","أدوات التطوير"]}},"owner":"yi-john-huang","repo":"sdd-mcp","repoPath":"yi-john-huang/sdd-mcp","stars":35,"forks":3,"updatedAt":"2026-02-08T00:07:58Z","topics":[],"category":"community","skillMd":{"name":"simple-task","description":"Implement simple features with best practices. Use when adding small features, bug fixes, or quick enhancements without the full SDD workflow. Invoked via /simple-task <description>.","bodyPreview":"# Simple Task Implementation\n\nImplement small features, bug fixes, or quick enhancements while following best practices from the project''s steering documents.\n\n## When to Use\n\nUse `/simple-task` for:\n- Small feature additions (e.g., \"add logout button\")\n- Bug fixes\n- Minor enhancements\n- Quick refactoring\n\nUse **full SDD workflow** for:\n- Complex features requiring multiple components\n- New modules or subsystems\n- Features needing formal requirements/design review\n\n## Workflow\n\n### Step 1: Under","body":"# Simple Task Implementation\n\nImplement small features, bug fixes, or quick enhancements while following best practices from the project''s steering documents.\n\n## When to Use\n\nUse `/simple-task` for:\n- Small feature additions (e.g., \"add logout button\")\n- Bug fixes\n- Minor enhancements\n- Quick refactoring\n\nUse **full SDD workflow** for:\n- Complex features requiring multiple components\n- New modules or subsystems\n- Features needing formal requirements/design review\n\n## Workflow\n\n### Step 1: Understand the Task\n\n1. Clarify what needs to be done\n2. Identify affected files/components\n3. Estimate scope (if larger than expected, suggest full SDD workflow)\n\n### Step 2: Apply TDD (Test-Driven Development)\n\n**Reference:** `.spec/steering/tdd-guideline.md`\n\nFollow the Red-Green-Refactor cycle:\n\n```\n1. RED    → Write a failing test first\n2. GREEN  → Write minimal code to pass\n3. REFACTOR → Clean up while tests pass\n```\n\n**Quick TDD Checklist:**\n- [ ] Write test before implementation\n- [ ] Test describes expected behavior\n- [ ] Minimal code to make test pass\n- [ ] Refactor without breaking tests\n\n### Step 3: Apply Design Principles\n\n**Reference:** `.spec/steering/principles.md`\n\n**SOLID Quick Reference:**\n- **S**ingle Responsibility: Each function/class does one thing\n- **O**pen/Closed: Extend behavior without modifying existing code\n- **L**iskov Substitution: Subtypes must be substitutable\n- **I**nterface Segregation: Small, focused interfaces\n- **D**ependency Inversion: Depend on abstractions\n\n**Other Principles:**\n- **DRY**: Don''t repeat yourself - extract common logic\n- **KISS**: Keep it simple - avoid unnecessary complexity\n- **YAGNI**: You aren''t gonna need it - only implement what''s required\n\n### Step 4: Code Quality Review\n\n**Reference:** `.spec/steering/linus-review.md`\n\nBefore finalizing, ask:\n1. **Taste**: Is the solution elegant? Can special cases be eliminated?\n2. **Simplicity**: Can it be simpler? Fewer lines? Less nesting?\n3. **Data Structures**: Is the right data structure used?\n4. **Breaking Changes**: Does this break existing functionality?\n\n**Quality Checklist:**\n- [ ] Functions are short and focused\n- [ ] No more than 3 levels of indentation\n- [ ] Clear, descriptive naming\n- [ ] No unnecessary complexity\n\n### Step 5: Security Check\n\n**Reference:** `.spec/steering/owasp-top10-check.md`\n\n**Quick Security Checklist:**\n- [ ] Input validation (sanitize user inputs)\n- [ ] No SQL/command injection (use parameterized queries)\n- [ ] Access control enforced\n- [ ] No secrets in code (use env vars)\n- [ ] Proper error handling (no stack traces to users)\n\n### Step 6: Implement and Test\n\n1. Write the failing test (RED)\n2. Implement minimal solution (GREEN)\n3. Run tests to confirm pass\n4. Refactor if needed\n5. Run full test suite\n6. Verify no lint/type errors\n\n## Reference Documents\n\nThese steering documents provide detailed guidance:\n\n| Document | Content |\n|----------|---------|\n| `tdd-guideline.md` | TDD methodology, test pyramid, Red-Green-Refactor |\n| `principles.md` | SOLID, DRY, KISS, YAGNI, Separation of Concerns |\n| `linus-review.md` | Code quality, \"good taste\", simplicity standards |\n| `owasp-top10-check.md` | Security checklist (OWASP Top 10) |\n\n## Output\n\nAfter implementing, provide:\n\n```markdown\n## Implementation Summary\n\n**Task:** {what was implemented}\n\n**Changes:**\n- {file1}: {what changed}\n- {file2}: {what changed}\n\n**Tests Added:**\n- {test description}\n\n**Principles Applied:**\n- TDD: {how TDD was followed}\n- Design: {which principles were applied}\n- Security: {security considerations}\n\n**Ready for:** {commit / further review / testing}\n```\n\n## Example\n\n```\nUser: /simple-task add a logout button to the navbar\n\nClaude:\n1. Understand: Add logout button that clears session and redirects to login\n2. TDD: Write test for logout functionality first\n3. Principles: Single responsibility - logout logic in AuthService\n4. Security: Ensure session is properly invalidated\n5. Implement: Button component + logout handler\n6. Test: Verify all tests pass\n```\n"},"lastSynced":"2026-03-06T06:37:28.149Z","agentAnalysis":{"suitability":{"en":"Perfect for Agile AI Agents needing rapid feature implementation and bug fixing capabilities.","zh":"适用于需要快速实现功能和修复bug的敏捷AI代理。","ja":"Agile AIエージェントが機能の迅速な実装とバグの修正機能を必要とする場合に最適です。","ko":"신속한 기능 구현 및 버그 수정 기능이 필요한 애자일 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de Inteligencia Artificial Ágiles que necesitan implementación rápida de características y capacidades de depuración de errores.","fr":"Parfait pour les Agents d''Intelligence Artificielle Agiles nécessitant une mise en œuvre rapide de fonctionnalités et de corrections de bogues.","de":"Perfekt für Agile KI-Agents, die eine schnelle Implementierung von Funktionen und Fehlernbehebungen benötigen.","pt":"Perfeito para Agentes de IA Ágeis que necessitam de implementação rápida de recursos e capacidades de correção de bugs.","ru":"Идеально подходит для Agile-агентов ИИ, которым требуются быстрая реализация функций и исправление ошибок.","ar":"مثالي لعميل الذكاء الاصطناعي المتقدم الذي يحتاج إلى تنفيذ سريع للميزات وإصلاح الأخطاء."},"recommendation":{"en":"Empowers agents to implement small features, bug fixes, or quick enhancements following best practices, utilizing steering documents for guidance and adhering to full SDD workflows for complex tasks, ensuring seamless integration with libraries and protocols.","zh":"赋予代理实现小功能、bug修复或快速增强的能力，利用指导文档进行指导，并遵循完整的SDD工作流程以执行复杂任务，确保与库和协议的无缝集成。","ja":"ベストプラクティスに従い、ステアリングドキュメントをガイダンスとして使用し、複雑なタスクには完全なSDDワークフローに従うことで、小規模な機能の実装、バグの修正、または迅速な強化を可能にします。また、ライブラリやプロトコルとのシームレスな統合も保証します。","ko":"베스트 프랙티스를 따르며, 스티어링 문서를 가이드로 사용하고, 복잡한 작업에는 완전한 SDD 워크플로우를 따르는ことで, 소규모 기능 구현, 버그 수정 또는 빠른 강화가 가능합니다. 또한 라이브러리 및 프로토콜과 무결점 통합도 보장합니다.","es":"Habilita a los agentes a implementar pequeñas características, correcciones de errores o mejoras rápidas siguiendo las mejores prácticas, utilizando documentos de orientación para la guía y ajustándose a flujos de trabajo de SDD completos para tareas complejas, garantizando una integración perfecta con bibliotecas y protocolos.","fr":"Permet aux agents de mettre en œuvre de petites fonctionnalités, de corriger des bogues ou d''effectuer des améliorations rapides en suivant les meilleures pratiques, en utilisant des documents de pilotage pour guider et en suivant des flux de travail SDD complets pour les tâches complexes, en garantissant une intégration transparente avec les bibliothèques et les protocoles.","de":"Ermächtigt die Agents, kleine Funktionen, Fehlerkorrekturen oder schnelle Verbesserungen umzusetzen, indem sie bewährte Verfahren befolgen, Steuerdokumente für die Führung verwenden und sich an vollständige SDD-Workflows für komplexe Aufgaben halten, um eine nahtlose Integration mit Bibliotheken und Protokollen sicherzustellen.","pt":"Habilita os agentes a implementar pequenos recursos, correções de bugs ou melhorias rápidas seguindo as melhores práticas, utilizando documentos de direção para orientação e aderindo aos fluxos de trabalho de SDD completo para tarefas complexas, garantindo integração perfeita com bibliotecas e protocolos.","ru":"Наделяет агентов возможностью реализовывать небольшие функции, исправлять ошибки или вносить быстрые улучшения, следуя лучшим практикам, используя руководящие документы для руководства и придерживаясь полных рабочих процессов SDD для сложных задач, обеспечивая бесперебойную интеграцию с библиотеками и протоколами.","ar":"يمنح الوكيل القدرة على تنفيذ ميزات صغيرة أو تصحيح الأخطاء أو تحسينات سريعة اتباعًا لأفضل الممارسات، واستخدام مستندات التوجيه لإرشاد وتطبيق سير العمل الكامل ل SDD لل مهام المعقدة، وضمان التكامل السلس مع المكتبات والبروتوكولات."},"useCases":{"en":["Implementing minor UI enhancements","Debugging and fixing bugs","Refactoring code for improved readability"],"zh":["实现次要UI增强","调试和修复bug","重构代码以提高可读性"],"ja":["マイナーアイウイ強化の実装","バグのデバッグと修正","コードのリファクタリングによる可読性の向上"],"ko":["소규모 UI 강화 구현","버그 디버깅 및 수정","코드 리팩토링을 통한 가독성 향상"],"es":["Implementación de mejoras menores de la IU","Depuración y corrección de errores","Reestructuración del código para mejorar la legibilidad"],"fr":["Mise en œuvre de petites améliorations de l''interface utilisateur","Débogage et correction des bogues","Réorganisation du code pour améliorer la lisibilité"],"de":["Implementierung kleiner Benutzeroberflächen-verbesserungen","Fehlerbehebung und Debugging","Umstrukturierung des Codes für verbesserte Lesbarkeit"],"pt":["Implementação de melhorias menores na interface do usuário","Depuração e correção de bugs","Reestruturação do código para melhor legibilidade"],"ru":["Реализация незначительных улучшений интерфейса пользователя","Отладка и исправление ошибок","Перестройка кода для улучшения читаемости"],"ar":["تنفيذ تحسينات طفيفة على واجهة المستخدم","تصحيح الأخطاء وإصلاحها","إعادة هيكلة الكود لتحسين القابلية للقراءة"]},"limitations":{"en":["Limited to small features and bug fixes","Requires access to project steering documents","Excludes complex features and new modules"],"zh":["仅限于小功能和bug修复","需要访问项目的指导文档","排除复杂功能和新模块"],"ja":["小規模な機能とバグの修正に限定される","プロジェクトのステアリングドキュメントへのアクセスが必要","複雑な機能と新しいモジュールは除外される"],"ko":["소규모 기능 및 버그 수정에만 한정됨","프로젝트의 스티어링 문서에 대한 액세스가 필요함","복잡한 기능 및 새로운 모듈은 제외됨"],"es":["Limitado a pequeñas características y correcciones de errores","Requiere acceso a documentos de orientación del proyecto","Excluye características complejas y nuevos módulos"],"fr":["Limité à de petites fonctionnalités et corrections de bogues","Nécessite l''accès aux documents de pilotage du projet","Exclut les fonctionnalités complexes et les nouveaux modules"],"de":["Begrenzt auf kleine Funktionen und Fehlernbehebungen","Erfordert Zugriff auf Projektleitdokumente","Schließt komplexe Funktionen und neue Module aus"],"pt":["Limitado a recursos e correções de bugs pequenos","Requer acesso a documentos de direção do projeto","Exclui recursos complexos e novos módulos"],"ru":["Ограничен pequenos recursos и исправление ошибок","Требует доступа к руководящим документам проекта","Исключает сложные функции и новые модули"],"ar":["محدود بالسمات والتصحيح الصغير للأخطاء","يتطلب الوصول إلى مستندات توجيه المشروع","استبعاد الميزات المعقدة والوحدات الجديدة"]},"version":4},"contentHash":"9c99da4c3560fe00cd1e96cf344ebea272f99496e68633e40915ceaae8795358","qualityScore":65}');
