INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yi-john-huang/sdd-mcp/simple-task', 'simple-task', 'yi-john-huang', 'sdd-mcp', 'community', 'simple-task yi-john-huang sdd-mcp community The simple-task skill implements small features, bug fixes, or quick enhancements while following best practices. It benefits developers working on AI agent projects. 简单任务是指在项目中实现小功能、修复bug和快速增强的过程，遵循项目的指导文档 シンプルタスクは、小さな機能の追加、バグの修正、クイックリファクタリングを行うプロセスです 심플 태스크는 프로젝트의 가이드라인을 따라 작은 기능 추가, 버그 수정, 빠른 리팩토링을 수행하는 프로세스입니다 La implementación de tareas simples es un proceso que sigue las mejores prácticas para agregar funciones, arreglar errores y mejorar el código L''implémentation de tâches simples est un processus qui suit les meilleures pratiques pour ajouter des fonctionnalités, corriger des erreurs et améliorer le code Die Implementierung von einfachen Aufgaben ist ein Prozess, der die besten Praktiken für die Hinzufügung von Funktionen, die Korrektur von Fehlern und die Verbesserung des Codes befolgt O Simple Task é uma ferramenta para implementar pequenas funcionalidades, correções de bugs e melhorias rápidas, seguindo as melhores práticas do projeto Simple Task - это инструмент для реализации небольших функций, исправления ошибок и быстрого улучшения, следуя лучшим практикам проекта أداة المهام البسيطة هي أداة لتنفيذ الميزات الصغيرة وتصحيح الأخطاء والتحسين السريع، متبعًا أفضل الممارسات للمشروع how to use simple-task simple-task alternative simple-task setup guide what is simple-task simple-task vs full SDD workflow simple-task implementation best practices simple-task install simple-task for AI agents AIエージェント 简单任务 小功能添加 bug修复 快速增强 项目指导文档 快速迭代开发 小规模功能实现 Implements small feature additions using /simple-task command Supports bug fixes and minor enhancements Follows best practices from project''s steering documents Uses full SDD workflow for complex features Enables quick refactoring for improved code quality Facilitates minor enhancements without formal requirements review simple-task is a skill that enables the implementation of small features, bug fixes, or quick enhancements in AI agent projects');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wbrown/janus-datalog/datalog', 'community', 'wbrown', 'janus-datalog', 'wbrown/janus-datalog', 'datalog', 35, 0, 65, '2026-02-25T03:11:48Z', '2026-03-06T06:37:39.112Z', '42b93efb0e1788f8c11f4c8a6fd42149e72110a2cc532e47e1ac742f223b4d2b', '{"id":"wbrown/janus-datalog/datalog","name":"datalog","description":{"en":"datalog is a Datomic-inspired embeddable database written in Golang, ideal for developers seeking a flexible EAV store. It enables querying and data exploration using the datalog CLI.","zh":"Datalog是一个使用Golang构建的Datomic风格数据库，提供了高性能的数据存储和查询能力","ja":"Datalogは、Golangで構築されたDatomic風のデータベースであり、高性能のデータストレージとクエリ機能を提供します","ko":"Datalog는 고성능의 Datomic 스타일 데이터베이스로 Golang으로 구축되어 데이터 저장 및 조회 기능을 제공합니다","es":"Datalog es una base de datos embebida inspirada en Datomic, escrita en Golang, que permite el almacenamiento de datos como datoms","fr":"Datalog est une base de données intégrée inspirée de Datomic, écrite en Golang, qui permet le stockage de données sous forme de datoms","de":"Datalog ist eine Datomic-inspirierte, einbettbare Datenbank, die in Golang geschrieben ist und das Speichern von Daten als Datoms ermöglicht","pt":"O Datalog é um banco de dados inspirado no Datomic, escrito em Golang, que permite consultas e exploração de dados","ru":"Datalog - это база данных, вдохновленная Datomic, написанная на Golang, которая позволяет запросы и исследование данных","ar":"Datalog هو قاعدة بيانات مشابهة ل Datomic، مكتوبة بلغة Golang، التي تسمح بالاستعلامات واستكشاف البيانات"},"seo":{"title":{"en":"datalog: Datomic-Inspired Database Setup Guide | AI Agent...","zh":"Datalog Setup Guide: 使用Golang构建Datomic风格数据库","ja":"Datalogベストプラクティス: Datomic-inspired AIエージェントの実装","ko":"Datalog구현 가이드: 고성능 Datomic 스타일 데이터베이스 구축","es":"Guía de configuración de Datalog: bases de datos embebida...","fr":"Guide de mise en place de Datalog : bases de données inté...","de":"Datalog-Setup-Anleitung: Datomic-inspirierte, einbettbare...","pt":"Guia de Configuração do Datalog: Consultas de Banco de Dados","ru":"Настройка Datalog: Руководство по запросам к базе данных ...","ar":"دليل إعداد Datalog: استعلامات قاعدة البيانات للآلات الذكية"},"description":{"en":"Unlock the power of Datalog, a Golang-based EAV store. Discover how to query and explore data with the datalog CLI and learn more about its Entity-Attribute-...","zh":"了解Datalog的特点和优势，掌握使用Golang构建Datomic风格数据库的方法，提高开发效率","ja":"Datalogの特徴とメリットを知り、Datomic-inspired AIエージェントの実装方法をマスターする","ko":"Datalog의 특징과 장점을 알아보고 고성능 Datomic 스타일 데이터베이스 구축 방법을 익혀 개발 능력을 향상시키세요","es":"Descubre cómo utilizar Datalog, una base de datos embebida inspirada en Datomic, para debugging y exploración de datos con el CLI de Datalog","fr":"Découvrez comment utiliser Datalog, une base de données intégrée inspirée de Datomic, pour le débogage et l''exploration de données avec le CLI Datalog","de":"Erfahren Sie, wie Sie Datalog, eine Datomic-inspirierte, einbettbare Datenbank, für Debugging und Datenexploration mit dem Datalog-CLI verwenden","pt":"Aprenda a configurar e consultar o Datalog, um banco de dados inspirado no Datomic, escrito em Golang para desenvolvedores","ru":"Узнайте, как настроить и запросить Datalog, базу данных, вдохновленную Datomic, написанную на Golang для ИИ Агентов","ar":"تعلم كيفية إعداد واستجواب Datalog، قاعدة بيانات مشابهة ل Datomic، مكتوبة بلغة Golang للآلات الذكية"},"definition":{"en":"datalog is an embeddable Datalog database inspired by Datomic, written in Golang, utilizing an Entity-Attribute-Value store model.","zh":"Datalog是一种使用Golang构建的Datomic风格数据库，采用EAV（实体-属性-值）存储模型","ja":"Datalogは、Golangで構築されたDatomic風のデータベースであり、EAV（エンティティ-属性-値）ストレージモデルを採用しています","ko":"Datalog는 고성능의 Datomic 스타일 데이터베이스로 EAV(엔티티-속성-값) 저장 모델을 사용합니다","es":"Datalog es una base de datos embebida que almacena datos como datoms, inspirada en Datomic","fr":"Datalog est une base de données intégrée qui stocke des données sous forme de datoms, inspirée de Datomic","de":"Datalog ist eine einbettbare Datenbank, die Daten als Datoms speichert, inspiriert von Datomic","pt":"O que é Datalog? Um banco de dados EAV (Entidade-Atributo-Valor) inspirado no Datomic","ru":"Что такое Datalog? База данных EAV (Сущность-Атрибут-Значение), вдохновленная Datomic","ar":"ما هو Datalog؟ قاعدة بيانات EAV (كائن-سمة-قيمة) مشابهة ل Datomic"},"features":{"en":["Queries janus-datalog databases using the datalog CLI for debugging and data exploration","Utilizes a Datomic-style EAV (Entity-Attribute-Value) store for flexible data modeling","Stores data as datoms: [entity attribute value tx] for efficient data retrieval","Supports attribute-value pairs connected by shared entity IDs for complex data relationships","Employs the datalog CLI for running queries against the database"],"zh":["支持Datomic风格的EAV（实体-属性-值）存储模型","使用Golang构建，提供高性能的数据存储和查询能力","提供datalog CLI工具，用于运行查询和调试","支持实体-属性-值对的存储和查询","采用无表结构的设计，实体之间通过共享实体ID连接"],"ja":["Datomic風のEAV（エンティティ-属性-値）ストレージモデルをサポート","Golangで構築されたため、高性能のデータストレージとクエリ機能を提供","datalog CLIツールを提供し、クエリの実行とデバッグが可能","エンティティ-属性-値のペアのストレージとクエリをサポート","テーブルレス設計を採用し、エンティティ間は共有エンティティIDで接続"],"ko":["Datomic 스타일의 EAV(엔티티-속성-값) 저장 모델을 지원","고성능의 데이터 저장 및 조회 기능을 제공하는 Golang으로 구축","datalog CLI 툴을 제공하여 쿼리 실행 및 디버깅이 가능","엔티티-속성-값의 페어 저장 및 조회를 지원","테이블리스設計을采用하여 엔티티 간에 共享 엔티티 ID로 연결"],"es":["Almacenamiento de datos como datoms","Inspiration en Datomic","Escrita en Golang","Interfaz de línea de comandos (CLI) para consultas","Modelo de datos EAV (Entity-Attribute-Value)"],"fr":["Stockage de données sous forme de datoms","Inspirée de Datomic","Écrite en Golang","Interface de ligne de commande (CLI) pour les requêtes","Modèle de données EAV (Entity-Attribute-Value)"],"de":["Speicherung von Daten als Datoms","Inspiriert von Datomic","Geschrieben in Golang","Kommandozeilen-Schnittstelle (CLI) für Abfragen","Datenmodell EAV (Entity-Attribute-Value)"],"pt":["Armazenamento de dados como datoms: [entidade atributo valor tx]","Modelo de dados EAV (Entidade-Atributo-Valor)","Suporte a consultas via CLI","Inspiração no Datomic","Escrito em Golang","Permite exploração de dados"],"ru":["Хранение данных в виде datoms: [сущность атрибут значение tx]","Модель данных EAV (Сущность-Атрибут-Значение)","Поддержка запросов через CLI","Вдохновленная Datomic","Написанная на Golang","Позволяет исследование данных"],"ar":["تخزين البيانات على شكل datoms: [كائن سمة قيمة tx]","نموذج بيانات EAV (كائن-سمة-قيمة)","دعم الاستعلامات عبر CLI","ملهمة ب Datomic","مكتوبة بلغة Golang","تسمح باستكشاف البيانات"]},"keywords":{"en":["how to use datalog","datalog database setup","datalog vs Datomic","datalog install guide","what is datalog","datalog alternative databases","datalog query language","datalog Golang implementation","datalog EAV store model"],"zh":["Datalog","Datomic","Golang","EAV存储模型","高性能数据库","数据存储","查询能力","datalog CLI","实体-属性-值"],"ja":["Datalog","Datomic","Golang","EAVストレージモデル","高性能データベース","データストレージ","クエリ機能","datalog CLI","エンティティ-属性-値"],"ko":["Datalog","Datomic","Golang","EAV 저장 모델","고성능 데이터베이스","데이터 저장","조회 능력","datalog CLI","엔티티-속성-값"],"es":["Datalog","bases de datos embebidas","Datomic","Golang","CLI","datoms","EAV","debugging","exploración de datos","herramientas de desarrollo"],"fr":["Datalog","bases de données intégrées","Datomic","Golang","CLI","datoms","EAV","débogage","exploration de données","outils de développement"],"de":["Datalog","einbettbare Datenbanken","Datomic","Golang","CLI","Datoms","EAV","Debugging","Datenexploration","Entwicklungstools","Künstliche Intelligenz Tools"],"pt":["Datalog","banco de dados EAV","Golang","Datomic","CLI","consultas de banco de dados","desenvolvimento de software","engenharia de dados","tecnologias de banco de dados"],"ru":["Datalog","база данных EAV","Golang","Datomic","CLI","запросы к базе данных","разработка программного обеспечения","инженерия данных","технологии базы данных","ИИ Агенты"],"ar":["Datalog","قاعدة بيانات EAV","Golang","Datomic","CLI","استعلامات قاعدة البيانات","تطوير البرمجيات","هندسة البيانات","تكنولوجيا قاعدة البيانات","الآلات الذكية"]}},"owner":"wbrown","repo":"janus-datalog","repoPath":"wbrown/janus-datalog","stars":35,"forks":0,"updatedAt":"2026-02-25T03:11:48Z","topics":[],"category":"community","skillMd":{"name":"datalog","description":">","bodyPreview":"# Datalog Query\n\nQuery janus-datalog databases for debugging and data exploration.\n\nThe user will provide a database path and describe what they want to know. Use the `datalog` CLI to run queries against the database.\n\n## Data Model\n\njanus-datalog is a **Datomic-style EAV (Entity-Attribute-Value) store**. All data is stored as datoms: `[entity attribute value tx]`. There are no tables — entities are just collections of attribute-value pairs, connected by shared entity IDs.\n\nAttributes follow a n","body":"# Datalog Query\n\nQuery janus-datalog databases for debugging and data exploration.\n\nThe user will provide a database path and describe what they want to know. Use the `datalog` CLI to run queries against the database.\n\n## Data Model\n\njanus-datalog is a **Datomic-style EAV (Entity-Attribute-Value) store**. All data is stored as datoms: `[entity attribute value tx]`. There are no tables — entities are just collections of attribute-value pairs, connected by shared entity IDs.\n\nAttributes follow a namespaced keyword convention: `:namespace/name` (e.g., `:person/name`, `:order/total`). This means attributes cluster by namespace, which is useful when exploring unknown databases.\n\n**Storage is CRDT-backed** (Conflict-free Replicated Data Types). Every write is preserved with a unique ElementID. Attribute cardinality determines conflict resolution:\n\n| Cardinality | Behavior | Example |\n|-------------|----------|---------|\n| One | Last-Writer-Wins — only the latest value is returned by default | `:person/name`, `:person/age` |\n| Many | Add-Wins Set — all distinct values are returned | `:person/tag`, `:person/role` |\n| Vector | RGA — ordered list with deterministic merge | `:product/tags`, `:playlist/songs` |\n\nBecause all writes are preserved, you can time-travel: `db.History()` returns all raw datoms (no CRDT resolution), and `db.AsOf(elementID)` queries CRDT-resolved state as of a specific transaction.\n\n## Tool\n\nBinary: `~/go/bin/datalog`\n\nInstall if missing:\n```bash\ngo install github.com/wbrown/janus-datalog/cmd/datalog@latest\n```\n\n## Invocation\n\n```bash\n# Run a query\n~/go/bin/datalog -db <path> -query ''<EDN query>''\n\n# With input bindings (repeatable, one per :in parameter after $)\n~/go/bin/datalog -db <path> -query ''<EDN query with :in>'' -in ''<EDN value>'' [-in ''<EDN value>'' ...]\n\n# With performance annotations\n~/go/bin/datalog -db <path> -verbose -query ''<EDN query>''\n\n# Export entire database to readable EDN (useful for small DBs)\n~/go/bin/datalog -db <path> -export <output.edn>\n```\n\nOutput is a markdown table. Errors go to stderr.\n\nIf the user says `/datalog <path>`, treat `$ARGUMENTS` as the database path. Start by discovering what''s in the database, then ask what they want to explore.\n\n## Finding Databases\n\n- Prebuilt benchmark DB: `datalog/storage/testdata/ohlc_benchmark.db`\n- Default path when unspecified: `datalog.db` in current directory\n- Test databases are created in temp directories by tests (look for `t.TempDir()` calls)\n- Ask the user if the path is unclear\n\n## EDN Query Syntax\n\nQueries are EDN vectors. The basic form:\n\n```clojure\n[:find <find-spec>\n :in <input-spec>       ;; optional, $ is implicit\n :where <clauses>]\n```\n\n### Find Spec\n\n```clojure\n;; Return specific variables\n[:find ?name ?age :where ...]\n\n;; With aggregations (non-aggregated vars become group-by keys)\n[:find ?dept (sum ?salary) (count ?e) :where ...]\n\n;; Available: sum, count, avg, min, max\n```\n\n### Where Clauses\n\n**Data patterns** — match entity-attribute-value triples:\n```clojure\n[?entity :attribute ?value]          ;; basic pattern\n[?entity :attribute \"literal\"]       ;; match literal value\n[?entity :attribute _]               ;; wildcard (attribute exists)\n[?entity :attribute ?value ?tx]      ;; with transaction ID\n```\n\n**Predicates** — filter results:\n```clojure\n[(> ?age 25)]\n[(< ?price 100.0)]\n[(!= ?name \"Alice\")]\n[(< 0 ?x 100)]          ;; chained: 0 < ?x < 100\n```\n\n**Expressions** — compute values:\n```clojure\n[(+ ?age 5) ?future-age]\n[(- ?price ?discount) ?net]\n[(* ?qty ?price) ?total]\n[(str ?first \" \" ?last) ?fullname]\n[(ground 42) ?answer]\n[(identity ?x) ?y]                       ;; pass-through binding\n```\n\n**Time extraction** — extract components from `time.Time` values:\n```clojure\n[(year ?timestamp) ?y]\n[(month ?timestamp) ?m]\n[(day ?timestamp) ?d]\n[(hour ?timestamp) ?h]\n[(minute ?timestamp) ?min]\n[(second ?timestamp) ?sec]\n```\n\n**NOT clauses** — exclude matches:\n```clojure\n(not [?p :person/deleted true])\n(not-join [?p]\n  [?p :person/status \"inactive\"])\n```\n\n**OR clauses** — alternative patterns:\n```clojure\n(or [?p :person/city \"New York\"]\n    [?p :person/city \"Boston\"])\n(or-join [?p]\n  [?p :role/admin true]\n  [?p :role/superuser true])\n```\n\n**Vector functions** — operate on cardinality-vector attributes:\n```clojure\n[(nth ?vec 0) ?first-element]           ;; get element by index\n[(first ?vec) ?head]                     ;; first element\n[(last ?vec) ?tail]                      ;; last element\n[(length ?vec) ?len]                     ;; number of elements\n[(contains? ?vec \"value\") ?found]        ;; boolean membership test\n[(index-of ?vec \"value\") ?pos]           ;; index of first match\n[(subvec ?vec 1 3) ?slice]               ;; sub-vector [start, end)\n```\n\n**`enumerate`** — expands a vector into one tuple per element with index. This is the primary way to query vector contents:\n```clojure\n;; Given :product/tags is a vector [\"electronics\" \"sale\" \"new\"]\n[:find ?tag ?idx\n :where [?e :product/label \"Widget\"]\n        [?e :product/tags ?vec]\n        [(enumerate ?vec) [?idx ?tag]]]\n;; Returns: [0 \"electronics\"], [1 \"sale\"], [2 \"new\"]\n```\n\nImportant: `enumerate` produces **multiple output tuples** from a single input tuple. The binding `[?idx ?tag]` is required — it destructures each element into an index and value. The data pattern that binds `?vec` must appear **before** the enumerate expression in the where clause, and the planner must not reorder it ahead of the pattern that provides the vector.\n\n**Database functions:**\n```clojure\n[(get-else $ ?e :person/nickname \"unknown\") ?nick]\n[(missing? $ ?e :person/email)]\n[(get-some $ ?e :person/nick :person/name :person/email) ?display]\n```\n\n**Subqueries** — nested queries that bind results into the outer query:\n```clojure\n;; Tuple binding — subquery returns one tuple, binds to variables\n[(q [:find (max ?h)\n     :in $ ?sym\n     :where [?p :price/symbol ?sym]\n            [?p :price/high ?h]]\n    $ ?s) [[?max-high]]]\n\n;; Relation binding — subquery returns multiple tuples\n[(q [:find ?p ?h\n     :in $ ?sym\n     :where [?p :price/symbol ?sym]\n            [?p :price/high ?h]]\n    $ ?s) [[?price ?high] ...]]\n```\n\nThe subquery `(q [...] $ ?var1 ?var2)` takes a full query, then lists the inputs to pass (matching the subquery''s `:in` clause). The binding after `)` determines how results are captured: `[[?x]]` for a single tuple, `[[?x ?y] ...]` for multiple tuples.\n\n**Tagged literals** — use typed constants directly in patterns and predicates:\n```clojure\n[#identity \"L85hash...\" :person/name ?name]   ;; match specific entity\n[?e :event/date #inst \"2024-06-15T10:30:00Z\"] ;; match timestamp\n[(> ?d #inst \"2024-01-01T00:00:00Z\")]          ;; compare against timestamp\n```\n\n### Input Parameters\n\n```clojure\n;; Scalar input\n[:find ?name :in $ ?target-age\n :where [?p :person/age ?target-age]\n        [?p :person/name ?name]]\n\n;; Collection input\n[:find ?name :in $ [?city ...]\n :where [?p :person/city ?city]\n        [?p :person/name ?name]]\n```\n\nPass `:in` values with the `-in` flag (one per binding, order matches `:in` after `$`):\n\n```bash\n# Scalar input\n~/go/bin/datalog -db <path> \\\n  -query ''[:find ?name :in $ ?age :where [?p :person/age ?age] [?p :person/name ?name]]'' \\\n  -in 30\n\n# String input (quote in EDN)\n~/go/bin/datalog -db <path> \\\n  -query ''[:find ?age :in $ ?name :where [?p :person/name ?name] [?p :person/age ?age]]'' \\\n  -in ''\"Alice\"''\n\n# Collection input\n~/go/bin/datalog -db <path> \\\n  -query ''[:find ?name :in $ [?city ...] :where [?p :person/city ?city] [?p :person/name ?name]]'' \\\n  -in ''[\"New York\" \"Boston\"]''\n\n# Multiple inputs\n~/go/bin/datalog -db <path> \\\n  -query ''[:find ?name :in $ ?min ?max :where [?p :person/age ?a] [(>= ?a ?min)] [(<= ?a ?max)] [?p :person/name ?name]]'' \\\n  -in 20 -in 30\n```\n\nEach `-in` value is parsed as EDN, so tagged literals work too: `-in ''#inst \"2024-01-01T00:00:00Z\"''`.\n\n### Order By\n\n```clojure\n[:find ?name ?age\n :order-by [?age :desc] [?name :asc]\n :where [?p :person/name ?name]\n        [?p :person/age ?age]]\n```\n\n### Time-Travel\n\n```go\n// Open a database\nd, _ := db.Open(\"path/to/db\")\n\n// History — all raw datoms, no CRDT resolution\nhist := d.History()\nhist.Query(`[:find ?name ?tx :where [?p :person/name ?name ?tx]]`)\n\n// As-of — CRDT-resolved state at a specific transaction\ntxID, _ := tx.Commit()  // returns datalog.ElementID\nasOf := d.AsOf(txID)\nasOf.Query(`[:find ?name :where [?p :person/name ?name]]`)\n```\n\n## Common Debugging Patterns\n\n### 1. Explore an unknown database\n\nStart by discovering the schema shape:\n\n```bash\n# What attributes exist?\n~/go/bin/datalog -db <path> -query ''[:find ?a :where [_ ?a _]]''\n\n# How many entities per attribute?\n~/go/bin/datalog -db <path> -query ''[:find ?a (count ?e) :where [?e ?a _]]''\n```\n\nThen sample values for attributes that look interesting:\n\n```bash\n~/go/bin/datalog -db <path> -query ''[:find ?v :where [_ :person/status ?v]]''\n```\n\n### 2. Inspect an entity through a known value\n\nDon''t query for entity IDs and copy them. Instead, join through a known value to see everything about an entity:\n\n```bash\n# All attributes and values for the entity named \"Alice\"\n~/go/bin/datalog -db <path> -query \\\n  ''[:find ?a ?v :where [?e :person/name \"Alice\"] [?e ?a ?v]]''\n```\n\nThis works for any attribute — find the entity through something you know, then fan out:\n\n```bash\n# Everything about the order with ID \"ORD-1234\"\n~/go/bin/datalog -db <path> -query \\\n  ''[:find ?a ?v :where [?e :order/id \"ORD-1234\"] [?e ?a ?v]]''\n```\n\n### 3. Follow references\n\nEntities reference other entities. Use variable joins to traverse:\n\n```bash\n# Who are Alice''s friends, and what cities do they live in?\n~/go/bin/datalog -db <path> -query \\\n  ''[:find ?friend-name ?city\n    :where [?p :person/name \"Alice\"]\n           [?p :person/friend ?f]\n           [?f :person/name ?friend-name]\n           [?f :person/city ?city]]''\n```\n\nChain as many hops as needed — each shared variable (`?f` above) is a join.\n\n### 4. Find missing or unexpected data\n\n```bash\n# People without an email\n~/go/bin/datalog -db <path> -query \\\n  ''[:find ?name\n    :where [?p :person/name ?name]\n           (not [?p :person/email _])]''\n\n# People in neither New York nor Boston\n~/go/bin/datalog -db <path> -query \\\n  ''[:find ?name ?city\n    :where [?p :person/name ?name]\n           [?p :person/city ?city]\n           [(!= ?city \"New York\")]\n           [(!= ?city \"Boston\")]]''\n```\n\n### 5. Aggregate to find outliers\n\n```bash\n# Which cities have the most people?\n~/go/bin/datalog -db <path> -query \\\n  ''[:find ?city (count ?p)\n    :where [?p :person/city ?city]]''\n\n# Average age by city\n~/go/bin/datalog -db <path> -query \\\n  ''[:find ?city (avg ?age)\n    :where [?p :person/city ?city]\n           [?p :person/age ?age]]''\n```\n\n### 6. For small databases, just export\n\n```bash\n~/go/bin/datalog -db <path> -export dump.edn\n```\n\nExport format is one datom per line: `[#identity \"hash\" :attribute value txid]`\n\n## Output Format\n\nResults are printed as markdown tables:\n\n```\n| ?name   | ?age |\n|---------|------|\n| Alice   |   30 |\n| Bob     |   25 |\n| Charlie |   35 |\n\n_3 tuples (1.234ms)_\n```\n\nWith `-verbose`, stderr gets annotation events showing index selection, join stats, and timing.\n\n## Entity Identity\n\nEntities are identified by an **Identity** — a SHA1 hash of a seed string, displayed as a 25-character L85-encoded string (a sort-order-preserving Base85 encoding).\n\nWhen you query for an entity variable like `?e`, the result symbol shows the L85 hash. You don''t normally need to use these directly — join through known attribute values instead (see debugging patterns above).\n\nThe `#identity \"L85hash\"` tagged literal exists for cases where you have a hash from logs or export output and need to look it up directly. This is the exception, not the normal workflow.\n\n## Notes\n\n- All attribute names are keywords starting with `:` (e.g., `:person/name`)\n- Integer literals are int64, float literals are float64\n- String literals use double quotes: `\"value\"`\n- The `_` wildcard matches any value without binding\n- Empty results return a table with headers but no tuples\n- Tagged literals: `#identity \"L85...\"`, `#inst \"RFC3339...\"`, `#bytes \"L85...\"`"},"lastSynced":"2026-03-06T06:37:39.112Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring flexible EAV data storage and querying, such as those built with Cursor, Windsurf, or Claude Code.","zh":"适用于需要灵活的EAV数据存储和查询的AI代理，例如使用Cursor、Windsurf或Claude Code构建的代理。","ja":"Cursor、Windsurf、またはClaude Codeで構築されたような、柔軟なEAVデータストレージおよびクエリを必要とするAIエージェントに適しています。","ko":"Cursor, Windsurf 또는 Claude Code로 구축된 것과 같은 유연한 EAV 데이터 저장소 및 쿼리가 필요한 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA que requieren un almacenamiento y consulta de datos EAV flexible, como aquellos construidos con Cursor, Windsurf o Claude Code.","fr":"Idéal pour les agents IA nécessitant un stockage et une interrogation de données EAV flexibles, tels que ceux construits avec Cursor, Windsurf ou Claude Code.","de":"Ideal für KI-Agents, die ein flexibles EAV-Datenspeicher- und Abfragesystem benötigen, wie z.B. solche, die mit Cursor, Windsurf oder Claude Code erstellt wurden.","pt":"Ideal para Agentes de IA que requerem armazenamento de dados EAV flexível e consulta, como aqueles construídos com Cursor, Windsurf ou Claude Code.","ru":"Идеально для ИИ-агентов, требующих гибкого хранения и запроса данных EAV, таких как те, которые построены с помощью Cursor, Windsurf или Claude Code.","ar":"مثالي لعميل الذكاء الاصطناعي الذين يحتاجون إلى تخزين بيانات مرن و استعلام EAV، مثل تلك التي بنيت مع Cursor، Windsurf أو Claude Code."},"recommendation":{"en":"Empowers agents to efficiently query and explore data using the datalog CLI, leveraging Datomic-inspired embeddable databases and EAV stores, with support for Golang and datalog query language.","zh":"使代理能够使用datalog CLI高效地查询和探索数据，利用受Datomic启发的可嵌入数据库和EAV存储，并支持Golang和datalog查询语言。","ja":"datalog CLIを使用してデータを効率的に照会して探索できるようにエージェントをEmpowerし、Datomicにインスパイアされた埋め込み可能なデータベースとEAVストアを活用し、Golangおよびdatalogクエリ言語をサポートします。","ko":"datalog CLI를 사용하여 데이터를 효율적으로 쿼리하고 탐색할 수 있도록 에이전트를 강화하고 Datomic에서 영감을 받은 임베디드 데이터베이스 및 EAV 저장소를 활용하며 Golang 및 datalog 쿼리 언어를 지원합니다.","es":"Permite a los agentes consultar y explorar datos de manera eficiente utilizando el CLI de datalog, aprovechando bases de datos embebibles inspiradas en Datomic y tiendas EAV, con soporte para Golang y lenguaje de consulta datalog.","fr":"Permet aux agents d''interroger et d''explorer les données de manière efficace en utilisant le CLI de datalog, en exploitant les bases de données intégrables inspirées de Datomic et les magasins EAV, avec un support pour Golang et le langage de requête datalog.","de":"Ermöglicht es den Agenten, Daten effizient abzufragen und zu erkunden, indem sie das datalog-CLI verwenden, das auf Datomic-inspirierten einbettbaren Datenbanken und EAV-Speichern basiert, mit Unterstützung für Golang und die datalog-Abfragesprache.","pt":"Permite que os agentes consultem e explorem dados de forma eficiente usando o datalog CLI, aproveitando bancos de dados incorporáveis inspirados em Datomic e lojas EAV, com suporte a Golang e linguagem de consulta datalog.","ru":"Наделяет агентов возможностью эффективно запрашивать и исследовать данные с помощью datalog CLI, используя встроенные базы данных, вдохновленные Datomic, и хранилища EAV, с поддержкой Golang и языка запросов datalog.","ar":"يمنح الوكلاء khảية استعلام و استكشاف البيانات بفعالية باستخدام datalog CLI، مستفيداً من قواعد البيانات المضمنة التي تم إلهامها من Datomic و مخازن EAV، مع دعم Golang و لغة استعلام datalog."},"useCases":{"en":["Debugging janus-datalog databases","Exploring entity-attribute-value pairs","Querying datoms for data analysis"],"zh":["调试janus-datalog数据库","探索实体-属性-值对","查询datom进行数据分析"],"ja":["janus-datalogデータベースのデバッグ","エンティティ-属性-値のペアの探索","データ分析のためのdatomの照会"],"ko":["janus-datalog 데이터베이스 디버깅","엔티티-속성-값 쌍 탐색","데이터 분석을 위한 datom 쿼리"],"es":["Depuración de bases de datos janus-datalog","Exploración de pares de entidad-atributo-valor","Consulta de datoms para análisis de datos"],"fr":["Débogage des bases de données janus-datalog","Exploration des paires d''entité-attribut-valeur","Interrogation des datoms pour l''analyse des données"],"de":["Fehlerbehebung in janus-datalog-Datenbanken","Erkundung von Entität-Attribut-Wert-Paaren","Abfrage von Datoms für Datenanalyse"],"pt":["Depuração de bancos de dados janus-datalog","Exploração de pares de entidade-atributo-valor","Consulta de datoms para análise de dados"],"ru":["Отладка баз данных janus-datalog","Изучение пар сущность-атрибут-значение","Запрос датома для анализа данных"],"ar":["تصحيح أخطاء قواعد البيانات janus-datalog","استكشاف أزواج الكيان-السمة-القيمة","استعلام datoms لتحليل البيانات"]},"limitations":{"en":["Requires datalog CLI installation","Golang compatibility necessary","Limited to EAV data model"],"zh":["需要datalog CLI安装","需要Golang兼容性","仅限EAV数据模型"],"ja":["datalog CLIのインストールが必要","Golangの互換性が必要","EAVデータモデルに限定"],"ko":["datalog CLI 설치가 필요함","Golang 호환성이 필요함","EAV 데이터 모델로 제한됨"],"es":["Requiere la instalación del CLI de datalog","Compatibilidad con Golang necesaria","Limitado al modelo de datos EAV"],"fr":["Nécessite l''installation du CLI de datalog","Compatibilité Golang nécessaire","Limité au modèle de données EAV"],"de":["Benötigt die Installation des datalog-CLI","Golang-Kompatibilität erforderlich","Begrenzt auf das EAV-Datenspeichermodell"],"pt":["Requer instalação do datalog CLI","Compatibilidade com Golang necessária","Limitado ao modelo de dados EAV"],"ru":["Требуется установка datalog CLI","Необходима совместимость с Golang","Ограничен моделью данных EAV"],"ar":["يتطلب تثبيت datalog CLI","التوافق مع Golang ضروري","محدود بنموذج بيانات EAV"]},"version":4},"contentHash":"42b93efb0e1788f8c11f4c8a6fd42149e72110a2cc532e47e1ac742f223b4d2b","qualityScore":65}');
