INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wbrown/janus-datalog/datalog', 'datalog', 'wbrown', 'janus-datalog', 'community', 'datalog wbrown janus-datalog community datalog is a Datomic-inspired embeddable database written in Golang, ideal for developers seeking a flexible EAV store. It enables querying and data exploration using the datalog CLI. Datalog是一个使用Golang构建的Datomic风格数据库，提供了高性能的数据存储和查询能力 Datalogは、Golangで構築されたDatomic風のデータベースであり、高性能のデータストレージとクエリ機能を提供します Datalog는 고성능의 Datomic 스타일 데이터베이스로 Golang으로 구축되어 데이터 저장 및 조회 기능을 제공합니다 Datalog es una base de datos embebida inspirada en Datomic, escrita en Golang, que permite el almacenamiento de datos como datoms Datalog est une base de données intégrée inspirée de Datomic, écrite en Golang, qui permet le stockage de données sous forme de datoms Datalog ist eine Datomic-inspirierte, einbettbare Datenbank, die in Golang geschrieben ist und das Speichern von Daten als Datoms ermöglicht O Datalog é um banco de dados inspirado no Datomic, escrito em Golang, que permite consultas e exploração de dados Datalog - это база данных, вдохновленная Datomic, написанная на Golang, которая позволяет запросы и исследование данных Datalog هو قاعدة بيانات مشابهة ل Datomic، مكتوبة بلغة Golang، التي تسمح بالاستعلامات واستكشاف البيانات how to use datalog datalog database setup datalog vs Datomic datalog install guide what is datalog datalog alternative databases datalog query language datalog Golang implementation datalog EAV store model Datalog Datomic Golang EAV存储模型 高性能数据库 数据存储 查询能力 datalog CLI 实体-属性-值 Queries janus-datalog databases using the datalog CLI for debugging and data exploration Utilizes a Datomic-style EAV (Entity-Attribute-Value) store for flexible data modeling Stores data as datoms: [entity attribute value tx] for efficient data retrieval Supports attribute-value pairs connected by shared entity IDs for complex data relationships Employs the datalog CLI for running queries against the database datalog is an embeddable Datalog database inspired by Datomic, written in Golang, utilizing an Entity-Attribute-Value store model.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('benjaminshoemaker/ai_coding_project_base/product-spec', 'community', 'benjaminshoemaker', 'ai_coding_project_base', 'benjaminshoemaker/ai_coding_project_base', 'product-spec', 32, 4, 65, '2026-02-24T18:47:00Z', '2026-03-06T06:38:50.143Z', '05fc539236fc9e67b0e645059e03c6522ac7a7669043a3b7373f41dd7ace5f09', '{"id":"benjaminshoemaker/ai_coding_project_base/product-spec","name":"product-spec","description":{"en":"The product-spec skill generates a product specification document for AI agents, guiding users through technical design and implementation planning. It benefits developers by producing executable documents.","zh":"产品规格设置指南是一种结构化的提示框架，用于构建软件产品。它指导您完成产品规格文档、技术设计和实施规划的生成","ja":"プロダクト仕様設定ガイドは、ソフトウェア製品の構築に使用される構造化されたプロンプトフレームワークです。製品仕様文書、技術設計、実装計画の生成をサポートします","ko":"제품 사양 설정 가이드는 소프트웨어 제품 구축에 사용되는 구조화된 프롬프트 프레임워크입니다. 제품 사양 문서, 기술 디자인, 구현 계획의 생성을 지원합니다","es":"La especificación de producto es una estructura de promps para la creación de software con asistentes de codificación de IA. Este toolkit te guía a través de la especificación de producto, diseño técnico y planificación de implementación.","fr":"La spécification de produit est un cadre de promps structurés pour la création de logiciels avec des assistants de codage IA. Ce toolkit vous guide à travers la spécification de produit, la conception technique et la planification de la mise en œuvre.","de":"Die Produkt-Spezifikation ist ein strukturiertes Promp-Framework für die Erstellung von Software mit KI-Coding-Assistenten. Dieses Toolkit führt Sie durch die Produkt-Spezifikation, technische Konzeption und Implementierungsplanung.","pt":"O ''product-spec'' é uma estrutura de prompt para construir produtos de software com assistentes de codificação de IA. Ele guia você através da especificação do produto, design técnico e planejamento de implementação.","ru":"Product-spec - это структурированный каркас для построения программных продуктов с помощью ИИ Агентов. Он ведет вас через спецификацию продукта, технический дизайн и планирование реализации.","ar":"product-spec هو إطار محدد لإنشاء منتجات برمجية مع مساعدة من وكلاء الترميز الذكية. إنه يوجهك خلال مواصفات المنتج والتصميم الفني وتخطيط التنفيذ"},"seo":{"title":{"en":"product-spec: Structured Prompt Framework for AI Agents |...","zh":"产品规格设置指南 - 使用AI工具构建软件产品","ja":"プロダクト仕様設定ガイド - AIエージェントを使用したソフトウェア製品の構築","ko":"제품 사양 설정 가이드 - AI 도구를 사용한 소프트웨어 제품 구축","es":"Guía de Configuración de Especificación de Producto con A...","fr":"Guide de Mise en Place de Spécification de Produit avec O...","de":"Einrichtungsanleitung für Produkt-Spezifikation mit KI-Ag...","pt":"Guia de Configuração de Especificação de Produto com Ferr...","ru":"Настройка продукта с помощью ИИ Агентов: Руководство","ar":"دليل إعداد مواصفات المنتج باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how product-spec streamlines software development with AI coding assistants. Get started with our setup guide and optimize your workflow today!","zh":"使用产品规格设置指南，通过AI工具构建软件产品，包括产品规格文档、技术设计和实施规划","ja":"プロダクト仕様設定ガイドを使用して、AIエージェントを使用したソフトウェア製品の構築を実現します。製品仕様文書、技術設計、実装計画などを含みます","ko":"제품 사양 설정 가이드를 사용하여 AI 도구를 사용한 소프트웨어 제품 구축을 구현합니다. 제품 사양 문서, 기술 디자인, 구현 계획 등을 포함합니다","es":"Aprende a crear un documento de especificación de producto para proyectos de software con asistentes de codificación de IA. Sigue nuestro checklist para una ...","fr":"Découvrez comment créer un document de spécification de produit pour les projets de logiciel avec des assistants de codage IA. Suivez notre checklist pour un...","de":"Erfahren Sie, wie Sie ein Produkt-Spezifikationsdokument für Software-Projekte mit KI-Coding-Assistenten erstellen. Befolgen Sie unsere Checkliste für eine e...","pt":"Aprenda a criar uma especificação de produto com a ajuda de assistentes de codificação de IA. Este guia aborda a estruturação de um projeto de software com f...","ru":"Узнайте, как создать спецификацию продукта с помощью ИИ Агентов. Это руководство поможет вам структурировать проект программного обеспечения с использованием...","ar":"تعرف على كيفية إنشاء مواصفات المنتج باستخدام أدوات الذكاء الاصطناعي. هذا الدليل يغطي هيكلة مشروع البرمجيات مع مساعدة من وكلاء الترميز الذكية"},"definition":{"en":"product-spec is a structured prompt framework for building software products with AI coding assistants, guiding technical design and implementation planning.","zh":"产品规格设置指南是一种用于构建软件产品的结构化提示框架","ja":"プロダクト仕様設定ガイドは、ソフトウェア製品の構築に使用される構造化されたプロンプトフレームワーク","ko":"제품 사양 설정 가이드는 소프트웨어 제품 구축에 사용되는 구조화된 프롬프트 프레임워크","es":"La especificación de producto es un documento que describe los requisitos y características de un proyecto de software.","fr":"La spécification de produit est un document qui décrit les exigences et les caractéristiques d''un projet de logiciel.","de":"Die Produkt-Spezifikation ist ein Dokument, das die Anforderungen und Eigenschaften eines Software-Projekts beschreibt.","pt":"Product-spec é uma ferramenta de inteligência artificial que ajuda a criar especificações de produto para projetos de software.","ru":"Product-spec - это инструмент ИИ Агентов, помогающий создавать спецификации продукта для проектов программного обеспечения.","ar":"product-spec هو أداة ذكاء اصطناعي تساعد على إنشاء مواصفات المنتج لمشاريع البرمجيات"},"features":{"en":["Generates PRODUCT_SPEC.md documents for AI agents","Guides users through a 8-step workflow, including directory guard and project root confirmation","Conducts guided Q&A with users to gather project specifications","Handles deferred decisions and reviews/refines documents with users","Produces documents that AI agents can execute against","Tracks progress using a checklist with steps like Step 1: Directory guard and Step 8: Suggest next step (/technical-spec)"],"zh":["生成产品规格文档","技术设计和实施规划","使用AI工具构建软件产品","包含目录保护、项目根确认、现有产品规格检查等功能","支持用户指导问答和产品规格文档编写","提供后续步骤建议（/technical-spec）"],"ja":["製品仕様文書の生成","技術設計と実装計画","AIエージェントを使用したソフトウェア製品の構築","ディレクトリ保護、プロジェクトルート確認、既存の製品仕様チェックなどの機能を含む","ユーザーガイドの質問と回答、および製品仕様文書の作成をサポート","次のステップの提案（/technical-spec）"],"ko":["제품 사양 문서 생성","기술 디자인 및 구현 계획","AI 도구를 사용한 소프트웨어 제품 구축","디렉토리 보호, 프로젝트 루트 확인, 기존 제품 사양 확인 등의 기능을 포함","사용자 가이드 질문과 답변, 및 제품 사양 문서 작성 지원","다음 단계 제안 (/technical-spec)"],"es":["Generación de documento de especificación de producto","Checklist para seguimiento del progreso","Diseño técnico y planificación de implementación","Compatibilidad con asistentes de codificación de IA","Revisión y refinamiento del documento de especificación","Sugerencias para el siguiente paso (/technical-spec)"],"fr":["Génération de document de spécification de produit","Checklist pour suivre les progrès","Conception technique et planification de la mise en œuvre","Compatibilité avec des assistants de codage IA","Révision et affinement du document de spécification","Suggestions pour l''étape suivante (/technical-spec)"],"de":["Erstellung von Produkt-Spezifikationsdokumenten","Checkliste für den Fortschrittsverlauf","Technische Konzeption und Implementierungsplanung","Kompatibilität mit KI-Coding-Assistenten","Überprüfung und Verfeinerung des Produkt-Spezifikationsdokuments","Vorschläge für den nächsten Schritt (/technical-spec)"],"pt":["Criação de documentos de especificação de produto","Estruturação de projetos de software com assistentes de codificação de IA","Planejamento de implementação com base em decisões técnicas","Revisão e refinamento da especificação do produto com o usuário","Integração com outras ferramentas de desenvolvimento de software","Suporte à tomada de decisões técnicas com base em requisitos do produto"],"ru":["Создание документов спецификации продукта","Структуризация проектов программного обеспечения с помощью ИИ Агентов","Планирование реализации на основе технических решений","Проверка и уточнение спецификации продукта с пользователем","Интеграция с другими инструментами разработки программного обеспечения","Поддержка принятия технических решений на основе требований продукта"],"ar":["إنشاء مستندات مواصفات المنتج","هيكلة مشاريع البرمجيات مع مساعدة من وكلاء الترميز الذكية","تخطيط التنفيذ بالاعتماد على القرارات الفنية","مراجعة وتحسين مواصفات المنتج مع المستخدم","التكامل مع أدوات تطوير البرمجيات الأخرى","دعم اتخاذ القرارات الفنية بالاعتماد على متطلبات المنتج"]},"keywords":{"en":["how to use product-spec","product-spec setup guide","product-spec alternative","what is product-spec","product-spec vs competitors","product-spec install","product-spec for AI agents","product-spec workflow","product-spec technical design","product-spec implementation planning"],"zh":["产品规格设置","AI工具","软件产品构建","产品规格文档","技术设计","实施规划","AI编码助手","结构化提示框架"],"ja":["プロダクト仕様設定","AIエージェント","ソフトウェア製品の構築","製品仕様文書","技術設計","実装計画","AIコーディングアシスタント","構造化されたプロンプトフレームワーク"],"ko":["제품 사양 설정","AI 도구","소프트웨어 제품 구축","제품 사양 문서","기술 디자인","구현 계획","AI 코딩 어시스트","구조화된 프롬프트 프레임워크"],"es":["especificación de producto","agentes de IA","asistentes de codificación","desarrollo de software","documentos de especificación","checklist de progreso","diseño técnico","planificación de implementación"],"fr":["spécification de produit","outils d''IA","assistants de codage","développement de logiciels","documents de spécification","checklist de progrès","conception technique","planification de la mise en œuvre"],"de":["Produkt-Spezifikation","KI-Agenten","KI-Coding-Assistenten","Software-Entwicklung","Produkt-Spezifikationsdokumente","Checkliste für den Fortschritt","technische Konzeption","Implementierungsplanung"],"pt":["product-spec","ferramentas de inteligência artificial","assistente de codificação de IA","especificação de produto","desenvolvimento de software","planejamento de implementação","revisão e refinamento","integração com outras ferramentas","tomada de decisões técnicas"],"ru":["product-spec","ИИ Агенты","инструменты искусственного интеллекта","спецификация продукта","разработка программного обеспечения","планирование реализации","проверка и уточнение","интеграция с другими инструментами","принятие технических решений"],"ar":["product-spec","أدوات الذكاء الاصطناعي","وكيل الترميز الذكي","مواصفات المنتج","تطوير البرمجيات","تخطيط التنفيذ","مراجعة وتحسين","التكامل مع أدوات أخرى","اتخاذ القرارات الفنية"]}},"owner":"benjaminshoemaker","repo":"ai_coding_project_base","repoPath":"benjaminshoemaker/ai_coding_project_base","stars":32,"forks":4,"updatedAt":"2026-02-24T18:47:00Z","topics":[],"category":"community","skillMd":{"name":"product-spec","description":"Generate PRODUCT_SPEC.md through guided Q&A. Use as the first step when starting a new greenfield project.","bodyPreview":"Generate a product specification document for the current project.\n\n## Workflow\n\nCopy this checklist and track progress:\n\n```\nProduct Spec Progress:\n- [ ] Step 1: Directory guard\n- [ ] Step 2: Project root confirmation\n- [ ] Step 3: Check for existing PRODUCT_SPEC.md\n- [ ] Step 4: Conduct guided Q&A with user\n- [ ] Step 5: Write PRODUCT_SPEC.md\n- [ ] Step 6: Handle deferred decisions\n- [ ] Step 7: Review and refine with user\n- [ ] Step 8: Suggest next step (/technical-spec)\n```\n\n## Directory Gua","body":"Generate a product specification document for the current project.\n\n## Workflow\n\nCopy this checklist and track progress:\n\n```\nProduct Spec Progress:\n- [ ] Step 1: Directory guard\n- [ ] Step 2: Project root confirmation\n- [ ] Step 3: Check for existing PRODUCT_SPEC.md\n- [ ] Step 4: Conduct guided Q&A with user\n- [ ] Step 5: Write PRODUCT_SPEC.md\n- [ ] Step 6: Handle deferred decisions\n- [ ] Step 7: Review and refine with user\n- [ ] Step 8: Suggest next step (/technical-spec)\n```\n\n## Directory Guard\n\n1. If `.toolkit-marker` exists in the current working directory → **STOP**:\n   \"You''re in the toolkit repo. Run this from your project directory instead:\n    `cd ~/Projects/your-project && /product-spec`\"\n\n## Project Root Confirmation\n\nBefore generating any files, confirm the output location with the user:\n\n```\nWill write PRODUCT_SPEC.md to: {absolute path of cwd}/\nContinue? (Yes / Change directory)\n```\n\nIf the user says \"Change directory\", ask for the correct path and instruct them to `cd` there first.\n\n## Existing File Guard (Prevent Overwrite)\n\nBefore asking any questions, check whether `PRODUCT_SPEC.md` already exists in the current directory.\n\n- If it does not exist: continue normally.\n- If it exists: **STOP** and ask the user what to do:\n  1. **Backup then overwrite (recommended)**: read the existing file and write it to `PRODUCT_SPEC.md.bak.YYYYMMDD-HHMMSS`, then write the new document to `PRODUCT_SPEC.md`\n  2. **Overwrite**: replace `PRODUCT_SPEC.md` with the new document\n  3. **Abort**: do not write anything; suggest they rename/move the existing file first\n\n## Process\n\nRead `.claude/skills/product-spec/PROMPT.md` and follow its instructions exactly:\n\n1. Ask the user to describe their idea\n2. Work through each question category (Problem, Users, Experience, Features, Data)\n3. Make recommendations with confidence levels\n4. Generate the final PRODUCT_SPEC.md document\n\n## Output\n\nWrite the completed specification to `PRODUCT_SPEC.md` in the current directory.\n\nAfter writing PRODUCT_SPEC.md, verify the file exists and is non-empty by reading the first few lines. If the file was not created successfully, report the error and retry.\n\n## Deferred Requirements Capture (During Q&A)\n\n**IMPORTANT:** Capture deferred requirements interactively during the Q&A process, not after.\n\n### When to Trigger\n\nDuring the Q&A, watch for signals that the user is deferring a requirement:\n- \"out of scope\"\n- \"not for MVP\" / \"post-MVP\"\n- \"v2\" / \"version 2\" / \"future\"\n- \"later\" / \"eventually\"\n- \"maybe\" / \"nice to have\"\n- \"we''ll skip that for now\"\n- \"not right now\"\n- \"that''s a separate thing\"\n\n### Capture Flow\n\nWhen you detect a deferral signal, immediately use AskUserQuestion:\n\n```\nQuestion: \"Would you like to save this to your deferred requirements?\"\nHeader: \"Defer?\"\nOptions:\n  - \"Yes, capture it\" — I''ll ask a few quick questions to document it\n  - \"No, skip\" — Don''t record this\n```\n\n**If user selects \"Yes, capture it\":**\n\nAsk these clarifying questions (can be combined into one AskUserQuestion with multiple questions):\n\n1. **What''s being deferred?**\n   \"In one sentence, what''s the requirement or feature?\"\n   (Pre-fill with your understanding from context)\n\n2. **Why defer it?**\n   Options: \"Out of scope for MVP\" / \"Needs more research\" / \"V2 feature\" / \"Resource constraints\" / \"Other\"\n\n3. **Notes for later?**\n   \"Any context that will help when revisiting this?\"\n   (Optional — user can skip)\n\n### Write to DEFERRED.md Immediately\n\nAfter collecting answers, append to `DEFERRED.md` right away (don''t wait until end).\n\n**If file doesn''t exist, create it:**\n\n```markdown\n# Deferred Requirements\n\n> Captured during specification Q&A. Review when planning future versions.\n\n## From PRODUCT_SPEC.md ({date})\n\n| Requirement | Reason | Notes |\n|-------------|--------|-------|\n| {user''s answer} | {selected reason} | {notes or \"—\"} |\n```\n\n**If file exists, append:**\n\n```markdown\n| {user''s answer} | {selected reason} | {notes or \"—\"} |\n```\n\n(If appending to a different spec''s section, add a new section header first.)\n\n### Continue Q&A\n\nAfter capturing (or skipping), continue the spec Q&A where you left off. Don''t break the flow.\n\n## Cross-Model Review (Automatic)\n\nAfter writing PRODUCT_SPEC.md, run cross-model review if Codex CLI is available:\n\n1. Check if Codex CLI is installed: `codex --version`\n2. If available, run `/codex-consult` on the generated document\n3. Present any findings to the user before proceeding\n\n**Consultation invocation:**\n```\n/codex-consult --research \"product requirements, user stories\" PRODUCT_SPEC.md\n```\n\n**If Codex finds issues:**\n- Show critical issues and recommendations\n- Ask user: \"Address findings before proceeding?\" (Yes/No)\n- If Yes: Apply suggested fixes\n- If No: Continue with noted issues\n\n**If Codex unavailable:** Skip silently and proceed to Next Step.\n\n## Error Handling\n\n| Situation | Action |\n|-----------|--------|\n| PROMPT.md not found at `.claude/skills/product-spec/PROMPT.md` | Stop and report \"Skill asset missing — reinstall toolkit or run /setup\" |\n| DEFERRED.md write fails (permissions or disk) | Output deferred items to terminal, warn user, continue with spec generation |\n| Codex CLI invocation fails or times out | Log the error, skip cross-model review, proceed to Next Step |\n\n## Next Step\n\nWhen complete, inform the user:\n```\nPRODUCT_SPEC.md created at ./PRODUCT_SPEC.md\nDeferred Requirements: {count} items captured to DEFERRED.md\nCross-Model Review: PASSED | PASSED WITH NOTES | SKIPPED\n\nNext: Run /technical-spec\n```\n"},"lastSynced":"2026-03-06T06:38:50.143Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automated technical design and implementation planning through comprehensive product specification documents.","zh":"非常适合需要通过综合产品规格文档自动化技术设计和实施规划的AI代理。","ja":"包括包括的な製品仕様書を通じた自動化された技術設計と実施計画を必要とするAIエージェントに最適です。","ko":"포괄적인 제품 사양 문서를 통해 자동화된 기술 설계 및 구현 계획이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan diseño y planificación técnica automatizados a través de documentos de especificación de producto completos.","fr":"Parfait pour les agents IA nécessitant une conception et une planification techniques automatisées via des documents de spécification de produit complets.","de":"Perfekt für KI-Agenten, die eine automatisierte technische Konzeption und Implementierungsplanung durch umfassende Produktspezifikationsdokumente benötigen.","pt":"Perfeito para Agentes de IA que necessitam de design e planejamento de implementação técnicos automatizados por meio de documentos de especificação de produtos abrangentes.","ru":"Идеально подходит для агентов ИИ, которым необходимы автоматизированный технический дизайн и планирование реализации через всесторонние документы спецификации продукта.","ar":"مثالي لعمليات وكيل الإي‌آي التي تحتاج إلى تصميم وتنفيذ تقنيين آليين من خلال وثائق مواصفات المنتج الشاملة."},"recommendation":{"en":"Empowers agents to generate executable product specification documents using guided Q&A sessions and technical planning, leveraging Markdown files like PRODUCT_SPEC.md for transparent project tracking and collaboration.","zh":"能够通过引导式问答会话和技术规划为代理生成可执行的产品规格文档，同时利用Markdown文件（如PRODUCT_SPEC.md）实现透明的项目跟踪和协作。","ja":"ガイド付きのQ&Aセッションと技術計画を利用して、エージェントが実行可能な製品仕様書を生成できるようにし、Markdownファイル（例：PRODUCT_SPEC.md）を使用して透明なプロジェクト追跡とコラボレーションを実現します。","ko":"가이드된 Q&A 세션 및 기술 계획을 사용하여 에이전트가 실행 가능한 제품 사양 문서를 생성할 수 있도록 하며, Markdown 파일(예: PRODUCT_SPEC.md)을 사용하여 투명한 프로젝트 추적 및 협력을实现합니다.","es":"Habilita a los agentes a generar documentos de especificación de producto ejecutables utilizando sesiones de preguntas y respuestas guiadas y planificación técnica, aprovechando archivos Markdown como PRODUCT_SPEC.md para un seguimiento y colaboración de proyectos transparentes.","fr":"Permet aux agents de générer des documents de spécification de produit exécutables à l''aide de sessions de questions et réponses guidées et de planification technique, en exploitant des fichiers Markdown comme PRODUCT_SPEC.md pour un suivi et une collaboration de projets transparents.","de":"Ermächtigt Agenten, ausführbare Produktspezifikationsdokumente zu erstellen, indem sie guided Q&A-Sitzungen und technische Planung nutzen und Markdown-Dateien wie PRODUCT_SPEC.md für transparente Projektverfolgung und -zusammenarbeit verwenden.","pt":"Habilita os agentes a gerar documentos de especificação de produtos executáveis usando sessões de perguntas e respostas orientadas e planejamento técnico, aproveitando arquivos Markdown como PRODUCT_SPEC.md para acompanhamento e colaboração de projetos transparentes.","ru":"Наделяет агентов возможностью генерировать исполняемые документы спецификации продукта с помощью руководимых сессий вопросов и ответов и технического планирования, используя файлы Markdown, такие как PRODUCT_SPEC.md, для прозрачной отслеживания и сотрудничества проектов.","ar":"يمنح الوكيل khảية توليد وثائق مواصفات المنتج القابلة للتنفيذ باستخدام جلسات أسئلة وأجوبة موجهة والتخطيط الفني، واستغلال ملفات Markdown مثل PRODUCT_SPEC.md لتعقب المشاريع والتعاون الشفاف."},"useCases":{"en":["Generating product specification documents for new projects","Automating technical design planning with Q&A sessions","Creating executable documents for project implementation"],"zh":["为新项目生成产品规格文档","使用Q&A会话自动化技术设计规划","创建可执行文档以用于项目实施"],"ja":["新しいプロジェクトの製品仕様書を生成する","Q&Aセッションを使用して技術設計計画を自動化する","プロジェクト実施のために実行可能なドキュメントを作成する"],"ko":["새로운 프로젝트를 위한 제품 사양 문서 생성","Q&A 세션을 사용하여 기술 설계 계획 자동화","프로젝트 구현을 위한 실행 가능한 문서 생성"],"es":["Generación de documentos de especificación de producto para nuevos proyectos","Automatización de la planificación del diseño técnico con sesiones de preguntas y respuestas","Creación de documentos ejecutables para la implementación de proyectos"],"fr":["Génération de documents de spécification de produit pour de nouveaux projets","Automatisation de la planification de la conception technique avec des sessions de questions et réponses","Création de documents exécutables pour la mise en œuvre de projets"],"de":["Erstellung von Produktspezifikationsdokumenten für neue Projekte","Automatisierung der technischen Konzeptionsplanung mit Q&A-Sitzungen","Erstellung von ausführbaren Dokumenten für die Projektimplementierung"],"pt":["Geração de documentos de especificação de produtos para novos projetos","Automatização do planejamento de design técnico com sessões de perguntas e respostas","Criação de documentos executáveis para implementação de projetos"],"ru":["Генерация документов спецификации продукта для новых проектов","Автоматизация планирования технического дизайна с помощью сессий вопросов и ответов","Создание исполняемых документов для реализации проектов"],"ar":["توليد وثائق مواصفات المنتج للمشاريع الجديدة","أتمتة تخطيط التصميم الفني بدورات الأسئلة والأجوبة","إنشاء وثائق قابلة للتنفيذ لتنفيذ المشاريع"]},"limitations":{"en":["Requires user input for guided Q&A","Limited to generating PRODUCT_SPEC.md files","Needs project root confirmation for proper directory setup"],"zh":["需要用户输入以进行引导式Q&A","仅限生成PRODUCT_SPEC.md文件","需要项目根目录确认以进行适当的目录设置"],"ja":["ガイド付きQ&Aのためにユーザー入力を必要とする","PRODUCT_SPEC.mdファイルの生成のみ","適切なディレクトリ設定のためにプロジェクトルートの確認が必要"],"ko":["가이드된 Q&A를 위해 사용자 입력이 필요","PRODUCT_SPEC.md 파일 생성만","적절한 디렉토리 설정을 위해 프로젝트 루트 확인이 필요"],"es":["Requiere la entrada del usuario para sesiones de preguntas y respuestas guiadas","Limitado a la generación de archivos PRODUCT_SPEC.md","Necesita la confirmación de la raíz del proyecto para una configuración de directorio adecuada"],"fr":["Nécessite une entrée utilisateur pour des sessions de questions et réponses guidées","Limité à la génération de fichiers PRODUCT_SPEC.md","Nécessite une confirmation de la racine du projet pour une configuration de répertoire correcte"],"de":["Benutzereingabe für guided Q&A-Sitzungen erforderlich","Begrenzt auf die Generierung von PRODUCT_SPEC.md-Dateien","Benötigt die Bestätigung der Projektwurzel für eine ordnungsgemäße Verzeichniseinrichtung"],"pt":["Requer entrada do usuário para sessões de perguntas e respostas orientadas","Limitado a gerar arquivos PRODUCT_SPEC.md","Necessita de confirmação da raiz do projeto para configuração de diretório adequada"],"ru":["Требует ввода пользователя для руководимых сессий вопросов и ответов","Ограничен генерацией файлов PRODUCT_SPEC.md","Требует подтверждения корня проекта для правильной настройки директории"],"ar":["يتطلب إدخال المستخدم لجلسات الأسئلة والأجوبة الموجهة","محدود بتوليد ملفات PRODUCT_SPEC.md","يحتاج إلى تأكيد جذر المشروع لإعداد الدليل المناسب"]},"version":4},"contentHash":"05fc539236fc9e67b0e645059e03c6522ac7a7669043a3b7373