INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('benjaminshoemaker/ai_coding_project_base/product-spec', 'product-spec', 'benjaminshoemaker', 'ai_coding_project_base', 'community', 'product-spec benjaminshoemaker ai_coding_project_base community The product-spec skill generates a product specification document for AI agents, guiding users through technical design and implementation planning. It benefits developers by producing executable documents. 产品规格设置指南是一种结构化的提示框架，用于构建软件产品。它指导您完成产品规格文档、技术设计和实施规划的生成 プロダクト仕様設定ガイドは、ソフトウェア製品の構築に使用される構造化されたプロンプトフレームワークです。製品仕様文書、技術設計、実装計画の生成をサポートします 제품 사양 설정 가이드는 소프트웨어 제품 구축에 사용되는 구조화된 프롬프트 프레임워크입니다. 제품 사양 문서, 기술 디자인, 구현 계획의 생성을 지원합니다 La especificación de producto es una estructura de promps para la creación de software con asistentes de codificación de IA. Este toolkit te guía a través de la especificación de producto, diseño técnico y planificación de implementación. La spécification de produit est un cadre de promps structurés pour la création de logiciels avec des assistants de codage IA. Ce toolkit vous guide à travers la spécification de produit, la conception technique et la planification de la mise en œuvre. Die Produkt-Spezifikation ist ein strukturiertes Promp-Framework für die Erstellung von Software mit KI-Coding-Assistenten. Dieses Toolkit führt Sie durch die Produkt-Spezifikation, technische Konzeption und Implementierungsplanung. O ''product-spec'' é uma estrutura de prompt para construir produtos de software com assistentes de codificação de IA. Ele guia você através da especificação do produto, design técnico e planejamento de implementação. Product-spec - это структурированный каркас для построения программных продуктов с помощью ИИ Агентов. Он ведет вас через спецификацию продукта, технический дизайн и планирование реализации. product-spec هو إطار محدد لإنشاء منتجات برمجية مع مساعدة من وكلاء الترميز الذكية. إنه يوجهك خلال مواصفات المنتج والتصميم الفني وتخطيط التنفيذ how to use product-spec product-spec setup guide product-spec alternative what is product-spec product-spec vs competitors product-spec install product-spec for AI agents product-spec workflow product-spec technical design product-spec implementation planning 产品规格设置 AI工具 软件产品构建 产品规格文档 技术设计 实施规划 AI编码助手 结构化提示框架 Generates PRODUCT_SPEC.md documents for AI agents Guides users through a 8-step workflow, including directory guard and project root confirmation Conducts guided Q&A with users to gather project specifications Handles deferred decisions and reviews/refines documents with users Produces documents that AI agents can execute against Tracks progress using a checklist with steps like Step 1: Directory guard and Step 8: Suggest next step (/technical-spec) product-spec is a structured prompt framework for building software products with AI coding assistants, guiding technical design and implementation planning.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sfc-gh-dflippo/snowflake-dbt-demo/dbt-artifacts', 'community', 'sfc-gh-dflippo', 'snowflake-dbt-demo', 'sfc-gh-dflippo/snowflake-dbt-demo', 'dbt-artifacts', 28, 8, 65, '2026-02-19T20:02:32Z', '2026-03-06T06:39:21.828Z', 'd6606a67970176e314ad3f11e6542f75866c50179345ba159d92ec1040a5199e', '{"id":"sfc-gh-dflippo/snowflake-dbt-demo/dbt-artifacts","name":"dbt-artifacts","description":{"en":"The dbt-artifacts skill enables AI agents to monitor dbt execution using the brooklyn-data/dbt_artifacts package, capturing metadata for analysis and monitoring. This skill benefits users seeking to track dbt runs and data quality.","zh":"dbt-artifacts Skill 是一个使用 Snowflake Data Cloud 监控 dbt 执行的项目，捕获详细的执行元数据并存储在可查询的表中","ja":"dbt-artifacts スキルは、Snowflake Data Cloud を使用して dbt 実行を監視するプロジェクトで、詳細な実行メタデータをキャプチャして分析可能なテーブルに保存します","ko":"dbt-artifacts Skill은 Snowflake Data Cloud를 사용하여 dbt 실행을 모니터링하는 프로젝트로,详细한 실행 메타데이터를 캡처하여 분석 가능한 테이블에 저장합니다","es":"dbt-artifacts es un paquete que captura metadatos de ejecución detallados durante las ejecuciones de dbt y los almacena en tablas consultables para análisis y monitoreo","fr":"dbt-artifacts est un package qui capture des métadonnées d''exécution détaillées lors des exécutions de dbt et les stocke dans des tables consultables pour analyse et surveillance","de":"dbt-artifacts ist ein Paket, das detaillierte Ausführungsmetadaten während der Ausführung von dbt erfasst und sie in abfragbaren Tabellen für Analyse und Überwachung speichert","pt":"O dbt-artifacts é um pacote que captura metadados de execução detalhados durante a execução do dbt e os armazena em tabelas consultáveis para análise e monitoramento","ru":"dbt-artifacts - это пакет, который захватывает詳細ные метаданные выполнения во время выполнения dbt и хранит их в запросных таблицах для анализа и мониторинга","ar":"dbt-artifacts هو حزمة تقوم bằng التقاط بيانات تشغيل مفصلة أثناء تشغيل dbt وتخزينها في جداول قابلة للاستعلام للتحليل والمراقبة"},"seo":{"title":{"en":"dbt-artifacts: Monitoring dbt Execution for AI Agents | A...","zh":"dbt-artifacts 设置指南：使用 Snowflake Data Cloud 监控 dbt 执行","ja":"dbt-artifacts セットアップガイド：Snowflake Data Cloud を使用した dbt 実行の監視","ko":"dbt-artifacts 설정 가이드: Snowflake Data Cloud를 사용한 dbt 실행 모니터링","es":"Guía de configuración de dbt-artifacts para monitoreo de ...","fr":"Guide de configuration de dbt-artifacts pour le monitorin...","de":"Konfigurationsleitfaden für dbt-artifacts zur Ausführungs...","pt":"Guia de Configuração dbt-artifacts: Ferramentas de IA par...","ru":"ИИ Агенты для dbt-artifacts: Руководство по Настройке и М...","ar":"دليل إعداد dbt-artifacts: أدوات ذكاء اصطناعي لمراقبة التنفيذ"},"description":{"en":"Unlock detailed dbt execution metadata with dbt-artifacts. Learn how to track test history, analyze run patterns, and monitor data quality metrics with this ...","zh":"使用 dbt-artifacts Skill 监控 dbt 执行，分析运行模式并跟踪数据质量指标，AIエージェント帮助您简化 dbt 监控","ja":"dbt-artifacts スキルを使用して dbt 実行を監視し、実行パターンを分析し、データ品質メトリックを追跡します。AIエージェントが dbt モニタリングを簡素化します","ko":"dbt-artifacts Skill을 사용하여 dbt 실행을 모니터링하고 실행 패턴을 분석하고 데이터 품질 메트릭을 추적합니다. AI 에이전트가 dbt 모니터링을 간소화합니다","es":"Aprende a utilizar dbt-artifacts con Snowflake Data Cloud para monitorear la ejecución de dbt y analizar patrones de ejecución","fr":"Découvrez comment utiliser dbt-artifacts avec Snowflake Data Cloud pour surveiller l''exécution de dbt et analyser les modèles d''exécution","de":"Erfahren Sie, wie Sie dbt-artifacts mit Snowflake Data Cloud verwenden, um die Ausführung von dbt zu überwachen und Ausführungsmuster zu analysieren","pt":"Aprenda a configurar e utilizar o dbt-artifacts com Ferramentas de IA para monitorar a execução do dbt e melhorar a qualidade dos dados","ru":"Узнайте, как настроить и использовать dbt-artifacts с ИИ Агентами для мониторинга выполнения dbt и улучшения качества данных","ar":"تعرف على كيفية إعداد وتشغيل dbt-artifacts مع أدوات ذكاء اصطناعي لمراقبة تنفيذ dbt وتحسين جودة البيانات"},"definition":{"en":"dbt-artifacts is a package that captures detailed execution metadata during dbt runs, storing it in queryable tables for analysis and monitoring.","zh":"dbt-artifacts 是一个使用 Snowflake Data Cloud 监控 dbt 执行的 Skill，提供详细的执行元数据","ja":"dbt-artifacts は、Snowflake Data Cloud を使用して dbt 実行を監視するスキルで、詳細な実行メタデータを提供します","ko":"dbt-artifacts는 Snowflake Data Cloud를 사용하여 dbt 실행을 모니터링하는 Skill로,詳細한 실행 메타데이터를 제공합니다","es":"dbt-artifacts es un paquete que permite a los agentes de inteligencia artificial monitorear la ejecución de dbt","fr":"dbt-artifacts est un package qui permet aux agents d''intelligence artificielle de surveiller l''exécution de dbt","de":"dbt-artifacts ist ein Paket, das es künstlichen Intelligenz-Agenten ermöglicht, die Ausführung von dbt zu überwachen","pt":"dbt-artifacts é um pacote que fornece funcionalidades de monitoramento e análise de execução do dbt","ru":"dbt-artifacts - это пакет, который предоставляет функциональность мониторинга и анализа выполнения dbt","ar":"dbt-artifacts هو حزمة توفر وظائف مراقبة وتحليل تشغيل dbt"},"features":{"en":["Captures detailed execution metadata during dbt runs","Stores metadata in queryable tables for analysis and monitoring","Tracks test and model execution history","Analyzes dbt run patterns over time","Monitors data quality metrics from dbt tests","Utilizes the brooklyn-data/dbt_artifacts package"],"zh":["监控 dbt 执行","分析运行模式","跟踪数据质量指标","捕获详细的执行元数据","存储在可查询的表中","使用 Snowflake Data Cloud"],"ja":["dbt 実行の監視","実行パターンの分析","データ品質メトリックの追跡","詳細な実行メタデータのキャプチャ","分析可能なテーブルへの保存","Snowflake Data Cloud の使用"],"ko":["dbt 실행 모니터링","실행 패턴 분석","데이터 품질 메트릭 추적","詳細한 실행 메타데이터 캡처","분석 가능한 테이블에 저장","Snowflake Data Cloud 사용"],"es":["Captura de metadatos de ejecución detallados","Almacenamiento de metadatos en tablas consultables","Análisis de patrones de ejecución de dbt","Monitoreo de la calidad de los datos desde pruebas de dbt","Integración con Snowflake Data Cloud"],"fr":["Capture de métadonnées d''exécution détaillées","Stockage de métadonnées dans des tables consultables","Analyse de modèles d''exécution de dbt","Surveillance de la qualité des données depuis les tests de dbt","Intégration avec Snowflake Data Cloud"],"de":["Erfassung detaillierter Ausführungsmetadaten","Speicherung von Metadaten in abfragbaren Tabellen","Analyse von Ausführungsmustern von dbt","Überwachung der Datenqualität von dbt-Tests","Integration mit Snowflake Data Cloud"],"pt":["Captura de metadados de execução detalhados","Armazenamento de metadados em tabelas consultáveis","Análise de padrões de execução do dbt","Monitoramento de métricas de qualidade de dados","Integração com o Snowflake Data Cloud"],"ru":["Захват 詳細ных метаданных выполнения","Хранение метаданных в запросных таблицах","Анализ паттернов выполнения dbt","Мониторинг метрик качества данных","Интеграция с Snowflake Data Cloud"],"ar":["التقاط بيانات تشغيل مفصلة","تخزين البيانات في جداول قابلة للاستعلام","تحليل أنماط تشغيل dbt","مراقبة مقاييس جودة البيانات","التكامل مع Snowflake Data Cloud"]},"keywords":{"en":["how to use dbt-artifacts","dbt-artifacts setup guide","dbt-artifacts alternative","dbt-artifacts vs brooklyn-data","dbt execution monitoring","dbt run analysis","data quality metrics with dbt","install dbt-artifacts","dbt-artifacts documentation"],"zh":["dbt-artifacts","Snowflake Data Cloud","dbt 执行监控","AIエージェント","dbt 运行模式分析","数据质量指标跟踪"],"ja":["dbt-artifacts","Snowflake Data Cloud","dbt 実行監視","AIエージェント","dbt 実行パターン分析","データ品質メトリックの追跡"],"ko":["dbt-artifacts","Snowflake Data Cloud","dbt 실행 모니터링","AI 에이전트","dbt 실행 패턴 분석","데이터 품질 메트릭 추적"],"es":["dbt-artifacts","monitoreo de ejecución de dbt","análisis de patrones de ejecución","Snowflake Data Cloud","agentes de inteligencia artificial","herramientas de inteligencia artificial","dbt y Snowflake","monitoreo de calidad de datos","pruebas de dbt"],"fr":["dbt-artifacts","surveillance de l''exécution de dbt","analyse de modèles d''exécution","Snowflake Data Cloud","agents d''intelligence artificielle","outils d''intelligence artificielle","dbt et Snowflake","surveillance de la qualité des données","tests de dbt"],"de":["dbt-artifacts","Überwachung der Ausführung von dbt","Analyse von Ausführungsmustern","Snowflake Data Cloud","künstliche Intelligenz-Agenten","künstliche Intelligenz-Tools","dbt und Snowflake","Überwachung der Datenqualität","dbt-Tests"],"pt":["dbt-artifacts","Ferramentas de IA","Monitoramento de execução","Análise de dados","Qualidade de dados","Snowflake Data Cloud","dbt","Metadados de execução","Tabelas consultáveis"],"ru":["dbt-artifacts","ИИ Агенты","Мониторинг выполнения","Анализ данных","Качество данных","Snowflake Data Cloud","dbt","Метаданные выполнения","Запросные таблицы"],"ar":["dbt-artifacts","أدوات ذكاء اصطناعي","مراقبة التنفيذ","تحليل البيانات","جودة البيانات","Snowflake Data Cloud","dbt","بيانات تشغيل","جداول قابلة للاستعلام"]}},"owner":"sfc-gh-dflippo","repo":"snowflake-dbt-demo","repoPath":"sfc-gh-dflippo/snowflake-dbt-demo","stars":28,"forks":8,"updatedAt":"2026-02-19T20:02:32Z","topics":[],"category":"community","skillMd":{"name":"dbt-artifacts","description":"","bodyPreview":"# dbt Artifacts Package - AI Instructions\n\n## Purpose\n\nThis skill enables AI agents to help users monitor dbt execution using the\nbrooklyn-data/dbt_artifacts package. The package captures detailed execution metadata during dbt\nruns and stores it in queryable tables for analysis and monitoring.\n\n## When to Use This Skill\n\nActivate this skill when users ask about:\n\n- Tracking test and model execution history\n- Analyzing dbt run patterns over time\n- Monitoring data quality metrics from dbt tests\n-","body":"# dbt Artifacts Package - AI Instructions\n\n## Purpose\n\nThis skill enables AI agents to help users monitor dbt execution using the\nbrooklyn-data/dbt_artifacts package. The package captures detailed execution metadata during dbt\nruns and stores it in queryable tables for analysis and monitoring.\n\n## When to Use This Skill\n\nActivate this skill when users ask about:\n\n- Tracking test and model execution history\n- Analyzing dbt run patterns over time\n- Monitoring data quality metrics from dbt tests\n- Investigating dbt performance issues or slow models\n- Setting up execution logging and observability\n- Querying dbt execution metadata programmatically\n- Comparing dbt monitoring approaches (Artifacts vs Event Tables)\n\n## What dbt Artifacts Does\n\nThe package captures one row per dbt artifact execution (models, tests, seeds, snapshots) with:\n\n- **Execution status**: success, error, skipped, fail, warn\n- **Runtime metrics**: Duration, rows affected, compile time\n- **Test results**: Failure counts, error messages\n- **Run context**: Command, environment, dbt version, threading\n- **Dependencies**: Model lineage and relationships\n\n## Core Tables Reference\n\n| Table              | Purpose                   | Key Columns                                                             |\n| ------------------ | ------------------------- | ----------------------------------------------------------------------- |\n| `invocations`      | One row per dbt run       | `command_invocation_id`, `dbt_command`, `target_name`, `run_started_at` |\n| `model_executions` | Model runtime performance | `status`, `total_node_runtime`, `rows_affected`, `materialization`      |\n| `test_executions`  | Data quality tracking     | `status`, `failures`, `total_node_runtime`, `message`                   |\n| `seeds`            | Seed file execution       | Similar to model_executions                                             |\n| `snapshots`        | Snapshot execution        | Similar to model_executions with SCD tracking                           |\n| `sources`          | Source freshness          | Freshness check results                                                 |\n| `exposures`        | Exposure execution        | Exposure dependencies                                                   |\n\n**Join Pattern**: Always join through `command_invocation_id` (links all executions in a run) and\n`node_id` (identifies specific artifact).\n\n## Installation & Setup\n\nWhen users need to install or configure dbt Artifacts:\n\n### Step 1: Add Package\n\nAdd to `packages.yml`:\n\n```yaml\npackages:\n  - package: brooklyn-data/dbt_artifacts\n    version: 2.9.3\n```\n\n### Step 2: Configure Hook\n\nAdd to `dbt_project.yml`:\n\n```yaml\non-run-end:\n  - \"{{ dbt_artifacts.upload_results(results) }}\"\n\nmodels:\n  dbt_artifacts:\n    +database: your_database\n    +schema: dbt_artifacts\n```\n\n### Step 3: Install and Initialize\n\n```bash\ndbt deps\ndbt run --select dbt_artifacts\n```\n\nAfter first run, all subsequent dbt invocations automatically log results.\n\n## Helping Users with Queries\n\n### Query Strategy\n\nWhen users ask for monitoring queries:\n\n1. **Identify the goal**: What are they trying to monitor? (test failures, slow models, run history,\n   etc.)\n2. **Reference query library**: Point to relevant queries in the `scripts/` directory (see\n   **Monitoring Queries** section below)\n3. **Customize as needed**: Adjust date ranges, filters, thresholds\n4. **Explain results**: Help interpret the output and recommend actions\n\n### Common Query Patterns\n\nAll queries are available as individual executable scripts. See the **Monitoring Queries** section\nbelow for detailed descriptions and usage.\n\n### Query Best Practices\n\n**ALWAYS recommend these patterns:**\n\n- ✅ Filter by `run_started_at` with specific date range (performance)\n\n  ```sql\n  WHERE run_started_at >= DATEADD(day, -7, CURRENT_TIMESTAMP())\n  ```\n\n- ✅ Use `command_invocation_id` to link related executions efficiently\n- ✅ Filter `HAVING COUNT(*) >= 5` for meaningful aggregations\n- ✅ Join through both `command_invocation_id` AND `node_id` when linking metadata to executions\n\n**NEVER do these:**\n\n- ❌ Query entire table without date filtering\n\n  ```sql\n  -- BAD: Scans entire history\n  SELECT * FROM test_executions WHERE status = ''fail'';\n\n  -- GOOD: Filtered by date\n  SELECT * FROM test_executions\n  WHERE status = ''fail''\n    AND run_started_at >= DATEADD(day, -7, CURRENT_TIMESTAMP());\n  ```\n\n- ❌ Create alerts for every single test failure (too noisy)\n- ❌ Store more than 6 months without archival strategy\n\n### Storage Management\n\n**Archival Strategy (Quarterly):**\n\n```sql\n-- Archive data older than 90 days\nCREATE TABLE dbt_artifacts_archive.model_executions_2024_q4 AS\nSELECT *\nFROM dbt_artifacts.model_executions\nWHERE run_started_at < DATEADD(day, -90, CURRENT_DATE());\n\n-- Delete archived data from active tables\nDELETE FROM dbt_artifacts.model_executions\nWHERE run_started_at < DATEADD(day, -90, CURRENT_DATE());\n```\n\n**Storage Planning:**\n\n- Small project (50 models, 100 tests): ~1-5 MB/week\n- Medium project (200 models, 500 tests): ~10-20 MB/week\n- Large project (1000+ models, 2000+ tests): ~50-100 MB/week\n\nPlan for **1-2 GB per quarter** for medium projects.\n\n## Comparing Monitoring Approaches\n\nWhen users ask \"Should I use dbt Artifacts or Event Tables?\":\n\n### Use dbt Artifacts When\n\n**Cross-platform compatibility is critical:**\n\n- Running dbt from multiple platforms (dbt Cloud, local CLI, Airflow, etc.)\n- Need consistent monitoring across all execution environments\n- Team uses mixed deployment strategies\n\n**Historical analysis is primary goal:**\n\n- Analyzing trends over 30+ days\n- Long-term performance baseline tracking\n- Quarterly or annual reporting on dbt execution\n- Compliance or audit trail requirements\n\n**Running dbt outside Snowflake:**\n\n- Using dbt Cloud exclusively\n- Executing dbt from Airflow, Azure DevOps, GitHub Actions\n- Local development with dbt CLI\n- Any non-Snowflake execution environment\n\n**Programmatic access to metadata required:**\n\n- Building custom dashboards in BI tools\n- Integrating with existing observability platforms\n- Creating custom alerting logic\n- Feeding data to data catalogs or lineage tools\n\n**Delayed reporting is acceptable:**\n\n- Runs on `on-run-end` hook (after full execution completes)\n- Historical batch analysis vs real-time monitoring\n- End-of-run summaries are sufficient\n\n### Avoid dbt Artifacts When\n\n**Real-time monitoring is critical:**\n\n- Need immediate notification of failures\n- Want to see execution progress during runs\n- Require detailed trace spans and profiling → **Use**: dbt Projects on Snowflake Event Tables\n\n**Running exclusively in Snowflake:**\n\n- Using dbt PROJECT objects in Snowflake\n- Native Snowflake integration preferred\n- Want Snowflake-native telemetry → **Use**: dbt Projects Event Tables\n\n**Storage constraints exist:**\n\n- Limited database space for historical data\n- Can''t maintain growing execution history\n- No archival strategy in place → **Use**: Event Tables with shorter retention or external logging\n\n### Use Both for Comprehensive Monitoring\n\n**Recommended Architecture:**\n\n```sql\ndbt Artifacts (Historical)          Event Tables (Real-time)\n        ↓                                    ↓\nLong-term trends                   Immediate alerts\nQuarterly reports                  Live dashboards\nCross-platform metrics             Trace-level profiling\nBI tool integration               Native Snowflake tools\n```\n\n**Example:**\n\n1. **Event Tables**: Monitor active runs in real-time, alert on failures immediately\n2. **dbt Artifacts**: Analyze historical patterns, track monthly trends, feed BI dashboards\n\n### Comparison Matrix\n\n| Feature                   | dbt Artifacts             | dbt Projects Event Tables     |\n| ------------------------- | ------------------------- | ----------------------------- |\n| **Execution Environment** | Any (Cloud, CLI, Airflow) | Snowflake native only         |\n| **Telemetry Timing**      | On run completion (hook)  | Real-time during execution    |\n| **Historical Data**       | User-managed retention    | Configurable retention policy |\n| **Platform Integration**  | Cross-platform            | Snowflake-native              |\n| **Query Interface**       | Standard SQL tables       | Event table syntax            |\n| **Setup Complexity**      | Package + hook config     | dbt PROJECT configuration     |\n| **Trace Spans**           | No                        | Yes (detailed profiling)      |\n| **Best For**              | Historical analysis       | Real-time monitoring          |\n\n## Monitoring Queries\n\nIndividual SQL scripts for common monitoring tasks. Execute with Snowflake CLI:\n\n```sql\nsnow sql -f scripts/<query_file>.sql -c default\n```\n\n### Test Quality Monitoring\n\n**scripts/test_reliability_metrics.sql**\n\n- Calculate pass/fail rates to identify flaky tests\n- Shows failure percentages and execution times\n- Filters tests with 5+ executions for statistical relevance\n\n**scripts/recent_test_failures.sql**\n\n- Track test failures from last 7 days with full context\n- Includes run details, test names, and error messages\n- Useful for immediate troubleshooting\n\n**scripts/test_execution_trends.sql**\n\n- Daily test execution counts and pass/fail rates\n- Track test suite health over 30-day period\n- Identify patterns in test failures\n\n### Model Performance Monitoring\n\n**scripts/slowest_models.sql**\n\n- Identify top 20 slowest models by average runtime\n- Shows min/max/avg execution times and row counts\n- Filter models with 5+ executions\n\n**scripts/model_execution_errors.sql**\n\n- Recent model failures (last 7 days) with error messages\n- Includes model path and execution context\n- Helps identify recurring model issues\n\n**scripts/performance_regression_detection.sql**\n\n- Compare recent (7-day) vs baseline (30-day) performance\n- Alert on models with 20%+ slowdown\n- Calculate performance degradation percentage\n\n### Execution History\n\n**scripts/dbt_run_summary.sql**\n\n- High-level overview of all dbt runs (last 30 days)\n- Shows commands, targets, versions, and refresh flags\n- Useful for audit trails and pattern analysis\n\n## Common User Tasks\n\n### Task 1: \"Show me recent test failures\"\n\n1. Run: `snow sql -f scripts/recent_test_failures.sql -c default`\n2. Adjust date range if needed (default: last 7 days)\n3. Explain how to interpret `failures` column (0 = pass, >0 = fail)\n4. Suggest filtering by specific test names or models if needed\n\n### Task 2: \"Which models are slowest?\"\n\n1. Run: `snow sql -f scripts/slowest_models.sql -c default`\n2. Help identify if slowness is consistent (avg) or intermittent (max)\n3. Suggest investigating models > 5 minutes or 2x baseline\n4. Recommend materialization changes or optimization strategies\n\n### Task 3: \"Track test reliability over time\"\n\n1. Run: `snow sql -f scripts/test_reliability_metrics.sql -c default`\n2. Help identify flaky tests (failure_rate_pct between 10-90%)\n3. Recommend investigating tests with 100% failure rate\n4. Suggest baseline: < 5% failure rate for healthy tests\n\n### Task 4: \"Set up dbt Artifacts\"\n\n1. Walk through 3-step installation (packages.yml → dbt_project.yml → dbt deps)\n2. Verify installation: `dbt run --select dbt_artifacts`\n3. Test logging: `dbt run` (any command) then query `invocations` table\n4. Recommend dedicated schema and archival strategy\n\n## Troubleshooting Common Issues\n\n| Issue                | Solution                                                                      |\n| -------------------- | ----------------------------------------------------------------------------- |\n| \"No data in tables\"  | Verify `on-run-end` hook in dbt_project.yml; run `dbt run` to trigger logging |\n| \"Tables not created\" | Run `dbt run --select dbt_artifacts` explicitly first                         |\n| \"Permission denied\"  | Ensure dbt user has CREATE/INSERT rights in target database/schema            |\n| \"Missing columns\"    | Update package: `dbt deps --upgrade` to latest version                        |\n| \"Slow queries\"       | Add date filter on `run_started_at`; consider archiving old data              |\n\n## Related Skills\n\n**Complementary Observability:**\n\n- `dbt-projects-on-snowflake` skill - For native Snowflake deployment with real-time event table\n  monitoring\n\n**When to use both together:**\n\n- **dbt Artifacts** for cross-platform monitoring and historical analysis across all dbt\n  environments\n- **dbt Projects on Snowflake** for real-time Snowflake-native monitoring with OpenTelemetry tracing\n\n**When to use one vs the other:**\n\n- Use **dbt Artifacts** alone if you run dbt outside Snowflake (dbt Cloud, Airflow, local)\n- Use **dbt Projects on Snowflake** alone if you exclusively run dbt within Snowflake\n- Use **both** for comprehensive enterprise monitoring (historical + real-time)\n\n---\n\n## Monitoring Best Practices\n\n### Test Quality Best Practices\n\n**Establish baselines:**\n\n- **Healthy**: Test failure rate < 5%\n- **Warning**: Test failure rate 5-10%\n- **Critical**: Test failure rate > 10%\n\n**Identify flaky tests:**\n\n- Failure rate between 10-90% (inconsistent results)\n- Recommend investigation or test refactoring\n\n**Alert on patterns:**\n\n- New test with 100% failure rate (incorrect test logic)\n- Previously stable test suddenly failing\n- Test execution time 2x+ baseline\n\n### Model Performance Best Practices\n\n**Performance thresholds:**\n\n- **Investigate**: Models consistently > 5 minutes\n- **Critical**: Runtime increase > 2x historical average\n- **Optimize**: Models in top 20 slowest\n\n**Alert strategies:**\n\n- High priority: Models with `status = ''error''`\n- Medium priority: Runtime increase > 50% from baseline\n- Low priority: Slow model trending (track over time)\n\n### Alerting Best Practices\n\n**High Priority (Immediate Action):**\n\n- Test status = ''fail'' or ''error''\n- Model status = ''error''\n- Critical model runtime > 2x baseline\n- Production environment failures\n\n**Medium Priority (Investigation Within 24h):**\n\n- Test status = ''warn''\n- Model skipped > 10% of runs\n- Runtime increase > 50% from baseline\n- Unusual invocation patterns\n\n**Low Priority (Track Trends):**\n\n- Slow model performance (not critical path)\n- Test success rate slowly declining\n- Incremental drift in execution duration\n\n---\n\n## Additional Resources\n\n- **SQL Scripts**: `scripts/` - Individual query files ready to execute with Snowflake CLI\n- **Package Documentation**:\n  [brooklyn-data.github.io/dbt_artifacts](https://brooklyn-data.github.io/dbt_artifacts)\n- **GitHub Repository**:\n  [github.com/brooklyn-data/dbt_artifacts](https://github.com/brooklyn-data/dbt_artifacts)\n"},"lastSynced":"2026-03-06T06:39:21.828Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Analysis Agents requiring advanced dbt execution monitoring and metadata analysis capabilities using the brooklyn-data/dbt_artifacts package.","zh":"适用于需要高级 dbt 执行监控和元数据分析能力的数据分析代理，利用 brooklyn-data/dbt_artifacts 包。","ja":"データ分析エージェントが高度な dbt 実行監視とメタデータ分析機能を必要とする場合に適しています。brooklyn-data/dbt_artifacts パッケージを使用します。","ko":"데이터 분석 에이전트가 고급 dbt 실행 모니터링 및 메타데이터 분석 기능을 필요로 할 때 적합합니다. brooklyn-data/dbt_artifacts 패키지를 사용합니다.","es":"Ideal para Agentes de Análisis de Datos que requieren una ejecución de monitoreo avanzada de dbt y capacidades de análisis de metadatos utilizando el paquete brooklyn-data/dbt_artifacts.","fr":"Idéal pour les Agents d''Analyse de Données nécessitant une surveillance avancée de l''exécution dbt et des capacités d''analyse de métadonnées en utilisant le paquet brooklyn-data/dbt_artifacts.","de":"Ideal für Datenanalyse-Agents, die eine erweiterte Überwachung der dbt-Ausführung und Metadatenanalysefunktionen unter Verwendung des Pakets brooklyn-data/dbt_artifacts erfordern.","pt":"Ideal para Agentes de Análise de Dados que exigem monitoramento avançado de execução dbt e capacidades de análise de metadados usando o pacote brooklyn-data/dbt_artifacts.","ru":"Идеально для Агентов Анализа Данных, требующих расширенного мониторинга выполнения dbt и возможностей анализа метаданных с использованием пакета brooklyn-data/dbt_artifacts.","ar":"مثالية للوكلاء التحليليين للبيانات الذين يتطلبون مراقبة متقدمة للتنفيذ dbt وقدرات تحليل البيانات الوصفية باستخدام حزمة brooklyn-data/dbt_artifacts."},"recommendation":{"en":"Empowers agents to capture detailed execution metadata during dbt runs, storing it in queryable tables for analysis and monitoring, utilizing the brooklyn-data/dbt_artifacts package for enhanced data quality metrics and test execution history tracking.","zh":"赋予代理捕获 dbt 运行期间的详细执行元数据的能力，将其存储在可查询的表中以进行分析和监控，利用 brooklyn-data/dbt_artifacts 包以获得增强的数据质量指标和测试执行历史跟踪。","ja":"エージェントが dbt 実行中に詳細な実行メタデータをキャプチャし、分析および監視のためにクエリ可能なテーブルに保存することを可能にします。brooklyn-data/dbt_artifacts パッケージを使用して、データ品質メトリクスとテスト実行履歴の追跡を強化します。","ko":"에이전트가 dbt 실행 중에详细한 실행 메타데이터를 캡처하여 분석 및 모니터링을 위해 쿼리 가능한 테이블에 저장할 수 있도록 합니다. brooklyn-data/dbt_artifacts 패키지를 사용하여 데이터 품질 메트릭과 테스트 실행 기록 추적을 강화합니다.","es":"Permite a los agentes capturar metadatos de ejecución detallados durante las ejecuciones de dbt, almacenándolos en tablas consultables para análisis y monitoreo, utilizando el paquete brooklyn-data/dbt_artifacts para métricas de calidad de datos mejoradas y seguimiento de la historia de ejecución de pruebas.","fr":"Permet aux agents de capturer des métadonnées d''exécution détaillées pendant les exécutions dbt, les stockant dans des tables interrogables pour l''analyse et la surveillance, en utilisant le paquet brooklyn-data/dbt_artifacts pour des métriques de qualité de données améliorées et un suivi de l''historique d''exécution des tests.","de":"Ermöglicht es Agents, detaillierte Ausführungsmetadaten während dbt-Läufen zu erfassen und in abfragbaren Tabellen für Analyse und Überwachung zu speichern, unter Verwendung des Pakets brooklyn-data/dbt_artifacts für verbesserte Datenqualitätsmetriken und Verlaufsverfolgung von Testausführungen.","pt":"Habilita os agentes a capturar metadados de execução detalhados durante as execuções dbt, armazenando-os em tabelas consultáveis para análise e monitoramento, utilizando o pacote brooklyn-data/dbt_artifacts para métricas aprimoradas de qualidade de dados e rastreamento de histórico de execução de testes.","ru":"Наделяет агентов возможностью захватывать подробные метаданные выполнения во время запусков dbt, храня их в запросных таблицах для анализа и мониторинга, используя пакет brooklyn-data/dbt_artifacts для улучшенных метрик качества данных и отслеживания истории выполнения тестов.","ar":"تمكّن الوكلاء من التقاط بيانات وصفية مفصلة أثناء تشغيل dbt، وتخزينها في جداول قابلة للاستعلام للتحليل والمراقبة، باستخدام حزمة brooklyn-data/dbt_artifacts لمقاييس جودة البيانات المعززة وتعقب سجل تشغيل الاختبارات."},"useCases":{"en":["Tracking test and model execution history for auditing and compliance","Analyzing dbt run patterns over time to optimize data pipeline performance","Monitoring data quality metrics from dbt tests for proactive issue detection"],"zh":["用于审计和合规性的测试和模型执行历史记录跟踪","随时间分析 dbt 运行模式以优化数据管道性能","监控 dbt 测试的数据质量指标以进行主动问题检测"],"ja":["監査およびコンプライアンスのためにテストおよびモデル実行履歴を追跡する","時間の経過に伴う dbt 実行パターンを分析してデータパイプラインのパフォーマンスを最適化する","dbt テストのデータ品質メトリクスを監視して事前に問題を検出する"],"ko":["감사 및 컴플라이언스 목적으로 테스트 및 모델 실행 기록을 추적하는 것","시간이 지남에 따라 dbt 실행 패턴을 분석하여 데이터 파이프라인 성능을 최적화하는 것","dbt 테스트의 데이터 품질 메트릭을 모니터링하여 사전 문제 감지를 수행하는 것"],"es":["Seguimiento de la historia de ejecución de pruebas y modelos para auditorías y cumplimiento","Análisis de patrones de ejecución de dbt a lo largo del tiempo para optimizar el rendimiento de la canalización de datos","Monitoreo de métricas de calidad de datos de pruebas dbt para la detección proactiva de problemas"],"fr":["Suivi de l''historique d''exécution des tests et des modèles pour les audits et la conformité","Analyse des modèles d''exécution dbt au fil du temps pour optimiser les performances du pipeline de données","Surveillance des métriques de qualité de données des tests dbt pour la détection proactive des problèmes"],"de":["Verfolgung der Ausführungshistorie von Tests und Modellen für Audits und Compliance","Analyse von dbt-Ausführungsmustern im Laufe der Zeit zur Optimierung der Datenpipelingleistung","Überwachung von Datenqualitätsmetriken von dbt-Tests zur proaktiven Problemerkennung"],"pt":["Rastreamento do histórico de execução de testes e modelos para auditoria e conformidade","Análise de padrões de execução dbt ao longo do tempo para otimizar o desempenho do pipeline de dados","Monitoramento de métricas de qualidade de dados de testes dbt para detecção proativa de problemas"],"ru":["Отслеживание истории выполнения тестов и моделей для аудита и соответствия требованиям","Анализ закономерностей выполнения dbt во времени для оптимизации производительности конвейера данных","Мониторинг метрик качества данных из тестов dbt для проактивного обнаружения проблем"],"ar":["تتبع سجل تشغيل الاختبارات والنماذج للتدقيق والامتثال","تحليل أنماط تشغيل dbt بمرور الوقت لتحسين أداء管ة البيانات","مراقبة مقاييس جودة البيانات من اختبارات dbt للكشف المبكر عن المشكلات"]},"limitations":{"en":["Requires installation and configuration of the brooklyn-data/dbt_artifacts package","Dependent on dbt execution for metadata collection"],"zh":["需要安装和配置 brooklyn-data/dbt_artifacts 包","依赖 dbt 执行以收集元数据"],"ja":["brooklyn-data/dbt_artifacts パッケージのインストールおよび設定が必要","メタデータの収集には dbt 実行に依存する"],"ko":["brooklyn-data/dbt_artifacts 패키지의 설치 및 구성이 필요","메타데이터 수집은 dbt 실행에 의존"],"es":["Requiere la instalación y configuración del paquete brooklyn-data/dbt_artifacts","Depende de la ejecución de dbt para la recopilación de metadatos"],"fr":["Nécessite l''installation et la configuration du paquet brooklyn-data/dbt_artifacts","Dépend de l''exécution dbt pour la collecte de métadonnées"],"de":["Erfordert die Installation und Konfiguration des Pakets brooklyn-data/dbt_artifacts","Hängt von der dbt-Ausführung für die Metadatenerfassung ab"],"pt":["Exige a instalação e configuração do pacote brooklyn-data/dbt_artifacts","Depende da execução dbt para coleta de metadados"],"ru":["Требует установки и настройки пакета brooklyn-data/dbt_artifacts","Зависит от выполнения dbt для сбора метаданных"],"ar":["يتطلب تثبيت وتكوين حزمة brooklyn-data/dbt_artifacts","يعتمد على تشغيل dbt لجمع البيانات الوصفية"]},"version":4},"contentHash":"d6606a67970176e314ad3f11e6542f75866c50179345ba159d92ec1040a5199e","qualityScore":65}');
