INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sfc-gh-dflippo/snowflake-dbt-demo/dbt-artifacts', 'dbt-artifacts', 'sfc-gh-dflippo', 'snowflake-dbt-demo', 'community', 'dbt-artifacts sfc-gh-dflippo snowflake-dbt-demo community The dbt-artifacts skill enables AI agents to monitor dbt execution using the brooklyn-data/dbt_artifacts package, capturing metadata for analysis and monitoring. This skill benefits users seeking to track dbt runs and data quality. dbt-artifacts Skill 是一个使用 Snowflake Data Cloud 监控 dbt 执行的项目，捕获详细的执行元数据并存储在可查询的表中 dbt-artifacts スキルは、Snowflake Data Cloud を使用して dbt 実行を監視するプロジェクトで、詳細な実行メタデータをキャプチャして分析可能なテーブルに保存します dbt-artifacts Skill은 Snowflake Data Cloud를 사용하여 dbt 실행을 모니터링하는 프로젝트로,详细한 실행 메타데이터를 캡처하여 분석 가능한 테이블에 저장합니다 dbt-artifacts es un paquete que captura metadatos de ejecución detallados durante las ejecuciones de dbt y los almacena en tablas consultables para análisis y monitoreo dbt-artifacts est un package qui capture des métadonnées d''exécution détaillées lors des exécutions de dbt et les stocke dans des tables consultables pour analyse et surveillance dbt-artifacts ist ein Paket, das detaillierte Ausführungsmetadaten während der Ausführung von dbt erfasst und sie in abfragbaren Tabellen für Analyse und Überwachung speichert O dbt-artifacts é um pacote que captura metadados de execução detalhados durante a execução do dbt e os armazena em tabelas consultáveis para análise e monitoramento dbt-artifacts - это пакет, который захватывает詳細ные метаданные выполнения во время выполнения dbt и хранит их в запросных таблицах для анализа и мониторинга dbt-artifacts هو حزمة تقوم bằng التقاط بيانات تشغيل مفصلة أثناء تشغيل dbt وتخزينها في جداول قابلة للاستعلام للتحليل والمراقبة how to use dbt-artifacts dbt-artifacts setup guide dbt-artifacts alternative dbt-artifacts vs brooklyn-data dbt execution monitoring dbt run analysis data quality metrics with dbt install dbt-artifacts dbt-artifacts documentation dbt-artifacts Snowflake Data Cloud dbt 执行监控 AIエージェント dbt 运行模式分析 数据质量指标跟踪 Captures detailed execution metadata during dbt runs Stores metadata in queryable tables for analysis and monitoring Tracks test and model execution history Analyzes dbt run patterns over time Monitors data quality metrics from dbt tests Utilizes the brooklyn-data/dbt_artifacts package dbt-artifacts is a package that captures detailed execution metadata during dbt runs, storing it in queryable tables for analysis and monitoring.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vultisig/vultisig-ios/batch-tasks', 'community', 'vultisig', 'vultisig-ios', 'vultisig/vultisig-ios', 'batch-tasks', 26, 15, 65, '2026-03-06T20:57:29Z', '2026-03-07T01:51:10.328Z', '273dc39ac7a42e206df82c939e13733c2299613d6048d8324988f79b30f153ec', '{"id":"vultisig/vultisig-ios/batch-tasks","name":"batch-tasks","description":{"en":"The batch-tasks skill automates overnight workflows by orchestrating multiple independent tasks in parallel. It benefits developers by integrating with CodeRabbit for automated PR review.","zh":"批量任务运行器用于orchestrates多个独立任务的并行运行，每个任务都有自己的分支、隔离工作树和 PR","ja":"バッチタスクランナーは複数の独立したタスクを並列で実行し、各タスクに独自のブランチ、分離されたワークツリー、PR を提供する","ko":"배치 작업 실행기는 여러 개의 독립적인 작업을 병렬로 실행하며, 각 작업에 대해 전용 브랜치, 분리된 워크 트리 및 PR을 제공한다","es":"Batch-tasks es un ejecutor de tareas que orquesta múltiples tareas en paralelo, ideal para flujos de trabajo asíncronos","fr":"Batch-tasks est un exécuteur de tâches qui orchestre plusieurs tâches en parallèle, idéal pour les flux de travail asynchrones","de":"Batch-tasks ist ein Task-Runner, der mehrere Aufgaben in Parallel ausführt, ideal für asynchrone Workflows","pt":"O batch-tasks é uma ferramenta que orquestra múltiplas tarefas independentes em paralelo, com integração com CodeRabbit para revisão automática de PR.","ru":"Batch-tasks — это инструмент, который координирует несколько независимых задач в параллели, с интеграцией с CodeRabbit для автоматического обзора PR.","ar":"batch-tasks هو أداة توجيه مهام مستقلة متعددة بالتوازي، مع التكامل مع CodeRabbit لاستعراض(PR) آلي"},"seo":{"title":{"en":"batch-tasks: Overnight Task Automation Setup Guide | AI A...","zh":"批量任务运行器 Setup Guide - Vultisig iOS App","ja":"バッチタスクランナー AIエージェント - Vultisig iOS App","ko":"배치 작업 실행기 설정 가이드 - Vultisig iOS App","es":"Guía de configuración de batch-tasks para flujos de traba...","fr":"Guide de mise en place de batch-tasks pour les flux de tr...","de":"Einrichtungsleitfaden für batch-tasks in asynchronen Work...","pt":"Guia de Configuração do batch-tasks: Execução de Tarefas ...","ru":"Настройка ИИ Агентов: batch-tasks для Параллельного Выпол...","ar":"دليل إعداد batch-tasks: تشغيل مهام متوازي مع أدوات ذكاء ا..."},"description":{"en":"Discover how to automate overnight tasks with batch-tasks. Learn to orchestrate multiple tasks in parallel and integrate with CodeRabbit for automated PR rev...","zh":"了解批量任务运行器的技术细节，包括并行任务运行和 CodeRabbit 集成","ja":"バッチタスクランナーの技術詳細を学ぶ - パラレルタスク実行と CodeRabbit 統合","ko":"배치 작업 실행기의 기술 세부 사항 알아보기 - 병렬 작업 실행 및 CodeRabbit 통합","es":"Automatice tareas independientes en paralelo con batch-tasks y CodeRabbit para revisiones de PR automatizadas","fr":"Automatisez des tâches indépendantes en parallèle avec batch-tasks et CodeRabbit pour des révisions de PR automatisées","de":"Automatisieren Sie unabhängige Aufgaben in Parallel mit batch-tasks und CodeRabbit für automatisierte PR-Überprüfungen","pt":"Aprenda a configurar o batch-tasks para executar tarefas independentes em paralelo, com integração com CodeRabbit para revisão automática de PR","ru":"Узнайте, как настроить batch-tasks для параллельного выполнения независимых задач, с интеграцией с CodeRabbit для автоматического обзора PR","ar":"تعلم كيفية إعداد batch-tasks لتشغيل مهام مستقلة بالتوازي، مع التكامل مع CodeRabbit لاستعراض(PR) آلي"},"definition":{"en":"batch-tasks is a task automation skill that orchestrates multiple independent tasks in parallel, designed for overnight or async workflows.","zh":"批量任务运行器是一种用于orchestrates多个独立任务的并行运行的工具","ja":"バッチタスクランナーは、複数の独立したタスクを並列で実行するためのツール","ko":"배치 작업 실행기는 여러 개의 독립적인 작업을 병렬로 실행하기 위한 도구","es":"Batch-tasks es un agente de AI que ejecuta tareas en paralelo y automatiza revisiones de PR con CodeRabbit","fr":"Batch-tasks est un outil d''AI qui exécute des tâches en parallèle et automatise les révisions de PR avec CodeRabbit","de":"Batch-tasks ist ein AI-Tool, das Aufgaben in Parallel ausführt und PR-Überprüfungen mit CodeRabbit automatisiert","pt":"O que é batch-tasks? É uma ferramenta de execução de tarefas em paralelo que orquestra múltiplas tarefas independentes.","ru":"Что такое batch-tasks? Это инструмент параллельного выполнения задач, который координирует несколько независимых задач.","ar":"ما هو batch-tasks؟ هو أداة تشغيل مهام بالتوازي التي توجيه مهام مستقلة متعددة"},"features":{"en":["Orchestrates multiple independent tasks in parallel using isolated worktrees and PRs","Integrates with CodeRabbit for automated PR review","Supports invocation via the `/batch-tasks` command","Allows specification of task dependencies using `after` syntax","Creates a separate branch for each task","Generates PRs for each task"],"zh":["并行任务运行","CodeRabbit 集成","每个任务都有自己的分支","每个任务都有自己的隔离工作树","每个任务都有自己的 PR"],"ja":["パラレルタスク実行","CodeRabbit 統合","各タスクに独自のブランチ","各タスクに分離されたワークツリー","各タスクに独自の PR"],"ko":["병렬 작업 실행","CodeRabbit 통합","각 작업에 대해 전용 브랜치","각 작업에 대해 분리된 워크 트리","각 작업에 대해 전용 PR"],"es":["Ejecución de tareas en paralelo","Integración con CodeRabbit para revisiones de PR automatizadas","Cada tarea se ejecuta en una rama y árbol de trabajo aislado","Soporte para flujos de trabajo asíncronos y nocturnos","Uso de comandos CLI para invocar tareas"],"fr":["Exécution de tâches en parallèle","Intégration avec CodeRabbit pour des révisions de PR automatisées","Chaque tâche s''exécute dans une branche et un arbre de travail isolé","Prise en charge des flux de travail asynchrones et nocturnes","Utilisation de commandes CLI pour invoquer des tâches"],"de":["Ausführung von Aufgaben in Parallel","Integration mit CodeRabbit für automatisierte PR-Überprüfungen","Jede Aufgabe wird in einer eigenen Branch und einem isolierten Arbeitsbaum ausgeführt","Unterstützung für asynchrone und nächtliche Workflows","Verwendung von CLI-Befehlen zum Aufrufen von Aufgaben"],"pt":["Execução de tarefas independentes em paralelo","Integração com CodeRabbit para revisão automática de PR","Cada tarefa recebe sua própria branch, worktree isolado e PR","Suporte a workflows assíncronos e noturnos","Comando `/batch-tasks` para iniciar a execução de tarefas"],"ru":["Параллельное выполнение независимых задач","Интеграция с CodeRabbit для автоматического обзора PR","Каждая задача получает свою собственную ветку, изолированную рабочую область и PR","Поддержка асинхронных и ночных рабочих процессов","Команда `/batch-tasks` для запуска выполнения задач"],"ar":["تشغيل مهام مستقلة بالتوازي","التكامل مع CodeRabbit لاستعراض(PR) آلي","كل مهمة تحصل على فرعها الخاص، شجرة عمل معزولة و(PR)","دعم سير عمل غير متزامن وночوي","الأمر `/batch-tasks` لتشغيل تشغيل المهام"]},"keywords":{"en":["how to use batch-tasks","batch-tasks alternative","batch-tasks setup guide","what is batch-tasks","batch-tasks vs CodeRabbit","batch-tasks install","automating overnight tasks","parallel task automation","CodeRabbit integration"],"zh":["批量任务运行器","并行任务运行","CodeRabbit 集成","Vultisig iOS App","批量任务 Setup Guide","AI 工具","批量任务技术细节"],"ja":["バッチタスクランナー","パラレルタスク実行","CodeRabbit 統合","Vultisig iOS App","バッチタスク Setup Guide","AIエージェント","バッチタスク技術詳細"],"ko":["배치 작업 실행기","병렬 작업 실행","CodeRabbit 통합","Vultisig iOS App","배치 작업 설정 가이드","AI 도구","배치 작업 기술 세부 사항"],"es":["batch-tasks","agente de AI","herramientas de AI","automatización de tareas","flujos de trabajo asíncronos","revisiones de PR automatizadas","CodeRabbit","CLI"],"fr":["batch-tasks","outil d''AI","outils d''AI","automatisation de tâches","flux de travail asynchrones","révisions de PR automatisées","CodeRabbit","CLI"],"de":["batch-tasks","AI-Tool","AI-Tools","Automatisierung von Aufgaben","asynchrone Workflows","automatisierte PR-Überprüfungen","CodeRabbit","CLI"],"pt":["batch-tasks","execução de tarefas em paralelo","integração com CodeRabbit","revisão automática de PR","workflows assíncronos","workflows noturnos","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["batch-tasks","параллельное выполнение задач","интеграция с CodeRabbit","автоматический обзор PR","асинхронные рабочие процессы","ночные рабочие процессы","инструменты разработки","разработка программного обеспечения"],"ar":["batch-tasks","تشغيل مهام بالتوازي","التكامل مع CodeRabbit","استعراض(PR) آلي","سير عمل غير متزامن","سير عمل ليلي","أدوات التطوير","تطوير البرمجيات"]}},"owner":"vultisig","repo":"vultisig-ios","repoPath":"vultisig/vultisig-ios","stars":26,"forks":15,"updatedAt":"2026-03-06T20:57:29Z","topics":[],"category":"community","skillMd":{"name":"batch-tasks","description":"Run multiple tasks overnight as parallel PRs. Produces a PRD per task, selects skills/rules, spawns isolated agents, and reports PR links.","bodyPreview":"# Batch — Overnight Task Runner\n\n## Overview\n\nOrchestrates multiple independent tasks in parallel. Each task gets its own branch, isolated worktree, and PR. Designed for overnight/async workflows where the user reviews results later. Integrates with CodeRabbit for automated PR review.\n\n## Usage\n\n```\n/batch-tasks\n1. #42\n2. Fix balance rounding on SendScreen\n3. #108 (after #1)\n4. https://github.com/vultisig/vultisig-ios/issues/55 (after #1, #3)\n```\n\nOr just invoke `/batch-tasks` without tasks and","body":"# Batch — Overnight Task Runner\n\n## Overview\n\nOrchestrates multiple independent tasks in parallel. Each task gets its own branch, isolated worktree, and PR. Designed for overnight/async workflows where the user reviews results later. Integrates with CodeRabbit for automated PR review.\n\n## Usage\n\n```\n/batch-tasks\n1. #42\n2. Fix balance rounding on SendScreen\n3. #108 (after #1)\n4. https://github.com/vultisig/vultisig-ios/issues/55 (after #1, #3)\n```\n\nOr just invoke `/batch-tasks` without tasks and you''ll be prompted for the task list.\n\n## Input\n\nThe user provides a numbered list of tasks. Each task can be:\n- **A GitHub issue** — `#123` or a full URL like `https://github.com/vultisig/vultisig-ios/issues/123`\n- **Plain text** — a short description of work to be done\n- **Mixed** — combine both formats freely\n\n### Dependency Syntax\n\nTasks can declare dependencies using `(after #N)` where N is the task number in the list:\n\n```\n/batch-tasks\n1. #42\n2. #108 (after #1)\n3. Fix balance rounding on SendScreen\n4. https://github.com/vultisig/vultisig-ios/issues/55 (after #1, #3)\n```\n\n- `(after #1)` — task 2 waits for task 1 to complete and branches from task 1''s branch instead of `main`\n- `(after #1, #3)` — task 4 waits for both task 1 and 3; branches from the last dependency''s branch\n- Tasks without `(after ...)` are independent and run in parallel from `main`\n\nIf the user invokes `/batch-tasks` without tasks, ask them to provide the task list.\n\n## Phase 0 — Issue Fetching\n\nBefore triaging, resolve all GitHub issue references. For each `#N` or issue URL, run:\n\n```bash\ngh issue view {N} --json title,body,labels,assignees\n```\n\nExtract from the response:\n- **Title** — becomes the task title\n- **Body** — provides requirements, context, and acceptance criteria for the PRD\n- **Labels** — help with skill/rule selection (e.g. `bug`, `enhancement`, `ui`, `blockchain`)\n\nIf an issue cannot be fetched (not found, permissions), flag it in the PRD output and ask the user for clarification.\n\nFor plain-text tasks, skip this phase — use the description as-is.\n\n### Label-to-Skill Hints\n\nUse issue labels as additional signal for skill selection:\n\n| Label contains... | Suggests skill |\n|---|---|\n| `ui`, `design`, `view` | `ui-components` |\n| `network`, `api`, `service` | `networking-guide` |\n| `model`, `data`, `storage` | `swiftdata-guide` |\n| `chain`, `blockchain`, `keygen`, `keysign` | `blockchain-guide` |\n| `bug`, `fix`, `refactor`, `enhancement` | `swift-patterns` |\n\n## Phase 1 — Triage & PRD Generation\n\nFor each task, produce a PRD block. Research the codebase BEFORE generating PRDs — use Glob, Grep, and Read to find relevant files so the PRD is grounded in real code.\n\n### Complexity Assessment\n\nEvaluate each task and assign a complexity level:\n\n| Complexity | Criteria | Action |\n|---|---|---|\n| **Simple** | 1-2 files, clear scope, no architectural decisions | Proceed normally |\n| **Moderate** | 3-5 files, some design choices, clear pattern to follow | Proceed with detailed approach |\n| **Complex** | 6+ files, architectural decisions, cross-cutting concerns, ambiguous requirements | Warn the user — suggest splitting or clarifying before approval |\n\n### PRD Format\n\nPresent all PRDs in a single message for approval:\n\n```\n## Task {n}: {title}\n- **Issue**: #{N} (if from GitHub, otherwise \"N/A\")\n- **Complexity**: {Simple | Moderate | Complex} — {one-line justification}\n- **Dependencies**: {none | \"after Task #X\" with explanation}\n- **Branch**: `{type}/{issue-number}-{slugified-title}` if from issue, else `{type}/{kebab-case-name}` (max 50 chars). Type is `fix` for bugs, `feat` for features/enhancements, `refactor` for refactors, `chore` for maintenance. Default to `fix` if unclear.\n- **Skills**: {comma-separated skill names to load}\n- **CLAUDE.md Rules**: {rule numbers that apply, e.g. #1, #6, #9}\n- **Key Files**: {files to read/modify, workspace-relative paths}\n- **Approach**: {2-4 sentences describing the implementation strategy}\n- **Acceptance Criteria**:\n  - {criterion 1}\n  - {criterion 2}\n  - SwiftLint passes with no new warnings\n```\n\nIf any task is **Complex**, add a warning block:\n\n```\n⚠️ Complex Tasks Detected:\n- Task {n}: {reason why it''s complex and suggestion to split or clarify}\n```\n\n### Skill Selection Guide\n\nChoose from these based on task nature:\n\n| Task involves... | Load skill |\n|---|---|\n| UI changes, colors, fonts, buttons, screens | `ui-components` |\n| State management, ViewModels, navigation, code style | `swift-patterns` |\n| API calls, networking, services | `networking-guide` |\n| SwiftData models, Storage, persistence | `swiftdata-guide` |\n| Blockchain logic, chains, TSS, keygen/keysign | `blockchain-guide` |\n\n### Rule Selection Guide\n\nAlways include **#9 (SwiftLint)**. Then add relevant rules:\n\n| Task involves... | Include rules |\n|---|---|\n| Any UI work | #1 (Design System), #6 (deprecated APIs) |\n| User-facing text | #4 (Localization) |\n| Buttons | #5 (PrimaryButton) |\n| Full screens | #8 (Screen component) |\n| Data models | #2 (SwiftData MainActor) |\n| Networking | #3 (TargetType + HTTPClient), #7 (async/await) |\n| Platform support | #10 (Cross-platform) |\n| Architecture changes | #11 (Business logic in ViewModels) |\n\n## Phase 2 — Approval\n\nAfter presenting all PRDs, ask the user to approve or adjust. Use AskUserQuestion with options:\n- \"Approve all — start execution\"\n- \"I want to adjust some tasks\"\n\nDo NOT proceed to Phase 3 until the user explicitly approves.\n\n## Phase 3 — Parallel Execution\n\n### Execution Order\n\n1. **Independent tasks** (no dependencies) — spawn ALL in parallel in a single message\n2. **Dependent tasks** — wait for their dependency to complete, then spawn them (using the dependency''s branch as base)\n\nFor each task, spawn an Agent with:\n- `subagent_type: \"general-purpose\"`\n- `isolation: \"worktree\"`\n- `run_in_background: true`\n\n### Agent Prompt Template\n\nUse this template for each agent''s prompt, filling in the PRD values:\n\n```\nYou are implementing a task for the Vultisig iOS app.\n\n## Task\n{task title}\n\n{If from GitHub issue, include the full issue body here for context}\n\n## Branch\nCreate branch: `{branch-name}` from `{base-branch}`\n{base-branch is \"main\" for independent tasks, or the dependency''s branch name for dependent tasks}\n\n## Skills to Load\nLoad these skills before starting work (use the Skill tool):\n{for each skill: - Load skill: `{skill-name}`}\n\n## CLAUDE.md Rules to Follow\nPay special attention to these rules from CLAUDE.md:\n{for each rule: - Rule #{n}: {brief description}}\n\n## Key Files\nRead these files first to understand the context:\n{for each file: - `{file-path}`}\n\n## Implementation Plan\n{approach from PRD}\n\n## Acceptance Criteria\n{criteria from PRD}\n\n## Workflow\n\n### Step 1 — Setup\n1. Load the skills listed above using the Skill tool\n2. Read all key files to understand the current code\n3. Create the branch: `git checkout {base-branch} && git pull && git checkout -b {branch-name}`\n\n### Step 2 — Implement\n4. Implement the changes following the plan and rules\n5. Follow all CLAUDE.md rules strictly\n\n### Step 3 — Quality Checks\n6. Run SwiftLint: `swiftlint lint --config VultisigApp/.swiftlint.yml VultisigApp/`\n7. Fix any SwiftLint warnings you introduced\n8. Run build check: `xcodebuild build -scheme VultisigApp -destination ''platform=iOS Simulator,name=iPhone 16'' -skipMacroValidation -skipPackagePluginValidation 2>&1 | tail -20`\n9. Fix any build errors (if build fails, prioritize fixing compile errors over creating the PR)\n\n### Step 4 — Self-Review\n10. Review your own changes by running: `git diff {base-branch}...HEAD`\n11. Check the diff against each applicable CLAUDE.md rule:\n    - Are there hardcoded colors/fonts? (Rule #1)\n    - Any @Model access off MainActor? (Rule #2)\n    - Hardcoded user-facing strings? (Rule #4)\n    - Custom button styles instead of PrimaryButton? (Rule #5)\n    - .foregroundColor() instead of .foregroundStyle()? (Rule #6)\n    - Completion handlers instead of async/await? (Rule #7)\n    - Any new SwiftLint warnings? (Rule #9)\n12. Check for: dead code, unused imports, missing error handling, force unwraps\n13. Fix any issues found in self-review before proceeding\n\n### Step 5 — Commit & Push\n14. Stage and commit changes with a clear message\n15. Push: `git push -u origin {branch-name}`\n\n### Step 6 — Create PR\n16. Create a pull request (NOT draft):\n\ngh pr create --title \"{pr-title}\" --body \"$(cat <<''PREOF''\n## Summary\n{2-3 bullet points of what was done}\n\n## Issue\n{If from GitHub issue: \"Closes #{N}\" — otherwise omit this section}\n\n## Changes\n{List each file changed with a one-line description of what changed}\n\n## CLAUDE.md Rules Applied\n{list rules that were followed}\n\n## Skills Used\n{list skills that were loaded}\n\n## Self-Review Checklist\n- [x] No hardcoded colors/fonts — using Theme.colors.* and Theme.fonts.*\n- [x] No hardcoded strings — using .localized\n- [x] SwiftLint passes with no new warnings\n- [x] Build succeeds\n- [x] No .foregroundColor() — using .foregroundStyle()\n- [x] async/await used — no completion handlers\n{only include checklist items relevant to the rules applied}\n\n## Test Plan\n- [ ] Manual testing: {specific steps to verify the change}\n{additional acceptance criteria as checkboxes}\n\nCo-Authored-By: Claude <noreply@anthropic.com>\nPREOF\n)\"\n\n### CRITICAL — Branch & PR are Required\nYou MUST complete Steps 5 and 6. The task is NOT done until the branch is pushed and the PR is created. Do not stop after implementation — always push and create the PR.\n\n### Error Handling\n- If SwiftLint fails and you cannot fix the warnings, still create the PR but note the warnings in the PR body under a \"Known Issues\" section\n- If the build fails and you cannot fix it, still create the PR but mark it as draft (`--draft` flag) and add a \"Build Issues\" section to the PR body explaining the errors\n- If any step fails catastrophically (cannot checkout, cannot push), output a clear error message with the step that failed and the error details\n```\n\n## Phase 4 — Reporting\n\nAfter ALL agents complete (including dependent tasks that run after their dependencies), present a summary table:\n\n```\n## Batch Complete\n\n| # | Task | Complexity | Branch | PR | Build | Lint | Status |\n|---|------|------------|--------|----|-------|------|--------|\n| 1 | {title} | {S/M/C} | `{branch}` | {PR URL} | pass/fail | pass/fail | pass/fail |\n| 2 | ... | ... | ... | ... | ... | ... | ... |\n\n### Next Steps\n- CodeRabbit will review each PR automatically\n- Run `/batch-review` to see a summary of all PR statuses and CodeRabbit feedback\n- Run `/batch-fix-reviews` to auto-fix CodeRabbit issues across all batch PRs\n- Run `/batch-retry 2, 4` to retry any failed tasks\n```\n\nIf any task failed, include the error summary below the table:\n\n```\n### Failures\n- **Task {n}**: {error summary — which step failed and why}\n```\n\n## Rules\n- Create real PRs (not draft) unless the build fails\n- Never merge PRs\n- Never force-push\n- Each task gets its own isolated worktree — no conflicts between tasks\n- Always run SwiftLint AND build check before creating the PR\n- Always self-review the diff before creating the PR\n- If a task is unclear, include a clarifying question in the PRD (Phase 1) rather than guessing\n- Base independent branches on `main`, dependent branches on their dependency''s branch\n- Include full file change list in PR body for easier review\n"},"lastSynced":"2026-03-07T01:51:10.328Z","agentAnalysis":{"suitability":{"en":"Ideal for Automated Workflow Agents requiring parallel task orchestration and automated PR review integration.","zh":"适用于需要并行任务编排和自动PR审查集成的自动化工作流代理。","ja":"並列タスクのオーケストレーションと自動PRレビューの統合が必要な自動化されたワークフロー エージェントに最適です。","ko":"병렬 작업 오케스트레이션 및 자동 PR 리뷰 통합이 필요한 자동화된 워크플로 에이전트에 적합합니다.","es":"Ideal para Agentes de Flujo de Trabajo Automatizados que requieren orquestación de tareas paralelas e integración de revisión de PR automatizada.","fr":"Idéal pour les Agents de Flux de Travail Automatisés nécessitant une orchestration de tâches parallèles et une intégration de révision de PR automatisée.","de":"Ideal für automatisierte Workflow-Agenten, die eine parallele Aufgabenorchestrierung und eine automatisierte PR-Überprüfung benötigen.","pt":"Ideal para Agentes de Fluxo de Trabalho Automatizados que exigem orquestração de tarefas paralelas e integração de revisão de PR automatizada.","ru":"Идеально подходит для автоматических агентов рабочих процессов, требующих параллельной оркестровки задач и автоматизированной интеграции обзора PR.","ar":"مثالي لワكلاء سير عمل آلي يتطلبون تنسيق مهام متوازي وتكامل مراجعة PR آلي."},"recommendation":{"en":"Empowers agents to orchestrate multiple independent tasks in parallel, leveraging isolated worktrees and automated PR reviews via CodeRabbit, streamlining overnight and async workflows with GitHub issue integration.","zh":"赋予代理人并行执行多个独立任务的能力，利用隔离的工作树和通过CodeRabbit自动化的PR审查，通过GitHub问题集成简化过夜和异步工作流程。","ja":"エージェントが独立した複数のタスクを並列に実行する能力を提供し、分離されたワークツリーとCodeRabbitを介した自動化されたPRレビューを利用し、GitHubの問題統合を介して夜間および非同期ワークフローを簡素化します。","ko":"에이전트가 독립적인 여러 작업을 병렬로 실행할 수 있는 기능을 제공하며, 고립된 작업 트리와 CodeRabbit을 통해 자동화된 PR 리뷰를 활용하여 GitHub 이슈 통합을 통해 밤과 비동기 워크플로를 간소화합니다.","es":"Habilita a los agentes a orquestar varias tareas independientes en paralelo, aprovechando worktrees aislados y revisiones de PR automatizadas a través de CodeRabbit, simplificando los flujos de trabajo nocturnos y asíncronos con la integración de problemas de GitHub.","fr":"Permet aux agents d''orchestrer plusieurs tâches indépendantes en parallèle, en exploitant des worktrees isolés et des révisions de PR automatisées via CodeRabbit, en simplifiant les flux de travail nocturnes et asynchrones avec l''intégration des problèmes GitHub.","de":"Ermächtigt Agenten, mehrere unabhängige Aufgaben parallel zu orchestrieren, indem isolierte Worktrees und automatisierte PR-Überprüfungen über CodeRabbit genutzt werden, wodurch Übernight- und asynchrone Workflows mit GitHub-Issue-Integration gestreamlined werden.","pt":"Habilita agentes a orquestrar várias tarefas independentes em paralelo, utilizando worktrees isoladas e revisões de PR automatizadas via CodeRabbit, simplificando fluxos de trabalho noturnos e assíncronos com integração de problemas do GitHub.","ru":"Наделяет агентов возможностью оркестровать несколько независимых задач параллельно, используя изолированные рабочие деревья и автоматизированные обзоры PR через CodeRabbit, оптимизируя ночные и асинхронные рабочие процессы с интеграцией проблем GitHub.","ar":"تمكن الوكلاء من تنسيق مهام متعددة مستقلة بالتوازي، باستخدام أشجار عمل معزولة ومراجعات PR آلية عبر CodeRabbit، وبذلك يبسط تدفقات العمل الليلية وغير المتزامنة مع دمج مشاكل GitHub."},"useCases":{"en":["Automating overnight workflows with parallel task execution","Streamlining code reviews with automated PR integration using CodeRabbit","Managing dependent tasks with sequential execution based on previous task completion"],"zh":["使用并行任务执行自动化夜间工作流程","使用CodeRabbit自动化PR集成简化代码审查","使用基于前一个任务完成的顺序执行管理依赖任务"],"ja":["並列タスク実行を使用して夜間ワークフローを自動化する","CodeRabbitを使用してPR統合を自動化してコードレビューを簡素化する","前のタスクの完了に基づいて順次実行を使用して依存タスクを管理する"],"ko":["병렬 작업 실행을 사용하여 밤 워크플로를 자동화합니다","CodeRabbit을 사용하여 PR 통합을 자동화하여 코드 리뷰를 간소화합니다","이전 작업의 완료를 기반으로 순차적 실행을 사용하여 의존 작업을 관리합니다"],"es":["Automatizar flujos de trabajo nocturnos con ejecución de tareas paralelas","Simplificar las revisiones de código con integración de PR automatizada utilizando CodeRabbit","Gestionar tareas dependientes con ejecución secuencial basada en la finalización de la tarea anterior"],"fr":["Automatiser les flux de travail nocturnes avec exécution de tâches parallèles","Simplifier les révisions de code avec intégration de PR automatisée à l''aide de CodeRabbit","Gérer des tâches dépendantes avec exécution séquentielle basée sur l''achèvement de la tâche précédente"],"de":["Automatisierung von Übernight-Workflows mit paralleler Aufgabenausführung"," Vereinfachung von Code-Reviews mit automatisierter PR-Integration unter Verwendung von CodeRabbit","Verwaltung von abhängigen Aufgaben mit sequenzieller Ausführung basierend auf der Vervollständigung der vorherigen Aufgabe"],"pt":["Automatizar fluxos de trabalho noturnos com execução de tarefas paralelas","Simplificar revisões de código com integração de PR automatizada usando CodeRabbit","Gerenciar tarefas dependentes com execução sequencial com base na conclusão da tarefa anterior"],"ru":["Автоматизация ночных рабочих процессов с параллельным выполнением задач","Упрощение обзоров кода с автоматизированной интеграцией PR с помощью CodeRabbit","Управление зависимыми задачами с последовательным выполнением на основе завершения предыдущей задачи"],"ar":["أتمتة تدفقات العمل الليلية مع تنفيذ مهام متوازي","تبسيط مراجعات الشفرة مع دمج مراجعة PR آلي باستخدام CodeRabbit","إدارة المهام التابعة مع التنفيذ التسلسلي dựa على إكمال المهمة السابقة"]},"limitations":{"en":["Requires GitHub repository access","Designed for async/overnight workflows, may not be suitable for real-time task execution"],"zh":["需要GitHub存储库访问","设计用于异步/夜间工作流程，可能不适合实时任务执行"],"ja":["GitHubリポジトリへのアクセスが必要","非同期/夜間ワークフロー用に設計されているため、リアルタイムのタスク実行には適していない"],"ko":["GitHub 리포지토리 액세스가 필요합니다","비동기/밤 워크플로우를 위해 설계되어 실시간 작업 실행에는 적합하지 않을 수 있음"],"es":["Requiere acceso al repositorio de GitHub","Diseñado para flujos de trabajo asíncronos y nocturnos, puede que no sea adecuado para la ejecución de tareas en tiempo real"],"fr":["Nécessite un accès au référentiel GitHub","Conçu pour les flux de travail asynchrones et nocturnes, peut ne pas être adapté pour l''exécution de tâches en temps réel"],"de":["Erfordert Zugriff auf das GitHub-Repository","Für asynchrone und Übernight-Workflows konzipiert, möglicherweise nicht geeignet für die Ausführung von Echtzeit-Aufgaben"],"pt":["Exige acesso ao repositório do GitHub","Projetado para fluxos de trabalho assíncronos/noturnos, pode não ser adequado para execução de tarefas em tempo real"],"ru":["Требует доступа к репозиторию GitHub","Предназначен для асинхронных/ночных рабочих процессов, может быть не подходящим для выполнения задач в реальном времени"],"ar":["يتطلب الوصول إلى مستودع GitHub","صمّم لتدفقات العمل غير المتزامنة / الليلية، قد لا تكون مناسبة للتنفيذ الفوري للمهام"]},"version":4},"contentHash":"273dc39ac7a42e206df82c939e13733c2299613d6048d8324988f79b30f153ec","qualityScore":65}');
