INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vultisig/vultisig-ios/batch-tasks', 'batch-tasks', 'vultisig', 'vultisig-ios', 'community', 'batch-tasks vultisig vultisig-ios community The batch-tasks skill automates overnight workflows by orchestrating multiple independent tasks in parallel. It benefits developers by integrating with CodeRabbit for automated PR review. 批量任务运行器用于orchestrates多个独立任务的并行运行，每个任务都有自己的分支、隔离工作树和 PR バッチタスクランナーは複数の独立したタスクを並列で実行し、各タスクに独自のブランチ、分離されたワークツリー、PR を提供する 배치 작업 실행기는 여러 개의 독립적인 작업을 병렬로 실행하며, 각 작업에 대해 전용 브랜치, 분리된 워크 트리 및 PR을 제공한다 Batch-tasks es un ejecutor de tareas que orquesta múltiples tareas en paralelo, ideal para flujos de trabajo asíncronos Batch-tasks est un exécuteur de tâches qui orchestre plusieurs tâches en parallèle, idéal pour les flux de travail asynchrones Batch-tasks ist ein Task-Runner, der mehrere Aufgaben in Parallel ausführt, ideal für asynchrone Workflows O batch-tasks é uma ferramenta que orquestra múltiplas tarefas independentes em paralelo, com integração com CodeRabbit para revisão automática de PR. Batch-tasks — это инструмент, который координирует несколько независимых задач в параллели, с интеграцией с CodeRabbit для автоматического обзора PR. batch-tasks هو أداة توجيه مهام مستقلة متعددة بالتوازي، مع التكامل مع CodeRabbit لاستعراض(PR) آلي how to use batch-tasks batch-tasks alternative batch-tasks setup guide what is batch-tasks batch-tasks vs CodeRabbit batch-tasks install automating overnight tasks parallel task automation CodeRabbit integration 批量任务运行器 并行任务运行 CodeRabbit 集成 Vultisig iOS App 批量任务 Setup Guide AI 工具 批量任务技术细节 Orchestrates multiple independent tasks in parallel using isolated worktrees and PRs Integrates with CodeRabbit for automated PR review Supports invocation via the `/batch-tasks` command Allows specification of task dependencies using `after` syntax Creates a separate branch for each task Generates PRs for each task batch-tasks is a task automation skill that orchestrates multiple independent tasks in parallel, designed for overnight or async workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Agents2AgentsAI/ata/babysit-pr', 'community', 'Agents2AgentsAI', 'ata', 'Agents2AgentsAI/ata', 'babysit-pr', 23, 0, 65, '2026-02-26T07:21:46Z', '2026-03-06T13:02:19.194Z', '165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5', '{"id":"Agents2AgentsAI/ata/babysit-pr","name":"babysit-pr","description":{"en":"The babysit-pr skill automates PR management for AI agents, persistently monitoring PRs until they are merged, closed, or require user intervention, benefiting engineering and research teams.","zh":"babysit-pr 是一款AI代理工具，用于端到端地解决工程和研究问题。它能持续监控PR，直到其被合并、关闭，或CI成功、所有评审评论已解决、批准就绪且无合并冲突。","ja":"babysit-pr は、エンジニアリングと研究問題を端末まで解決するためのAIエージェントです。PRがマージまたはクローズされるまで、CIの成功、未解決のレビューコメント、承認状態、マージコンフリクトを永続的に監視します。","ko":"babysit-pr은 엔지니어링 및 연구 문제를 종단간 해결하는 AI 에이전트입니다. PR이 병합되거나 닫힐 때까지 CI 성공, 미해결 리뷰 코멘트, 승인 상태, 병합 충돌 위험을 지속적으로 감시합니다.","es":"babysit-pr es un agente de IA que resuelve problemas de ingeniería de manera persistente, gestionando PRs hasta su resolución","fr":"babysit-pr est un outil d''IA qui résout les problèmes d''ingénierie de manière persistante, en gérant les PR jusqu''à leur résolution","de":"babysit-pr ist ein KI-Agent, der Ingenieursprobleme persistent löst, indem er PRs bis zu ihrer Lösung verwaltet","pt":"O babysit-pr é um agente AI que automatiza persistentemente a monitorização de Pull Requests. Gerencia processos de CI, deteta conflitos de merge e assegura que todos os comentários de revisão são tratados, libertando os desenvolvedores para outras tarefas.","ru":"babysit-pr — это ИИ агент для персистентной автоматизации мониторинга Pull Requests. Управляет процессами CI, обнаруживает конфликты слияния и обеспечивает обработку всех комментариев ревью, освобождая разработчиков для других задач.","ar":"babysit-pr هو أداة ذكاء اصطناعي لأتمتة مراقبة طلبات السحب بشكل مستمر. تدير عمليات CI، تكتشف تعارضات الدمج، وتضمن معالجة جميع تعليقات المراجعة، مما يحرر المطورين للمهام الأخرى."},"seo":{"title":{"en":"babysit-pr: Automated PR Management for AI Agents | AI Ag...","zh":"babysit-pr 设置指南：AI代理持续监控PR直至合并","ja":"babysit-pr セットアップガイド：AIエージェントによるPR自動監視","ko":"babysit-pr 설정 가이드: AI 에이전트가 PR을 병합까지 지속 관리","es":"Guía de configuración de babysit-pr: Resolución de proble...","fr":"Configurer babysit-pr: Outils d''IA pour résoudre les prob...","de":"Einrichten von babysit-pr: Lösung von Ingenieursproblemen...","pt":"babysit-pr: Guia de Configuração para Automação de Pull R...","ru":"babysit-pr: Руководство по настройке ИИ Агента для Pull R...","ar":"babysit-pr: دليل إعداد أدوات الذكاء الاصطناعي لأتمتة طلبا..."},"description":{"en":"Streamline your PR workflow with babysit-pr! Learn how to automate PR management and resolve merge conflicts efficiently - get started now!","zh":"babysit-pr AI代理可自动监控拉取请求，持续检查CI状态、未解决的评审评论、合并冲突风险和所需批准，直至PR合并、关闭或需要用户协助。","ja":"babysit-pr AIエージェントは、PRがマージまたはクローズされるまで、CIステータス、未解決のレビューコメント、マージコンフリクトを自動監視し、ユーザー支援が必要な場合に通知します。","ko":"babysit-pr AI 에이전트는 PR이 병합되거나 닫힐 때까지 CI 상태, 미해결 리뷰 코멘트, 병합 충돌 위험을 지속적으로 모니터링하며 사용자 도움이 필요할 때 알림을 보냅니다.","es":"Automatice la resolución de problemas de ingeniería con babysit-pr, un agente de IA que gestiona PR de manera persistente hasta su resolución","fr":"Résolvez les problèmes d''ingénierie avec babysit-pr, un outil d''IA qui gère les PR de manière persistante jusqu''à leur résolution","de":"Automatisieren Sie die Lösung von Ingenieursproblemen mit babysit-pr, einem KI-Agenten, der PRs persistent verwaltet, bis sie gelöst sind","pt":"Automatize a gestão de Pull Requests com o agente AI babysit-pr. Monitora CI, conflitos de merge e comentários de revisão até a resolução final. Aumente a pr...","ru":"Автоматизируйте управление Pull Requests с ИИ агентом babysit-pr. Мониторит CI, конфликты слияния и комментарии ревью до финального разрешения. Повысьте прод...","ar":"أتمتة إدارة طلبات السحب باستخدام أداة الذكاء الاصطناعي babysit-pr. تراقب CI، تعارضات الدمج، وتعليقات المراجعة حتى الحل النهائي. تعزيز إنتاجية الفريق."},"definition":{"en":"babysit-pr is a skill that automates the management of pull requests (PRs) for AI agents, ensuring efficient resolution of merge conflicts and CI issues.","zh":"babysit-pr 是一个AI代理技能，旨在持久地监控拉取请求（PR）。其目标是直到PR被合并或关闭，或CI成功、所有评审评论已处理、所需批准不阻塞合并且无潜在合并冲突，或出现需要用户帮助的情况时才停止。","ja":"babysit-pr は、プルリクエスト（PR）を永続的に監視するAIエージェントスキルです。PRがマージまたはクローズされる、CIが成功し未解決のレビューコメントがなく承認がブロックされずマージコンフリクトのリスクがない、またはユーザーヘルプが必要な状況が発生するまで動作します。","ko":"babysit-pr은 풀 리퀘스트(PR)를 지속적으로 관리하는 AI 에이전트 스킬입니다. PR이 병합되거나 닫히거나, CI가 성공하고 미해결 리뷰 코멘트가 없으며 필요한 승인이 병합을 차단하지 않고 잠재적 병합 충돌이 없거나 사용자 도움이 필요한 상황이 발생할 때까지 작동합니다.","es":"babysit-pr es un agente de IA que gestiona de manera persistente las solicitudes de extracción (PR) hasta que se produzca una de las salidas finales","fr":"babysit-pr est un outil d''IA qui gère de manière persistante les demandes d''extraction (PR) jusqu''à ce qu''une des sorties finales se produise","de":"babysit-pr ist ein KI-Agent, der die Pull-Requests (PR) persistent verwaltet, bis eine der Endausgaben auftritt","pt":"babysit-pr é um agente de IA que monitoriza automaticamente um Pull Request até um resultado terminal: ser merged/closed, CI bem-sucedido sem comentários por resolver, ou até necessitar de intervenção manual por problemas de infraestrutura.","ru":"babysit-pr — это ИИ агент, который автоматически мониторит Pull Request до терминального исхода: merged/closed, успешный CI без нерешенных комментариев, или до необходимости ручного вмешательства из-за проблем инфраструктуры.","ar":"babysit-pr هي أداة ذكاء اصطناعي تراقب طلبات السحب تلقائيًا حتى نتيجة نهائية: دمج/إغلاق، CI ناجح دون تعليقات عالقة، أو حتى تتطلب تدخلاً يدويًا بسبب مشاكل البنية التحتية."},"features":{"en":["Monitors PRs until merged or closed","Checks for successful CI and unaddressed review comments","Verifies required review approval and potential merge conflicts","Retries flaky failures until retry budget is exhausted","Surfaces permission issues and CI infrastructure problems"],"zh":["持久监控PR状态直至合并或关闭","自动检查CI流水线是否成功","识别并跟踪未解决的代码评审评论","验证所需批准是否已获得且不阻塞合并","检测潜在的Git合并冲突风险","在基础设施问题或 flaky 测试重试预算耗尽时请求用户协助"],"ja":["PRがマージまたはクローズされるまでの永続的監視","CIパイプラインの成功自動チェック","未解決のコードレビューコメントの識別と追跡","必要な承認が取得されマージをブロックしていないことの検証","潜在的なGitマージコンフリクトリスクの検出","インフラ問題やフレーキーテストのリトライ予算枯渇時のユーザー支援要請"],"ko":["PR이 병합되거나 닫힐 때까지 지속적인 모니터링","CI 파이프라인 성공 여부 자동 확인","미해결 코드 리뷰 코멘트 식별 및 추적","필요한 승인이 획득되었고 병합을 차단하지 않는지 확인","잠재적인 Git 병합 충돌 위험 감지","인프라 문제 또는 flaky 테스트 재시도 예산 소진 시 사용자 지원 요청"],"es":["Gestión persistente de PR hasta su resolución","Detección de comentarios de revisión no abordados","Verificación de aprobación de revisión requerida","Detección de conflictos de fusión potenciales","Integración con infraestructura de CI"],"fr":["Gestion persistante des PR jusqu''à leur résolution","Détection de commentaires de révision non abordés","Vérification de l''approbation de révision requise","Détection de conflits de fusion potentiels","Intégration avec l''infrastructure de CI"],"de":["Persistente Verwaltung von PR bis zur Lösung","Erkennung von nicht behandelten Überprüfungskommentaren","Überprüfung der erforderlichen Überprüfungsgebühr","Erkennung von potenziellen Merge-Konflikten","Integration mit der CI-Infrastruktur"],"pt":["Monitorização persistente até resolução do PR (merged ou closed)","Verificação automática do estado de sucesso da CI","Deteção de comentários de revisão não abordados","Validação de aprovações de revisão necessárias para merge","Análise de conflitos de merge em potencial","Escalamento para ajuda do utilizador em falhas de infraestrutura ou erros flaky"],"ru":["Персистентный мониторинг до разрешения PR (merged или closed)","Автоматическая проверка статуса успешности CI","Обнаружение необработанных комментариев ревью","Проверка необходимых одобрений ревью для слияния","Анализ потенциальных конфликтов слияния","Эскалация для помощи пользователя при сбоях инфраструктуры или flaky ошибках"],"ar":["مراقبة مستمرة حتى حل طلب السحب (دمج أو إغلاق)","التحقق التلقائي من حالة نجاح CI","كشف تعليقات المراجعة التي لم تتم معالجتها","التحقق من الموافقات المطلوبة للدمج","تحليل تعارضات الدمج المحتملة","تصعيد للمساعدة manual في حالات فشل البنية التحتية أو الأخطاء المتقطعة"]},"keywords":{"en":["how to use babysit-pr","babysit-pr setup guide","automated PR management","CI issue resolution","merge conflict resolution","babysit-pr alternative","babysit-pr vs github actions","babysit-pr install","babysit-pr tutorial"],"zh":["babysit-pr AI代理","PR自动监控工具","GitHub CI检查","代码评审自动化","合并冲突检测","AI工程代理","拉取请求管理","持续集成自动化"],"ja":["babysit-pr AIエージェント","PR自動監視ツール","GitHub CIチェック","コードレビュー自動化","マージコンフリクト検出","AIエンジニアリングエージェント","プルリクエスト管理","継続的インテグレーション自動化"],"ko":["babysit-pr AI 에이전트","PR 자동 모니터링 도구","GitHub CI 확인","코드 리뷰 자동화","병합 충돌 감지","AI 엔지니어링 에이전트","풀 리퀘스트 관리","지속적 통합 자동화"],"es":["Agentes de IA para ingeniería","Resolución de problemas de ingeniería","Gestión de PR","Integración con CI","Automatización de flujos de trabajo","Herramientas de desarrollo de software","Resolución de conflictos de fusión","Aprobación de revisión requerida"],"fr":["Outils d''IA pour l''ingénierie","Résolution de problèmes d''ingénierie","Gestion des PR","Intégration avec la CI","Automatisation des flux de travail","Outils de développement de logiciels","Résolution de conflits de fusion","Approbation de révision requise"],"de":["KI-Agents für Ingenieurwesen","Lösung von Ingenieursproblemen","Verwaltung von PR","Integration mit der CI","Automatisierung von Arbeitsabläufen","Werkzeuge für Software-Entwicklung","Lösung von Merge-Konflikten","Überprüfungsgebühr erforderlich"],"pt":["agente AI para pull requests","automação de code review","monitorização de CI GitHub Actions","resolver conflitos de merge automaticamente","ferramenta DevOps para developers","babysit-pr configuração tutorial","automatizar gestão de PR"],"ru":["ИИ агент для pull requests","автоматизация code review","мониторинг CI GitHub Actions","разрешение конфликтов слияния автоматически","инструмент DevOps для разработчиков","babysit-pr руководство по настройке","автоматизация управления PR"],"ar":["أداة ذكاء اصطناعي لطلبات السحب","أتمتة مراجعة الكود","مراقبة CI GitHub Actions","حل تعارضات الدمج تلقائيًا","أداة DevOps للمطورين","دليل إعداد babysit-pr","أتمتة إدارة طلبات السحب"]}},"owner":"Agents2AgentsAI","repo":"ata","repoPath":"Agents2AgentsAI/ata","stars":23,"forks":0,"updatedAt":"2026-02-26T07:21:46Z","topics":[],"category":"community","skillMd":{"name":"babysit-pr","description":"Babysit a GitHub pull request after creation by continuously polling CI checks/workflow runs, new review comments, and mergeability state until the PR is ready to merge (or merged/closed). Diagnose failures, retry likely flaky failures up to 3 times, auto-fix/push branch-related issues when appropriate, and stop only when user help is required (for example CI infrastructure issues, exhausted flaky retries, or ambiguous/blocking situations). Use when the user asks Codex to monitor a PR, watch CI, handle review comments, or keep an eye on failures and feedback on an open PR.","bodyPreview":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission pr","body":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission problems, or ambiguity that cannot be resolved safely).\n\nDo not stop merely because a single snapshot returns `idle` while checks are still pending.\n\n## Inputs\nAccept any of the following:\n\n- No PR argument: infer the PR from the current branch (`--pr auto`)\n- PR number\n- PR URL\n\n## Core Workflow\n\n1. When the user asks to \"monitor\"/\"watch\"/\"babysit\" a PR, start with the watcher''s continuous mode (`--watch`) unless you are intentionally doing a one-shot diagnostic snapshot.\n2. Run the watcher script to snapshot PR/CI/review state (or consume each streamed snapshot from `--watch`).\n3. Inspect the `actions` list in the JSON response.\n4. If `diagnose_ci_failure` is present, inspect failed run logs and classify the failure.\n5. If the failure is likely caused by the current branch, patch code locally, commit, and push.\n6. If `process_review_comment` is present, inspect surfaced review items and decide whether to address them.\n7. If a review item is actionable and correct, patch code locally, commit, and push.\n8. If the failure is likely flaky/unrelated and `retry_failed_checks` is present, rerun failed jobs with `--retry-failed-now`.\n9. If both actionable review feedback and `retry_failed_checks` are present, prioritize review feedback first; a new commit will retrigger CI, so avoid rerunning flaky checks on the old SHA unless you intentionally defer the review change.\n10. On every loop, verify mergeability / merge-conflict status (for example via `gh pr view`) in addition to CI and review state.\n11. After any push or rerun action, immediately return to step 1 and continue polling on the updated SHA/state.\n12. If you had been using `--watch` before pausing to patch/commit/push, relaunch `--watch` yourself in the same turn immediately after the push (do not wait for the user to re-invoke the skill).\n13. Repeat polling until the PR is green + review-clean + mergeable, `stop_pr_closed` appears, or a user-help-required blocker is reached.\n14. Maintain terminal/session ownership: while babysitting is active, keep consuming watcher output in the same turn; do not leave a detached `--watch` process running and then end the turn as if monitoring were complete.\n\n## Commands\n\n### One-shot snapshot\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --once\n```\n\n### Continuous watch (JSONL)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --watch\n```\n\n### Trigger flaky retry cycle (only when watcher indicates)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --retry-failed-now\n```\n\n### Explicit PR target\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr <number-or-url> --once\n```\n\n## CI Failure Classification\nUse `gh` commands to inspect failed runs before deciding to rerun.\n\n- `gh run view <run-id> --json jobs,name,workflowName,conclusion,status,url,headSha`\n- `gh run view <run-id> --log-failed`\n\nPrefer treating failures as branch-related when logs point to changed code (compile/test/lint/typecheck/snapshots/static analysis in touched areas).\n\nPrefer treating failures as flaky/unrelated when logs show transient infra/external issues (timeouts, runner provisioning failures, registry/network outages, GitHub Actions infra errors).\n\nIf classification is ambiguous, perform one manual diagnosis attempt before choosing rerun.\n\nRead `.codex/skills/babysit-pr/references/heuristics.md` for a concise checklist.\n\n## Review Comment Handling\nThe watcher surfaces review items from:\n\n- PR issue comments\n- Inline review comments\n- Review submissions (COMMENT / APPROVED / CHANGES_REQUESTED)\n\nIt intentionally surfaces Codex reviewer bot feedback (for example comments/reviews from `chatgpt-codex-connector[bot]`) in addition to human reviewer feedback. Most unrelated bot noise should still be ignored.\nFor safety, the watcher only auto-surfaces trusted human review authors (for example repo OWNER/MEMBER/COLLABORATOR, plus the authenticated operator) and approved review bots such as Codex.\nOn a fresh watcher state file, existing pending review feedback may be surfaced immediately (not only comments that arrive after monitoring starts). This is intentional so already-open review comments are not missed.\n\nWhen you agree with a comment and it is actionable:\n\n1. Patch code locally.\n2. Commit with `codex: address PR review feedback (#<n>)`.\n3. Push to the PR head branch.\n4. Resume watching on the new SHA immediately (do not stop after reporting the push).\n5. If monitoring was running in `--watch` mode, restart `--watch` immediately after the push in the same turn; do not wait for the user to ask again.\n\nIf you disagree or the comment is non-actionable/already addressed, record it as handled by continuing the watcher loop (the script de-duplicates surfaced items via state after surfacing them).\nIf a code review comment/thread is already marked as resolved in GitHub, treat it as non-actionable and safely ignore it unless new unresolved follow-up feedback appears.\n\n## Git Safety Rules\n\n- Work only on the PR head branch.\n- Avoid destructive git commands.\n- Do not switch branches unless necessary to recover context.\n- Before editing, check for unrelated uncommitted changes. If present, stop and ask the user.\n- After each successful fix, commit and `git push`, then re-run the watcher.\n- If you interrupted a live `--watch` session to make the fix, restart `--watch` immediately after the push in the same turn.\n- Do not run multiple concurrent `--watch` processes for the same PR/state file; keep one watcher session active and reuse it until it stops or you intentionally restart it.\n- A push is not a terminal outcome; continue the monitoring loop unless a strict stop condition is met.\n\nCommit message defaults:\n\n- `codex: fix CI failure on PR #<n>`\n- `codex: address PR review feedback (#<n>)`\n\n## Monitoring Loop Pattern\nUse this loop in a live Codex session:\n\n1. Run `--once`.\n2. Read `actions`.\n3. First check whether the PR is now merged or otherwise closed; if so, report that terminal state and stop polling immediately.\n4. Check CI summary, new review items, and mergeability/conflict status.\n5. Diagnose CI failures and classify branch-related vs flaky/unrelated.\n6. Process actionable review comments before flaky reruns when both are present; if a review fix requires a commit, push it and skip rerunning failed checks on the old SHA.\n7. Retry failed checks only when `retry_failed_checks` is present and you are not about to replace the current SHA with a review/CI fix commit.\n8. If you pushed a commit or triggered a rerun, report the action briefly and continue polling (do not stop).\n9. After a review-fix push, proactively restart continuous monitoring (`--watch`) in the same turn unless a strict stop condition has already been reached.\n10. If everything is passing, mergeable, not blocked on required review approval, and there are no unaddressed review items, report success and stop.\n11. If blocked on a user-help-required issue (infra outage, exhausted flaky retries, unclear reviewer request, permissions), report the blocker and stop.\n12. Otherwise sleep according to the polling cadence below and repeat.\n\nWhen the user explicitly asks to monitor/watch/babysit a PR, prefer `--watch` so polling continues autonomously in one command. Use repeated `--once` snapshots only for debugging, local testing, or when the user explicitly asks for a one-shot check.\nDo not stop to ask the user whether to continue polling; continue autonomously until a strict stop condition is met or the user explicitly interrupts.\nDo not hand control back to the user after a review-fix push just because a new SHA was created; restarting the watcher and re-entering the poll loop is part of the same babysitting task.\nIf a `--watch` process is still running and no strict stop condition has been reached, the babysitting task is still in progress; keep streaming/consuming watcher output instead of ending the turn.\n\n## Polling Cadence\nUse adaptive polling and continue monitoring even after CI turns green:\n\n- While CI is not green (pending/running/queued or failing): poll every 1 minute.\n- After CI turns green: start at every 1 minute, then back off exponentially when there is no change (for example 1m, 2m, 4m, 8m, 16m, 32m), capping at every 1 hour.\n- Reset the green-state polling interval back to 1 minute whenever anything changes (new commit/SHA, check status changes, new review comments, mergeability changes, review decision changes).\n- If CI stops being green again (new commit, rerun, or regression): return to 1-minute polling.\n- If any poll shows the PR is merged or otherwise closed: stop polling immediately and report the terminal state.\n\n## Stop Conditions (Strict)\nStop only when one of the following is true:\n\n- PR merged or closed (stop as soon as a poll/snapshot confirms this).\n- PR is ready to merge: CI succeeded, no surfaced unaddressed review comments, not blocked on required review approval, and no merge conflict risk.\n- User intervention is required and Codex cannot safely proceed alone.\n\nKeep polling when:\n\n- `actions` contains only `idle` but checks are still pending.\n- CI is still running/queued.\n- Review state is quiet but CI is not terminal.\n- CI is green but mergeability is unknown/pending.\n- CI is green and mergeable, but the PR is still open and you are waiting for possible new review comments or merge-conflict changes per the green-state cadence.\n- The PR is green but blocked on review approval (`REVIEW_REQUIRED` / similar); continue polling on the green-state cadence and surface any new review comments without asking for confirmation to keep watching.\n\n## Output Expectations\nProvide concise progress updates while monitoring and a final summary that includes:\n\n- During long unchanged monitoring periods, avoid emitting a full update on every poll; summarize only status changes plus occasional heartbeat updates.\n- Treat push confirmations, intermediate CI snapshots, and review-action updates as progress updates only; do not emit the final summary or end the babysitting session unless a strict stop condition is met.\n- A user request to \"monitor\" is not satisfied by a couple of sample polls; remain in the loop until a strict stop condition or an explicit user interruption.\n- A review-fix commit + push is not a completion event; immediately resume live monitoring (`--watch`) in the same turn and continue reporting progress updates.\n- When CI first transitions to all green for the current SHA, emit a one-time celebratory progress update (do not repeat it on every green poll). Preferred style: `🚀 CI is all green! 33/33 passed. Still on watch for review approval.`\n- Do not send the final summary while a watcher terminal is still running unless the watcher has emitted/confirmed a strict stop condition; otherwise continue with progress updates.\n\n- Final PR SHA\n- CI status summary\n- Mergeability / conflict status\n- Fixes pushed\n- Flaky retry cycles used\n- Remaining unresolved failures or review comments\n\n## References\n\n- Heuristics and decision tree: `.codex/skills/babysit-pr/references/heuristics.md`\n- GitHub CLI/API details used by the watcher: `.codex/skills/babysit-pr/references/github-api-notes.md`\n"},"lastSynced":"2026-03-06T13:02:19.194Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated PR management and monitoring for merge, close, or intervention outcomes.","zh":"非常适合需要自动化PR管理和监控的开发代理，用于合并、关闭或干预结果。","ja":"開発エージェントが自動化されたPR管理と監視を必要とするマージ、クローズ、または介入の結果に最適です。","ko":"개발 에이전트가 자동화된 PR 관리 및 모니터링을 필요로 하는 병합, 닫기 또는 개입 결과에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión y monitoreo de PR automatizados para resultados de fusión, cierre o intervención.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion et d''un suivi de PR automatisés pour les résultats de fusion, de fermeture ou d''intervention.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte PR-Verwaltung und -Überwachung für Merge-, Schließ- oder Interventionsergebnisse benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento e monitoramento de PR automatizados para mesclar, fechar ou resultados de intervenção.","ru":"Идеально для агентов разработки, которым необходим автоматизированный управление и мониторинг PR для слияния, закрытия или результатов вмешательства.","ar":"مثالي لعميل التطوير الذي يحتاج إلى إدارة ومراقبة طلبات الاندماج الآلية للمerge ، أو الإغلاق ، أو مخرجات التدخل."},"recommendation":{"en":"Empowers agents to persistently monitor PRs, ensuring successful CI, addressing review comments, and resolving potential merge conflicts, all while awaiting required review approvals and handling permission PRs through protocols like CI infrastructure and retry budgets.","zh":"赋予代理持续监控PR的能力，确保CI成功，解决审查评论，并在等待所需审查批准的同时解决潜在的合并冲突，并通过协议如CI基础设施和重试预算处理权限PR。","ja":"エージェントがPRを継続的に監視できるようにし、CIの成功を確保し、レビューのコメントを解決し、レビューの承認を待機しながら潜在的なマージのコンフリクトを解決し、CIインフラストラクチャやリトライ予算などのプロトコルを介して権限PRを処理します。","ko":"에이전트가 PR을 지속적으로 모니터링할 수 있도록 하여 CI 성공을 보장하고, 리뷰 코멘트를 해결하며, 리뷰 승인을 기다리는 동안 잠재적인 병합 충돌을 해결하며, CI 인프라스트럭처 및 재시도 예산과 같은 프로토콜을 통해 권한 PR을 처리합니다.","es":"Habilita a los agentes a monitorear persistentemente las PR, garantizando el éxito de la CI, abordando los comentarios de revisión y resolviendo los posibles conflictos de fusión, todo mientras se esperan las aprobaciones de revisión requeridas y se manejan las PR de permisos a través de protocolos como la infraestructura de CI y los presupuestos de reintento.","fr":"Permet aux agents de surveiller en permanence les PR, en garantissant la réussite de la CI, en traitant les commentaires d''examen et en résolvant les conflits de fusion potentiels, le tout en attendant les approbations d''examen requises et en gérant les PR de permissions via des protocoles tels que l''infrastructure CI et les budgets de réessai.","de":"Ermächtigt die Agenten, PRs persistent zu überwachen, den Erfolg von CI sicherzustellen, die Überprüfungskommentare anzusprechen und mögliche Merge-Konflikte zu lösen, während die erforderlichen Überprüfungsgenehmigungen abgewartet werden und die Berechtigungs-PRs durch Protokolle wie CI-Infrastruktur und Wiederholungsbudgets gehandhabt werden.","pt":"Habilita os agentes a monitorar persistentemente os PRs, garantindo o sucesso da CI, abordando comentários de revisão e resolvendo potenciais conflitos de mesclagem, tudo enquanto aguarda as aprovações de revisão necessárias e lida com permissões de PR por meio de protocolos como infraestrutura de CI e orçamentos de repetição.","ru":"Наделяет агентов возможностью постоянно отслеживать PR, обеспечивая успешную CI, решая комментарии к обзору и решая потенциальные конфликты слияния, все это при ожидании необходимых одобрений обзора и обработке разрешений PR через протоколы, такие как инфраструктура CI и бюджеты повторения.","ar":"يمنح الوكلاء القدرة على مراقبة طلبات الاندماج بانتظام ، وضمان نجاحCI ، ومعالجة تعليقات المراجعة وحل النزاعات المحتملة للمerge ، كل ذلك مع انتظار الموافقات اللازمة للمراجعة ومعالجة صلاحيات PR من خلال بروتوكولات مثل بنية تحتية CI وميزانيات الإعادة."},"useCases":{"en":["Automating PR management for engineering teams","Monitoring CI success and review comment resolution","Identifying and flagging PRs requiring user intervention due to issues like flaky failures or permission problems"],"zh":["为工程团队自动化PR管理","监控CI成功和审查评论解决","确定并标记需要用户干预的PR，例如由于不稳定失败或权限问题"],"ja":["エンジニアリングチームのPR管理の自動化","CIの成功とレビューのコメントの解決の監視","ユーザー介入が必要なPRの特定とフラグ付け、たとえば不安定な失敗または権限の問題"],"ko":["엔지니어링 팀의 PR 관리 자동화","CI 성공 및 리뷰 코멘트 해결 모니터링","사용자 개입이 필요한 PR 식별 및 플래그 지정, 예를 들어 불안정한 실패 또는 권한 문제"],"es":["Automatización de la gestión de PR para equipos de ingeniería","Monitoreo del éxito de la CI y la resolución de comentarios de revisión","Identificación y marcado de PR que requieren intervención del usuario debido a problemas como fallos inestables o problemas de permisos"],"fr":["Automatisation de la gestion des PR pour les équipes d''ingénierie","Surveillance de la réussite de la CI et de la résolution des commentaires d''examen","Identification et marquage des PR nécessitant une intervention utilisateur en raison de problèmes tels que des échecs instables ou des problèmes de permissions"],"de":["Automatisierung der PR-Verwaltung für Ingenieurteams","Überwachung des Erfolgs von CI und der Behebung von Überprüfungskommentaren","Identifizierung und Markierung von PR, die aufgrund von Problemen wie unstabilen Fehlern oder Berechtigungsproblemen eine Benutzereingabe erfordern"],"pt":["Automatizar o gerenciamento de PR para equipes de engenharia","Monitorar o sucesso da CI e a resolução de comentários de revisão","Identificar e sinalizar PRs que necessitam de intervenção do usuário devido a problemas como falhas instáveis ou problemas de permissão"],"ru":["Автоматизировать управление PR для инженерных команд","Отслеживать успех CI и решать комментарии к обзору","Определять и помечать PR, требующие вмешательства пользователя из-за проблем, таких как нестабильные сбои или проблемы с разрешениями"],"ar":["توفير إدارة طلبات الاندماج الآلية لفريق الهندسة","مراقبة نجاحCI وحل تعليقات المراجعة","تحديد وتعليم طلبات الاندماج التي تتطلب تدخل المستخدم بسبب مشاكل مثل الفشل غير المستقر أو مشاكل الصلاحية"]},"limitations":{"en":["Requires access to PR and CI infrastructure","Dependent on successful CI and review processes","May require user intervention for certain issues like permission PRs or repeated flaky failures"],"zh":["需要访问PR和CI基础设施","依赖于成功的CI和审查流程","可能需要用户干预来解决某些问题，例如权限PR或重复的不稳定失败"],"ja":["PRとCIインフラストラクチャへのアクセスが必要","成功したCIとレビューのプロセスに依存","一部の問題、たとえば権限PRまたは繰り返しの不安定な失敗については、ユーザー介入が必要になる場合がある"],"ko":["PR 및 CI 인프라스트럭처에 대한 액세스가 필요함","성공한 CI 및 리뷰 프로세스에 의존함","일부 문제, 예를 들어 권한 PR 또는 반복되는 불안정한 실패에 대해서는 사용자 개입이 필요할 수 있음"],"es":["Requiere acceso a la infraestructura de PR y CI","Dependiente de procesos de CI y revisión exitosos","Puede requerir intervención del usuario para ciertos problemas como PR de permisos o fallos inestables repetidos"],"fr":["Nécessite un accès à l''infrastructure PR et CI","Dépendante de processus de CI et d''examen réussis","Peut nécessiter une intervention utilisateur pour certains problèmes tels que des PR de permissions ou des échecs instables répétés"],"de":["Erfordert Zugriff auf PR- und CI-Infrastruktur","Abhängig von erfolgreichen CI- und Überprüfungsprozessen","Kann Benutzereingriffe für bestimmte Probleme wie Berechtigungs-PR oder wiederholte unstabile Fehler erfordern"],"pt":["Requer acesso à infraestrutura de PR e CI","Depende de processos de CI e revisão bem-sucedidos","Pode requerer intervenção do usuário para problemas específicos como PRs de permissão ou falhas repetidas instáveis"],"ru":["Требует доступа к инфраструктуре PR и CI","Зависит от успешных процессов CI и обзора","Может требовать вмешательства пользователя для определенных проблем, таких как PR разрешений или повторяющихся нестабильных сбоев"],"ar":["يتطلب الوصول إلى بنية تحتية PR وCI","يعتمد على عمليات CI والمراجعة الناجحة","يمكن أن يتطلب تدخل المستخدم لمشاكل معينة مثل PR صلاحيات أو فشل متكرر غير مستقر"]},"version":4},"contentHash":"165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5","qualityScore":65}');
