INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Agents2AgentsAI/ata/babysit-pr', 'babysit-pr', 'Agents2AgentsAI', 'ata', 'community', 'babysit-pr Agents2AgentsAI ata community The babysit-pr skill automates PR management for AI agents, persistently monitoring PRs until they are merged, closed, or require user intervention, benefiting engineering and research teams. babysit-pr 是一款AI代理工具，用于端到端地解决工程和研究问题。它能持续监控PR，直到其被合并、关闭，或CI成功、所有评审评论已解决、批准就绪且无合并冲突。 babysit-pr は、エンジニアリングと研究問題を端末まで解決するためのAIエージェントです。PRがマージまたはクローズされるまで、CIの成功、未解決のレビューコメント、承認状態、マージコンフリクトを永続的に監視します。 babysit-pr은 엔지니어링 및 연구 문제를 종단간 해결하는 AI 에이전트입니다. PR이 병합되거나 닫힐 때까지 CI 성공, 미해결 리뷰 코멘트, 승인 상태, 병합 충돌 위험을 지속적으로 감시합니다. babysit-pr es un agente de IA que resuelve problemas de ingeniería de manera persistente, gestionando PRs hasta su resolución babysit-pr est un outil d''IA qui résout les problèmes d''ingénierie de manière persistante, en gérant les PR jusqu''à leur résolution babysit-pr ist ein KI-Agent, der Ingenieursprobleme persistent löst, indem er PRs bis zu ihrer Lösung verwaltet O babysit-pr é um agente AI que automatiza persistentemente a monitorização de Pull Requests. Gerencia processos de CI, deteta conflitos de merge e assegura que todos os comentários de revisão são tratados, libertando os desenvolvedores para outras tarefas. babysit-pr — это ИИ агент для персистентной автоматизации мониторинга Pull Requests. Управляет процессами CI, обнаруживает конфликты слияния и обеспечивает обработку всех комментариев ревью, освобождая разработчиков для других задач. babysit-pr هو أداة ذكاء اصطناعي لأتمتة مراقبة طلبات السحب بشكل مستمر. تدير عمليات CI، تكتشف تعارضات الدمج، وتضمن معالجة جميع تعليقات المراجعة، مما يحرر المطورين للمهام الأخرى. how to use babysit-pr babysit-pr setup guide automated PR management CI issue resolution merge conflict resolution babysit-pr alternative babysit-pr vs github actions babysit-pr install babysit-pr tutorial babysit-pr AI代理 PR自动监控工具 GitHub CI检查 代码评审自动化 合并冲突检测 AI工程代理 拉取请求管理 持续集成自动化 Monitors PRs until merged or closed Checks for successful CI and unaddressed review comments Verifies required review approval and potential merge conflicts Retries flaky failures until retry budget is exhausted Surfaces permission issues and CI infrastructure problems babysit-pr is a skill that automates the management of pull requests (PRs) for AI agents, ensuring efficient resolution of merge conflicts and CI issues.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('CellixJs/cellixjs/madr-enforcement', 'community', 'CellixJs', 'cellixjs', 'CellixJs/cellixjs', 'madr-enforcement', 16, 0, 65, '2026-02-10T14:45:50Z', '2026-03-06T06:43:22.798Z', '07fc09384c84a905e7a4763e1e4ee802c925ee6237ac8bf6f8cf64ea9230ee44', '{"id":"CellixJs/cellixjs/madr-enforcement","name":"madr-enforcement","description":{"en":"The madr-enforcement skill enforces architectural standards in CellixJS projects, ensuring adherence to Domain Driven Design principles and guidelines. This benefits developers working on CellixJS projects.","zh":"MADR 强制执行技能确保 CellixJS 项目代码遵循架构标准和模式，提高开发效率","ja":"MADR Enforcement Skill は CellixJS プロジェクトのコードがアーキテクチャ標準とパターンに準拠していることを保証し、開発効率を向上させる","ko":"MADR 강제 실행 스킬은 CellixJS 프로젝트 코드가 아키텍처 표준과 패턴을 준수하는지 확인하고 개발 효율성을 향상시키는 방법","es":"madr-enforcement es una habilidad que garantiza la adherencia a los estándares arquitectónicos en proyectos CellixJS mediante el uso de Markdown Any Decision Records (MADRs)","fr":"madr-enforcement est une compétence qui assure le respect des normes architecturales dans les projets CellixJS en utilisant les Markdown Any Decision Records (MADRs)","de":"madr-enforcement ist eine Fähigkeit, die die Einhaltung der Architekturstandards in CellixJS-Projekten durch die Verwendung von Markdown Any Decision Records (MADRs) sicherstellt","pt":"O madr-enforcement é uma habilidade que garante a adesão às normas arquiteturais em projetos CellixJS, utilizando TypeScript e Domain Driven Design","ru":"ИИ Агент madr-enforcement обеспечивает соблюдение архитектурных стандартов в проектах CellixJS, используя TypeScript и Domain Driven Design","ar":"وظيفة madr-enforcement تضمن الامتثال لمعايير التصميم المعماري في مشاريع CellixJS، باستخدام TypeScript و Domain Driven Design"},"seo":{"title":{"en":"madr-enforcement: Architectural Standards Enforcement for...","zh":"MADR 强制执行技能 - CellixJS 项目架构标准","ja":"MADR Enforcement Skill - CellixJS プロジェクトのアーキテクチャ標準","ko":"MADR 강제 실행 스킬 - CellixJS 프로젝트 아키텍처 표준","es":"Guía de configuración de madr-enforcement para DDD","fr":"Mise en place de madr-enforcement pour la conception orie...","de":"Einrichtungsleitfaden für madr-enforcement in Domain-Driv...","pt":"Guia de Configuração do madr-enforcement para Desenvolved...","ru":"Настройка ИИ Агента madr-enforcement для Разработчиков","ar":"دليل إعداد madr-enforcement لأدوات الذكاء الاصطناعي للمطورين"},"description":{"en":"Discover how madr-enforcement ensures CellixJS projects adhere to Domain Driven Design standards and guidelines - learn more and get started today!","zh":"使用 MADR 强制执行技能确保 CellixJS 项目代码遵循架构标准和模式，提高开发效率","ja":"MADR Enforcement Skill を使用して CellixJS プロジェクトのコードがアーキテクチャ標準とパターンに準拠していることを保証し、開発効率を向上させる","ko":"MADR 강제 실행 스킬을 사용하여 CellixJS 프로젝트 코드가 아키텍처 표준과 패턴을 준수하는지 확인하고 개발 효율성을 향상시키는 방법","es":"Aprende a implementar madr-enforcement en tus proyectos CellixJS para asegurar la adherencia a los estándares arquitectónicos","fr":"Découvrez comment mettre en œuvre madr-enforcement dans vos projets CellixJS pour garantir le respect des normes architecturales","de":"Erfahren Sie, wie Sie madr-enforcement in Ihren CellixJS-Projekten implementieren, um die Einhaltung der Architekturstandards sicherzustellen","pt":"Aprenda a configurar o madr-enforcement para garantir a adesão às normas arquiteturais em projetos CellixJS","ru":"Узнайте, как настроить madr-enforcement для обеспечения соблюдения архитектурных стандартов в проектах CellixJS","ar":"تعلم كيفية إعداد madr-enforcement لضمان الامتثال لمعايير التصميم المعماري في مشاريع CellixJS"},"definition":{"en":"madr-enforcement is a skill that enforces architectural standards and patterns in CellixJS projects based on Markdown Any Decision Records (MADRs).","zh":"MADR 强制执行技能是一种确保代码遵循架构标准和模式的方法","ja":"MADR Enforcement Skill はコードがアーキテクチャ標準とパターンに準拠していることを保証する方法","ko":"MADR 강제 실행 스킬은 코드가 아키텍처 표준과 패턴을 준수하는지 확인하는 방법","es":"madr-enforcement es una habilidad que aplica las decisiones arquitectónicas registradas en Markdown","fr":"madr-enforcement est une compétence qui applique les décisions architecturales enregistrées en Markdown","de":"madr-enforcement ist eine Fähigkeit, die die in Markdown aufgezeichneten Architekturentscheidungen anwendet","pt":"O que é madr-enforcement? É uma habilidade que garante a adesão às normas arquiteturais em projetos CellixJS","ru":"Что такое madr-enforcement? Это ИИ Агент, обеспечивающий соблюдение архитектурных стандартов в проектах CellixJS","ar":"ما هي وظيفة madr-enforcement؟ هي وظيفة تضمن الامتثال لمعايير التصميم المعماري في مشاريع CellixJS"},"features":{"en":["Enforces architectural standards and patterns from MADRs","Ensures code adherence to Domain Driven Design (DDD) principles","Reviews pull requests for compliance with established patterns","Supports TypeScript for robust and maintainable code","Utilizes Markdown Any Decision Records (MADRs) for binding architectural decisions","Located in apps/docs/docs/decisions/ for easy access and reference"],"zh":["确保代码遵循架构标准和模式","支持 Domain Driven Design (DDD)","使用 TypeScript 开发","集成 MADR 文档","自动检查代码是否符合架构标准","提高开发效率"],"ja":["コードがアーキテクチャ標準とパターンに準拠していることを保証","Domain Driven Design (DDD) をサポート","TypeScript を使用して開発","MADR ドキュメントを統合","コードがアーキテクチャ標準に準拠していることを自動でチェック","開発効率を向上させる"],"ko":["코드가 아키텍처 표준과 패턴을 준수하는지 확인","Domain Driven Design (DDD) 지원","TypeScript 사용","MADR 문서 통합","코드가 아키텍처 표준에 준수하는지 자동으로 확인","개발 효율성을 향상시키는 방법"],"es":["Aplicación de patrones arquitectónicos establecidos","Uso de Markdown Any Decision Records (MADRs) para registrar decisiones arquitectónicas","Seguimiento de la adherencia a los estándares arquitectónicos en proyectos CellixJS","Soporte para TypeScript","Integración con Domain-Driven Design (DDD)"],"fr":["Application de modèles architecturaux établis","Utilisation de Markdown Any Decision Records (MADRs) pour enregistrer les décisions architecturales","Suivi du respect des normes architecturales dans les projets CellixJS","Prise en charge de TypeScript","Intégration avec la conception orientée domaine (DDD)"],"de":["Anwendung etablierter Architekturmuster","Verwendung von Markdown Any Decision Records (MADRs) zur Aufzeichnung von Architekturentscheidungen","Überwachung der Einhaltung der Architekturstandards in CellixJS-Projekten","Unterstützung für TypeScript","Integration mit Domain-Driven Design (DDD)"],"pt":["Garantia de adesão às normas arquiteturais","Utilização de TypeScript e Domain Driven Design","Integração com Markdown Any Decision Records (MADRs)","Verificação de código em projetos CellixJS","Suporte à revisão de pull requests"],"ru":["Обеспечение соблюдения архитектурных стандартов","Использование TypeScript и Domain Driven Design","Интеграция с Markdown Any Decision Records (MADRs)","Проверка кода в проектах CellixJS","Поддержка рассмотрения запросов на слияние"],"ar":["ضمان الامتثال لمعايير التصميم المعماري","استخدام TypeScript و Domain Driven Design","التكامل مع Markdown Any Decision Records (MADRs)","فحص الكود في مشاريع CellixJS","دعم استعراض طلبات الدمج"]},"keywords":{"en":["how to use madr-enforcement","what is madr-enforcement","madr-enforcement alternative","madr-enforcement vs domain driven design","madr-enforcement install","madr-enforcement setup guide","cellixjs architectural standards","domain driven design enforcement","typescript madr-enforcement"],"zh":["MADR 强制执行技能","CellixJS 项目","架构标准","Domain Driven Design","TypeScript","MADR 文档","代码检查","开发效率"],"ja":["MADR Enforcement Skill","CellixJS プロジェクト","アーキテクチャ標準","Domain Driven Design","TypeScript","MADR ドキュメント","コードチェック","開発効率"],"ko":["MADR 강제 실행 스킬","CellixJS 프로젝트","아키텍처 표준","Domain Driven Design","TypeScript","MADR 문서","코드 확인","개발 효율성"],"es":["madr-enforcement","CellixJS","Domain-Driven Design","DDD","TypeScript","Markdown Any Decision Records","MADRs","patrones arquitectónicos","estándares arquitectónicos"],"fr":["madr-enforcement","CellixJS","conception orientée domaine","DDD","TypeScript","Markdown Any Decision Records","MADRs","modèles architecturaux","normes architecturales"],"de":["madr-enforcement","CellixJS","Domain-Driven Design","DDD","TypeScript","Markdown Any Decision Records","MADRs","Architekturmuster","Architekturstandards"],"pt":["madr-enforcement","CellixJS","TypeScript","Domain Driven Design","MADRs","Desenvolvimento de software","Arquitetura de software","Normas arquiteturais"],"ru":["madr-enforcement","CellixJS","TypeScript","Domain Driven Design","MADRs","Разработка программного обеспечения","Архитектура программного обеспечения","Архитектурные стандарты"],"ar":["madr-enforcement","CellixJS","TypeScript","Domain Driven Design","MADRs","تطوير البرمجيات","هندسة البرمجيات","معايير التصميم المعماري"]}},"owner":"CellixJs","repo":"cellixjs","repoPath":"CellixJs/cellixjs","stars":16,"forks":0,"updatedAt":"2026-02-10T14:45:50Z","topics":["ddd","ddd-example","domain-driven-design","typescript"],"category":"community","skillMd":{"name":"madr-enforcement","description":">","version":"1.0","bodyPreview":"# MADR Enforcement Skill\n\nThis skill ensures that code written in the CellixJS project adheres to the architectural standards, patterns, \nand guidelines documented in our Markdown Any Decision Records (MADRs). All ADRs are located in \n`apps/docs/docs/decisions/` and represent binding architectural decisions that must be followed.\n\n## When to Use This Skill\n\nUse this skill when:\n\n- **Writing new code** - Ensure it follows established architectural patterns from ADRs\n- **Reviewing pull requests**","body":"# MADR Enforcement Skill\n\nThis skill ensures that code written in the CellixJS project adheres to the architectural standards, patterns, \nand guidelines documented in our Markdown Any Decision Records (MADRs). All ADRs are located in \n`apps/docs/docs/decisions/` and represent binding architectural decisions that must be followed.\n\n## When to Use This Skill\n\nUse this skill when:\n\n- **Writing new code** - Ensure it follows established architectural patterns from ADRs\n- **Reviewing pull requests** - Verify code compliance with documented standards\n- **Refactoring existing code** - Align implementations with current ADRs\n- **Adding dependencies** - Check against technology choices documented in ADRs\n- **Making design decisions** - Verify alignment or identify need for new ADR\n- **Implementing features** - Follow patterns from relevant domain/infrastructure ADRs\n\n## CellixJS Architectural Decisions (ADRs)\n\nAll architectural decisions are documented in `apps/docs/docs/decisions/`. The following ADRs define \nstandards that **MUST** be enforced in code:\n\n### Architecture & Design Patterns\n\n#### ADR-0003: Domain-Driven Design (DDD)\n\n**Standards to Enforce:**\n\n1. **Bounded Contexts** - Code must be organized by bounded context\n   - Location: `packages/ocom/domain/contexts/{context-name}/`\n   - Each context has its own ubiquitous language\n   \n2. **Entity Structure** - Entities must follow DDD patterns\n   - File: `{entity}.ts`\n   - Must have unique identity (ID)\n   - Contains business logic methods\n   - Props interface defines state\n   \n3. **Value Objects** - Immutable objects defined by their values\n   - File: `{entity}.value-objects.ts`\n   - Must be immutable\n   - Use `@lucaspaganini/value-objects` framework\n   \n4. **Aggregate Roots** - Entry points for entity clusters\n   - File: `{entity}.ts` (aggregate root entities)\n   - Enforces business rules for the aggregate\n   - Guards integrity of related entities\n   \n5. **Unit of Work Pattern** - Atomic operations on domain models\n   - File: `{entity}.uow.ts`\n   - Transaction boundary for persistence\n   - One per aggregate root\n\n6. **Layer Separation**\n   - **Domain Layer**: Business logic only, no infrastructure\n   - **Application Service Layer**: Orchestration, coordinates use cases\n   - **Infrastructure Service Layer**: External systems, third-party APIs\n\n**Code Review Checklist:**\n- [ ] Is code organized by bounded context?\n- [ ] Do entities have unique identifiers?\n- [ ] Are value objects immutable?\n- [ ] Are aggregate boundaries respected?\n- [ ] Is domain logic separate from infrastructure?\n- [ ] Are Unit of Work patterns used for persistence?\n\n#### ADR-0019: MonoRepo and Turborepo\n\n**Standards to Enforce:**\n\n1. **Package Organization**\n   - Workspace structure defined in `pnpm-workspace.yaml`\n   - Package naming: `@ocom/*` or `@cellix/*`\n   \n2. **Build System**\n   - Use Turborepo for builds: `pnpm run build`\n   - Respect package dependencies\n   - Use affected builds: `pnpm run build:affected`\n   \n3. **Testing**\n   - Package-level tests in each workspace\n   - Use `pnpm run test:affected`\n   - Coverage reports per package\n\n**Code Review Checklist:**\n- [ ] Is new code in the correct workspace package?\n- [ ] Are package dependencies declared in package.json?\n- [ ] Do build scripts use Turborepo commands?\n- [ ] Are tests co-located with the code they test?\n\n### Code Quality & Standards\n\n#### ADR-0012: Biome for Linting\n\n**Standards to Enforce:**\n\n1. **Linting and Formatting**\n   - Use Biome (not ESLint or Prettier)\n   - Configuration in `biome.json`\n   - Run before commits: `pnpm run lint`\n   \n2. **Type Safety**\n   - Biome provides type-aware linting\n   - Strict TypeScript configuration\n   - No `any` types without justification\n   \n3. **Code Style**\n   - Tab indentation (per biome.json)\n   - Follow Biome''s formatting rules\n   - Auto-fix with `pnpm run format`\n\n**Code Review Checklist:**\n- [ ] Does code pass Biome linting?\n- [ ] Is code formatted with Biome?\n- [ ] Are TypeScript types strict and complete?\n- [ ] No ESLint or Prettier configurations added?\n\n#### ADR-0013: Test Suite Architecture\n\n**Standards to Enforce:**\n\n1. **Test Framework**\n   - Use Vitest for unit tests\n   - Test coverage via `pnpm run test:coverage`\n   \n2. **Test Organization**\n   - Unit tests: Co-located with source files\n   - Integration tests: Separate directory\n   - E2E tests: SerenityJS (ADR-0007)\n   \n3. **Coverage Requirements**\n   - Coverage reports in `packages/*/coverage/`\n   - Minimum coverage thresholds enforced\n\n**Code Review Checklist:**\n- [ ] Are unit tests written for new code?\n- [ ] Do tests use Vitest framework?\n- [ ] Is test coverage adequate?\n- [ ] Are tests co-located appropriately?\n\n#### ADR-0022: Snyk Security Integration\n\n**Standards to Enforce:**\n\n1. **Security Scanning**\n   - Run Snyk before commits: `pnpm run snyk`\n   - Includes SAST (code), SCA (dependencies), IaC (Bicep)\n   \n2. **Vulnerability Management**\n   - Fix critical/high vulnerabilities immediately\n   - Document exceptions in `.snyk` file\n   - Get CODEOWNERS approval for ignores\n   \n3. **Workflow**\n   - Scan during development with `snyk_code_scan` MCP tool\n   - Verify fixes with re-scan\n   - Pass Snyk gate before commit\n\n**Code Review Checklist:**\n- [ ] Does code pass Snyk security scans?\n- [ ] Are vulnerabilities addressed or documented?\n- [ ] Are new dependencies scanned with `gh-advisory-database` MCP tool?\n- [ ] Are suppressed issues justified with expiration?\n\n### Infrastructure & Technology\n\n#### ADR-0002: OpenTelemetry\n\n**Standards to Enforce:**\n\n1. **Observability**\n   - Use `@azure/monitor-opentelemetry`\n   - Automatic instrumentation for MongoDB, Azure Functions\n   - GraphQL tracing via Apollo Server\n   \n2. **Integration**\n   - Package: `@ocom/service-otel`\n   - Configured via OpenTelemetry SDK\n\n**Code Review Checklist:**\n- [ ] Are new services instrumented with OpenTelemetry?\n- [ ] Is tracing configured for external calls?\n- [ ] Are metrics and logs properly structured?\n\n#### ADR-0011: Bicep for Infrastructure as Code\n\n**Standards to Enforce:**\n\n1. **IaC Language**\n   - Use Bicep (not ARM templates, Terraform)\n   - Location: `iac/` directory\n   \n2. **Resource Naming**\n   - Follow naming conventions in ADR-0021\n   - Use resource scoping strategy\n   \n3. **Deployment**\n   - Azure infrastructure deployments per ADR-0014\n   - CI/CD via Azure DevOps (ADR-0020)\n\n**Code Review Checklist:**\n- [ ] Is infrastructure defined in Bicep?\n- [ ] Do resource names follow conventions?\n- [ ] Are Bicep files scanned with Snyk IaC?\n\n#### ADR-0014: Azure Infrastructure Deployments\n\n**Standards to Enforce:**\n\n1. **Azure Functions**\n   - Version 4.x\n   - TypeScript runtime\n   - Registered via `cellix.registerAzureFunctionHandler()`\n   \n2. **Service Registration**\n   - Use `Cellix` class for DI orchestration\n   - Register services with `serviceRegistry.registerService()`\n   \n3. **Context Specification**\n   - Define context via `setContext()`\n   - Provide typed service access\n\n**Code Review Checklist:**\n- [ ] Are Azure Functions v4 patterns followed?\n- [ ] Is dependency injection used correctly?\n- [ ] Are services registered properly?\n\n### Technology Choices\n\n#### ADR-0004: Identity and Access Management\n#### ADR-0005: Authorization\n\n**Standards to Enforce:**\n\n1. **Authentication**\n   - Follow IAM patterns from ADR-0004\n   \n2. **Authorization**\n   - Implement authorization per ADR-0005\n\n**Code Review Checklist:**\n- [ ] Is authentication implemented correctly?\n- [ ] Are authorization checks in place?\n- [ ] Do security patterns match ADRs?\n\n#### ADR-0010: React Router Loaders\n\n**Standards to Enforce:**\n\n1. **Data Loading**\n   - Use React Router loaders for initial data\n   - Co-locate with route definitions\n   \n2. **UI Patterns**\n   - Loader functions return route data\n   - Components access via `useLoaderData()`\n\n**Code Review Checklist:**\n- [ ] Are loaders used for data fetching?\n- [ ] Is data loading co-located with routes?\n\n## Code Enforcement Workflow\n\n### When Writing New Code\n\n1. **Identify Relevant ADRs**\n   - Search `apps/docs/docs/decisions/` for applicable standards\n   - Read ADRs related to your domain, technology, or pattern\n   \n2. **Apply ADR Standards**\n   - Follow file naming conventions\n   - Use documented patterns\n   - Respect layer boundaries\n   \n3. **Verify Compliance**\n   - Run linting: `pnpm run lint`\n   - Run tests: `pnpm run test`\n   - Run security scan: `pnpm run snyk`\n   - Full verification: `pnpm run verify`\n\n### When Reviewing Code\n\n1. **Check ADR Alignment**\n   - Identify which ADRs apply to the changes\n   - Verify code follows documented patterns\n   \n2. **Common Violations**\n   - Domain logic in infrastructure layer (violates ADR-0003)\n   - Using ESLint instead of Biome (violates ADR-0012)\n   - Missing tests (violates ADR-0013)\n   - Unscanned dependencies (violates ADR-0022)\n   - Not using Bicep for infrastructure (violates ADR-0011)\n   \n3. **Request Changes**\n   - Reference specific ADR in review comments\n   - Explain which standard is violated\n   - Suggest corrective action\n\n### When Making Architectural Decisions\n\n1. **Check Existing ADRs**\n   - Search for related decisions\n   - Verify no conflicts with current ADRs\n   \n2. **Determine if New ADR Needed**\n   - New framework/library adoption → Requires ADR\n   - New architectural pattern → Requires ADR\n   - Infrastructure changes → Requires ADR\n   - Refactoring without architectural impact → No ADR needed\n   \n3. **Create ADR if Required**\n   - Follow process in ADR-0001\n   - Use templates in `apps/docs/docs/decisions/`\n   - Get approval from deciders before implementing\n\n## ADR Index by Category\n\n### Architecture & Design\n- **ADR-0003**: Domain-Driven Design (DDD)\n- **ADR-0019**: MonoRepo and Turborepo\n\n### Code Quality & Security\n- **ADR-0012**: Biome linting\n- **ADR-0013**: Test suite architecture\n- **ADR-0015**: SonarCloud integration\n- **ADR-0016**: SonarCloud code duplication\n- **ADR-0022**: Snyk security integration\n\n### Infrastructure & DevOps\n- **ADR-0002**: OpenTelemetry observability\n- **ADR-0011**: Bicep for IaC\n- **ADR-0014**: Azure infrastructure deployments\n- **ADR-0018**: Docusaurus Azure pipeline\n- **ADR-0020**: Azure DevOps monorepo pipeline\n- **ADR-0021**: Bicep resource scoping\n\n### Technology & Tools\n- **ADR-0004**: Identity and access management\n- **ADR-0005**: Authorization patterns\n- **ADR-0006**: Maps integration\n- **ADR-0007**: SerenityJS testing\n- **ADR-0008**: White-label architecture\n- **ADR-0009**: Cache purging\n- **ADR-0010**: React Router loaders\n- **ADR-0017**: Chrome content overrides\n- **ADR-0023**: TsGo migration\n\n### Process & Documentation\n- **ADR-0001**: MADR for architectural decisions\n\n## Common Code Patterns by ADR\n\n### DDD Pattern (ADR-0003)\n\n**Correct Implementation:**\n```typescript\n// packages/ocom/domain/contexts/user/user.ts\nexport interface UserProps {\n  readonly id: UserId;\n  readonly email: Email;\n  readonly profile: UserProfile;\n}\n\nexport class User implements AggregateRoot<UserProps> {\n  constructor(private props: UserProps) {}\n  \n  get id(): UserId { return this.props.id; }\n  \n  updateEmail(newEmail: Email): void {\n    // Domain logic here\n    this.props = { ...this.props, email: newEmail };\n  }\n  \n  // No database or infrastructure code here!\n}\n```\n\n**Incorrect Implementation (violates ADR-0003):**\n```typescript\n// ❌ WRONG: Domain entity with database code\nexport class User {\n  async save(): Promise<void> {\n    await mongoose.model(''User'').save(this); // Infrastructure in domain!\n  }\n}\n```\n\n### Service Registration (ADR-0014)\n\n**Correct Implementation:**\n```typescript\n// Proper dependency injection\nCellix.initializeServices<ApiContextSpec>((serviceRegistry) => {\n  serviceRegistry.registerService(new ServiceMongoose(...));\n  serviceRegistry.registerService(new ServiceOtel(...));\n})\n.setContext((serviceRegistry) => ({ \n  domainDataSource: contextBuilder(serviceRegistry.getService(ServiceMongoose)),\n  telemetry: serviceRegistry.getService(ServiceOtel)\n}));\n```\n\n### Turborepo Usage (ADR-0019)\n\n**Correct Commands:**\n```bash\n# Build all packages\npnpm run build\n\n# Build only affected packages\npnpm run build:affected\n\n# Test with turbo caching\npnpm run test\n```\n\n**Incorrect:**\n```bash\n# ❌ WRONG: Building individual packages directly\ncd packages/ocom/domain && npm run build\n```\n\n## Enforcement During Code Generation\n\nWhen generating code:\n\n1. **Start with ADR Review**\n   - Identify applicable ADRs for the task\n   - Read relevant sections\n   \n2. **Generate Code Following Standards**\n   - Use patterns from ADRs\n   - Follow file naming conventions\n   - Respect layer boundaries\n   \n3. **Verify Compliance**\n   - Check code against ADR requirements\n   - Run verification suite\n   - Reference ADRs in comments if needed\n\n## References\n\n### Internal Documentation\n- **All ADRs**: `apps/docs/docs/decisions/`\n- **ADR-0001**: MADR Architecture Decisions (process for creating ADRs)\n- **ADR Templates**: `apps/docs/docs/decisions/adr-template.md`\n\n### External Resources\n- [MADR Project](https://adr.github.io/madr/)\n- [Domain-Driven Design](https://www.domainlanguage.com/ddd/)\n- [Biome Documentation](https://biomejs.dev/)\n- [Turborepo Documentation](https://turbo.build/)\n"},"lastSynced":"2026-03-06T06:43:22.798Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing strict adherence to Domain Driven Design principles and Markdown Any Decision Records (MADRs) in CellixJS projects.","zh":"非常适合需要严格遵守领域驱动设计原则和Markdown Any Decision Records (MADRs)的代码审查代理，特别是在CellixJS项目中。","ja":"ドメイン駆動設計の原則とMarkdown Any Decision Records (MADRs)を厳格に遵守する必要があるコードレビュー代理に最適です。特にCellixJSプロジェクトで。","ko":"도메인 주도 설계 원칙과 Markdown Any Decision Records(MADRs)를 엄격히 준수해야 하는 코드 리뷰 에이전트에게 적합합니다. 특히 CellixJS 프로젝트에서.","es":"Perfecto para Agentes de Revisión de Código que necesitan una estricta adherencia a los principios de Domain Driven Design y Registros de Decisiones Markdown (MADRs) en proyectos de CellixJS.","fr":"Parfait pour les agents de revue de code nécessitant une stricte adhésion aux principes de Domain Driven Design et des enregistrements de décision Markdown (MADRs) dans les projets CellixJS.","de":"Perfekt für Code-Review-Agenten, die eine strikte Einhaltung der Domain-Driven-Design-Prinzipien und der Markdown-Entscheidungsprotokolle (MADRs) in CellixJS-Projekten benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de adesão estrita aos princípios de Domain Driven Design e Registros de Decisões em Markdown (MADRs) em projetos CellixJS.","ru":"Идеально подходит для агентов код-ревью, которым необходима строгая соблюдение принципов Domain Driven Design и Markdown Any Decision Records (MADRs) в проектах CellixJS.","ar":"مثالي لعميل مراجعة الشفرة الذي يحتاج إلى امتثال صارم لمبادئ Domain Driven Design وسجلات القرارات في Markdown (MADRs) في مشاريع CellixJS."},"recommendation":{"en":"Empowers agents to enforce architectural standards, ensuring code compliance with established patterns and guidelines documented in MADRs, and facilitates review of pull requests against these standards using CellixJS and Markdown files located in `apps/docs/docs/decisions/`.","zh":"赋予代理人执行架构标准的能力，确保代码遵守既定的模式和指南，这些指南记录在MADRs中，并使用CellixJS和位于`apps/docs/docs/decisions/`的Markdown文件来促进对这些标准的拉取请求审查。","ja":"エージェントがアーキテクチャ標準を実施する能力を与え、コードが確立されたパターンとガイドラインに準拠することを保証します。これらのガイドラインはMADRsに記載されており、CellixJSと`apps/docs/docs/decisions/`に位置するMarkdownファイルを使用して、これらの標準に対するプルリクエストのレビューを促進します。","ko":"에이전트가 아키텍처 표준을 적용할 수 있는 능력을 부여하여 코드가 확립된 패턴과 가이드라인을 준수하도록 하며, 이러한 가이드라인은 MADRs에 기록되어 있으며, CellixJS와 `apps/docs/docs/decisions/`에 위치한 Markdown 파일을 사용하여 이러한 표준에 대한 풀 리퀘스트 리뷰를 촉진합니다.","es":"Habilita a los agentes a hacer cumplir los estándares arquitectónicos, garantizando el cumplimiento del código con los patrones y directrices establecidos documentados en MADRs, y facilita la revisión de solicitudes de extracción contra estos estándares utilizando CellixJS y archivos Markdown ubicados en `apps/docs/docs/decisions/`.","fr":"Permet aux agents d''appliquer les normes architecturales, en garantissant la conformité du code avec les modèles et directives établis documentés dans les MADRs, et facilite l''examen des demandes d''extraction par rapport à ces normes en utilisant CellixJS et des fichiers Markdown situés dans `apps/docs/docs/decisions/`.","de":"Ermächtigt die Agenten, die architektonischen Standards durchzusetzen, indem sie sicherstellen, dass der Code den etablierten Mustern und Richtlinien entspricht, die in den MADRs dokumentiert sind, und erleichtert die Überprüfung von Pull-Requests gegen diese Standards mithilfe von CellixJS und Markdown-Dateien im Verzeichnis `apps/docs/docs/decisions/`.","pt":"Habilita os agentes a impor padrões arquiteturais, garantindo a conformidade do código com padrões e diretrizes estabelecidos documentados em MADRs, e facilita a revisão de solicitações de pull contra esses padrões usando CellixJS e arquivos Markdown localizados em `apps/docs/docs/decisions/`.","ru":"Наделяет агентов возможностью обеспечивать соблюдение архитектурных стандартов, гарантируя соответствие кода установленным шаблонам и руководящим принципам, документированным в MADRs, и облегчает проверку запросов на слияние по отношению к этим стандартам с использованием CellixJS и файлов Markdown, расположенных в `apps/docs/docs/decisions/`.","ar":"يمنح الوكلاء القدرة على فرض المعايير المعمارية، وضمان امتثال الشفرة للأنماط والمبادئ التوجيهية المثبتة الموثقة في MADRs، وتسهيل مراجعة طلبات السحب ضد هذه المعايير باستخدام CellixJS وملفات Markdown الموجودة في `apps/docs/docs/decisions/`."},"useCases":{"en":["Enforcing Domain Driven Design principles in new code","Reviewing pull requests for MADR compliance","Validating code adherence to architectural decisions"],"zh":["在新代码中执行领域驱动设计原则","审查拉取请求以确保MADR合规性","验证代码对架构决策的遵守"],"ja":["新しいコードでドメイン駆動設計の原則を実施する","MADRの準拠性を確保するためにプルリクエストをレビューする","コードがアーキテクチャ上の決定を遵守していることを検証する"],"ko":["새 코드에서 도메인 주도 설계 원칙을 적용합니다","MADR 준수를 위해 풀 리퀘스트를 리뷰합니다","코드가 아키텍처 결정에 따라 규칙을 준수하는지 검증합니다"],"es":["Aplicar los principios de Domain Driven Design en el nuevo código","Revisar solicitudes de extracción para el cumplimiento de MADR","Validar la adherencia del código a las decisiones arquitectónicas"],"fr":[" Appliquer les principes de Domain Driven Design dans le nouveau code","Réviser les demandes d''extraction pour la conformité aux MADRs","Valider la conformité du code aux décisions architecturales"],"de":["Die Prinzipien von Domain-Driven Design in neuen Code anwenden","Überprüfen von Pull-Requests auf MADR-Konformität","Überprüfen der Einhaltung des Codes mit den architektonischen Entscheidungen"],"pt":["Impor princípios de Domain Driven Design em novo código","Revisar solicitações de pull para conformidade com MADR","Validar adesão do código a decisões arquiteturais"],"ru":["Внедрение принципов Domain Driven Design в новый код","Проверка запросов на слияние на соответствие MADR","Проверка соблюдения кодом архитектурных решений"],"ar":["فرض مبادئ Domain Driven Design في الشفرة الجديدة","مراجعة طلبات السحب للامتثال للمADR","التحقق من امتثال الشفرة للقرارات المعمارية"]},"limitations":{"en":["Requires access to CellixJS project files","Limited to CellixJS projects with MADRs in `apps/docs/docs/decisions/`"],"zh":["需要访问CellixJS项目文件","仅限于`apps/docs/docs/decisions/`中具有MADRs的CellixJS项目"],"ja":["CellixJSプロジェクトファイルへのアクセスが必要","MADRsを`apps/docs/docs/decisions/`に持つCellixJSプロジェクトのみに限定される"],"ko":["CellixJS 프로젝트 파일에 접근할 수 있어야 합니다","MADRs를 `apps/docs/docs/decisions/`에持つ CellixJS 프로젝트에만 제한됩니다"],"es":["Requiere acceso a los archivos del proyecto CellixJS","Limitado a proyectos CellixJS con MADRs en `apps/docs/docs/decisions/`"],"fr":["Nécessite l''accès aux fichiers du projet CellixJS","Limité aux projets CellixJS avec des MADRs dans `apps/docs/docs/decisions/`"],"de":["Benötigt Zugriff auf die Projektdateien von CellixJS","Begrenzt auf CellixJS-Projekte mit MADRs im Verzeichnis `apps/docs/docs/decisions/`"],"pt":["Requer acesso a arquivos de projeto CellixJS","Limitado a projetos CellixJS com MADRs em `apps/docs/docs/decisions/`"],"ru":["Требует доступа к файлам проекта CellixJS","Ограничен проектами CellixJS с MADRs в `apps/docs/docs/decisions/`"],"ar":["يتطلب الوصول إلى ملفات مشروع CellixJS","محدود بمشاريع CellixJS التي تحتوي على MADRs في `apps/docs/docs/decisions/`"]},"version":4},"contentHash":"07fc09384c84a905e7a4763e1e4ee802c925ee6237ac8bf6f8cf64ea9230ee44","qualityScore":65}');
