INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CellixJs/cellixjs/madr-enforcement', 'madr-enforcement', 'CellixJs', 'cellixjs', 'community', 'madr-enforcement CellixJs cellixjs community ddd ddd-example domain-driven-design typescript The madr-enforcement skill enforces architectural standards in CellixJS projects, ensuring adherence to Domain Driven Design principles and guidelines. This benefits developers working on CellixJS projects. MADR 强制执行技能确保 CellixJS 项目代码遵循架构标准和模式，提高开发效率 MADR Enforcement Skill は CellixJS プロジェクトのコードがアーキテクチャ標準とパターンに準拠していることを保証し、開発効率を向上させる MADR 강제 실행 스킬은 CellixJS 프로젝트 코드가 아키텍처 표준과 패턴을 준수하는지 확인하고 개발 효율성을 향상시키는 방법 madr-enforcement es una habilidad que garantiza la adherencia a los estándares arquitectónicos en proyectos CellixJS mediante el uso de Markdown Any Decision Records (MADRs) madr-enforcement est une compétence qui assure le respect des normes architecturales dans les projets CellixJS en utilisant les Markdown Any Decision Records (MADRs) madr-enforcement ist eine Fähigkeit, die die Einhaltung der Architekturstandards in CellixJS-Projekten durch die Verwendung von Markdown Any Decision Records (MADRs) sicherstellt O madr-enforcement é uma habilidade que garante a adesão às normas arquiteturais em projetos CellixJS, utilizando TypeScript e Domain Driven Design ИИ Агент madr-enforcement обеспечивает соблюдение архитектурных стандартов в проектах CellixJS, используя TypeScript и Domain Driven Design وظيفة madr-enforcement تضمن الامتثال لمعايير التصميم المعماري في مشاريع CellixJS، باستخدام TypeScript و Domain Driven Design how to use madr-enforcement what is madr-enforcement madr-enforcement alternative madr-enforcement vs domain driven design madr-enforcement install madr-enforcement setup guide cellixjs architectural standards domain driven design enforcement typescript madr-enforcement MADR 强制执行技能 CellixJS 项目 架构标准 Domain Driven Design TypeScript MADR 文档 代码检查 开发效率 Enforces architectural standards and patterns from MADRs Ensures code adherence to Domain Driven Design (DDD) principles Reviews pull requests for compliance with established patterns Supports TypeScript for robust and maintainable code Utilizes Markdown Any Decision Records (MADRs) for binding architectural decisions Located in apps/docs/docs/decisions/ for easy access and reference madr-enforcement is a skill that enforces architectural standards and patterns in CellixJS projects based on Markdown Any Decision Records (MADRs).');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hookvibe/hookcode/file-context-planning', 'community', 'hookvibe', 'hookcode', 'hookvibe/hookcode', 'file-context-planning', 3, 1, 65, '2026-02-27T14:57:39Z', '2026-03-06T07:02:03.025Z', 'fbf5c369fe9b953ce769a36607848a2a8954d6082431ee28ee273263ca75b72a', '{"id":"hookvibe/hookcode/file-context-planning","name":"file-context-planning","description":{"en":"file-context-planning is a skill that enables intelligent code review and automation through conversations and Webhooks. It benefits developers by providing a visual console for real-time task execution monitoring.","zh":"文件上下文规划是HookCode代码审查平台的一项技能，用于通过对话和Webhook触发CLI编码助手","ja":"ファイルコンテキスト計画は、HookCode AIエージェントの機能で、対話とWebhookを通じてCLIコーディングアシスタントをトリガーする","ko":"파일 컨텍스트 계획은 HookCode 코드 리뷰 플랫폼의 기능으로 대화와 Webhook을 통해 CLI 코딩 도우미를 트리거합니다","es":"La planificación de contexto de archivo es una habilidad de AI Agent que utiliza archivos markdown persistentes como memoria de trabajo en disco","fr":"La planification de contexte de fichier est une compétence d''outils IA qui utilise des fichiers markdown persistants comme mémoire de travail sur disque","de":"Die Dateikontextplanung ist eine Fähigkeit von KI-Tools, die persistente Markdown-Dateien als Arbeitsgedächtnis auf Disk verwendet","pt":"O skill file-context-planning permite trabalhar com arquivos de forma eficiente, utilizando a plataforma HookCode para automação de tarefas e revisão de código","ru":"Навык file-context-planning позволяет работать с файлами эффективно, используя платформу HookCode для автоматизации задач и проверки кода","ar":"الوظيفة file-context-planning تسمح بالعمل مع الملفات بفعالية، باستخدام منصة HookCode للتحكم الآلي في المهام ومراجعة الشفرة"},"seo":{"title":{"en":"file-context-planning: CLI Automation Setup Guide | AI Ag...","zh":"文件上下文规划设置指南 - HookCode 代码审查","ja":"ファイルコンテキスト計画のベストプラクティス - HookCode AIエージェント","ko":"파일 컨텍스트 계획 구현 가이드 - HookCode 코드 리뷰","es":"Guía de Configuración de Planificación de Contexto de Arc...","fr":"Guide de Configuration de la Planification de Contexte de...","de":"Einrichtungsleitfaden für Dateikontextplanung mit KI-Tool","pt":"Guia de Configuração do Planejamento de Arquivos com Ferr...","ru":"Настройка планирования контекста файлов с помощью ИИ Агентов","ar":"دليل إعداد تخطيط السياق الملفات مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how file-context-planning simplifies code review and automation. Learn to trigger CLI coding assistants and monitor tasks in real-time. Get started ...","zh":"了解文件上下文规划的技术细节，并发现如何使用HookCode代码审查平台提高开发效率","ja":"HookCode AIエージェントのファイルコンテキスト計画機能を活用して、開発プロセスを最適化する方法を学ぶ","ko":"HookCode 코드 리뷰 플랫폼의 파일 컨텍스트 계획 기능을 사용하여 개발 프로세스를 개선하는 방법을 알아보세요","es":"Aprende a utilizar la planificación de contexto de archivo con HookCode y CLI para una automatización de código eficiente","fr":"Découvrez comment utiliser la planification de contexte de fichier avec HookCode et CLI pour une automation de code efficace","de":"Erfahren Sie, wie Sie die Dateikontextplanung mit HookCode und CLI für eine effiziente Codeautomatisierung nutzen","pt":"Aprenda a configurar o planejamento de arquivos com o skill file-context-planning e melhore sua produtividade com ferramentas de IA","ru":"Узнайте, как настроить планирование контекста файлов с помощью навыка file-context-planning и повысьте свою производительность с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد تخطيط السياق الملفات باستخدام مهارة file-context-planning وزيادة إنتاجيتك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"file-context-planning is a Codex-compatible skill that uses persistent markdown files as working memory on disk for planning and automation purposes.","zh":"文件上下文规划是一种通过对话和Webhook触发CLI编码助手的技术","ja":"ファイルコンテキスト計画は、CLIコーディングアシスタントをトリガーするための対話とWebhookを使用する技術","ko":"파일 컨텍스트 계획은 CLI 코딩 도우미를 트리거하는 대화와 Webhook을 사용하는 기술","es":"La planificación de contexto de archivo es una técnica que utiliza archivos para almacenar y recuperar información de contexto","fr":"La planification de contexte de fichier est une technique qui utilise des fichiers pour stocker et récupérer des informations de contexte","de":"Die Dateikontextplanung ist eine Technik, die Dateien zur Speicherung und Wiederherstellung von Kontextinformationen verwendet","pt":"O que é planejamento de arquivos? É uma técnica de trabalho que utiliza arquivos de markdown como memória de trabalho em disco","ru":"Что такое планирование контекста файлов? Это техника работы, которая использует файлы markdown как рабочую память на диске","ar":"ما هو تخطيط السياق الملفات؟ إنه تقنية عمل تستخدم ملفات markdown كذاكرة عمل على القرص"},"features":{"en":["Triggers CLI coding assistants through conversations and Webhooks","Supports independent deployment for flexible automation","Provides a visual console for real-time task execution monitoring","Utilizes persistent markdown files as working memory on disk","Compatible with Codex for instruction-only automation","Refactors planning files for traceability under docs/en/developer/plans/<hash>"],"zh":["支持独立部署","提供可视化控制台用于实时任务执行监控","使用持久化Markdown文件作为工作内存","支持Codex兼容的指令","通过Webhook触发CLI编码助手"],"ja":["独立デプロイをサポート","リアルタイムタスク実行モニタリング用の可視化コンソールを提供","永続的なMarkdownファイルをワーキングメモリとして使用","Codex互換の指令をサポート","Webhookを通じてCLIコーディングアシスタントをトリガー"],"ko":["독립 배포 지원","실시간 태스크 실행 모니터링을 위한 시각화 콘솔 제공","영속적인 Markdown 파일을 작업 메모리として 사용","Codex 호환指令 지원","Webhook을 통해 CLI 코딩 도우미를 트리거"],"es":["Utiliza archivos markdown persistentes como memoria de trabajo en disco","Permite la automatización de código mediante CLI","Soporta la implementación independiente","Proporciona una consola visual para monitorear la ejecución de tareas en tiempo real","Utiliza Webhooks para desencadenar asistentes de codificación","Compatibilidad con Codex"],"fr":["Utilise des fichiers markdown persistants comme mémoire de travail sur disque","Permet l''automation de code via CLI","Prend en charge le déploiement indépendant","Fournit une console visuelle pour surveiller l''exécution des tâches en temps réel","Utilise des Webhooks pour déclencher des assistants de codage","Compatibilité avec Codex"],"de":["Verwendet persistente Markdown-Dateien als Arbeitsgedächtnis auf Disk","Ermöglicht die Automatisierung von Code über CLI","Unterstützt die unabhängige Implementierung","Bietet eine visuelle Konsole für die Überwachung der Aufgabenausführung in Echtzeit","Verwendet Webhooks, um Codierungsassistenten auszulösen","Kompatibilität mit Codex"],"pt":["Utiliza a plataforma HookCode para automação de tarefas","Suporta deploy independente","Fornece uma consola visual para monitoramento de execução de tarefas em tempo real","Permite trabalhar com arquivos de markdown como memória de trabalho em disco","Integração com Webhooks para triggers de CLI"],"ru":["Использует платформу HookCode для автоматизации задач","Поддерживает независимый deploy","Предоставляет визуальную консоль для мониторинга выполнения задач в реальном времени","Позволяет работать с файлами markdown как рабочей памятью на диске","Интеграция с Webhooks для триггеров CLI"],"ar":["تستخدم منصة HookCode للتحكم الآلي في المهام","تدعم النشر المستقل","توفر واجهة مرئية لمراقبة تنفيذ المهام في الوقت الفعلي","تسمح بالعمل مع ملفات markdown كذاكرة عمل على القرص","التكامل مع Webhooks لتحفيز CLI"]},"keywords":{"en":["how to use file-context-planning","file-context-planning alternative","file-context-planning setup guide","what is file-context-planning","file-context-planning vs automation platforms","file-context-planning install","Codex-compatible skills","CLI automation tools","code review and automation platforms"],"zh":["文件上下文规划","HookCode代码审查","CLI编码助手","Webhook","Codex兼容","代码审查平台","开发效率","AI工具"],"ja":["ファイルコンテキスト計画","HookCode AIエージェント","CLIコーディングアシスタント","Webhook","Codex互換","コードレビュープラットフォーム","開発効率","AIエージェント"],"ko":["파일 컨텍스트 계획","HookCode 코드 리뷰","CLI 코딩 도우미","Webhook","Codex 호환","コード 리뷰 플랫폼","개발 효율","AI 도구"],"es":["planificación de contexto de archivo","AI Agent","automatización de código","CLI","Codex","Webhooks","desarrollo de software","herramientas de desarrollo","integración de código"],"fr":["planification de contexte de fichier","Outil IA","automation de code","CLI","Codex","Webhooks","développement de logiciels","outils de développement","intégration de code"],"de":["Dateikontextplanung","KI-Tool","Codeautomatisierung","CLI","Codex","Webhooks","Softwareentwicklung","Entwicklungstools","Codeintegration"],"pt":["planejamento de arquivos","ferramentas de IA","automação de tarefas","revisão de código","HookCode","markdown","Webhooks","CLI","deploy independente"],"ru":["планирование контекста файлов","ИИ Агенты","автоматизация задач","проверка кода","HookCode","markdown","Webhooks","CLI","независимый deploy"],"ar":["تخطيط السياق الملفات","أدوات الذكاء الاصطناعي","التحكم الآلي في المهام","مراجعة الشفرة","HookCode","markdown","Webhooks","CLI","نشر مستقل"]}},"owner":"hookvibe","repo":"hookcode","repoPath":"hookvibe/hookcode","stars":3,"forks":1,"updatedAt":"2026-02-27T14:57:39Z","topics":[],"category":"community","skillMd":{"name":"file-context-planning","description":"Manus-style file-based planning for Codex CLI. Stores task_plan.md/findings.md/progress.md under docs/en/developer/plans/<session-hash>/ for durable planning + traceability.","version":"4.0.0","bodyPreview":"# Planning with Files (Codex)\n\n{/* Align this Claude skill''s path examples with the .claude directory layout. docs/en/developer/plans/claude-skills-audit-20260227/task_plan.md claude-skills-audit-20260227 */}\nWork like Manus: Use persistent markdown files as your \"working memory on disk.\"\n{/* Refactor planning files to live under docs/en/developer/plans/<hash> for traceability. sddsa89612jk4hbwas678 */}\n\n## What This Skill Does (Codex-Compatible)\n\nCodex skills are instruction-only. There are **n","body":"# Planning with Files (Codex)\n\n{/* Align this Claude skill''s path examples with the .claude directory layout. docs/en/developer/plans/claude-skills-audit-20260227/task_plan.md claude-skills-audit-20260227 */}\nWork like Manus: Use persistent markdown files as your \"working memory on disk.\"\n{/* Refactor planning files to live under docs/en/developer/plans/<hash> for traceability. sddsa89612jk4hbwas678 */}\n\n## What This Skill Does (Codex-Compatible)\n\nCodex skills are instruction-only. There are **no automatic hooks** (e.g., \"PreToolUse\", \"Stop\").\n\nTo get the benefits, you must **manually**:\n- Create a **session folder** under `docs/en/developer/plans/<session-hash>/`\n- Re-read `task_plan.md` before major decisions\n- Update `task_plan.md`, `findings.md`, and `progress.md` throughout the work\n- Add the same `<session-hash>` into inline code comments for traceability\n\n## Operational Checklist (Replace Claude Hooks)\n\nWhen using this skill on a complex task:\n\n1. Create a new session hash (example: `sddsa89612jk4hbwas678`).\n2. If `docs/en/developer/plans/<session-hash>/` does not exist, initialize it (script or template copy).\n3. Fill `task_plan.md` (goal, phases, key questions) **before** implementing anything.\n4. Before major decisions or phase changes, re-read `task_plan.md` (refreshes goals into the attention window).\n5. After every 2 information-gathering actions, append key discoveries into `findings.md` (2-Action Rule).\n6. After completing a phase, return to the session folder and update:\n   - phase status in `task_plan.md`\n   - session log + tests in `progress.md`\n7. When the task is done, update `docs/en/change-log/0.0.0.md` with the hash + one-line summary + relative link to the plan.\n\n## Important: Where Files Go (Repo Layout)\n\nWhen using this skill:\n\n- **Skill assets** (templates/scripts/reference) live in: `.claude/skills/file-context-planning/`\n  - Templates: `.claude/skills/file-context-planning/templates/`\n  - Scripts: `.claude/skills/file-context-planning/scripts/`\n- **Your planning files** live in a **hash folder** under: `docs/en/developer/plans/<session-hash>/`\n\n| Location | What Goes There |\n|----------|-----------------|\n| Skill directory (`.claude/skills/file-context-planning/`) | Templates, scripts, reference docs |\n| `docs/en/developer/plans/<session-hash>/` | `task_plan.md`, `findings.md`, `progress.md` |\n\nThis ensures your planning files are:\n- durable (versionable docs)\n- easy to link to (relative links)\n- traceable from code via the session hash\n\n## Quick Start\n\nBefore ANY complex task:\n\n### Option A: Initialize via Script (Fastest)\n\nCreates `docs/en/developer/plans/<session-hash>/` and copies templates there if missing.\n{/* Document docs navigation sync behavior (Mintlify vs Docusaurus). docs/en/developer/plans/dsim8xybp9oa18nz1gfq/task_plan.md dsim8xybp9oa18nz1gfq */}\nAlso syncs `docs/docs.json` when present (Mintlify) so the new session files are discoverable; if `docs/docs.json` is absent (Docusaurus), the sync step is skipped.\n\n```bash\nbash .claude/skills/file-context-planning/scripts/init-session.sh \"<session-hash>\" \"<session-title>\"\n```\n\nIf you need a one-off backfill or want to rebuild the navigation index deterministically:\n\n```bash\nbash .claude/skills/file-context-planning/scripts/sync-docs-json-plans.sh\n```\n\n### Option B: Copy Templates (Most Detailed)\n\n```bash\nmkdir -p docs/en/developer/plans/<session-hash>\ncp .claude/skills/file-context-planning/templates/task_plan.md docs/en/developer/plans/<session-hash>/task_plan.md\ncp .claude/skills/file-context-planning/templates/findings.md docs/en/developer/plans/<session-hash>/findings.md\ncp .claude/skills/file-context-planning/templates/progress.md docs/en/developer/plans/<session-hash>/progress.md\n```\n\nThen:\n\n1. **Fill `task_plan.md` first** — Goal, phases, key questions\n2. **Re-read plan before decisions** — Refreshes goals in the attention window\n3. **Update after each phase** — Mark status complete, log errors\n4. **Log discoveries continuously** — `findings.md` for knowledge, `progress.md` for session/test logs\n\nOptional completion check:\n\n```bash\nbash .claude/skills/file-context-planning/scripts/check-complete.sh <session-hash>\n```\n\n> **Note:** All three planning files should be created in `docs/en/developer/plans/<session-hash>/`, not in your project root and not in the skill folder.\n\n## The Core Pattern\n\n```\nContext Window = RAM (volatile, limited)\nFilesystem = Disk (persistent, unlimited)\n\n→ Anything important gets written to disk.\n```\n\n## File Purposes\n\n| File | Purpose | When to Update |\n|------|---------|----------------|\n| `task_plan.md` | Phases, progress, decisions | After each phase |\n| `findings.md` | Research, discoveries | After ANY discovery |\n| `progress.md` | Session log, test results | Throughout session |\n\n## Traceability: Hash in Inline Comments\n\nTo link code changes back to the plan folder, include the session hash in **every changed area** via an inline comment:\n\n{/* Align traceability format with repo-root AGENTS.md (include plan path + hash). docs/en/developer/plans/docsworkflowapi20260121/task_plan.md docsworkflowapi20260121 */}\n**Format:** `<one sentence in English> <relative-plan-path> <session-hash>`\n\n**Plan path:** `docs/en/developer/plans/<session-hash>/task_plan.md`\n\nExamples:\n\n- JS/TS/Go: `// Add input validation for webhook payload. docs/en/developer/plans/sddsa89612jk4hbwas678/task_plan.md sddsa89612jk4hbwas678`\n- Python/Shell/YAML: `# Document retry backoff behavior. docs/en/developer/plans/sddsa89612jk4hbwas678/task_plan.md sddsa89612jk4hbwas678`\n- SQL: `-- Prevent duplicate inserts via unique key. docs/en/developer/plans/sddsa89612jk4hbwas678/task_plan.md sddsa89612jk4hbwas678`\n- Markdown: `{/* Explain why this doc section changed. docs/en/developer/plans/sddsa89612jk4hbwas678/task_plan.md sddsa89612jk4hbwas678 */}`\n\nThis creates a stable backlink: comment → hash → `docs/en/developer/plans/<hash>/`.\n\n## Release Note Update (Required)\n\nWhen the task is completed, update `docs/en/change-log/0.0.0.md` with:\n- the session hash\n- a one-line summary\n- a relative link to the plan (recommend linking `task_plan.md`)\n\nExample entry:\n\n```md\n- sddsa89612jk4hbwas678: Refactor file-context-planning to store plans in hash folders. ([plan](../developer/plans/sddsa89612jk4hbwas678/task_plan.md))\n```\n\n{/* Keep changelog entries clean and single-line (no extra HTML comment lines). l290bb7v758opd6uxu6r */}\n> **Note:** Do not add an extra `{/* ... */}` line above changelog bullets. The bullet itself (hash + plan link) is enough traceability.\n\n{/* Prefer stdin to avoid shell expansion when summaries contain code-like characters. l290bb7v758opd6uxu6r */}\n> **Tip:** If your summary contains backticks or other shell-sensitive characters, pipe it via stdin: `printf ''%s'' \"<summary>\" | bash .claude/skills/file-context-planning/scripts/append-changelog.sh \"<hash>\"`.\n\n## Critical Rules\n\n### 1. Create Plan First\nNever start a complex task without a session folder containing `task_plan.md`. Non-negotiable.\n\n### 2. The 2-Action Rule\n> \"After every 2 information-gathering actions, IMMEDIATELY save key findings to text files.\"\n\nThis prevents visual/multimodal information from being lost.\n\n### 3. Read Before Decide\nBefore major decisions, read the plan file. This keeps goals in your attention window.\n\n### 4. Update After Act\nAfter completing any phase:\n- Mark phase status: `in_progress` → `complete`\n- Log any errors encountered\n- Note files created/modified\n\n### 5. Log ALL Errors\nEvery error goes in the plan file. This builds knowledge and prevents repetition.\n\n```markdown\n## Errors Encountered\n| Error | Attempt | Resolution |\n|-------|---------|------------|\n| FileNotFoundError | 1 | Created default config |\n| API timeout | 2 | Added retry logic |\n```\n\n### 6. Never Repeat Failures\n```\nif action_failed:\n    next_action != same_action\n```\nTrack what you tried. Mutate the approach.\n\n## The 3-Strike Error Protocol\n\n```\nATTEMPT 1: Diagnose & Fix\n  → Read error carefully\n  → Identify root cause\n  → Apply targeted fix\n\nATTEMPT 2: Alternative Approach\n  → Same error? Try different method\n  → Different tool? Different library?\n  → NEVER repeat exact same failing action\n\nATTEMPT 3: Broader Rethink\n  → Question assumptions\n  → Search for solutions\n  → Consider updating the plan\n\nAFTER 3 FAILURES: Escalate to User\n  → Explain what you tried\n  → Share the specific error\n  → Ask for guidance\n```\n\n## Read vs Write Decision Matrix\n\n| Situation | Action | Reason |\n|-----------|--------|--------|\n| Just wrote a file | DON''T read | Content still in context |\n| Viewed image/PDF | Write findings NOW | Multimodal → text before lost |\n| Browser returned data | Write to file | Screenshots don''t persist |\n| Starting new phase | Read plan/findings | Re-orient if context stale |\n| Error occurred | Read relevant file | Need current state to fix |\n| Resuming after gap | Read all planning files | Recover state |\n\n## The 5-Question Reboot Test\n\nIf you can answer these, your context management is solid:\n\n| Question | Answer Source |\n|----------|---------------|\n| Where am I? | Current phase in task_plan.md |\n| Where am I going? | Remaining phases |\n| What''s the goal? | Goal statement in plan |\n| What have I learned? | findings.md |\n| What have I done? | progress.md |\n\n## When to Use This Pattern\n\n**Use for:**\n- Multi-step tasks (3+ steps)\n- Research tasks\n- Building/creating projects\n- Tasks spanning many tool calls\n- Anything requiring organization\n\n**Skip for:**\n- Simple questions\n- Single-file edits\n- Quick lookups\n\n## Templates\n\nCopy these templates to start:\n\n- [templates/task_plan.md](templates/task_plan.md) — Phase tracking\n- [templates/findings.md](templates/findings.md) — Research storage\n- [templates/progress.md](templates/progress.md) — Session logging\n\n## Scripts\n\nHelper scripts for automation:\n\n- `scripts/init-session.sh` — Initialize all planning files\n- `scripts/check-complete.sh` — Verify all phases complete\n- `scripts/append-changelog.sh` — Append changelog entry (hash + plan link)\n\n## Advanced Topics\n\n- **Manus Principles:** See [reference.md](reference.md)\n- **Real Examples:** See [examples.md](examples.md)\n\n## Anti-Patterns\n\n| Don''t | Do Instead |\n|-------|------------|\n| Keep todos only in chat memory | Persist the plan in task_plan.md |\n| State goals once and forget | Re-read plan before decisions |\n| Hide errors and retry silently | Log errors to plan file |\n| Stuff everything in context | Store large content in files |\n| Start executing immediately | Create plan file FIRST |\n| Repeat failed actions | Track attempts, mutate approach |\n| Create planning files in repo root | Create `docs/en/developer/plans/<hash>/` |\n"},"lastSynced":"2026-03-06T07:02:03.025Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing advanced code review and automation through file context planning.","zh":"非常适合需要高级代码审查和自动化的开发代理，通过文件上下文规划实现。","ja":"開発エージェントが高度なコードレビューと自動化を必要とする場合に最適です。ファイルのコンテキスト計画を通じて実現します。","ko":"개발 에이전트가 고급 코드 리뷰와 자동화를 필요로 할 때 완벽합니다. 파일 맥락 계획을 통해 구현됩니다.","es":"Ideal para Agentes de Desarrollo que necesitan revisión de código avanzada y automatización mediante planificación de contexto de archivos.","fr":"Parfait pour les Agents de Développement nécessitant une revue de code avancée et une automatisation via la planification de contexte de fichiers.","de":"Perfekt für Entwicklungs-Agents, die erweiterte Code-Überprüfung und Automatisierung durch Dateikontextplanung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de revisão de código avançada e automação por meio de planejamento de contexto de arquivo.","ru":"Идеально для агентов разработки, которым требуется расширенный обзор кода и автоматизация через планирование контекста файла.","ar":"مثالي للوكلاء النموزجيين الذين يحتاجون إلى استعراض شفرة متقدم وتوضيح من خلال تخطيط سياق الملف."},"recommendation":{"en":"Empowers agents to perform intelligent code reviews and automate tasks through conversations and Webhooks, utilizing visual consoles for real-time task execution monitoring and persistent markdown files as working memory on disk.","zh":"赋予代理执行智能代码审查和自动化任务的能力，通过对话和Webhooks，利用视觉控制台进行实时任务执行监控，并使用持久的Markdown文件作为磁盘上的工作内存。","ja":"エージェントがインテリジェントなコードレビューを実行し、会話やWebhooksを通じてタスクを自動化する能力を提供します。視覚的なコンソールを使用してリアルタイムのタスク実行を監視し、ディスク上のワーキングメモリとして永続的なMarkdownファイルを使用します。","ko":"에이전트가 지능형 코드 리뷰를 수행하고 대화와 Webhooks를 통해 작업을 자동화할 수 있는 능력을 부여합니다. 시각적 콘솔을 사용하여 실시간 작업 실행을 모니터링하고 디스크上的 작업 메모리として 영속적인 Markdown 파일을 사용합니다.","es":"Permite a los agentes realizar revisiones de código inteligentes y automatizar tareas mediante conversaciones y Webhooks, utilizando consolas visuales para el monitoreo en tiempo real de la ejecución de tareas y archivos markdown persistentes como memoria de trabajo en disco.","fr":"Permet aux agents d''effectuer des revues de code intelligentes et d''automatiser des tâches via des conversations et des Webhooks, en utilisant des consoles visuelles pour le suivi en temps réel de l''exécution des tâches et des fichiers markdown persistants comme mémoire de travail sur disque.","de":"Ermöglicht Agents, intelligente Code-Überprüfungen durchzuführen und Aufgaben durch Konversationen und Webhooks zu automatisieren, unter Verwendung visueller Konsolen zur Echtzeit-Überwachung der Aufgabenausführung und persistenter Markdown-Dateien als Arbeitsgedächtnis auf der Festplatte.","pt":"Habilita os agentes a realizar revisões de código inteligentes e automatizar tarefas por meio de conversas e Webhooks, utilizando consoles visuais para monitoramento de execução de tarefas em tempo real e arquivos markdown persistentes como memória de trabalho em disco.","ru":"Наделяет агентов возможностью проводить интеллектуальные обзоры кода и автоматизировать задачи через разговоры и Webhooks, используя визуальные консоли для мониторинга выполнения задач в реальном времени и постоянные файлы markdown как рабочую память на диске.","ar":"يمكن للوكلاء من خلاله أداء استعراض ذكي للشفرة وتوضيح المهام من خلال المحادثات و Webhooks، واستخدام وحدات التحكم المرئية لمراقبة تنفيذ المهام في الوقت الفعلي وملفات markdown المستدامة كذاكرة عمل على القرص."},"useCases":{"en":["Automating code reviews with real-time task monitoring","Generating planning files for traceability and version control","Debugging code execution with visual console outputs"],"zh":["使用实时任务监控自动化代码审查","生成用于可追溯性和版本控制的规划文件","使用视觉控制台输出调试代码执行"],"ja":["リアルタイムタスク監視を使用したコードレビューの自動化","トレーサビリティとバージョン管理のための計画ファイルの生成","視覚的なコンソール出力を使用したコード実行のデバッグ"],"ko":["실시간 작업 모니터링을 사용한 코드 리뷰 자동화","추적성 및 버전 관리를 위한 계획 파일 생성","시각적 콘솔 출력을 사용한 코드 실행 디버깅"],"es":["Automatización de revisiones de código con monitoreo de tareas en tiempo real","Generación de archivos de planificación para trazabilidad y control de versiones","Depuración de ejecución de código con salidas de consola visual"],"fr":["Automatisation des revues de code avec suivi des tâches en temps réel","Génération de fichiers de planification pour la traçabilité et le contrôle de version","Débogage de l''exécution du code avec sorties de console visuelle"],"de":["Automatisierung von Code-Überprüfungen mit Echtzeit-Aufgabenüberwachung","Erstellung von Planungsdateien für Rückverfolgbarkeit und Versionskontrolle","Debugging der Code-Ausführung mit visuellen Konsolenausgaben"],"pt":["Automatizar revisões de código com monitoramento de tarefas em tempo real","Gerar arquivos de planejamento para rastreabilidade e controle de versão","Depurar execução de código com saídas de console visual"],"ru":["Автоматизировать обзор кода с мониторингом задач в реальном времени","Генерировать файлы планирования для отслеживаемости и контроля версий","Отладить выполнение кода с помощью визуальных консольных выводов"],"ar":["توفير استعراض الشفرة تلقائياً مع مراقبة المهام في الوقت الفعلي","توليد ملفات تخطيط لتعقبها ومراقبة الإصدارات","تصحيح أخطاء تنفيذ الشفرة باستخدام إخراج وحدات التحكم المرئية"]},"limitations":{"en":["Requires filesystem access for persistent markdown files","Limited to Codex-compatible skills and instruction-only workflows"],"zh":["需要文件系统访问以使用持久的Markdown文件","仅限于Codex兼容的技能和指令のみワークフロー"],"ja":["永続的なMarkdownファイルを使用するためにファイルシステムへのアクセスが必要","Codex互換のスキルと指令のみワークフローに限定される"],"ko":["영속적인 Markdown 파일을 사용하기 위해 파일 시스템 액세스가 필요합니다","Codex 호환되는 스킬과 지시 전용 워크플로에만 제한됩니다"],"es":["Requiere acceso al sistema de archivos para los archivos markdown persistentes","Limitado a habilidades compatibles con Codex y flujos de trabajo solo de instrucción"],"fr":["Nécessite un accès au système de fichiers pour les fichiers markdown persistants","Limité aux compétences compatibles Codex et aux workflows en instruction uniquement"],"de":["Erfordert Dateisystemzugriff für persistente Markdown-Dateien","Beschränkt auf Codex-kompatible Skills und nur-Befehls-Workflows"],"pt":["Requer acesso ao sistema de arquivos para arquivos markdown persistentes","Limitado a habilidades compatíveis com Codex e fluxos de trabalho de instrução apenas"],"ru":["Требует доступа к файловой системе для постоянных файлов markdown","Ограничен навыками, совместимыми с Codex, и рабочими процессами только с инструкциями"],"ar":["يتطلب الوصول إلى نظام الملفات لملفات markdown المستدامة","محدود بالمهارات المتوافقة مع Codex وعمليات العمل الإرشادية فقط"]},"version":4},"contentHash":"fbf5c369fe9b953ce769a36607848a2a8954d6082431ee28ee273263ca75b72a","qualityScore":65}');
