INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hookvibe/hookcode/file-context-planning', 'file-context-planning', 'hookvibe', 'hookcode', 'community', 'file-context-planning hookvibe hookcode community file-context-planning is a skill that enables intelligent code review and automation through conversations and Webhooks. It benefits developers by providing a visual console for real-time task execution monitoring. 文件上下文规划是HookCode代码审查平台的一项技能，用于通过对话和Webhook触发CLI编码助手 ファイルコンテキスト計画は、HookCode AIエージェントの機能で、対話とWebhookを通じてCLIコーディングアシスタントをトリガーする 파일 컨텍스트 계획은 HookCode 코드 리뷰 플랫폼의 기능으로 대화와 Webhook을 통해 CLI 코딩 도우미를 트리거합니다 La planificación de contexto de archivo es una habilidad de AI Agent que utiliza archivos markdown persistentes como memoria de trabajo en disco La planification de contexte de fichier est une compétence d''outils IA qui utilise des fichiers markdown persistants comme mémoire de travail sur disque Die Dateikontextplanung ist eine Fähigkeit von KI-Tools, die persistente Markdown-Dateien als Arbeitsgedächtnis auf Disk verwendet O skill file-context-planning permite trabalhar com arquivos de forma eficiente, utilizando a plataforma HookCode para automação de tarefas e revisão de código Навык file-context-planning позволяет работать с файлами эффективно, используя платформу HookCode для автоматизации задач и проверки кода الوظيفة file-context-planning تسمح بالعمل مع الملفات بفعالية، باستخدام منصة HookCode للتحكم الآلي في المهام ومراجعة الشفرة how to use file-context-planning file-context-planning alternative file-context-planning setup guide what is file-context-planning file-context-planning vs automation platforms file-context-planning install Codex-compatible skills CLI automation tools code review and automation platforms 文件上下文规划 HookCode代码审查 CLI编码助手 Webhook Codex兼容 代码审查平台 开发效率 AI工具 Triggers CLI coding assistants through conversations and Webhooks Supports independent deployment for flexible automation Provides a visual console for real-time task execution monitoring Utilizes persistent markdown files as working memory on disk Compatible with Codex for instruction-only automation Refactors planning files for traceability under docs/en/developer/plans/<hash> file-context-planning is a Codex-compatible skill that uses persistent markdown files as working memory on disk for planning and automation purposes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Dr-SoloDev/ginva/documentation', 'community', 'Dr-SoloDev', 'ginva', 'Dr-SoloDev/ginva', 'documentation', 2, 0, 65, '2026-02-26T21:30:41Z', '2026-03-06T07:07:41.845Z', '5c9ada2648589ccd15ab8f8beff62ac2cc20ec32d0535c9ade89342357e49cf3', '{"id":"Dr-SoloDev/ginva/documentation","name":"documentation","description":{"en":"The documentation skill provides a comprehensive workflow for generating API documentation, architecture documentation, and technical content from codebases, benefiting developers and project maintainers.","zh":"文档工作流是一种用于生成API文档、架构文档、README文件、代码注释和技术文档的综合工作流","ja":"ドキュメントワークフローは、APIドキュメント、建築ドキュメント、READMEファイル、コードコメント、テクニカルコンテンツを生成するための包括的なワークフローです","ko":"문서 작업 흐름은 API 문서, 아키텍처 문서, README 파일, 코드 주석 및 기술 문서를 생성하기 위한 포괄적인 작업 흐름입니다","es":"El flujo de trabajo de documentación es una herramienta para generar documentación de API, arquitectura y código.","fr":"Le flux de travail de documentation est un outil pour générer la documentation d''API, d''architecture et de code.","de":"Der Dokumentations-Workflow ist ein Tool zum Generieren von API-Dokumentation, Architektur-Dokumentation und Code-Dokumentation.","pt":"O fluxo de trabalho de documentação é uma solução abrangente para gerar documentação de API, arquitetura e READMEs","ru":"Поток документации - это комплексное решение для генерации документации API, архитектуры и файлов README","ar":"يتضمن تدفق الوثائق حلاً شاملًا لإنشاء وثائق API والهيكل والملفات الرئيسية"},"seo":{"title":{"en":"Documentation: Comprehensive Workflow Bundle for AI Agent...","zh":"文档工作流设置指南 - Decentralized Pawn Shop 协议文档最佳实践","ja":"ドキュメントワークフロー設定ガイド - AIエージェントによるDefiプロトコル文書化","ko":"문서 작업 흐름 설정 가이드 - 탈중앙화 폰 ショップ 프로토콜 문서화","es":"Guía de configuración de documentación para Desarrolladores","fr":"Configurer la documentation pour les développeurs","de":"Documentation-Setup-Leitfa