INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Dr-SoloDev/ginva/documentation', 'documentation', 'Dr-SoloDev', 'ginva', 'community', 'documentation Dr-SoloDev ginva community The documentation skill provides a comprehensive workflow for generating API documentation, architecture documentation, and technical content from codebases, benefiting developers and project maintainers. 文档工作流是一种用于生成API文档、架构文档、README文件、代码注释和技术文档的综合工作流 ドキュメントワークフローは、APIドキュメント、建築ドキュメント、READMEファイル、コードコメント、テクニカルコンテンツを生成するための包括的なワークフローです 문서 작업 흐름은 API 문서, 아키텍처 문서, README 파일, 코드 주석 및 기술 문서를 생성하기 위한 포괄적인 작업 흐름입니다 El flujo de trabajo de documentación es una herramienta para generar documentación de API, arquitectura y código. Le flux de travail de documentation est un outil pour générer la documentation d''API, d''architecture et de code. Der Dokumentations-Workflow ist ein Tool zum Generieren von API-Dokumentation, Architektur-Dokumentation und Code-Dokumentation. O fluxo de trabalho de documentação é uma solução abrangente para gerar documentação de API, arquitetura e READMEs Поток документации - это комплексное решение для генерации документации API, архитектуры и файлов README يتضمن تدفق الوثائق حلاً شاملًا لإنشاء وثائق API والهيكل والملفات الرئيسية how to use documentation workflow what is documentation in software development documentation workflow bundle alternative documentation vs readme files documentation setup guide for AI agents documentation install for Solana projects 文档工作流 Decentralized Pawn Shop 协议 Defi 文档 API 文档生成 架构文档生成 代码注释生成 技术文档生成 Generates API documentation from codebases Creates architecture documentation for project overview Supports generation of README files and code comments Enables creation of user guides and maintenance of wikis Includes documentation planning phase for workflow optimization Documentation is a comprehensive workflow bundle for generating API documentation, architecture documentation, README files, code comments, and technical content from codebases.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MeganHarrison/alleato-pm/Writing Hookify Rules', 'community', 'MeganHarrison', 'alleato-pm', 'MeganHarrison/alleato-pm', 'Writing Hookify Rules', 1, 0, 65, '2026-03-07T12:40:04Z', '2026-03-07T12:51:26.151Z', 'cf7a6a0b92092f44c6532bd9af7189748a9c3b4d044005418230b08cc99ac55c', '{"id":"MeganHarrison/alleato-pm/Writing Hookify Rules","name":"Writing Hookify Rules","description":{"en":"Writing Hookify Rules enables developers to define patterns and display messages using markdown files with YAML frontmatter. This skill benefits AI agents and developers working with Hookify.","zh":"Hookify 规则是用于定义模式和消息的 markdown 文件，通过 YAML 前置内容启用或禁用规则","ja":"Hookify ルールは、パターンとメッセージを定義するための markdown ファイルです。YAML フロントマターを使用してルールを有効または無効にします","ko":"Hookify 규칙은 패턴과 메시지를 정의하는 마크다운 파일입니다. YAML 프론트매터를 사용하여 규칙을启用 또는 비활성화합니다","es":"Las reglas Hookify son archivos markdown con frontmatter YAML que definen patrones y mensajes personalizados. Aprende a configurarlas.","fr":"Les règles Hookify sont des fichiers markdown avec frontmatter YAML qui définissent des modèles et des messages personnalisés. Apprenez à les configurer.","de":"Hookify-Regeln sind Markdown-Dateien mit YAML-Frontmatter, die Muster und benutzerdefinierte Nachrichten definieren. Erfahren Sie, wie Sie sie einrichten.","pt":"O Hookify permite a criação de regras personalizadas com markdown e YAML, melhorando a interação com as ferramentas de IA. Aprenda a configurar suas regras agora.","ru":"С помощью Hookify вы можете создавать индивидуальные правила с markdown и YAML, чтобы улучшить взаимодействие с ИИ Агентами. Узнайте, как настроить свои правила.","ar":"باستخدام Hookify ، يمكنك إنشاء قواعد مخصصة مع markdown و YAML لتحسين التفاعل مع أدوات الذكاء الاصطناعي. تعلم كيفية إعداد قواعدك الآن."},"seo":{"title":{"en":"Writing Hookify Rules: Setup Guide for AI Agents","zh":"Writing Hookify 规则设置指南","ja":"Hookify ルールの作成ベストプラクティス - AIエージェント","ko":"Hookify 규칙 작성 가이드 - AI 도구","es":"Guía de configuración de reglas Hookify para agentes de IA","fr":"Guide de configuration des règles Hookify pour les outils...","de":"Einrichtungsleitfaden für Hookify-Regeln für KI-Tools","pt":"Guia de Configuração de Regras Hookify para Ferramentas d...","ru":"Настройка правил Hookify для ИИ Агентов: лучшие практики","ar":"دليل إعداد قواعد Hookify لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create custom Hookify rules with YAML frontmatter and regex patterns. Learn to trigger messages with markdown formatting and warnings.","zh":"了解如何编写 Hookify 规则以定义模式和消息，提高开发效率。查看我们的设置指南和最佳实践","ja":"Hookify ルールを作成してパターンとメッセージを定義する方法を学びましょう。AIエージェント開発のための設定ガイドとベストプラクティス","ko":"Hookify 규칙을 작성하여 패턴과 메시지를 정의하는 방법을 알아보세요. AI 도구 개발을 위한 설정 가이드와 베스트 프랙티스","es":"Aprende a escribir reglas Hookify para agentes de IA con nuestro tutorial paso a paso. Descubre cómo definir patrones y mensajes personalizados.","fr":"Découvrez comment écrire des règles Hookify pour les outils d''IA avec notre didacticiel étape par étape. Apprenez à définir des modèles et des messages perso...","de":"Erfahren Sie, wie Sie Hookify-Regeln für KI-Tools schreiben, mit unserem Schritt-für-Schritt-Tutorial. Entdecken Sie, wie Sie Muster und benutzerdefinierte N...","pt":"Aprenda a criar regras personalizadas para o Hookify com markdown e YAML, melhorando a funcionalidade das ferramentas de IA","ru":"Откройте для себя, как создавать индивидуальные правила для Hookify с помощью markdown и YAML, чтобы повысить функциональность ИИ Агентов","ar":"اكتشف كيفية إنشاء قواعد مخصصة لـ Hookify باستخدام markdown و YAML لتحسين أداء أدوات الذكاء الاصطناعي"},"definition":{"en":"Writing Hookify Rules is a technique for creating markdown files with YAML frontmatter to define patterns and messages for AI agents.","zh":"Hookify 规则是用于定义特定事件触发时显示的消息的 markdown 文件","ja":"Hookify ルールは、特定のイベントが発生したときに表示されるメッセージを定義するための markdown ファイルです","ko":"Hookify 규칙은 특정 이벤트가 발생했을 때 표시되는 메시지를 정의하는 마크다운 파일입니다","es":"Una regla Hookify es un archivo markdown que define un patrón y una respuesta para agentes de IA.","fr":"Une règle Hookify est un fichier markdown qui définit un modèle et une réponse pour les outils d''IA.","de":"Eine Hookify-Regel ist eine Markdown-Datei, die ein Muster und eine Antwort für KI-Tools definiert.","pt":"Regras Hookify são arquivos markdown com frontmatter YAML que definem padrões e mensagens para exibir quando esses padrões são detectados","ru":"Правила Hookify представляют собой файлы markdown с frontmatter YAML, которые определяют шаблоны и сообщения для отображения при обнаружении этих шаблонов","ar":"قواعد Hookify هي ملفات markdown مع YAML frontmatter التي تحدد الأنماط والرسائل المعروضة عند مطابقة هذه الأنماط"},"features":{"en":["Supports YAML frontmatter for rule definition","Utilizes regex patterns for matching and triggering messages","Allows markdown formatting and warnings in message display","Stores rules in .claude/hookify.{rule-name}.local.md files","Triggers messages based on events like bash, file, stop, prompt, or all"],"zh":["使用 YAML 前置内容启用或禁用规则","支持正则表达式模式匹配","可定义显示的消息和警告","支持 markdown 格式的消息","规则存储在 `.claude/hookify.{rule-name}.local.md` 文件中"],"ja":["YAML フロントマターを使用してルールを有効または無効にする","正規表現パターンマッチをサポート","表示されるメッセージと警告を定義可能","markdown フォーマットのメッセージをサポート","ルールは `.claude/hookify.{rule-name}.local.md` ファイルに保存される"],"ko":["YAML 프론트매터를 사용하여 규칙을启用 또는 비활성화","정규식 패턴 매칭을 지원","표시되는 메시지와 경고를 정의할 수 있음","마크다운 형식의 메시지를 지원","규칙은 `.claude/hookify.{rule-name}.local.md` 파일에 저장됨"],"es":["Definir patrones con expresiones regulares","Crear mensajes personalizados con formato markdown","Almacenar reglas en archivos markdown con frontmatter YAML","Habilitar o deshabilitar reglas según sea necesario","Soporte para eventos como bash, archivo, parada o prompt"],"fr":["Définir des modèles avec des expressions régulières","Créer des messages personnalisés avec format markdown","Stocker des règles dans des fichiers markdown avec frontmatter YAML","Activer ou désactiver des règles selon les besoins","Prise en charge d''événements tels que bash, fichier, arrêt ou invite"],"de":["Muster mit regulären Ausdrücken definieren","Benutzerdefinierte Nachrichten mit Markdown-Format erstellen","Regeln in Markdown-Dateien mit YAML-Frontmatter speichern","Regeln nach Bedarf aktivieren oder deaktivieren","Unterstützung für Ereignisse wie Bash, Datei, Stopp oder Prompt"],"pt":["Criação de regras personalizadas com markdown","Uso de YAML frontmatter para definição de padrões","Suporte a regex para padrões complexos","Integração com eventos como bash, file, stop, prompt e all","Exibição de mensagens personalizadas com markdown"],"ru":["Создание индивидуальных правил с markdown","Использование YAML frontmatter для определения шаблонов","Поддержка regex для сложных шаблонов","Интеграция с событиями seperti bash, file, stop, prompt и all","Отображение индивидуальных сообщений с markdown"],"ar":["إنشاء قواعد مخصصة مع markdown","استخدام YAML frontmatter لتعريف الأنماط","دعم regex للأنماط المعقدة","التكامل مع أحداث مثل bash و file و stop و prompt و all","عرض رسائل مخصصة مع markdown"]},"keywords":{"en":["how to write Hookify rules","Writing Hookify Rules setup guide","what is Writing Hookify Rules","Writing Hookify Rules alternative","Writing Hookify Rules vs competitors","Hookify rules regex patterns","YAML frontmatter for Hookify rules"],"zh":["Hookify 规则","AI 工具开发","markdown 文件","YAML 前置内容","正则表达式模式匹配","消息定义","规则存储","开发效率提高"],"ja":["Hookify ルール","AIエージェント開発","markdown ファイル","YAML フロントマター","正規表現パターンマッチ","メッセージ定義","ルール保存","開発効率向上"],"ko":["Hookify 규칙","AI 도구 개발","마크다운 파일","YAML 프론트매터","정규식 패턴 매칭","메시지 정의","규칙 저장","개발 효율 향상"],"es":["reglas Hookify","agentes de IA","expresiones regulares","formato markdown","frontmatter YAML","configuración de reglas","personalización de mensajes","Herramientas de IA","desarrollo de reglas"],"fr":["règles Hookify","outils d''IA","expressions régulières","format markdown","frontmatter YAML","configuration de règles","personnalisation de messages","Outils d''IA","développement de règles"],"de":["Hookify-Regeln","KI-Tools","reguläre Ausdrücke","Markdown-Format","YAML-Frontmatter","Regelkonfiguration","Anpassung von Nachrichten","KI-Tools","Regelentwicklung"],"pt":["regras hookify","ferramentas de ia","markdown","yaml","regex","eventos","mensagens personalizadas","configuração de regras","desenvolvimento de ia"],"ru":["правила hookify","ии агенты","markdown","yaml","regex","события","индивидуальные сообщения","настройка правил","разработка ии"],"ar":["قواعد hookify","أدوات الذكاء الاصطناعي","markdown","yaml","regex","أحداث","رسائل مخصصة","إعداد قواعد","تطوير الذكاء الاصطناعي"]}},"owner":"MeganHarrison","repo":"alleato-pm","repoPath":"MeganHarrison/alleato-pm","stars":1,"forks":0,"updatedAt":"2026-03-07T12:40:04Z","topics":[],"category":"community","skillMd":{"name":"Writing Hookify Rules","description":"This skill should be used when the user asks to create a hookify rule, write a hook rule, configure hookify, add a hookify rule, or needs guidance on hookify rule syntax and patterns.","version":"0.1.0","bodyPreview":"# Writing Hookify Rules\n\n## Overview\n\nHookify rules are markdown files with YAML frontmatter that define patterns to watch for and messages to show when those patterns match. Rules are stored in `.claude/hookify.{rule-name}.local.md` files.\n\n## Rule File Format\n\n### Basic Structure\n\n```markdown\n---\nname: rule-identifier\nenabled: true\nevent: bash|file|stop|prompt|all\npattern: regex-pattern-here\n---\n\nMessage to show Claude when this rule triggers.\nCan include markdown formatting, warnings, suggest","body":"# Writing Hookify Rules\n\n## Overview\n\nHookify rules are markdown files with YAML frontmatter that define patterns to watch for and messages to show when those patterns match. Rules are stored in `.claude/hookify.{rule-name}.local.md` files.\n\n## Rule File Format\n\n### Basic Structure\n\n```markdown\n---\nname: rule-identifier\nenabled: true\nevent: bash|file|stop|prompt|all\npattern: regex-pattern-here\n---\n\nMessage to show Claude when this rule triggers.\nCan include markdown formatting, warnings, suggestions, etc.\n```\n\n### Frontmatter Fields\n\n**name** (required): Unique identifier for the rule\n- Use kebab-case: `warn-dangerous-rm`, `block-console-log`\n- Be descriptive and action-oriented\n- Start with verb: warn, prevent, block, require, check\n\n**enabled** (required): Boolean to activate/deactivate\n- `true`: Rule is active\n- `false`: Rule is disabled (won''t trigger)\n- Can toggle without deleting rule\n\n**event** (required): Which hook event to trigger on\n- `bash`: Bash tool commands\n- `file`: Edit, Write, MultiEdit tools\n- `stop`: When agent wants to stop\n- `prompt`: When user submits a prompt\n- `all`: All events\n\n**action** (optional): What to do when rule matches\n- `warn`: Show message but allow operation (default)\n- `block`: Prevent operation (PreToolUse) or stop session (Stop events)\n- If omitted, defaults to `warn`\n\n**pattern** (simple format): Regex pattern to match\n- Used for simple single-condition rules\n- Matches against command (bash) or new_text (file)\n- Python regex syntax\n\n**Example:**\n```yaml\nevent: bash\npattern: rm\\s+-rf\n```\n\n### Advanced Format (Multiple Conditions)\n\nFor complex rules with multiple conditions:\n\n```markdown\n---\nname: warn-env-file-edits\nenabled: true\nevent: file\nconditions:\n  - field: file_path\n    operator: regex_match\n    pattern: \\.env$\n  - field: new_text\n    operator: contains\n    pattern: API_KEY\n---\n\nYou''re adding an API key to a .env file. Ensure this file is in .gitignore!\n```\n\n**Condition fields:**\n- `field`: Which field to check\n  - For bash: `command`\n  - For file: `file_path`, `new_text`, `old_text`, `content`\n- `operator`: How to match\n  - `regex_match`: Regex pattern matching\n  - `contains`: Substring check\n  - `equals`: Exact match\n  - `not_contains`: Substring must NOT be present\n  - `starts_with`: Prefix check\n  - `ends_with`: Suffix check\n- `pattern`: Pattern or string to match\n\n**All conditions must match for rule to trigger.**\n\n## Message Body\n\nThe markdown content after frontmatter is shown to Claude when the rule triggers.\n\n**Good messages:**\n- Explain what was detected\n- Explain why it''s problematic\n- Suggest alternatives or best practices\n- Use formatting for clarity (bold, lists, etc.)\n\n**Example:**\n```markdown\n⚠️ **Console.log detected!**\n\nYou''re adding console.log to production code.\n\n**Why this matters:**\n- Debug logs shouldn''t ship to production\n- Console.log can expose sensitive data\n- Impacts browser performance\n\n**Alternatives:**\n- Use a proper logging library\n- Remove before committing\n- Use conditional debug builds\n```\n\n## Event Type Guide\n\n### bash Events\n\nMatch Bash command patterns:\n\n```markdown\n---\nevent: bash\npattern: sudo\\s+|rm\\s+-rf|chmod\\s+777\n---\n\nDangerous command detected!\n```\n\n**Common patterns:**\n- Dangerous commands: `rm\\s+-rf`, `dd\\s+if=`, `mkfs`\n- Privilege escalation: `sudo\\s+`, `su\\s+`\n- Permission issues: `chmod\\s+777`, `chown\\s+root`\n\n### file Events\n\nMatch Edit/Write/MultiEdit operations:\n\n```markdown\n---\nevent: file\npattern: console\\.log\\(|eval\\(|innerHTML\\s*=\n---\n\nPotentially problematic code pattern detected!\n```\n\n**Match on different fields:**\n```markdown\n---\nevent: file\nconditions:\n  - field: file_path\n    operator: regex_match\n    pattern: \\.tsx?$\n  - field: new_text\n    operator: regex_match\n    pattern: console\\.log\\(\n---\n\nConsole.log in TypeScript file!\n```\n\n**Common patterns:**\n- Debug code: `console\\.log\\(`, `debugger`, `print\\(`\n- Security risks: `eval\\(`, `innerHTML\\s*=`, `dangerouslySetInnerHTML`\n- Sensitive files: `\\.env$`, `credentials`, `\\.pem$`\n- Generated files: `node_modules/`, `dist/`, `build/`\n\n### stop Events\n\nMatch when agent wants to stop (completion checks):\n\n```markdown\n---\nevent: stop\npattern: .*\n---\n\nBefore stopping, verify:\n- [ ] Tests were run\n- [ ] Build succeeded\n- [ ] Documentation updated\n```\n\n**Use for:**\n- Reminders about required steps\n- Completion checklists\n- Process enforcement\n\n### prompt Events\n\nMatch user prompt content (advanced):\n\n```markdown\n---\nevent: prompt\nconditions:\n  - field: user_prompt\n    operator: contains\n    pattern: deploy to production\n---\n\nProduction deployment checklist:\n- [ ] Tests passing?\n- [ ] Reviewed by team?\n- [ ] Monitoring ready?\n```\n\n## Pattern Writing Tips\n\n### Regex Basics\n\n**Literal characters:** Most characters match themselves\n- `rm` matches \"rm\"\n- `console.log` matches \"console.log\"\n\n**Special characters need escaping:**\n- `.` (any char) → `\\.` (literal dot)\n- `(` `)` → `\\(` `\\)` (literal parens)\n- `[` `]` → `\\[` `\\]` (literal brackets)\n\n**Common metacharacters:**\n- `\\s` - whitespace (space, tab, newline)\n- `\\d` - digit (0-9)\n- `\\w` - word character (a-z, A-Z, 0-9, _)\n- `.` - any character\n- `+` - one or more\n- `*` - zero or more\n- `?` - zero or one\n- `|` - OR\n\n**Examples:**\n```\nrm\\s+-rf         Matches: rm -rf, rm  -rf\nconsole\\.log\\(   Matches: console.log(\n(eval|exec)\\(    Matches: eval( or exec(\nchmod\\s+777      Matches: chmod 777, chmod  777\nAPI_KEY\\s*=      Matches: API_KEY=, API_KEY =\n```\n\n### Testing Patterns\n\nTest regex patterns before using:\n\n```bash\npython3 -c \"import re; print(re.search(r''your_pattern'', ''test text''))\"\n```\n\nOr use online regex testers (regex101.com with Python flavor).\n\n### Common Pitfalls\n\n**Too broad:**\n```yaml\npattern: log    # Matches \"log\", \"login\", \"dialog\", \"catalog\"\n```\nBetter: `console\\.log\\(|logger\\.`\n\n**Too specific:**\n```yaml\npattern: rm -rf /tmp  # Only matches exact path\n```\nBetter: `rm\\s+-rf`\n\n**Escaping issues:**\n- YAML quoted strings: `\"pattern\"` requires double backslashes `\\\\s`\n- YAML unquoted: `pattern: \\s` works as-is\n- **Recommendation**: Use unquoted patterns in YAML\n\n## File Organization\n\n**Location:** All rules in `.claude/` directory\n**Naming:** `.claude/hookify.{descriptive-name}.local.md`\n**Gitignore:** Add `.claude/*.local.md` to `.gitignore`\n\n**Good names:**\n- `hookify.dangerous-rm.local.md`\n- `hookify.console-log.local.md`\n- `hookify.require-tests.local.md`\n- `hookify.sensitive-files.local.md`\n\n**Bad names:**\n- `hookify.rule1.local.md` (not descriptive)\n- `hookify.md` (missing .local)\n- `danger.local.md` (missing hookify prefix)\n\n## Workflow\n\n### Creating a Rule\n\n1. Identify unwanted behavior\n2. Determine which tool is involved (Bash, Edit, etc.)\n3. Choose event type (bash, file, stop, etc.)\n4. Write regex pattern\n5. Create `.claude/hookify.{name}.local.md` file in project root\n6. Test immediately - rules are read dynamically on next tool use\n\n### Refining a Rule\n\n1. Edit the `.local.md` file\n2. Adjust pattern or message\n3. Test immediately - changes take effect on next tool use\n\n### Disabling a Rule\n\n**Temporary:** Set `enabled: false` in frontmatter\n**Permanent:** Delete the `.local.md` file\n\n## Examples\n\nSee `${CLAUDE_PLUGIN_ROOT}/examples/` for complete examples:\n- `dangerous-rm.local.md` - Block dangerous rm commands\n- `console-log-warning.local.md` - Warn about console.log\n- `sensitive-files-warning.local.md` - Warn about editing .env files\n\n## Quick Reference\n\n**Minimum viable rule:**\n```markdown\n---\nname: my-rule\nenabled: true\nevent: bash\npattern: dangerous_command\n---\n\nWarning message here\n```\n\n**Rule with conditions:**\n```markdown\n---\nname: my-rule\nenabled: true\nevent: file\nconditions:\n  - field: file_path\n    operator: regex_match\n    pattern: \\.ts$\n  - field: new_text\n    operator: contains\n    pattern: any\n---\n\nWarning message\n```\n\n**Event types:**\n- `bash` - Bash commands\n- `file` - File edits\n- `stop` - Completion checks\n- `prompt` - User input\n- `all` - All events\n\n**Field options:**\n- Bash: `command`\n- File: `file_path`, `new_text`, `old_text`, `content`\n- Prompt: `user_prompt`\n\n**Operators:**\n- `regex_match`, `contains`, `equals`, `not_contains`, `starts_with`, `ends_with`\n"},"lastSynced":"2026-03-07T12:51:26.151Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude, AutoGPT, and LangChain needing custom pattern detection and markdown-based message display capabilities.","zh":"非常适合需要自定义模式检测和基于 markdown 的消息显示功能的 AI 代理，如 Claude、AutoGPT 和 LangChain。","ja":"Claude、AutoGPT、LangChain などのカスタムパターンデTECTIONと Markdown ベースのメッセージ表示機能が必要な AI エージェントに最適です。","ko":"Claude, AutoGPT, LangChain 등의 사용자 정의 패턴 감지 및 마크다운 기반 메시지 표시 기능이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA como Claude, AutoGPT y LangChain que necesitan detección de patrones personalizados y capacidades de visualización de mensajes basados en markdown.","fr":"Parfait pour les agents IA comme Claude, AutoGPT et LangChain ayant besoin de détection de modèles personnalisés et de capacités d''affichage de messages basés sur markdown.","de":"Perfekt für KI-Agents wie Claude, AutoGPT und LangChain, die benutzerdefinierte Mustererkennung und Markdown-basierte Nachrichtenanzeigefunktionen benötigen.","pt":"Perfeito para Agentes de IA como Claude, AutoGPT e LangChain que necessitam de detecção de padrões personalizados e capacidades de exibição de mensagens baseadas em markdown.","ru":"Идеально подходит для агентов ИИ, таких как Claude, AutoGPT и LangChain, которым необходима функция обнаружения пользовательских шаблонов и возможность отображения сообщений на основе markdown.","ar":"مثالي ليعملاء الذكاء الاصطناعي مثل Claude و AutoGPT و LangChain الذين يحتاجون إلى كشف الأنماط المخصصة وقدرات عرض الرسائل المستندة إلى markdown."},"recommendation":{"en":"Empowers agents to define patterns and display messages using markdown files with YAML frontmatter, leveraging regex patterns and event triggers like bash, file, stop, prompt, or all, to provide personalized user experiences.","zh":"赋予代理定义模式和使用带有 YAML 前置内容的 Markdown 文件显示消息的能力，利用正则表达式模式和 bash、文件、停止、提示或所有等事件触发器，提供个性化的用户体验。","ja":"エージェントが YAML フロントマターを備えた Markdown ファイルを使用してパターンを定義し、メッセージを表示する機能を提供し、正規表現パターンと bash、ファイル、停止、プロンプト、またはすべてなどのイベント トリガーを利用して、個人化されたユーザー エクスペリエンスを提供します。","ko":"bash, 파일, 정지, 프롬프트 또는 모두 등의 이벤트 트리거와 함께 YAML 전면 물음을 갖춘 마크다운 파일을 사용하여 패턴을 정의하고 메시지를 표시하는 에이전트의 능력을 부여하여 개인화된 사용자 경험을 제공합니다.","es":"Habilita a los agentes a definir patrones y mostrar mensajes utilizando archivos markdown con frontmatter YAML, aprovechando patrones regex y desencadenadores de eventos como bash, archivo, detener, prompt o todos, para proporcionar experiencias personalizadas para el usuario.","fr":"Permet aux agents de définir des modèles et d''afficher des messages en utilisant des fichiers markdown avec frontmatter YAML, en exploitant des modèles regex et des déclencheurs d''événements tels que bash, fichier, arrêter, invite ou tous, pour fournir des expériences personnalisées pour l''utilisateur.","de":"Ermöglicht es Agents, Muster zu definieren und Nachrichten mit Markdown-Dateien und YAML-Frontmatter anzuzeigen, indem Regex-Muster und EreignisTrigger wie bash, Datei, stoppen, Prompt oder alle verwendet werden, um personalisierte Benutzeroberflächen bereitzustellen.","pt":"Habilita os agentes a definir padrões e exibir mensagens usando arquivos markdown com frontmatter YAML, aproveitando padrões regex e gatilhos de eventos como bash, arquivo, parar, prompt ou todos, para fornecer experiências personalizadas para os usuários.","ru":"Позволяет агентам определять шаблоны и отображать сообщения с помощью файлов markdown с YAML-заголовком, используя шаблоны regex и триггеры событий, такие как bash, файл, остановка, запрос или все, для предоставления персонализированных пользовательских опытов.","ar":"تمكّن الوكلاء من تعريف الأنماط وعرض الرسائل باستخدام ملفات markdown مع YAML في مقدمته، واستخدام الأنماط regex ومتغيرات الأحداث مثل bash وملف وايقاف وطلب أو كلها، لتوفير تجارب مستخدم شخصية."},"useCases":{"en":["Defining custom rules for event-based messaging","Creating markdown-based alerts with regex pattern matching","Triggering personalized messages based on user interactions"],"zh":["定义基于事件的消息的自定义规则","创建使用正则表达式模式匹配的基于 markdown 的警报","触发基于用户交互的个性化消息"],"ja":["イベントベースのメッセージのカスタム ルールを定義する","正規表現パターン マッチングを使用した Markdown ベースのアラートを作成する","ユーザーとのやり取りに基づいて個性化メッセージをトリガーする"],"ko":["이벤트 기반 메시지의 사용자 정의 규칙을 정의한다","정규식 패턴 일치를 사용하는 마크다운 기반 경보를 생성한다","사용자 상호 작용에 따라 개인화된 메시지를 트리거한다"],"es":["Definir reglas personalizadas para la mensajería basada en eventos","Crear alertas basadas en markdown con coincidencia de patrones regex","Desencadenar mensajes personalizados en función de las interacciones del usuario"],"fr":["Définir des règles personnalisées pour la messagerie basée sur les événements","Créer des alertes basées sur markdown avec une correspondance de modèles regex","Déclencher des messages personnalisés en fonction des interactions de l''utilisateur"],"de":["Definieren benutzerdefinierter Regeln für ereignisbasierte Messaging","Erstellen von Markdown-basierten Alerts mit Regex-Mustervergleich","Auslösen personalisierter Nachrichten in Abhängigkeit von Benutzerinteraktionen"],"pt":["Definir regras personalizadas para mensagens baseadas em eventos","Criar alertas baseados em markdown com correspondência de padrões regex","Acionar mensagens personalizadas com base em interações do usuário"],"ru":["Определение пользовательских правил для сообщений, основанных на событиях","Создание оповещений на основе markdown с сопоставлением шаблонов regex","Запуск персонализированных сообщений на основе взаимодействия пользователя"],"ar":["تحديد قواعد مخصصة للرسائل المستندة إلى الأحداث","إنشاء تنبيهات مستندة إلى markdown مع مطابقة الأنماط regex","تشغيل رسائل مخصصة بناءً على تفاعلات المستخدم"]},"limitations":{"en":["Requires markdown files with YAML frontmatter","Dependent on Hookify rules engine","Limited to regex pattern matching"],"zh":["需要带有 YAML 前置内容的 markdown 文件","依赖于 Hookify 规则引擎","仅限于正则表达式模式匹配"],"ja":["YAML フロントマターを備えた Markdown ファイルが必要","Hookify ルール エンジンに依存する","正規表現パターン マッチングのみに限定される"],"ko":["YAML 전면 물음을 갖춘 마크다운 파일이 필요하다","Hookify 규칙 엔진에 의존한다","정규식 패턴 일치만으로 제한된다"],"es":["Requiere archivos markdown con frontmatter YAML","Dependiente del motor de reglas Hookify","Limitado a la coincidencia de patrones regex"],"fr":["Nécessite des fichiers markdown avec frontmatter YAML","Dépendant du moteur de règles Hookify","Limité à la correspondance de modèles regex"],"de":["Benötigt Markdown-Dateien mit YAML-Frontmatter","Abhängig vom Hookify-Regelmodul","Begrenzt auf Regex-Mustervergleich"],"pt":["Exige arquivos markdown com frontmatter YAML","Dependente do mecanismo de regras do Hookify","Limitado à correspondência de padrões regex"],"ru":["Требует файлов markdown с YAML-заголовком","Зависит от механизма правил Hookify","Ограничен сопоставлением шаблонов regex"],"ar":["يتطلب ملفات markdown مع YAML في مقدمته","يعتمد على محرك قواعد Hookify","محدود بمطابقة الأنماط regex"]},"version":4},"contentHash":"cf7a6a0b92092f44c6532bd9af7189748a9c3b4d044005418230b08cc99ac55c","qualityScore":65}');
