INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MeganHarrison/alleato-pm/Writing Hookify Rules', 'Writing Hookify Rules', 'MeganHarrison', 'alleato-pm', 'community', 'Writing Hookify Rules MeganHarrison alleato-pm community Writing Hookify Rules enables developers to define patterns and display messages using markdown files with YAML frontmatter. This skill benefits AI agents and developers working with Hookify. Hookify 规则是用于定义模式和消息的 markdown 文件，通过 YAML 前置内容启用或禁用规则 Hookify ルールは、パターンとメッセージを定義するための markdown ファイルです。YAML フロントマターを使用してルールを有効または無効にします Hookify 규칙은 패턴과 메시지를 정의하는 마크다운 파일입니다. YAML 프론트매터를 사용하여 규칙을启用 또는 비활성화합니다 Las reglas Hookify son archivos markdown con frontmatter YAML que definen patrones y mensajes personalizados. Aprende a configurarlas. Les règles Hookify sont des fichiers markdown avec frontmatter YAML qui définissent des modèles et des messages personnalisés. Apprenez à les configurer. Hookify-Regeln sind Markdown-Dateien mit YAML-Frontmatter, die Muster und benutzerdefinierte Nachrichten definieren. Erfahren Sie, wie Sie sie einrichten. O Hookify permite a criação de regras personalizadas com markdown e YAML, melhorando a interação com as ferramentas de IA. Aprenda a configurar suas regras agora. С помощью Hookify вы можете создавать индивидуальные правила с markdown и YAML, чтобы улучшить взаимодействие с ИИ Агентами. Узнайте, как настроить свои правила. باستخدام Hookify ، يمكنك إنشاء قواعد مخصصة مع markdown و YAML لتحسين التفاعل مع أدوات الذكاء الاصطناعي. تعلم كيفية إعداد قواعدك الآن. how to write Hookify rules Writing Hookify Rules setup guide what is Writing Hookify Rules Writing Hookify Rules alternative Writing Hookify Rules vs competitors Hookify rules regex patterns YAML frontmatter for Hookify rules Hookify 规则 AI 工具开发 markdown 文件 YAML 前置内容 正则表达式模式匹配 消息定义 规则存储 开发效率提高 Supports YAML frontmatter for rule definition Utilizes regex patterns for matching and triggering messages Allows markdown formatting and warnings in message display Stores rules in .claude/hookify.{rule-name}.local.md files Triggers messages based on events like bash, file, stop, prompt, or all Writing Hookify Rules is a technique for creating markdown files with YAML frontmatter to define patterns and messages for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SixtySecondsApp/use60/Sales Lead Enrichment', 'community', 'SixtySecondsApp', 'use60', 'SixtySecondsApp/use60', 'Sales Lead Enrichment', 0, 0, 65, '2026-03-06T11:53:42Z', '2026-03-07T03:39:48.656Z', '1419ceb13c115068714ea8b64eb1dafc959f9c9a2f802c20b3482aa4fcb48a2f', '{"id":"SixtySecondsApp/use60/Sales Lead Enrichment","name":"Sales Lead Enrichment","description":{"en":"Sales Lead Enrichment is a team of parallel research agents that transform a name and company into a complete intelligence profile, solving the problem of sales teams wasting time on bad leads with stale data.","zh":"Sales Lead Enrichment是一种AI驱动的销售工具，通过并行研究代理快速转换姓名和公司成完整的智能-profile","ja":"Sales Lead Enrichmentは、並列研究エージェントを利用して名前と会社を完全なインテリジェンスプロファイルに変換するAI駆動のセールスツールです","ko":"Sales Lead Enrichment는 이름과 회사를 완전한 지능 프로파일로 빠르게 변환하는 인공지능 기반 판매 도구입니다","es":"El enriquecimiento de leads de ventas con Agentes de IA transforma nombres y empresas en perfiles de inteligencia completos, mejorando la eficiencia de los equipos de ventas","fr":"L''enrichissement de leads de vente avec les outils d''IA transforme les noms et les entreprises en profils d''intelligence complets, améliorant l''efficacité des équipes de vente","de":"Das Vertriebslead-Enrichment mit KI-Agenten wandelt Namen und Unternehmen in vollständige Intelligenzprofile um, um die Effizienz der Vertriebsteams zu verbessern","pt":"O Enriquecimento de Leads de Vendas é uma solução que transforma nomes e empresas em perfis de inteligência completos, reduzindo o tempo de vendas gasto em leads ruins","ru":"Обогащение продажных лидов - это решение, которое превращает имена и компании в полные интеллектуальные профили, сокращая время продаж, потраченное на плохие лиды","ar":"توسيع قيادة المبيعات هو حل يتحول الأسماء والشركات إلى ملفات تعريف ذكاء كاملة، ويقلل من الوقت الذي تقضيه المبيعات في قيادة سيئة"