INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SixtySecondsApp/use60/Sales Lead Enrichment', 'Sales Lead Enrichment', 'SixtySecondsApp', 'use60', 'community', 'Sales Lead Enrichment SixtySecondsApp use60 community Sales Lead Enrichment is a team of parallel research agents that transform a name and company into a complete intelligence profile, solving the problem of sales teams wasting time on bad leads with stale data. Sales Lead Enrichment是一种AI驱动的销售工具，通过并行研究代理快速转换姓名和公司成完整的智能-profile Sales Lead Enrichmentは、並列研究エージェントを利用して名前と会社を完全なインテリジェンスプロファイルに変換するAI駆動のセールスツールです Sales Lead Enrichment는 이름과 회사를 완전한 지능 프로파일로 빠르게 변환하는 인공지능 기반 판매 도구입니다 El enriquecimiento de leads de ventas con Agentes de IA transforma nombres y empresas en perfiles de inteligencia completos, mejorando la eficiencia de los equipos de ventas L''enrichissement de leads de vente avec les outils d''IA transforme les noms et les entreprises en profils d''intelligence complets, améliorant l''efficacité des équipes de vente Das Vertriebslead-Enrichment mit KI-Agenten wandelt Namen und Unternehmen in vollständige Intelligenzprofile um, um die Effizienz der Vertriebsteams zu verbessern O Enriquecimento de Leads de Vendas é uma solução que transforma nomes e empresas em perfis de inteligência completos, reduzindo o tempo de vendas gasto em leads ruins Обогащение продажных лидов - это решение, которое превращает имена и компании в полные интеллектуальные профили, сокращая время продаж, потраченное на плохие лиды توسيع قيادة المبيعات هو حل يتحول الأسماء والشركات إلى ملفات تعريف ذكاء كاملة، ويقلل من الوقت الذي تقضيه المبيعات في قيادة سيئة how to use Sales Lead Enrichment what is Sales Lead Enrichment Sales Lead Enrichment alternative Sales Lead Enrichment vs Claygent Sales Lead Enrichment install Sales Lead Enrichment setup guide Sales Lead Enrichment for AI agents proactive meeting prep with Sales Lead Enrichment pipeline intelligence with Sales Lead Enrichment Sales Lead Enrichment AIエージェント工具 销售工具 智能-profile 并行研究代理 CRM自动化 Transforms a name and company into a complete intelligence profile Utilizes parallel research agents for efficient lead enrichment Provides autonomous CRM actions for streamlined sales processes Covers 50-60% of contacts at best, reducing bad leads with stale data Faster and deeper research capabilities compared to traditional methods Integrates with org-variables and capabilities for enhanced functionality Sales Lead Enrichment is a process that utilizes AI to proactively prepare sales teams for meetings and provide pipeline intelligence, automating CRM actions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cacr92/WeReply/wechat-automation', 'community', 'cacr92', 'WeReply', 'cacr92/WeReply', 'wechat-automation', 0, 0, 65, '2026-03-06T12:59:22.230Z', '2026-03-06T14:18:45.596Z', 'dc38cc513b39f884476ec338fd2ac676e7f84018f637e575920590d48d8f426d', '{"id":"cacr92/WeReply/wechat-automation","name":"wechat-automation","description":{"en":"The WeChat-automation skill provides expert guidance for WeChat monitoring and automation using wxauto and Accessibility API, benefiting developers and power users. It enables automated responses and conversation control.","zh":"微信聊天自动回复助手使用Python 3.12和wxauto实现Windows平台的自动化，使用Swift和Accessibility API实现macOS平台的自动化","ja":"WeChat Automation AIエージェントは、Python 3.12とwxautoを使用してWindowsプラットフォームでの自動化を実現し、SwiftとAccessibility APIを使用してmacOSプラットフォームでの自動化を実現します","ko":"WeChat 자동화 설정 가이드는 Python 3.12와 wxauto를 사용하여 Windows 플랫폼에서 자동화를 구현하며, Swift와 Accessibility API를 사용하여 macOS 플랫폼에서 자동화를 구현합니다","es":"WeChat Automation utiliza agentes de plataforma para monitorizar conversaciones y controlar la entrada de texto. Nuestra arquitectura utiliza wxauto en Windows y Accessibility API en macOS.","fr":"L''automation WeChat utilise des agents de plateforme pour surveiller les conversations et contrôler la saisie de texte. Notre architecture utilise wxauto sous Windows et Accessibility API sous macOS.","de":"Die WeChat-Automatisierung verwendet Plattform-Agents, um Konversationen zu überwachen und die Texteingabe zu steuern. Unsere Architektur verwendet wxauto unter Windows und Accessibility API unter macOS.","pt":"O WeChat Automation utiliza agentes de plataforma para monitorar conversas e controlar a caixa de entrada","ru":"ИИ Агенты для WeChat Автоматизации используются для мониторинга разговоров и управления окном ввода","ar":"آليات الويتشات تتيح مراقبة المحادثات وتحكم صندوق الإدخال باستخدام وكلاء منصة"},"s